response:
Below is a **complete, runnable mini-ORM** built on top of `sqlite3`. It demonstrates the core ORM concepts from scratch:

- model classes ↔ tables  
- field/column descriptors  
- primary keys and auto-increment  
- create table  
- insert / update / delete  
- queries with filtering, ordering, limits  
- lazy relationships (`belongs_to`, `has_many`)

Save it as `mini_orm.py` and run it with `python mini_orm.py`.

```python
import sqlite3
import sys
from typing import Any, Optional


# --------------------------------------------------------------------------- #
# Registry so string references ("Author", "Post") can be resolved at runtime
# --------------------------------------------------------------------------- #
_MODEL_REGISTRY: dict[str, type] = {}


# --------------------------------------------------------------------------- #
# Helpers
# --------------------------------------------------------------------------- #
_MISSING = object()

_SQLITE_TYPES = {int: "INTEGER", str: "TEXT", float: "REAL", bool: "INTEGER", bytes: "BLOB"}


def _sql_type(t):
    if isinstance(t, str):
        return t
    return _SQLITE_TYPES.get(t, "TEXT")


def _resolve_model(ref):
    if isinstance(ref, type):
        return ref
    if ref in _MODEL_REGISTRY:
        return _MODEL_REGISTRY[ref]
    raise RuntimeError(f"Model {ref!r} is not registered")


# --------------------------------------------------------------------------- #
# Column descriptor
# --------------------------------------------------------------------------- #
class Column:
    def __init__(self, type_, *, primary_key=False, nullable=True, default=None,
                 unique=False, foreign_key=None):
        self.type = type_
        self.primary_key = primary_key
        self.nullable = nullable
        self.default = default
        self.unique = unique
        self.foreign_key = foreign_key
        self.name = None

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return instance.__dict__.get(self.name, self.default)

    def __set__(self, instance, value):
        instance.__dict__[self.name] = value

    def __repr__(self):
        return f"Column({self.name!r}, {self.type})"


# --------------------------------------------------------------------------- #
# Relationships (lazy loading)
# --------------------------------------------------------------------------- #
class _Relationship:
    def __init__(self, target, fk):
        self.target = target
        self.fk = fk
        self.cache_attr = None

    def _target(self):
        return _resolve_model(self.target)

    def _target_pk(self):
        return self._target()._pk_column()


class BelongsTo(_Relationship):
    def __set_name__(self, owner, name):
        self.cache_attr = f"_rel_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if self.cache_attr in instance.__dict__:
            return instance.__dict__[self.cache_attr]

        db = instance._db or _DEFAULT_DB
        target = self._target()
        fk_val = getattr(instance, self.fk, None)
        value = target.get(db, fk_val) if (db is not None and fk_val is not None) else None
        instance.__dict__[self.cache_attr] = value
        return value

    def __set__(self, instance, value):
        instance.__dict__[self.cache_attr] = value
        target = self._target()
        pk_name = target._pk_column()
        setattr(instance, self.fk, getattr(value, pk_name) if value is not None else None)


class HasMany(_Relationship):
    def __set_name__(self, owner, name):
        self.cache_attr = f"_rel_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if self.cache_attr in instance.__dict__:
            return instance.__dict__[self.cache_attr]

        db = instance._db or _DEFAULT_DB
        target = self._target()
        pk_val = getattr(instance, owner._pk_column(), None)
        if db is None or pk_val is None:
            items = []
        else:
            items = target.query(db).filter(**{self.fk: pk_val}).all()
        instance.__dict__[self.cache_attr] = items
        return items


# --------------------------------------------------------------------------- #
# Database / engine
# --------------------------------------------------------------------------- #
class Database:
    def __init__(self, path=":memory:"):
        self.path = path
        self.conn = sqlite3.connect(path, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row

    def execute(self, sql, params=()):
        cur = self.conn.cursor()
        cur.execute(sql, params)
        self.conn.commit()
        return cur

    def close(self):
        self.conn.close()


_DEFAULT_DB: Optional[Database] = None


def set_default_db(db: Database):
    global _DEFAULT_DB
    _DEFAULT_DB = db


# --------------------------------------------------------------------------- #
# Query builder
# --------------------------------------------------------------------------- #
class Query:
    _OP = {"eq": "=", "ne": "!=", "gt": ">", "gte": ">=",
           "lt": "<", "lte": "<=", "like": "LIKE"}

    def __init__(self, model, db):
        self.model = model
        self.db = db
        self._conditions = []
        self._order = None
        self._limit = None
        self._offset = None

    def filter(self, **kwargs):
        for key, value in kwargs.items():
            if "__" in key:
                field, op = key.rsplit("__", 1)
                if op not in self._OP and op != "in":
                    field, op = key, "eq"
            else:
                field, op = key, "eq"

            if field not in self.model._columns:
                raise ValueError(f"Unknown field {field!r} on {self.model.__name__}")
            self._conditions.append((field, op, value))
        return self

    def order_by(self, *fields):
        parts = []
        for f in fields:
            if f.startswith("-"):
                parts.append(f[1:] + " DESC")
            else:
                parts.append(f + " ASC")
        self._order = ", ".join(parts)
        return self

    def limit(self, n):
        self._limit = int(n)
        return self

    def offset(self, n):
        self._offset = int(n)
        return self

    def _build(self):
        sql = f"SELECT * FROM {self.model._table_name}"
        params = []

        if self._conditions:
            clauses = []
            for field, op, value in self._conditions:
                if op == "in":
                    placeholders = ", ".join("?" for _ in value)
                    clauses.append(f"{field} IN ({placeholders})")
                    params.extend(value)
                else:
                    if op not in self._OP:
                        raise ValueError(f"Unknown operator {op!r}")
                    clauses.append(f"{field} {self._OP[op]} ?")
                    params.append(value)
            sql += " WHERE " + " AND ".join(clauses)

        if self._order:
            sql += " ORDER BY " + self._order
        if self._limit is not None:
            sql += " LIMIT ?"
            params.append(self._limit)
        if self._offset is not None:
            sql += " OFFSET ?"
            params.append(self._offset)

        return sql, params

    def all(self):
        if self.db is None:
            raise RuntimeError("No database available")
        sql, params = self._build()
        cur = self.db.execute(sql, params)
        return [self.model._from_row(r, self.db) for r in cur.fetchall()]

    def first(self):
        self.limit(1)
        rows = self.all()
        return rows[0] if rows else None

    def count(self):
        if self.db is None:
            raise RuntimeError("No database available")
        sql = f"SELECT COUNT(*) AS c FROM {self.model._table_name}"
        params = []
        if self._conditions:
            clauses = []
            for field, op, value in self._conditions:
                if op == "in":
                    placeholders = ", ".join("?" for _ in value)
                    clauses.append(f"{field} IN ({placeholders})")
                    params.extend(value)
                else:
                    clauses.append(f"{field} {self._OP[op]} ?")
                    params.append(value)
            sql += " WHERE " + " AND ".join(clauses)
        cur = self.db.execute(sql, params)
        return cur.fetchone()["c"]


# --------------------------------------------------------------------------- #
# Metaclass
# --------------------------------------------------------------------------- #
class ModelMeta(type):
    def __new__(mcs, name, bases, namespace):
        if name == "Model":
            return super().__new__(mcs, name, bases, namespace)

        # inherit columns from bases
        columns = {}
        for base in bases:
            if hasattr(base, "_columns"):
                for k, v in base._columns.items():
                    if k not in columns:
                        columns[k] = v

        # collect new columns
        for key, val in list(namespace.items()):
            if isinstance(val, Column):
                columns[key] = val

        namespace["_columns"] = columns
        namespace["_table_name"] = namespace.get("__tablename__", name.lower() + "s")

        cls = super().__new__(mcs, name, bases, namespace)
        _MODEL_REGISTRY[name] = cls
        return cls


# --------------------------------------------------------------------------- #
# Base Model
# --------------------------------------------------------------------------- #
class Model(metaclass=ModelMeta):
    _columns = {}
    _table_name = ""
    _persisted = False
    _db = None

    def __init__(self, **kwargs):
        self._persisted = False
        self._db = kwargs.pop("_db", None)

        # defaults
        for name, col in type(self)._columns.items():
            if col.default is not None:
                setattr(self, name, col.default)

        for key, value in kwargs.items():
            setattr(self, key, value)

    # ---- helpers ----
    @classmethod
    def _pk_column(cls):
        for name, col in cls._columns.items():
            if getattr(col, "primary_key", False):
                return name
        if "id" in cls._columns:
            return "id"
        return None

    # ---- schema ----
    @classmethod
    def create_table(cls, db: Database):
        lines = []
        for name, col in cls._columns.items():
            line = f"{name} {_sql_type(col.type)}"
            if col.primary_key:
                line += " PRIMARY KEY"
            if not col.nullable and not col.primary_key:
                line += " NOT NULL"
            if col.unique:
                line += " UNIQUE"
            if col.foreign_key:
                fk = col.foreign_key
                # allow "authors.id" or "authors(id)"
                if "." in fk and "(" not in fk:
                    table, column = fk.split(".", 1)
                    fk = f"{table}({column})"
                line += f" REFERENCES {fk}"
            lines.append(line)

        sql = (
            f"CREATE TABLE IF NOT EXISTS {cls._table_name} (\n  "
            + ",\n  ".join(lines)
            + "\n)"
        )
        db.execute(sql)

    # ---- query entry points ----
    @classmethod
    def query(cls, db=None):
        db = db or _DEFAULT_DB
        return Query(cls, db)

    @classmethod
    def get(cls, db, pk):
        if db is None or pk is None:
            return None
        return cls.query(db).filter(**{cls._pk_column(): pk}).first()

    @classmethod
    def all(cls, db=None):
        return cls.query(db).all()

    # ---- hydration ----
    @classmethod
    def _from_row(cls, row, db=None):
        instance = cls()
        for name in cls._columns:
            setattr(instance, name, row[name])
        instance._persisted = True
        instance._db = db
        return instance

    # ---- persistence ----
    def save(self, db=None):
        db = db or self._db or _DEFAULT_DB
        if db is None:
            raise RuntimeError("No database available")
        self._db = db

        cls = type(self)
        table = cls._table_name
        pk_name = cls._pk_column()
        columns = list(cls._columns.keys())

        # UPDATE path
        if self._persisted and pk_name and getattr(self, pk_name) is not None:
            fields = [c for c in columns if c != pk_name]
            if fields:
                set_clause = ", ".join(f"{c}=?" for c in fields)
                params = [getattr(self, c) for c in fields] + [getattr(self, pk_name)]
                db.execute(f"UPDATE {table} SET {set_clause} WHERE {pk_name}=?", params)
        else:
            # INSERT path (omit auto PK if not provided)
            pk_val = getattr(self, pk_name) if pk_name else None
            insert_cols = [c for c in columns if not (c == pk_name and pk_val is None)]
            placeholders = ", ".join("?" for _ in insert_cols)
            params = [getattr(self, c) for c in insert_cols]
            cur = db.execute(
                f"INSERT INTO {table} ({', '.join(insert_cols)}) VALUES ({placeholders})",
                params,
            )
            if pk_name and pk_val is None:
                setattr(self, pk_name, cur.lastrowid)
            self._persisted = True

        # invalidate cached relationships
        for key in list(self.__dict__.keys()):
            if key.startswith("_rel_"):
                del self.__dict__[key]

        return self

    def delete(self, db=None):
        db = db or self._db or _DEFAULT_DB
        if db is None:
            raise RuntimeError("No database available")
        self._db = db

        cls = type(self)
        if not self._persisted:
            return

        pk_name = cls._pk_column()
        if pk_name and getattr(self, pk_name) is not None:
            db.execute(
                f"DELETE FROM {cls._table_name} WHERE {pk_name}=?",
                (getattr(self, pk_name),),
            )
        self._persisted = False

    def __repr__(self):
        cls = type(self)
        pk_name = cls._pk_column()
        pk_val = getattr(self, pk_name) if pk_name else None
        return f"{cls.__name__}(pk={pk_val!r})"


# --------------------------------------------------------------------------- #
# Demo
# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    db = Database(":memory:")
    set_default_db(db)

    class Author(Model):
        __tablename__ = "authors"
        id = Column(int, primary_key=True)
        name = Column(str, nullable=False)
        posts = HasMany("Post", "author_id")

    class Post(Model):
        __tablename__ = "posts"
        id = Column(int, primary_key=True)
        title = Column(str, nullable=False)
        body = Column(str, default="")
        author_id = Column(int, foreign_key="authors.id")
        author = BelongsTo("Author", "author_id")

    # schema
    Author.create_table(db)
    Post.create_table(db)

    # insert
    alice = Author(name="Alice").save()
    bob = Author(name="Bob").save()

    p1 = Post(title="Hello", body="first post", author=alice).save()
    p2 = Post(title="Second", author_id=bob.id).save()

    print("Authors:", [a.name for a in Author.query(db).all()])

    print("\nPosts (newest first):")
    for p in Post.query(db).order_by("-id").all():
        author_name = p.author.name if p.author else None
        print(f"  {p.id}: {p.title!r} -> {author_name}")

    # relationship helpers
    print("\nAlice's posts:", [p.title for p in alice.posts])
    print("Posts by Bob:", [p.title for p in Post.query(db).filter(author_id=bob.id).all()])

    # filtering operators
    print("\nTitles starting with 'H':",
          [p.title for p in Post.query(db).filter(title__like="H%").all()])

    # update
    p1.title = "Hello, updated"
    p1.save()
    print("\nAfter update:", Post.get(db, p1.id).title)

    # delete
    p2.delete()
    print("Post count after delete:", Post.query(db).count())

    db.close()
```

## How the pieces work

- **`Column`** is a descriptor. Reading/writing `author.name` actually stores the value in the instance `__dict__`, while the `Column` object (stored on the class) keeps schema metadata such as SQL type, nullability, and foreign keys.
- **`ModelMeta`** scans a model class body for `Column` instances and builds `_columns`. It also registers every model by name so `BelongsTo("Author")` / `HasMany("Post")` can be resolved lazily.
- **`Model`** provides the shared persistence logic:
  - `create_table()` translates Python types into SQLite column definitions.
  - `save()` does an `INSERT` (omitting a missing auto primary key so SQLite assigns one) or an `UPDATE` when the row already exists.
  - `delete()` removes by primary key.
- **`Query`** builds SQL incrementally. `filter()` supports equality and operators like `title__like`, `id__gt`, `id__in`, ordering with `order_by("-id")`, and `limit`/`offset`.
- **Relationships** are lazy:
  - `BelongsTo` loads the related object on first access and keeps the foreign key in sync when assigned.
  - `HasMany` runs a filtered query when first accessed.
- **`Database`** wraps a `sqlite3` connection. A module-level default database can be set with `set_default_db()`, which keeps the demo code concise.

### Extending it

This is intentionally small. Natural next steps for a production ORM would be: migrations, transactions/contexts, connection pooling, eager loading, caching invalidation across relationships, schema constraints/indexes, and support for multiple backends. But the example above already captures the basic ORM workflow end to end.

## ORM basics

An ORM (Object-Relational Mapper) maps **objects in Python** to **rows in relational tables** and maps **class attributes** to **table columns**.

At a minimum, an ORM has these moving parts:

1. **Engine / connection**  
   Owns the DB connection, executes SQL, manages transactions.

2. **Declarative model metadata**  
   Classes declare fields. A metaclass collects those fields and derives the table name and column definitions.

3. **Field descriptors**  
   Column objects are descriptors, so attribute access on an instance reads/writes a value dictionary (`_values`), while class-level access returns the field itself.

4. **Unit of work / persistence**  
   The ORM decides whether an object is new or existing, then generates `INSERT` or `UPDATE`, and tracks dirty fields.

5. **Query builder**  
   Composes SQL from Python calls (`filter`, `order_by`, `limit`) and hydrates result rows back into model instances.

6. **Identity mapping (optional but important in real ORMs)**  
   Ensures the same DB row becomes the same Python object within a session.

Common real-world challenges: N+1 queries, lazy loading, transactions, schema migrations, dialect differences, and object graph consistency. The implementation below is an educational but runnable **Active Record-style core**.

---

## Mini ORM implementation

```python
import sqlite3
from typing import Any, Callable, Dict, List, Optional


# --------------------------------------------------------------------------- #
# Fields (descriptors)
# --------------------------------------------------------------------------- #

class Field:
    """Base column descriptor.

    On an instance:
        obj.name returns obj._values["name"]
    On a class:
        Model.name returns the Field object itself
    """

    def __init__(
        self,
        sql_type: str,
        *,
        primary_key: bool = False,
        nullable: bool = True,
        default: Any = None,
        unique: bool = False,
    ) -> None:
        self.sql_type = sql_type
        self.primary_key = primary_key
        self.nullable = nullable
        self.default = default
        self.unique = unique
        self.name: Optional[str] = None

    def __set_name__(self, owner: type, name: str) -> None:
        self.name = name

    def __get__(self, obj: Any, objtype: Optional[type] = None) -> Any:
        if obj is None:
            return self
        return obj._values.get(self.name, self._resolve_default())

    def __set__(self, obj: Any, value: Any) -> None:
        obj._values[self.name] = value
        obj._dirty.add(self.name)

    def _resolve_default(self) -> Any:
        if callable(self.default):
            return self.default()
        return self.default


class IntegerField(Field):
    def __init__(self, **kwargs: Any) -> None:
        super().__init__("INTEGER", **kwargs)


class StringField(Field):
    def __init__(self, **kwargs: Any) -> None:
        super().__init__("TEXT", **kwargs)


class FloatField(Field):
    def __init__(self, **kwargs: Any) -> None:
        super().__init__("REAL", **kwargs)


class BooleanField(Field):
    def __init__(self, **kwargs: Any) -> None:
        super().__init__("INTEGER", **kwargs)


class ForeignKeyField(IntegerField):
    """A minimal FK is just an integer column pointing at another table."""

    def __init__(self, to: type, **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self.to = to


# --------------------------------------------------------------------------- #
# Engine
# --------------------------------------------------------------------------- #

class Engine:
    """Thin wrapper around sqlite3. A real ORM would support many dialects."""

    def __init__(self, database: str = ":memory:") -> None:
        self._connection = sqlite3.connect(database)
        self._connection.row_factory = sqlite3.Row

    def execute(self, sql: str, parameters: tuple = ()) -> sqlite3.Cursor:
        cursor = self._connection.execute(sql, parameters)
        self._connection.commit()
        return cursor

    def close(self) -> None:
        self._connection.close()


# --------------------------------------------------------------------------- #
# Metaclass: collects fields and table metadata
# --------------------------------------------------------------------------- #

class ModelMeta(type):
    def __new__(mcs, name: str, bases: tuple, namespace: dict, **kwargs: Any) -> type:
        # Do not process the abstract base class itself.
        if name == "Model":
            return super().__new__(mcs, name, bases, namespace)

        # Inherit fields from base classes.
        fields: Dict[str, Field] = {}
        for base in bases:
            fields.update(getattr(base, "_fields", {}))

        # Collect newly declared fields.
        for key, value in list(namespace.items()):
            if isinstance(value, Field):
                fields[key] = value

        namespace["_fields"] = fields
        namespace["__tablename__"] = namespace.get("__tablename__", name.lower())

        return super().__new__(mcs, name, bases, namespace)


# --------------------------------------------------------------------------- #
# Query builder
# --------------------------------------------------------------------------- #

_OPERATORS = {
    "": "=",
    "eq": "=",
    "ne": "!=",
    "gt": ">",
    "lt": "<",
    "gte": ">=",
    "lte": "<=",
    "like": "LIKE",
}


class Query:
    def __init__(self, model: type, engine: Optional[Engine] = None) -> None:
        self.model = model
        self.engine = model._resolve_engine(engine)
        self._conditions: List[str] = []
        self._params: List[Any] = []
        self._order_by: Optional[str] = None
        self._limit: Optional[int] = None
        self._offset: Optional[int] = None

    def filter(self, **criteria: Any) -> "Query":
        """Supports equality and operators such as age__gte=18."""
        for key, value in criteria.items():
            if "__" in key:
                column, op = key.rsplit("__", 1)
            else:
                column, op = key, ""

            if column not in self.model._fields:
                raise ValueError(f"Unknown column: {column}")
            if op not in _OPERATORS and op != "in":
                raise ValueError(f"Unknown operator: {op}")

            if op == "in":
                if not value:
                    # SQL IN () is invalid; represent as always false.
                    self._conditions.append("0 = 1")
                    continue
                placeholders = ", ".join("?" for _ in value)
                self._conditions.append(f"{column} IN ({placeholders})")
                self._params.extend(value)
            else:
                self._conditions.append(f"{column} {_OPERATORS[op]} ?")
                self._params.append(value)

        return self

    def order_by(self, column: str, descending: bool = False) -> "Query":
        if column not in self.model._fields:
            raise ValueError(f"Unknown column: {column}")
        direction = "DESC" if descending else "ASC"
        self._order_by = f"{column} {direction}"
        return self

    def limit(self, count: int) -> "Query":
        if count < 0:
            raise ValueError("limit must be non-negative")
        self._limit = count
        return self

    def offset(self, count: int) -> "Query":
        if count < 0:
            raise ValueError("offset must be non-negative")
        self._offset = count
        return self

    def all(self) -> List[Any]:
        sql = f"SELECT * FROM {self.model.__tablename__}"
        if self._conditions:
            sql += " WHERE " + " AND ".join(self._conditions)
        if self._order_by:
            sql += " ORDER BY " + self._order_by
        if self._limit is not None:
            sql += f" LIMIT {self._limit}"
        if self._offset is not None:
            sql += f" OFFSET {self._offset}"

        rows = self.engine.execute(sql, tuple(self._params)).fetchall()
        return [self.model._from_row(row) for row in rows]

    def first(self) -> Optional[Any]:
        return self.limit(1).all()[0] if self.limit(1).all() else None

    def count(self) -> int:
        sql = f"SELECT COUNT(*) AS c FROM {self.model.__tablename__}"
        if self._conditions:
            sql += " WHERE " + " AND ".join(self._conditions)
        row = self.engine.execute(sql, tuple(self._params)).fetchone()
        return int(row["c"])

    def delete(self) -> int:
        sql = f"DELETE FROM {self.model.__tablename__}"
        if self._conditions:
            sql += " WHERE " + " AND ".join(self._conditions)
        cursor = self.engine.execute(sql, tuple(self._params))
        return cursor.rowcount


# --------------------------------------------------------------------------- #
# Base model
# --------------------------------------------------------------------------- #

class Model(metaclass=ModelMeta):
    _engine: Optional[Engine] = None

    def __init__(self, **kwargs: Any) -> None:
        self._values: Dict[str, Any] = {}
        self._dirty: set[str] = set()
        self._persisted: bool = False

        for key, value in kwargs.items():
            if key not in self._fields:
                raise TypeError(f"{type(self).__name__} has no field {key!r}")
            setattr(self, key, value)

        # Apply defaults for omitted fields.
        for name, field in self._fields.items():
            if name not in self._values and field.default is not None:
                self._values[name] = (
                    field.default() if callable(field.default) else field.default
                )

    # ---------------------------- engine helpers ---------------------------- #

    @classmethod
    def _resolve_engine(cls, engine: Optional[Engine]) -> Engine:
        if engine is not None:
            return engine
        if cls._engine is not None:
            return cls._engine
        if Model._engine is not None:
            return Model._engine
        raise RuntimeError(
            "No engine configured. Pass engine=... or set Model._engine = engine"
        )

    @classmethod
    def _primary_key(cls) -> Optional[str]:
        for name, field in cls._fields.items():
            if field.primary_key:
                return name
        return None

    # ---------------------------- schema ----------------------------------- #

    @classmethod
    def create_table(cls, engine: Optional[Engine] = None) -> None:
        engine = cls._resolve_engine(engine)
        columns: List[str] = []
        for name, field in cls._fields.items():
            parts = [name, field.sql_type]
            if field.primary_key:
                parts.append("PRIMARY KEY")
            if not field.nullable and not field.primary_key:
                parts.append("NOT NULL")
            if field.unique and not field.primary_key:
                parts.append("UNIQUE")
            columns.append(" ".join(parts))

        sql = (
            f"CREATE TABLE IF NOT EXISTS {cls.__tablename__} "
            f"({', '.join(columns)})"
        )
        engine.execute(sql)

    # ---------------------------- hydration -------------------------------- #

    @classmethod
    def _from_row(cls, row: sqlite3.Row) -> "Model":
        obj = cls.__new__(cls)
        obj._values = {}
        obj._dirty = set()
        obj._persisted = True
        for name in cls._fields:
            obj._values[name] = row[name]
        return obj

    # ---------------------------- persistence ------------------------------ #

    def save(self, engine: Optional[Engine] = None) -> "Model":
        engine = type(self)._resolve_engine(engine)
        table = type(self).__tablename__
        pk = type(self)._primary_key()

        # Existing object: update only dirty, non-primary-key columns.
        if self._persisted:
            dirty_columns = [
                name for name in self._dirty
                if name != pk
            ]
            if dirty_columns:
                assignments = ", ".join(f"{name} = ?" for name in dirty_columns)
                sql = f"UPDATE {table} SET {assignments} WHERE {pk} = ?"
                params = [self._values[name] for name in dirty_columns]
                params.append(self._values[pk])
                engine.execute(sql, tuple(params))
            self._dirty.clear()
            return self

        # New object: insert.
        columns = list(type(self)._fields)
        if pk is not None and self._values.get(pk) is None:
            columns = [column for column in columns if column != pk]

        placeholders = ", ".join("?" for _ in columns)
        sql = (
            f"INSERT INTO {table} ({', '.join(columns)}) "
            f"VALUES ({placeholders})"
        )
        params = [self._values.get(column) for column in columns]
        cursor = engine.execute(sql, tuple(params))

        if pk is not None and self._values.get(pk) is None:
            self._values[pk] = cursor.lastrowid

        self._persisted = True
        self._dirty.clear()
        return self

    def delete(self, engine: Optional[Engine] = None) -> None:
        engine = type(self)._resolve_engine(engine)
        table = type(self).__tablename__
        pk = type(self)._primary_key()

        if not self._persisted or pk is None or self._values.get(pk) is None:
            raise RuntimeError("Cannot delete an object that has not been persisted")

        engine.execute(
            f"DELETE FROM {table} WHERE {pk} = ?",
            (self._values[pk],),
        )
        self._persisted = False

    # ---------------------------- query API -------------------------------- #

    @classmethod
    def query(cls, engine: Optional[Engine] = None) -> Query:
        return Query(cls, engine)

    @classmethod
    def all(cls, engine: Optional[Engine] = None) -> List["Model"]:
        return cls.query(engine).all()

    @classmethod
    def get(cls, primary_key_value: Any, engine: Optional[Engine] = None) -> Optional["Model"]:
        pk = cls._primary_key()
        if pk is None:
            raise RuntimeError("Model has no primary key")
        return cls.query(engine).filter(**{pk: primary_key_value}).first()

    def __repr__(self) -> str:
        fields = ", ".join(
            f"{name}={self._values.get(name)!r}" for name in type(self)._fields
        )
        return f"{type(self).__name__}({fields})"


# --------------------------------------------------------------------------- #
# Example usage
# --------------------------------------------------------------------------- #

if __name__ == "__main__":
    class User(Model):
        __tablename__ = "users"

        id = IntegerField(primary_key=True)
        name = StringField(nullable=False)
        email = StringField(unique=True)
        age = IntegerField(default=0)
        active = BooleanField(default=True)

    engine = Engine("demo.db")
    Model._engine = engine

    User.create_table()

    # Insert
    ada = User(name="Ada Lovelace", email="ada@example.com", age=36)
    ada.save()
    print("created:", ada)

    # Query + filter
    adults = User.query().filter(age__gte=18).order_by("name").all()
    print("adults:", adults)

    # Update
    ada.age = 37
    ada.save()
    print("updated:", User.get(ada.id))

    # Count and delete
    print("count before delete:", User.query().count())
    ada.delete()
    print("count after delete:", User.query().count())

    engine.close()
```

### What this code demonstrates

- **Metaclass-driven mapping**: `ModelMeta` turns class-level `Field` objects into `_fields` and derives `__tablename__`.
- **Descriptor field access**: reading `user.age` reads `user._values["age"]`; writing updates the dirty set.
- **Schema generation**: `create_table()` emits `CREATE TABLE`.
- **Hydration**: `_from_row()` rebuilds model instances from `sqlite3.Row`.
- **Dirty tracking**: `save()` does `UPDATE` only for changed columns on persisted objects and `INSERT` for new objects.
- **Query composition**: `filter(age__gte=18)`, `order_by`, `limit`, `offset`, `count`, and `delete`.
- **Primary key hydration**: after insert, `lastrowid` is written back into the object.

### Limitations you would remove in a production ORM

- No real **Session / unit of work**; persistence is Active Record style.
- No **identity map**, so the same row can become multiple Python objects.
- No **relationships / lazy loading** (`user.posts`), joins, or eager loading.
- No **migrations**, dialect abstraction, or advanced SQL composition.
- SQLite only; no PostgreSQL/MySQL-specific types or behaviors.
- Minimal transaction API and no rollback handling beyond SQLite defaults.

```python
#!/usr/bin/env python3
"""boolean_logic.py - a small but complete Boolean-logic toolkit in Python.

Features:
  * Primitive gates: NOT, AND, OR, NAND, NOR, XOR, XNOR, IMPLIES, IFF
  * Combinational circuits: half-adder, full-adder, 4-bit ripple-carry adder
  * A Boolean expression language with a recursive-descent parser
  * Truth-table generation, classification (tautology / contradiction / satisfiable)
  * Conversion to disjunctive / conjunctive normal form (DNF / CNF)
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from itertools import product
from typing import Any, Dict, List, Set, Tuple

# ---------------------------------------------------------------------------
# 1. Primitive logic gates
# ---------------------------------------------------------------------------
def NOT(a: bool) -> bool:   return not a
def AND(a: bool, b: bool) -> bool:  return a and b
def OR(a: bool, b: bool) -> bool:   return a or b
def NAND(a: bool, b: bool) -> bool: return not (a and b)
def NOR(a: bool, b: bool) -> bool:  return not (a or b)
def XOR(a: bool, b: bool) -> bool:  return a ^ b
def XNOR(a: bool, b: bool) -> bool: return not (a ^ b)
def IMPLIES(a: bool, b: bool) -> bool: return (not a) or b
def IFF(a: bool, b: bool) -> bool: return a == b


GATES: Dict[str, Tuple[int, Any]] = {
    "NOT":      (1, NOT),
    "AND":      (2, AND),
    "OR":       (2, OR),
    "NAND":     (2, NAND),
    "NOR":      (2, NOR),
    "XOR":      (2, XOR),
    "XNOR":     (2, XNOR),
    "IMPLIES":  (2, IMPLIES),
    "IFF":      (2, IFF),
}


def print_gate_table(name: str) -> None:
    arity, fn = GATES[name]
    for combo in product([False, True], repeat=arity):
        if arity == 1:
            print(f"{name}({int(combo[0])}) = {int(fn(*combo))}")
        else:
            print(f"{name}({int(combo[0])}, {int(combo[1])}) = {int(fn(*combo))}")


# ---------------------------------------------------------------------------
# 2. Combinational circuits
# ---------------------------------------------------------------------------
def half_adder(a: bool, b: bool) -> Tuple[bool, bool]:
    """Return (sum, carry)."""
    return XOR(a, b), AND(a, b)


def full_adder(a: bool, b: bool, cin: bool) -> Tuple[bool, bool]:
    """Return (sum, carry_out)."""
    s1, c1 = half_adder(a, b)
    s, c2 = half_adder(s1, cin)
    return s, OR(c1, c2)


def ripple_carry_adder(a_bits: List[bool], b_bits: List[bool]) -> Tuple[List[bool], bool]:
    """Little-endian bit lists -> (sum bits, final carry)."""
    n = max(len(a_bits), len(b_bits))
    a = a_bits + [False] * (n - len(a_bits))
    b = b_bits + [False] * (n - len(b_bits))
    cin = False
    sums: List[bool] = []
    for i in range(n):
        s, cout = full_adder(a[i], b[i], cin)
        sums.append(s)
        cin = cout
    return sums, cin


def bits_from_int(x: int, width: int) -> List[bool]:
    return [bool((x >> i) & 1) for i in range(width)]


def int_from_bits(bits: List[bool]) -> int:
    v = 0
    for i, b in enumerate(bits):
        if b:
            v |= (1 << i)
    return v


# ---------------------------------------------------------------------------
# 3. Boolean expression language
# ---------------------------------------------------------------------------
@dataclass
class Node:
    pass


@dataclass
class Const(Node):
    value: bool


@dataclass
class Var(Node):
    name: str


@dataclass
class Not(Node):
    operand: Node


@dataclass
class Bin(Node):
    op: str
    left: Node
    right: Node


_KEYWORDS = {"NOT", "AND", "OR", "XOR", "NAND", "NOR",
             "IMPLIES", "IFF", "TRUE", "FALSE"}

_TOKEN_RE = re.compile(
    r'\s*(?P<op>->|<->|&&|\|\||[&|!^~()])'
    r'|(?P<ident>[A-Za-z_][A-Za-z0-9_]*)'
)


class ParseError(Exception):
    pass


def tokenize(s: str) -> List[Tuple[str, Any]]:
    pos = 0
    toks: List[Tuple[str, Any]] = []
    while pos < len(s):
        m = _TOKEN_RE.match(s, pos)
        if not m:
            raise ParseError(f"Unexpected character at {pos}: {s[pos:]!r}")
        pos = m.end()
        if m.group("op") is not None:
            toks.append(("OP", m.group("op")))
        else:
            word = m.group("ident")
            if word.upper() in _KEYWORDS:
                toks.append(("KW", word.upper()))
            else:
                toks.append(("ID", word))
    toks.append(("EOF", None))
    return toks


class Parser:
    def __init__(self, tokens: List[Tuple[str, Any]]):
        self.toks = tokens
        self.i = 0

    def peek(self) -> Tuple[str, Any]:
        return self.toks[self.i]

    def advance(self) -> Tuple[str, Any]:
        t = self.toks[self.i]
        self.i += 1
        return t

    def _val(self) -> Any:
        t = self.peek()
        return t[1] if t[1] is not None else ""

    def parse(self) -> Node:
        node = self.iff()
        if self.peek()[0] != "EOF":
            raise ParseError(f"Trailing tokens: {self.peek()}")
        return node

    # ---- precedence (low -> high): IFF < IMPLIES < OR < XOR < AND < NOT ----
    def iff(self) -> Node:
        node = self.implies()
        while (self.peek()[0] == "KW" and self.peek()[1] == "IFF") or self._val() == "<->":
            self.advance()
            rhs = self.implies()
            node = Bin("IFF", node, rhs)
        return node

    def implies(self) -> Node:
        node = self.or_()
        if (self.peek()[0] == "KW" and self.peek()[1] == "IMPLIES") or self._val() == "->":
            self.advance()
            rhs = self.implies()          # right-associative
            node = Bin("IMPLIES", node, rhs)
        return node

    def or_(self) -> Node:
        node = self.xor()
        while ((self.peek()[0] == "KW" and self.peek()[1] in ("OR", "NOR"))
               or self._val() in ("|", "||")):
            tok = self.advance()
            op = "NOR" if (tok[0] == "KW" and tok[1] == "NOR") else "OR"
            rhs = self.xor()
            node = Bin(op, node, rhs)
        return node

    def xor(self) -> Node:
        node = self.and_()
        while ((self.peek()[0] == "KW" and self.peek()[1] in ("XOR", "XNOR"))
               or self._val() == "^"):
            tok = self.advance()
            op = "XNOR" if (tok[0] == "KW" and tok[1] == "XNOR") else "XOR"
            rhs = self.and_()
            node = Bin(op, node, rhs)
        return node

    def and_(self) -> Node:
        node = self.not_()
        while ((self.peek()[0] == "KW" and self.peek()[1] in ("AND", "NAND"))
               or self._val() in ("&", "&&")):
            tok = self.advance()
            op = "NAND" if (tok[0] == "KW" and tok[1] == "NAND") else "AND"
            rhs = self.not_()
            node = Bin(op, node, rhs)
        return node

    def not_(self) -> Node:
        t = self.peek()
        if (t[0] == "KW" and t[1] == "NOT") or (t[0] == "OP" and t[1] in ("!", "~")):
            self.advance()
            return Not(self.not_())
        return self.primary()

    def primary(self) -> Node:
        t = self.peek()
        if t[0] == "KW" and t[1] in ("TRUE", "FALSE"):
            self.advance()
            return Const(t[1] == "TRUE")
        if t[0] == "ID":
            self.advance()
            return Var(t[1])
        if t[0] == "OP" and t[1] == "(":
            self.advance()
            node = self.iff()
            if not (self.peek()[0] == "OP" and self.peek()[1] == ")"):
                raise ParseError("Expected ')'")
            self.advance()
            return node
        raise ParseError(f"Unexpected token {t}")


def parse(s: str) -> Node:
    return Parser(tokenize(s)).parse()


def evaluate(node: Node, env: Dict[str, bool]) -> bool:
    if isinstance(node, Const):
        return node.value
    if isinstance(node, Var):
        return bool(env[node.name])
    if isinstance(node, Not):
        return not evaluate(node.operand, env)
    if isinstance(node, Bin):
        l = evaluate(node.left, env)
        r = evaluate(node.right, env)
        op = node.op
        if op == "AND":      return l and r
        if op == "OR":       return l or r
        if op == "XOR":      return l ^ r
        if op == "NAND":     return not (l and r)
        if op == "NOR":      return not (l or r)
        if op == "XNOR":     return not (l ^ r)
        if op == "IMPLIES":  return (not l) or r
        if op == "IFF":      return l == r
    raise ValueError(f"Unknown node {node!r}")


def variables(node: Node) -> List[str]:
    out: Set[str] = set()

    def walk(n: Node) -> None:
        if isinstance(n, Var):
            out.add(n.name)
        elif isinstance(n, Const):
            pass
        elif isinstance(n, Not):
            walk(n.operand)
        elif isinstance(n, Bin):
            walk(n.left)
            walk(n.right)

    walk(node)
    return sorted(out)


def truth_table(expr: str) -> None:
    node = parse(expr)
    vs = variables(node)
    width = max(len(v) for v in vs) if vs else 1
    header = "  ".join(v.rjust(width) for v in vs) + "   => " + expr
    print(header)
    print("-" * len(header))
    for combo in product([False, True], repeat=len(vs)):
        env = dict(zip(vs, combo))
        val = evaluate(node, env)
        row = "  ".join(str(int(env[v])).rjust(width) for v in vs)
        print(f"{row}   => {int(val)}")


def classify(expr: str) -> str:
    node = parse(expr)
    vs = variables(node)
    vals = [evaluate(node, dict(zip(vs, combo)))
            for combo in product([False, True], repeat=len(vs))]
    if all(vals):
        return "tautology"
    if not any(vals):
        return "contradiction"
    return "satisfiable (contingent)"


def to_dnf(expr: str) -> str:
    node = parse(expr)
    vs = variables(node)
    terms: List[str] = []
    for combo in product([False, True], repeat=len(vs)):
        env = dict(zip(vs, combo))
        if evaluate(node, env):
            lits = [v if env[v] else f"(NOT {v})" for v in vs]
            terms.append("(" + " AND ".join(lits) + ")")
    return " OR ".join(terms) if terms else "FALSE"


def to_cnf(expr: str) -> str:
    node = parse(expr)
    vs = variables(node)
    clauses: List[str] = []
    for combo in product([False, True], repeat=len(vs)):
        env = dict(zip(vs, combo))
        if not evaluate(node, env):
            lits = [f"(NOT {v})" if env[v] else v for v in vs]
            clauses.append("(" + " OR ".join(lits) + ")")
    return " AND ".join(clauses) if clauses else "TRUE"


# ---------------------------------------------------------------------------
# 4. Demo
# ---------------------------------------------------------------------------
def main() -> None:
    print("=" * 60)
    print("1. Primitive gate tables")
    print("=" * 60)
    for g in ("NOT", "AND", "OR", "XOR", "IMPLIES", "IFF"):
        print_gate_table(g)
        print()

    print("=" * 60)
    print("2. Combinational circuit: ripple-carry addition")
    print("=" * 60)
    for (a, b) in ((5, 3), (7, 7), (10, 6)):
        ab = bits_from_int(a, 4)
        bb = bits_from_int(b, 4)
        sums, carry = ripple_carry_adder(ab, bb)
        result = int_from_bits(sums) + (int(carry) << 4)
        print(f"{a:2d} + {b:2d} = {result:2d}   (4-bit sum={int_from_bits(sums):2d}, carry_out={int(carry)})")
    print()

    print("=" * 60)
    print("3. Expression truth tables")
    print("=" * 60)
    for expr in ("A AND B", "A OR B", "A XOR B", "A -> B", "(A AND B) -> (A OR B)"):
        truth_table(expr)
        print(f"classification: {classify(expr)}\n")

    print("=" * 60)
    print("4. DNF / CNF conversion")
    print("=" * 60)
    expr = "(A AND B) OR (NOT A AND C)"
    print("expr :", expr)
    print("DNF  :", to_dnf(expr))
    print("CNF  :", to_cnf(expr))
    print()

    print("=" * 60)
    print("5. A tautology and a contradiction")
    print("=" * 60)
    for expr in ("A OR (NOT A)", "A AND (NOT A)"):
        print(f"{expr!r}: {classify(expr)}")


if __name__ == "__main__":
    main()
```

### What this gives you

- **Gates** as plain functions operating on Python `bool`s, plus a printable truth table for each.
- **Circuits** built compositionally from gates: `half_adder`, `full_adder`, and a 4-bit ripple-carry adder.
- **An expression mini-language** supporting constants (`TRUE`/`FALSE`), variables, `NOT`, `AND`, `OR`, `XOR`, `NAND`, `NOR`, `XNOR`, `IMPLIES` (`->`), `IFF` (`<->`), with standard precedence and parentheses.
- **Analysis tools**: full truth tables, tautology/contradiction/satisfiability classification, and automatic DNF/CNF generation.

Run it with:

```bash
python boolean_logic.py
```

The script is self-contained, uses only the standard library, and prints gate tables, addition demos, expression truth tables, normal forms, and classifications so you can verify every claim directly.

## Exercise

Build a **TTL + LRU in-memory cache decorator** for pure functions:

- Cache results keyed by the call arguments.
- Entries expire after `ttl` seconds.
- At most `maxsize` entries; evict least-recently-used when full.
- Work for both sync functions and (bonus) async functions.
- Handle the common pitfalls: unhashable args, mutable return values, expired entries left in storage.

---

## Step-by-step solution

### Step 1 — Start with the simplest cache (no TTL, no eviction)

```python
import functools

def simple_cache(func):
    cache = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]

    return wrapper
```

**Problem:** `args` may contain unhashable types (lists/dicts), and there is no expiry or size limit. Also returning the same mutable object twice can cause accidental mutation sharing.

### Step 2 — Make keys robust and cache immutable snapshots

```python
import functools, json

def make_key(args, kwargs):
    # Convert to a JSON-serializable, hashable form.
    def normalize(x):
        if isinstance(x, dict):
            return ("__dict__", tuple(sorted((k, normalize(v)) for k, v in x.items())))
        if isinstance(x, (list, tuple)):
            return ("__seq__", tuple(normalize(i) for i in x))
        if isinstance(x, set):
            return ("__set__", tuple(sorted(normalize(i) for i in x)))
        return x
    return (normalize(args), normalize(kwargs))
```

For mutable return values, deep-copy on store and (optionally) on read, or document that only immutable results are cached.

### Step 3 — Add TTL (time-to-live)

Store `(value, expires_at)` instead of just `value`, and prune on read.

```python
import time

class CacheEntry:
    __slots__ = ("value", "expires_at")
    def __init__(self, value, expires_at):
        self.value = value
        self.expires_at = expires_at
```

### Step 4 — Add LRU eviction

Use `collections.OrderedDict` (or a doubly-linked list + dict). On hit, move to end; on insert when full, pop the first (LRU) item.

```python
from collections import OrderedDict
```

### Step 5 — Thread safety

Guard the cache with a lock (or use `threading.RLock`), especially when the cached function itself is slow.

### Step 6 — Async support

Detect coroutines with `asyncio.iscoroutinefunction`; provide a separate async wrapper that awaits the result.

---

## Final solution

```python
import asyncio
import functools
import threading
import time
from collections import OrderedDict
from copy import deepcopy


def _normalize(obj):
    """Convert an object into a hashable, JSON-friendly form for cache keys."""
    if isinstance(obj, dict):
        return ("__dict__", tuple(sorted((_normalize(k), _normalize(v)) for k, v in obj.items())))
    if isinstance(obj, (list, tuple)):
        return ("__seq__", tuple(_normalize(x) for x in obj))
    if isinstance(obj, set):
        return ("__set__", tuple(sorted(_normalize(x) for x in obj)))
    if isinstance(obj, (int, float, str, bool, bytes, type(None))):
        return obj
    # Fallback: use repr for objects we can't deeply normalize (best effort).
    return ("__repr__", repr(obj))


def _make_key(args, kwargs):
    return (_normalize(args), _normalize(kwargs))


class TTLCache:
    """Thread-safe TTL + LRU cache."""

    def __init__(self, maxsize=128, ttl=60):
        if maxsize <= 0:
            raise ValueError("maxsize must be > 0")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.maxsize = maxsize
        self.ttl = ttl
        self._store = OrderedDict()   # key -> (value, expires_at)
        self._lock = threading.RLock()

    def get(self, key):
        with self._lock:
            item = self._store.get(key)
            if item is None:
                return None, False  # (value, found)
            value, expires_at = item
            if time.monotonic() >= expires_at:
                del self._store[key]
                return None, False
            # Move to end (most recently used).
            self._store.move_to_end(key)
            return deepcopy(value), True

    def set(self, key, value):
        with self._lock:
            expires_at = time.monotonic() + self.ttl
            if key in self._store:
                self._store.move_to_end(key)
            self._store[key] = (deepcopy(value), expires_at)
            while len(self._store) > self.maxsize:
                self._store.popitem(last=False)

    def clear(self):
        with self._lock:
            self._store.clear()


def cache(ttl=60, maxsize=128, copy=True):
    """Decorator factory for sync and async functions."""

    def decorator(func):
        cache_obj = TTLCache(maxsize=maxsize, ttl=ttl)

        if asyncio.iscoroutinefunction(func):
            @functools.wraps(func)
            async def async_wrapper(*args, **kwargs):
                key = _make_key(args, kwargs)
                value, found = cache_obj.get(key)
                if found:
                    return value
                result = await func(*args, **kwargs)
                cache_obj.set(key, result)
                return result if not copy else deepcopy(result)
            async_wrapper.cache = cache_obj
            async_wrapper.cache_clear = cache_obj.clear
            return async_wrapper

        @functools.wraps(func)
        def sync_wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            value, found = cache_obj.get(key)
            if found:
                return value
            result = func(*args, **kwargs)
            cache_obj.set(key, result)
            return result if not copy else deepcopy(result)

        sync_wrapper.cache = cache_obj
        sync_wrapper.cache_clear = cache_obj.clear
        return sync_wrapper

    return decorator


# ---------------- Demo ----------------

@cache(ttl=2, maxsize=3)
def expensive(n):
    print(f"computing for {n}")
    time.sleep(0.5)
    return {"n": n, "square": n * n}


@cache(ttl=2, maxsize=3)
async def async_expensive(n):
    await asyncio.sleep(0.5)
    return n * n


def main():
    print(expensive(4))   # miss -> computes
    print(expensive(4))   # hit -> cached
    r = expensive(4)
    r["square"] = 999     # mutate returned copy; cache unaffected
    print(expensive(4))    # still 16

    expensive.cache_clear()
    print(expensive(4))   # miss again after clear

    async def run():
        print(await async_expensive(7))
        print(await async_expensive(7))

    asyncio.run(run())


if __name__ == "__main__":
    main()
```

### Key points to remember

1. **Always normalize arguments** before hashing; otherwise lists/dicts raise `TypeError: unhashable`.
2. **Store `expires_at` using `time.monotonic()`**, not wall-clock time, to avoid clock jumps causing premature expiry or stale forever.
3. **Evict on read and on write** so expired entries don’t accumulate.
4. **`OrderedDict.move_to_end` + `popitem(last=False)`** gives O(1) LRU semantics.
5. **Deep-copy returned values** to prevent callers from mutating cached state (optional but recommended for mutable types).
6. **Use a lock**; Python dicts are thread-safe for single operations, but combined get-then-set races still happen.
7. For async, provide a separate wrapper—mixing sync and async in one wrapper breaks `await`.

Here is a complete, runnable example that covers the main object-oriented concepts in Python: class attributes, instance attributes, methods, properties, encapsulation, class/staticmethods, inheritance, polymorphism, abstract base classes, special methods (`__str__`, `__repr__`, `__eq__`), and dataclasses.

```python
from __future__ import annotations

import math
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import ClassVar


class Shape(ABC):
    """Abstract base class demonstrating class attributes and abstract methods."""

    _instance_count: ClassVar[int] = 0

    def __init__(self, name: str) -> None:
        self.name = name
        Shape._instance_count += 1

    @abstractmethod
    def area(self) -> float:
        """Subclasses must implement this."""

    @classmethod
    def instance_count(cls) -> int:
        return cls._instance_count

    @staticmethod
    def description() -> str:
        return "A geometric shape"

    def __str__(self) -> str:
        return f"{self.name} ({type(self).__name__})"

    def __repr__(self) -> str:
        return f"{type(self).__name__}(name={self.name!r})"


class Rectangle(Shape):
    def __init__(self, name: str, width: float, height: float) -> None:
        super().__init__(name)
        self.width = width
        self.height = height

    def area(self) -> float:
        return self.width * self.height

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Rectangle):
            return NotImplemented
        return (
            self.name,
            self.width,
            self.height,
        ) == (other.name, other.width, other.height)


class Circle(Shape):
    def __init__(self, name: str, radius: float) -> None:
        super().__init__(name)
        if radius <= 0:
            raise ValueError("radius must be positive")
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2


class BankAccount:
    """Demonstrates encapsulation, properties, and alternate constructors."""

    interest_rate: ClassVar[float] = 0.03

    def __init__(self, owner: str, opening_balance: float = 0.0) -> None:
        if not BankAccount.validate_owner(owner):
            raise ValueError("owner must be a non-empty string")
        if opening_balance < 0:
            raise ValueError("opening balance cannot be negative")

        self.owner = owner
        self.__balance = opening_balance  # name-mangled private attribute

    @property
    def balance(self) -> float:
        return self.__balance

    def deposit(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("deposit amount must be positive")
        self.__balance += amount

    def withdraw(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("withdrawal amount must be positive")
        if amount > self.__balance:
            raise ValueError("insufficient funds")
        self.__balance -= amount

    def apply_interest(self) -> None:
        self.__balance *= 1 + self.interest_rate

    @classmethod
    def from_mapping(cls, data: dict[str, float | str]) -> "BankAccount":
        return cls(str(data["owner"]), float(data["balance"]))

    @staticmethod
    def validate_owner(name: object) -> bool:
        return isinstance(name, str) and bool(name.strip())

    def __str__(self) -> str:
        return f"BankAccount(owner={self.owner!r}, balance={self.balance:.2f})"

    def __repr__(self) -> str:
        return f"BankAccount(owner={self.owner!r}, balance={self.balance!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, BankAccount):
            return NotImplemented
        return (
            self.owner == other.owner
            and abs(self.balance - other.balance) < 1e-9
        )


class Person:
    def __init__(self, name: str, age: int) -> None:
        self.name = name
        self.age = age

    def introduce(self) -> str:
        return f"I am {self.name} and I am {self.age} years old."


class Employee(Person):
    """Demonstrates inheritance, method overriding, and property setters."""

    def __init__(
        self,
        name: str,
        age: int,
        employee_id: int,
        salary: float,
    ) -> None:
        super().__init__(name, age)
        self.employee_id = employee_id
        self._salary = float(salary)

    @property
    def salary(self) -> float:
        return self._salary

    @salary.setter
    def salary(self, value: float) -> None:
        if value < 0:
            raise ValueError("salary cannot be negative")
        self._salary = float(value)

    def give_raise(self, percent: float) -> None:
        if percent <= -1:
            raise ValueError("raise percentage must be greater than -100%")
        self.salary *= 1 + percent

    def introduce(self) -> str:
        return (
            f"{super().introduce()} "
            f"I work as employee #{self.employee_id}."
        )


@dataclass
class Point:
    """Demonstrates the modern dataclass approach."""

    x: float
    y: float
    label: str = "point"
    distance_from_origin: float = field(init=False, repr=False)

    def __post_init__(self) -> None:
        self.distance_from_origin = math.hypot(self.x, self.y)

    def move(self, dx: float, dy: float) -> "Point":
        return Point(self.x + dx, self.y + dy, self.label)


def main() -> None:
    # Abstract base classes and polymorphism
    rect = Rectangle("my rectangle", 4, 5)
    circle = Circle("my circle", 2)

    print("Shapes:", rect, circle)
    print("Areas:", rect.area(), round(circle.area(), 2))
    print("Total shapes created:", Shape.instance_count())
    print("Shape description:", Shape.description())

    # Encapsulation and properties
    account = BankAccount("Alice", 100.0)
    account.deposit(50.0)
    account.withdraw(30.0)
    account.apply_interest()
    print(account)

    duplicate = BankAccount.from_mapping(
        {"owner": "Alice", "balance": account.balance}
    )
    print("Accounts equal?", account == duplicate)
    print("Owner validation:", BankAccount.validate_owner("Bob"))

    # Inheritance and polymorphism
    people: list[Person] = [
        Person("Sam", 30),
        Employee("Dana", 28, 1001, 75000),
    ]

    for person in people:
        print(person.introduce())

    employee = people[1]
    assert isinstance(employee, Employee)
    employee.give_raise(0.10)
    print("Salary after 10% raise:", employee.salary)

    # Dataclass
    point = Point(3, 4, label="A")
    print("Point:", point)
    print("Distance from origin:", point.distance_from_origin)
    print("Moved point:", point.move(1, -1))


if __name__ == "__main__":
    main()
```

### What this demonstrates

- `Shape` is an abstract base class: it cannot be instantiated directly and forces subclasses to implement `area()`.
- `Rectangle` and `Circle` inherit from `Shape`, call `super().__init__()`, and override behavior.
- `BankAccount` uses `__balance`, a name-mangled private attribute, while exposing safe access through the `balance` property.
- `@classmethod` provides alternate constructors such as `from_mapping`.
- `@staticmethod` provides utility functions that do not need instance or class state.
- `Employee` inherits from `Person`, calls `super().introduce()`, overrides `introduce()`, and validates state through a property setter.
- `Point` shows the concise `@dataclass` style, including computed fields via `__post_init__`.
- Special methods make objects print, compare, and represent themselves cleanly.

A “code review practice” is best implemented as a combination of **small, testable units**, **explicit contracts**, and **automated checks**. The example below shows a reviewable Python module, its tests, and a lightweight AST-based reviewer that catches common review issues such as missing docstrings/type hints, long functions, high branch counts, mutable default arguments, broad exception handlers, and stray `print` calls.

## Complete runnable example

Save this as `code_review_example.py` and run it with Python 3.9+:

```python
"""Demonstrates reviewable Python code plus a small automated reviewer."""

from __future__ import annotations

import ast
import inspect
import unittest
from dataclasses import dataclass
from decimal import Decimal
from enum import Enum
from typing import List


# ---------------------------------------------------------------------------
# Reviewable domain code
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class Customer:
    """Immutable customer used for pricing decisions.

    Invariants:
        * ``id`` is non-empty.
        * ``loyalty_points`` is never negative.
    """

    id: str
    loyalty_points: int
    is_premium: bool = False

    def __post_init__(self) -> None:
        if not self.id:
            raise ValueError("customer id must be non-empty")
        if self.loyalty_points < 0:
            raise ValueError("loyalty_points must be >= 0")


def discount_rate(customer: Customer) -> Decimal:
    """Return the discount rate for ``customer`` as a decimal fraction."""
    if customer.is_premium:
        return Decimal("0.20")
    if customer.loyalty_points >= 1_000:
        return Decimal("0.15")
    if customer.loyalty_points >= 500:
        return Decimal("0.10")
    return Decimal("0.00")


def apply_discount(price: Decimal, customer: Customer) -> Decimal:
    """Apply ``customer``'s discount to ``price`` and quantize to cents."""
    if price < 0:
        raise ValueError("price must be non-negative")
    discounted = price * (Decimal("1.00") - discount_rate(customer))
    return discounted.quantize(Decimal("0.01"))


# ---------------------------------------------------------------------------
# Tests: these are part of the reviewable change, not an afterthought.
# ---------------------------------------------------------------------------

class TestPricing(unittest.TestCase):
    def test_premium_customer_gets_twenty_percent(self) -> None:
        customer = Customer(id="p1", loyalty_points=10, is_premium=True)
        self.assertEqual(discount_rate(customer), Decimal("0.20"))

    def test_loyalty_thresholds(self) -> None:
        self.assertEqual(discount_rate(Customer("a", 499)), Decimal("0.00"))
        self.assertEqual(discount_rate(Customer("b", 500)), Decimal("0.10"))
        self.assertEqual(discount_rate(Customer("c", 1_000)), Decimal("0.15"))

    def test_apply_discount_quantizes(self) -> None:
        customer = Customer(id="x", loyalty_points=500)
        self.assertEqual(apply_discount(Decimal("10.00"), customer), Decimal("9.00"))
        self.assertEqual(apply_discount(Decimal("12.345"), customer), Decimal("11.11"))

    def test_invalid_inputs_are_rejected(self) -> None:
        with self.assertRaises(ValueError):
            Customer(id="", loyalty_points=0)
        with self.assertRaises(ValueError):
            Customer(id="x", loyalty_points=-1)
        with self.assertRaises(ValueError):
            apply_discount(Decimal("-1.00"), Customer(id="x", loyalty_points=0))


# ---------------------------------------------------------------------------
# A small automated code-review helper
# ---------------------------------------------------------------------------

class Severity(str, Enum):
    INFO = "INFO"
    WARNING = "WARNING"
    ERROR = "ERROR"


@dataclass(frozen=True)
class Finding:
    filename: str
    line: int
    severity: Severity
    message: str

    def __str__(self) -> str:
        return f"{self.filename}:{self.line} [{self.severity.value}] {self.message}"


class PythonCodeReviewer:
    """A minimal, dependency-free reviewer for educational and CI use."""

    def __init__(self, source: str, filename: str = "<memory>") -> None:
        self.source = source
        self.filename = filename
        self.tree = ast.parse(source)

    def review(self) -> List[Finding]:
        findings: List[Finding] = []

        for func in ast.walk(self.tree):
            if isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
                findings.extend(self._review_function(func))

        for class_node in ast.walk(self.tree):
            if isinstance(class_node, ast.ClassDef) and not ast.get_docstring(class_node):
                findings.append(
                    Finding(
                        self.filename,
                        class_node.lineno,
                        Severity.WARNING,
                        f"class {class_node.name!r} is missing a docstring",
                    )
                )

        for node in ast.walk(self.tree):
            if isinstance(node, ast.ExceptHandler) and node.type is None:
                findings.append(
                    Finding(
                        self.filename,
                        node.lineno,
                        Severity.ERROR,
                        "bare 'except:' hides bugs; catch a specific exception",
                    )
                )

            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "print"
            ):
                findings.append(
                    Finding(
                        self.filename,
                        node.lineno,
                        Severity.INFO,
                        "avoid print() in library code; use logging",
                    )
                )

        findings.sort(key=lambda f: (f.line, f.severity.value))
        return findings

    def _review_function(self, func: ast.FunctionDef | ast.AsyncFunctionDef) -> List[Finding]:
        findings: List[Finding] = []
        name = func.name
        line = func.lineno

        if not ast.get_docstring(func):
            findings.append(
                Finding(
                    self.filename,
                    line,
                    Severity.WARNING,
                    f"function {name!r} is missing a docstring",
                )
            )

        missing = self._missing_annotations(func)
        if missing:
            findings.append(
                Finding(
                    self.filename,
                    line,
                    Severity.WARNING,
                    f"function {name!r} is missing type hints: {', '.join(missing)}",
                )
            )

        length = (func.end_lineno or func.lineno) - func.lineno + 1
        if length > 20:
            findings.append(
                Finding(
                    self.filename,
                    line,
                    Severity.WARNING,
                    f"function {name!r} is {length} lines long; consider splitting it",
                )
            )

        branches = self._branch_count(func)
        if branches > 8:
            findings.append(
                Finding(
                    self.filename,
                    line,
                    Severity.WARNING,
                    f"function {name!r} has {branches} branches; consider simplifying",
                )
            )

        defaults = list(func.args.defaults) + [
            d for d in func.args.kw_defaults if d is not None
        ]
        for default in defaults:
            if isinstance(default, (ast.List, ast.Dict, ast.Set)):
                findings.append(
                    Finding(
                        self.filename,
                        line,
                        Severity.ERROR,
                        f"function {name!r} uses a mutable default argument",
                    )
                )
            if (
                isinstance(default, ast.Call)
                and isinstance(default.func, ast.Name)
                and default.func.id in {"list", "dict", "set"}
            ):
                findings.append(
                    Finding(
                        self.filename,
                        line,
                        Severity.ERROR,
                        f"function {name!r} uses a mutable default argument",
                    )
                )

        return findings

    @staticmethod
    def _missing_annotations(func: ast.FunctionDef | ast.AsyncFunctionDef) -> List[str]:
        missing: List[str] = []

        for arg in (
            func.args.posonlyargs
            + func.args.args
            + func.args.kwonlyargs
        ):
            if arg.arg in {"self", "cls"}:
                continue
            if arg.annotation is None:
                missing.append(arg.arg)

        if func.args.vararg is not None and func.args.vararg.annotation is None:
            missing.append("*" + func.args.vararg.arg)
        if func.args.kwarg is not None and func.args.kwarg.annotation is None:
            missing.append("**" + func.args.kwarg.arg)
        if func.returns is None:
            missing.append("return value")

        return missing

    @staticmethod
    def _branch_count(func: ast.FunctionDef | ast.AsyncFunctionDef) -> int:
        count = 0
        for node in ast.walk(func):
            if isinstance(node, (ast.If, ast.For, ast.AsyncFor, ast.While, ast.Try, ast.With, ast.AsyncWith)):
                count += 1
            elif isinstance(node, ast.BoolOp):
                count += len(node.values) - 1
        return count


def main() -> None:
    # Run tests first; a review should never approve untested behavior.
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestPricing)
    test_result = unittest.TextTestRunner(verbosity=2).run(suite)

    # Review the good example.
    good_snippet = inspect.getsource(discount_rate) + "\n\n" + inspect.getsource(apply_discount)
    good_findings = PythonCodeReviewer(good_snippet, "pricing.py").review()

    print("\nReview of reviewable example:")
    if good_findings:
        for finding in good_findings:
            print(finding)
    else:
        print("No findings. Looks good.")

    # Review a deliberately poor example to show what the reviewer catches.
    bad_code = """
def process(data=[]):
    try:
        for x in data:
            if x > 0 and x < 10 or x == 42:
                print(x)
    except:
        pass
    return data
"""
    bad_findings = PythonCodeReviewer(bad_code, "bad_example.py").review()

    print("\nReview of deliberately poor example:")
    for finding in bad_findings:
        print(finding)

    if not test_result.wasSuccessful():
        raise SystemExit(1)


if __name__ == "__main__":
    main()
```

## Suggested CI configuration

A practical review pipeline usually runs formatting, linting, typing, tests, and security checks before human review:

```yaml
# .github/workflows/ci.yml
name: ci
on: [pull_request]

jobs:
  quality:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: "3.11"
      - run: python -m pip install --upgrade pip
      - run: python -m pip install ruff black mypy pytest bandit
      - run: black --check .
      - run: ruff check .
      - run: mypy .
      - run: pytest -q
      - run: bandit -r .
```

## Review checklist to apply in pull requests

1. **Scope**: Is the diff small enough to review in one sitting?
2. **Correctness**: Are edge cases covered by tests?
3. **Contracts**: Are public functions typed and documented?
4. **Errors**: Are failures explicit and recoverable?
5. **State**: Is mutable/global state avoided or clearly justified?
6. **Security**: Are inputs validated and secrets kept out of code?
7. **Performance**: Are expensive operations obvious and bounded?
8. **Maintainability**: Are names clear and functions single-purpose?
9. **Observability**: Are logs/metrics used instead of `print`?
10. **Backward compatibility**: Are breaking changes documented?

The automated reviewer above is intentionally simple; in production, combine it with mature tools such as `ruff`, `black`, `mypy`, `pytest`, and `bandit`, then use human review for design, naming, and domain correctness.

# Composition Over Inheritance in Python

**Composition** means building objects out of other objects (“has-a”) instead of deriving from base classes (“is-a”). Benefits: looser coupling, runtime flexibility, easier testing, avoids the fragile base class / diamond problems.

## Full runnable example

```python
# composition_over_inheritance.py
"""A complete, runnable demonstration of composition over inheritance."""

from typing import Protocol, Callable, List
from dataclasses import dataclass, field
import random


# ---------------------------------------------------------------------------
# 1. BEHAVIOR INTERFACES (Protocols) — define *capabilities*, not types
# ---------------------------------------------------------------------------
class FlyBehavior(Protocol):
    def fly(self) -> str: ...

class SwimBehavior(Protocol):
    def swim(self) -> str: ...

class WalkBehavior(Protocol):
    def walk(self) -> str: ...

class SoundBehavior(Protocol):
    def make_sound(self) -> str: ...


# ---------------------------------------------------------------------------
# 2. CONCRETE BEHAVIORS — interchangeable strategy objects
# ---------------------------------------------------------------------------
class CanFly:
    def fly(self) -> str:
        return "flapping wings and soaring"

class CannotFly:
    def fly(self) -> str:
        return "cannot fly (wings absent or clipped)"

class SwimsWell:
    def swim(self) -> str:
        return "swimming with webbed feet"

class Sinks:
    def swim(self) -> str:
        return "sinks immediately"

class WalksOnTwoLegs:
    def walk(self) -> str:
        return "walking on two legs"

class WalksOnFourLegs:
    def walk(self) -> str:
        return "walking on four legs"

class Quacks:
    def make_sound(self) -> str:
        return "Quack!"

class Barks:
    def make_sound(self) -> str:
        return "Woof!"

class Silent:
    def make_sound(self) -> str:
        return "(silence)"


# ---------------------------------------------------------------------------
# 3. THE COMPOSED OBJECT — Animal delegates to behaviors it "has"
# ---------------------------------------------------------------------------
@dataclass
class Animal:
    name: str
    fly_behavior: FlyBehavior
    swim_behavior: SwimBehavior
    walk_behavior: WalkBehavior
    sound_behavior: SoundBehavior

    # --- actions delegate to composed behaviors ---
    def fly(self) -> str:
        return f"{self.name}: {self.fly_behavior.fly()}"

    def swim(self) -> str:
        return f"{self.name}: {self.swim_behavior.swim()}"

    def walk(self) -> str:
        return f"{self.name}: {self.walk_behavior.walk()}"

    def speak(self) -> str:
        return f"{self.name}: {self.sound_behavior.make_sound()}"

    # --- runtime flexibility: swap behaviors on the fly ---
    def set_fly_behavior(self, b: FlyBehavior) -> None:
        self.fly_behavior = b

    def set_sound_behavior(self, b: SoundBehavior) -> None:
        self.sound_behavior = b

    def describe(self) -> str:
        return (
            f"{self.name} can: "
            f"fly={self.fly_behavior.fly()!r}, "
            f"swim={self.swim_behavior.swim()!r}, "
            f"walk={self.walk_behavior.walk()!r}, "
            f"sound={self.sound_behavior.make_sound()!r}"
        )


# ---------------------------------------------------------------------------
# 4. FACTORY HELPERS — build common animals without subclassing
# ---------------------------------------------------------------------------
def make_duck(name: str = "Duck") -> Animal:
    return Animal(name, CanFly(), SwimsWell(), WalksOnTwoLegs(), Quacks())

def make_dog(name: str = "Dog") -> Animal:
    return Animal(name, CannotFly(), Sinks(), WalksOnFourLegs(), Barks())

def make_penguin(name: str = "Penguin") -> Animal:
    # Note: a penguin can't fly but swims well — easy to express via composition
    return Animal(name, CannotFly(), SwimsWell(), WalksOnTwoLegs(), Silent())

def make_platypus(name: str = "Platypus") -> Animal:
    return Animal(name, CannotFly(), SwimsWell(), WalksOnFourLegs(), Silent())


# ---------------------------------------------------------------------------
# 5. DEMO
# ---------------------------------------------------------------------------
def main() -> None:
    animals: List[Animal] = [
        make_duck("Donald"),
        make_dog("Rex"),
        make_penguin("Pingu"),
        make_platypus("Perry"),
    ]

    print("=== Capabilities ===")
    for a in animals:
        print(a.describe())

    print("\n=== Actions ===")
    for a in animals:
        print(a.fly())
        print(a.swim())
        print(a.walk())
        print(a.speak())
        print()

    # Runtime behavior swap: a duck that learns to bark (silly but illustrates power)
    print("=== Runtime swap ===")
    donald = animals[0]
    donald.set_sound_behavior(Barks())
    print(donald.speak())          # Donald: Woof!
    donald.set_fly_behavior(CannotFly())
    print(donald.fly())            # Donald: cannot fly...

    # Behaviors are reusable, testable, and don't need an Animal to test
    print("\n=== Testing a behavior in isolation ===")
    fly = CanFly()
    print(fly.fly())


if __name__ == "__main__":
    main()
```

## Why this beats inheritance

| Concern | Inheritance (`class Duck(Bird, Swimmer, Walker)`) | Composition (above) |
|---|---|---|
| Adding a new capability | New mixin / base class → MRO headaches | Add a Protocol + implementation |
| Changing behavior at runtime | Hard / impossible | `set_*_behavior()` |
| Testing | Must instantiate animal | Test behavior objects alone |
| Diamond problem | Real risk (multiple inheritance) | None |
| Reuse across unrelated types | Forced into one hierarchy | Duck and Airplane can both `CanFly` |

## Key take-aways

1. **Program to interfaces (Protocols)**, not concrete classes.
2. **Inject behaviors** via constructor (`Animal(...)`).
3. **Delegate** calls: `Animal.fly` → `self.fly_behavior.fly()`.
4. **Swap at runtime** when state or context changes (e.g., a flightless bird after an injury).
5. Behaviors are **small, single-purpose, independently testable** objects.

## Optional: decorator-based composition (mixin-free)

If you prefer a functional style, the same idea works with callables:

```python
@dataclass
class Robot:
    name: str
    move: Callable[[], str]   # injected behavior
    speak: Callable[[], str]

r = Robot("R2", lambda: "rolls on wheels", lambda: "beep boop")
print(r.move(), r.speak())
```

Run the first file with `python composition_over_inheritance.py` — no external dependencies beyond Python 3.10+ (for `Protocol`/`dataclass` ergonomics; works on 3.8+ with `typing_extensions`).

Composition over inheritance is usually the better default in Python, but it introduces its own failure modes: wiring, delegation, lifecycle, coupling, and object-graph complexity. Below are common pitfalls, with code for each.

---

## 1. Brittle method forwarding

**Pitfall:** You manually forward every method from the composed object. When the component gains a method, the composite silently lacks it.

```python
class Engine:
    def start(self): return "engine started"
    def stop(self): return "engine stopped"
    def diagnostics(self): return {"rpm": 0}  # added later

class Car:
    def __init__(self, engine: Engine):
        self.engine = engine

    def start(self):
        return self.engine.start()

    def stop(self):
        return self.engine.stop()

    # Forgot to forward diagnostics()
```

**Better:** Prefer exposing the component as an attribute (`car.engine.diagnostics()`) or forward only the operations that are genuinely part of the composite’s contract.

```python
class Car:
    def __init__(self, engine: Engine):
        self.engine = engine

    @property
    def diagnostics(self):
        return self.engine.diagnostics
```

---

## 2. Dangerous catch-all `__getattr__` delegation

**Pitfall:** A generic `__getattr__` makes the composite look like the component, but it can hide bugs, forward private attributes, recurse during initialization, and make IDE/type checking worse.

```python
class Wrapper:
    def __init__(self, inner):
        self.inner = inner

    def __getattr__(self, name):
        # BUG: during __init__, before self.inner exists,
        # accessing self.inner calls __getattr__ again -> recursion
        return getattr(self.inner, name)
```

**Better:** If you must delegate dynamically, guard private/internal names and avoid recursion.

```python
class Wrapper:
    def __init__(self, inner):
        self._inner = inner

    def __getattr__(self, name):
        if name.startswith("_"):
            raise AttributeError(name)
        return getattr(self._inner, name)
```

Even better: delegate explicitly or expose the component directly.

---

## 3. Coupling to concrete implementations instead of contracts

**Pitfall:** The composite depends on a concrete class, so swapping implementations for testing or production becomes hard.

```python
class SqlUserRepository:
    def find(self, user_id: int): ...

class UserService:
    def __init__(self, repo: SqlUserRepository):  # concrete
        self.repo = repo
```

**Better:** Depend on a protocol or ABC.

```python
from typing import Protocol

class UserRepository(Protocol):
    def find(self, user_id: int) -> dict: ...

class UserService:
    def __init__(self, repo: UserRepository):
        self.repo = repo
```

This keeps composition flexible without forcing inheritance.

---

## 4. Circular references between composed objects

**Pitfall:** Parent and child hold strong references to each other. This complicates serialization, pickling, garbage collection reasoning, and can cause deep recursion.

```python
class Node:
    def __init__(self, parent=None):
        self.parent = parent
        self.children = []

    def add_child(self, child):
        child.parent = self
        self.children.append(child)
```

**Better:** Use `weakref` for back-references when the child does not own the parent.

```python
import weakref

class Node:
    def __init__(self, parent=None):
        self._parent = weakref.ref(parent) if parent is not None else None
        self.children = []

    @property
    def parent(self):
        return self._parent() if self._parent is not None else None

    def add_child(self, child):
        child._parent = weakref.ref(self)
        self.children.append(child)
```

---

## 5. Unclear resource ownership and lifecycle

**Pitfall:** The composite creates a resource but never defines who closes it. Both caller and composite may close it, or nobody does.

```python
import sqlite3

class ReportGenerator:
    def __init__(self):
        self.conn = sqlite3.connect(":memory:")

    def generate(self):
        return self.conn.execute("SELECT 1").fetchall()

# Connection is never closed.
```

**Better:** Make ownership explicit and use context-manager protocol.

```python
import sqlite3
from contextlib import contextmanager

class ReportGenerator:
    def __init__(self, conn=None):
        self._owns_conn = conn is None
        self.conn = conn or sqlite3.connect(":memory:")

    def generate(self):
        return self.conn.execute("SELECT 1").fetchall()

    def close(self):
        if self._owns_conn:
            self.conn.close()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
```

---

## 6. Duplicating or caching derived state

**Pitfall:** The composite stores a derived value that can drift from the source component.

```python
class PricingService:
    def total(self, items):
        return sum(item.price for item in items)

class Cart:
    def __init__(self, pricing):
        self.pricing = pricing
        self.items = []
        self.total = 0  # stale cache

    def add(self, item):
        self.items.append(item)
        # forgot to update self.total
```

**Better:** Compute derived state from authoritative components.

```python
class Cart:
    def __init__(self, pricing):
        self.pricing = pricing
        self.items = []

    def add(self, item):
        self.items.append(item)

    @property
    def total(self):
        return self.pricing.total(self.items)
```

If caching is needed, invalidate it deliberately or use a cache with clear invalidation rules.

---

## 7. Constructor explosion / object soup

**Pitfall:** Composition can produce constructors with too many collaborators, making objects hard to create and reason about.

```python
class OrderService:
    def __init__(
        self, db, cache, logger, metrics, clock, queue, tax_service,
        inventory_service, payment_gateway, notifier,
    ):
        ...
```

**Better:** Group stable dependencies into a configuration or service bundle, or use a factory/builder. Be careful not to recreate a god object.

```python
from dataclasses import dataclass

@dataclass(frozen=True)
class OrderDependencies:
    db: object
    cache: object
    logger: object
    metrics: object

class OrderService:
    def __init__(self, deps: OrderDependencies, clock, tax_service):
        self.deps = deps
        self.clock = clock
        self.tax_service = tax_service
```

---

## 8. Test pain from too many direct dependencies

**Pitfall:** Every test must construct many mocks even for simple behavior.

```python
def test_calculate_tax():
    service = TaxService(
        db=Mock(), cache=Mock(), logger=Mock(), metrics=Mock(),
        clock=lambda: fixed_time, rates=Mock(),
    )
    ...
```

**Better:** For unit tests, use lightweight fakes or aggregate dependencies. Alternatively, test focused components directly instead of testing the whole composed graph.

```python
class FakeClock:
    def now(self):
        return datetime(2025, 1, 1)

class FakeRates:
    def for_region(self, region):
        return Decimal("0.2")

def test_calculate_tax():
    service = TaxService(clock=FakeClock(), rates=FakeRates())
    assert service.calculate(region="US") == Decimal("20.00")
```

---

## 9. Serialization and pickling failures

**Pitfall:** Composed objects often contain non-serializable components such as locks, sockets, thread pools, or database connections.

```python
import pickle
import threading

class Worker:
    def __init__(self):
        self.lock = threading.Lock()

pickle.dumps(Worker())  # TypeError
```

**Better:** Exclude runtime-only state and reconstruct it lazily.

```python
import pickle
import threading

class Worker:
    def __init__(self):
        self._lock = None

    @property
    def lock(self):
        if self._lock is None:
            self._lock = threading.Lock()
        return self._lock

    def __getstate__(self):
        state = self.__dict__.copy()
        state["_lock"] = None
        return state

    def __setstate__(self, state):
        self.__dict__.update(state)
```

---

## 10. Equality, hashing, and mutability surprises

**Pitfall:** Two composites with identical components may compare unequal by default because Python uses identity. Or, if you make them comparable/hashable incorrectly, mutable components break hashing.

```python
class Line:
    def __init__(self, a, b):
        self.a = a
        self.b = b

Line(Point(0, 0), Point(1, 1)) == Line(Point(0, 0), Point(1, 1))  # False
```

**Better:** Define value equality carefully, and usually disable hashing for mutable composites.

```python
class Line:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def __eq__(self, other):
        if not isinstance(other, Line):
            return NotImplemented
        return self.a == other.a and self.b == other.b

    __hash__ = None  # mutable object: unhashable
```

---

## 11. Hidden global or ambient dependencies

**Pitfall:** Composition becomes meaningless if the composite still reaches out to globals, singletons, or module-level state.

```python
import time

class RetryPolicy:
    def should_retry(self, attempt):
        return time.time() < self.deadline  # hidden global clock
```

**Better:** Inject the dependency explicitly.

```python
class RetryPolicy:
    def __init__(self, clock):
        self.clock = clock

    def should_retry(self, attempt, deadline):
        return self.clock() < deadline
```

This preserves testability and composability.

---

## 12. Mutating shared components accidentally

**Pitfall:** Multiple composites share one component instance. A mutation through one composite unexpectedly affects another.

```python
shared_cache = {}

service_a = UserService(cache=shared_cache)
service_b = AdminService(cache=shared_cache)

service_a.cache["user:1"] = "Alice"
# service_b sees it too, maybe unexpectedly
```

**Better:** Decide ownership explicitly: clone, scope, or clearly document shared mutable state.

```python
class UserService:
    def __init__(self, cache):
        self.cache = cache  # shared by design

# Or, for independent state:
service_a = UserService(cache={})
service_b = AdminService(cache={})
```

---

## Practical checklist

- Expose components as attributes before inventing forwarding methods.
- Use protocols/ABCs, not concrete classes, for composite dependencies.
- Avoid circular references or use `weakref`.
- Define clear resource ownership and context-manager behavior.
- Do not cache derived state unless invalidation is explicit.
- Keep constructors manageable; group dependencies deliberately.
- Use fakes rather than mocks where possible.
- Handle serialization with `__getstate__`/`__setstate__`.
- Define equality/hash semantics intentionally.
- Inject clocks, randomness, configuration, and services instead of using globals.

Composition is most effective when the object graph is explicit, small, and owned by clearly defined boundaries. The main danger is not composition itself, but letting implicit coupling, lifecycle ambiguity, and forwarding boilerplate creep back in.

# Composition Over Inheritance — Practical Exercise & Solution

## Exercise

You are building a small reporting module. Initially it supports:

- Data source: in-memory records.
- Output format: CSV.

Soon you need:
- JSON output,
- data from a JSON file,
- maybe Markdown output later.

**Task:** Refactor so that combining sources and formats does not create a class explosion (e.g. `CsvInMemoryReport`, `JsonFileReport`, …).

---

## Step-by-step solution

### 1. Recognize the anti-pattern

With inheritance, every combination becomes a subclass:

```python
class Report: ...
class CsvReport(Report): ...
class JsonReport(Report): ...
class CsvFileReport(CsvReport): ...
class JsonFileReport(JsonReport): ...
```

This grows as `sources × formats`.

### 2. Identify the two varying behaviors

- **Getting data** → `DataSource`
- **Formatting data** → `Formatter`

These are independent, so compose them into a `Report`.

### 3. Define protocols (interfaces)

```python
from typing import Protocol, List, Dict, Any
import csv, io, json


class DataSource(Protocol):
    def get_data(self) -> List[Dict[str, Any]]:
        """Return records as list of dictionaries."""
        ...


class Formatter(Protocol):
    def format(self, data: List[Dict[str, Any]]) -> str:
        """Convert records into a string representation."""
        ...
```

### 4. Implement concrete sources and formatters

```python
class InMemoryDataSource:
    def __init__(self, records: List[Dict[str, Any]]):
        self._records = [dict(r) for r in records]

    def get_data(self) -> List[Dict[str, Any]]:
        return self._records


class JsonFileDataSource:
    def __init__(self, path: str):
        self.path = path

    def get_data(self) -> List[Dict[str, Any]]:
        with open(self.path, "r", encoding="utf-8") as f:
            return json.load(f)


class CsvFormatter:
    def format(self, data: List[Dict[str, Any]]) -> str:
        if not data:
            return ""
        buffer = io.StringIO()
        writer = csv.DictWriter(buffer, fieldnames=list(data[0].keys()))
        writer.writeheader()
        writer.writerows(data)
        return buffer.getvalue().rstrip("\r\n")


class JsonFormatter:
    def __init__(self, indent: int = 2):
        self.indent = indent

    def format(self, data: List[Dict[str, Any]]) -> str:
        return json.dumps(data, indent=self.indent, ensure_ascii=False)
```

### 5. Compose in `Report`

```python
class Report:
    def __init__(self, source: DataSource, formatter: Formatter):
        self.source = source
        self.formatter = formatter

    def generate(self) -> str:
        data = self.source.get_data()
        return self.formatter.format(data)
```

### 6. Use any combination without new classes

```python
records = [
    {"name": "Alice", "score": 90},
    {"name": "Bob", "score": 82},
]

# In-memory + CSV
report = Report(InMemoryDataSource(records), CsvFormatter())
print(report.generate())

# In-memory + JSON
report = Report(InMemoryDataSource(records), JsonFormatter(indent=4))
print(report.generate())
```

### 7. Extensibility proof: add Markdown without touching `Report`

```python
class MarkdownTableFormatter:
    def format(self, data: List[Dict[str, Any]]) -> str:
        if not data:
            return ""
        headers = list(data[0].keys())
        lines = [
            "| " + " | ".join(headers) + " |",
            "| " + " | ".join(["---"] * len(headers)) + " |",
        ]
        for row in data:
            lines.append("| " + " | ".join(str(row[h]) for h in headers) + " |")
        return "\n".join(lines)


report = Report(InMemoryDataSource(records), MarkdownTableFormatter())
print(report.generate())
```

No changes to `Report`, `DataSource`, or `Formatter` contracts.

---

## Final solution (copy-paste runnable)

```python
from typing import Protocol, List, Dict, Any
import csv, io, json


class DataSource(Protocol):
    def get_data(self) -> List[Dict[str, Any]]: ...

class Formatter(Protocol):
    def format(self, data: List[Dict[str, Any]]) -> str: ...


class InMemoryDataSource:
    def __init__(self, records: List[Dict[str, Any]]):
        self._records = [dict(r) for r in records]

    def get_data(self) -> List[Dict[str, Any]]:
        return self._records


class JsonFileDataSource:
    def __init__(self, path: str):
        self.path = path

    def get_data(self) -> List[Dict[str, Any]]:
        with open(self.path, "r", encoding="utf-8") as f:
            return json.load(f)


class CsvFormatter:
    def format(self, data: List[Dict[str, Any]]) -> str:
        if not data:
            return ""
        buffer = io.StringIO()
        writer = csv.DictWriter(buffer, fieldnames=list(data[0].keys()))
        writer.writeheader()
        writer.writerows(data)
        return buffer.getvalue().rstrip("\r\n")


class JsonFormatter:
    def __init__(self, indent: int = 2):
        self.indent = indent

    def format(self, data: List[Dict[str, Any]]) -> str:
        return json.dumps(data, indent=self.indent, ensure_ascii=False)


class Report:
    def __init__(self, source: DataSource, formatter: Formatter):
        self.source = source
        self.formatter = formatter

    def generate(self) -> str:
        return self.formatter.format(self.source.get_data())


if __name__ == "__main__":
    records = [{"name": "Alice", "score": 90}, {"name": "Bob", "score": 82}]
    print(Report(InMemoryDataSource(records), CsvFormatter()).generate())
    print()
    print(Report(InMemoryDataSource(records), JsonFormatter(indent=4)).generate())
```

### Why this is composition over inheritance
- `Report` **has-a** source and **has-a** formatter instead of **is-a** variant.
- New behaviors are added by new small classes, not by multiplying subclasses.
- You can swap implementations at runtime (e.g., choose formatter from config) with no code changes in `Report`.

## Composition over inheritance (Python)

**Core idea:** Build complex behavior by **combining objects** (has-a relationships) instead of creating deep class hierarchies (is-a relationships).

### Why it’s preferred (interview bullets)
- **Flexibility:** swap behaviors at runtime.
- **Loose coupling:** components depend on small interfaces, not giant base classes.
- **Testability:** mock components independently.
- **Avoids “god base classes”** and fragile hierarchies (e.g., `FlyingSwimmingWalkingDuck`).

### Tiny example: bad vs good

**Bad (inheritance):**
```python
class Animal:
    def move(self): ...
    def speak(self): ...

class Duck(Animal):
    def move(self): return "swim"
    def speak(self): return "quack"

class Penguin(Animal):
    def move(self): return "waddle"
    def speak(self): return "honk"
# Problem: if you need a duck that walks, you either override move or add a mixin → hierarchy sprawl.
```

**Good (composition):**
```python
from dataclasses import dataclass
from typing import Protocol

class MoveBehavior(Protocol):
    def move(self) -> str: ...

class SpeakBehavior(Protocol):
    def speak(self) -> str: ...

@dataclass
class Swim:
    def move(self) -> str: return "swim"

@dataclass
class Waddle:
    def move(self) -> str: return "waddle"

@dataclass
class Quack:
    def speak(self) -> str: return "quack"

@dataclass
class Honk:
    def speak(self) -> str: return "honk"

class Animal:
    def __init__(self, move: MoveBehavior, speak: SpeakBehavior):
        self.move_behavior = move
        self.speak_behavior = speak

    def move(self) -> str:
        return self.move_behavior.move()

    def speak(self) -> str:
        return self.speak_behavior.speak()

    # Runtime flexibility
    def set_move(self, move: MoveBehavior) -> None:
        self.move_behavior = move

# Usage
duck = Animal(Swim(), Quack())
print(duck.move(), duck.speak())   # swim quack

# Swap behavior at runtime
duck.set_move(Waddle())
print(duck.move())  # waddle
```

### “Core” implementation (clean, commented)

```python
from dataclasses import dataclass
from typing import Protocol, runtime_checkable

# ------------------------------------------------------------
# 1. Define small behavior contracts (interfaces via Protocol)
# ------------------------------------------------------------
@runtime_checkable
class Mover(Protocol):
    """Anything that can produce a movement description."""
    def move(self) -> str: ...

@runtime_checkable
class Speaker(Protocol):
    """Anything that can produce a vocalization."""
    def speak(self) -> str: ...

# ------------------------------------------------------------
# 2. Concrete behaviors (leaf components)
# ------------------------------------------------------------
@dataclass(frozen=True)
class Fly:
    def move(self) -> str:
        return "fly"

@dataclass(frozen=True)
class Swim:
    def move(self) -> str:
        return "swim"

@dataclass(frozen=True)
class Waddle:
    def move(self) -> str:
        return "waddle"

@dataclass(frozen=True)
class Quack:
    def speak(self) -> str:
        return "quack"

@dataclass(frozen=True)
class Honk:
    def speak(self) -> str:
        return "honk"

# ------------------------------------------------------------
# 3. The composed object delegates to components
# ------------------------------------------------------------
class Animal:
    """
    An animal is built from behaviors, not from a base class.
    All behavior comes through composition.
    """
    def __init__(self, mover: Mover, speaker: Speaker) -> None:
        self._mover = mover
        self._speaker = speaker

    # Public API delegates to components (no inherited logic)
    def move(self) -> str:
        return self._mover.move()

    def speak(self) -> str:
        return self._speaker.speak()

    # Runtime composition: change behavior without subclassing
    def change_mover(self, mover: Mover) -> None:
        if not isinstance(mover, Mover):
            raise TypeError("mover must implement Mover protocol")
        self._mover = mover

    def change_speaker(self, speaker: Speaker) -> None:
        if not isinstance(speaker, Speaker):
            raise TypeError("speaker must implement Speaker protocol")
        self._speaker = speaker

# ------------------------------------------------------------
# 4. Usage / demonstration
# ------------------------------------------------------------
if __name__ == "__main__":
    duck = Animal(mover=Swim(), speaker=Quack())
    print(duck.move(), duck.speak())   # swim quack

    # Runtime swap: duck becomes a walking duck
    duck.change_mover(Waddle())
    print(duck.move(), duck.speak())   # waddle quack

    penguin = Animal(mover=Waddle(), speaker=Honk())
    print(penguin.move(), penguin.speak())  # waddle honk
```

### Interview talking points
- **“Is-a” vs “Has-a”:** composition = has-a; inheritance = is-a.
- **When to use inheritance:** truly stable taxonomies (e.g., `list` subclasses) or framework hooks.
- **When to avoid:** behavioral variation, optional capabilities, cross-cutting concerns.
- **Python specifics:** `Protocol` (structural typing) makes composition feel natural; dataclasses keep components lightweight.

