Below is a complete, runnable Python example of an in-memory relational table with multiple index types, index selection in a mini query planner, and a performance benchmark compared with `sqlite3`.

It demonstrates:

- `HashIndex` for equality lookups
- `OrderedIndex` (sorted-entry index, the in-memory analogue of a B-tree range index) for ranges, prefix scans, and ordered scans
- Composite keys, `UNIQUE` constraints, partial indexes, and covering indexes
- A small query executor with index selection (`EXPLAIN`-style plan)
- Concurrency via `RLock`
- A benchmark plus a comparison to real SQLite index behavior

Save as `indexes_demo.py` and run with `python indexes_demo.py`.

```python
"""In-memory database indexes in pure Python.

This is an educational but complete implementation.  Production databases
store ordered indexes as B+/B-trees on disk; here the ordered index is a
sorted array of entries (logarithmic search, linear insert) so the file
stays self-contained and dependency-free.
"""

from __future__ import annotations

import bisect
import os
import pickle
import sqlite3
import threading
import time
from dataclasses import dataclass
from typing import Any, Callable, Iterable, Optional


# --------------------------------------------------------------------------- #
# Ordering sentinels
# --------------------------------------------------------------------------- #
class _Null:
    """SQL NULL with a stable sort position (NULLs first)."""

    def __eq__(self, other):
        return isinstance(other, _Null)

    def __lt__(self, other):
        return not isinstance(other, _Null)

    def __le__(self, other):
        return True

    def __gt__(self, other):
        return False

    def __ge__(self, other):
        return isinstance(other, _Null)

    def __hash__(self):
        return 0

    def __repr__(self):
        return "NULL"


_NULL = _Null()


class _NegInf:
    def __lt__(self, other):
        return True

    def __le__(self, other):
        return True

    def __gt__(self, other):
        return False

    def __ge__(self, other):
        return isinstance(other, _NegInf)

    def __eq__(self, other):
        return isinstance(other, _NegInf)


class _PosInf:
    def __lt__(self, other):
        return False

    def __le__(self, other):
        return isinstance(other, _PosInf)

    def __gt__(self, other):
        return True

    def __ge__(self, other):
        return True

    def __eq__(self, other):
        return isinstance(other, _PosInf)


_NEFINF = _NegInf()
_POSINF = _PosInf()

MIN_ROWID_BOUND = -1
MAX_ROWID_BOUND = 10**9

# --------------------------------------------------------------------------- #
# Index entry container
# --------------------------------------------------------------------------- #
@dataclass(order=True)
class _Entry:
    """A single ordered-index entry.  Sorted by (key, rowid)."""

    key: tuple
    rowid: int


# --------------------------------------------------------------------------- #
# Base index
# --------------------------------------------------------------------------- #
class IntegrityError(Exception):
    pass


class BaseIndex:
    def __init__(
        self,
        name: str,
        columns: Iterable[str],
        unique: bool = False,
        include: Iterable[str] = (),
        predicate: Optional[Callable[[dict], bool]] = None,
    ):
        self.name = name
        self.columns = tuple(columns)
        self.unique = unique
        self.include = tuple(include)
        self.predicate = predicate
        self.covering_cols = self.columns + self.include
        self._payloads: dict[int, dict] = {}  # rowid -> covering values
        self._lock = threading.RLock()

    # ---------------- helpers ---------------- #
    def applies(self, row: dict) -> bool:
        return self.predicate is None or bool(self.predicate(row))

    def _norm(self, value: Any) -> Any:
        if value is None:
            return _NULL
        if isinstance(value, (_Null, _NegInf, _PosInf)):
            return value
        return value

    def key_for(self, row: dict) -> tuple:
        return tuple(self._norm(row.get(c)) for c in self.columns)

    def normalize_input(self, key: Any) -> Optional[tuple]:
        if key is None:
            return None
        if isinstance(key, (list, tuple)):
            vals = list(key)
        else:
            vals = [key]
        return tuple(self._norm(v) for v in vals)

    def payload_for(self, row: dict) -> dict:
        # Stores every column this index can "cover".
        return {c: row.get(c) for c in self.covering_cols}

    # ---------------- public API ---------------- #
    def insert(self, row: dict, rowid: int) -> None:
        if not self.applies(row):
            return
        key = self.key_for(row)
        with self._lock:
            if self.unique and self._contains(key):
                raise IntegrityError(
                    f"UNIQUE violation on index '{self.name}' for key {key!r}"
                )
            self._insert(key, rowid)
            self._payloads[rowid] = self.payload_for(row)

    def delete(self, rowid: int) -> None:
        with self._lock:
            if rowid not in self._payloads:
                return
            self._delete(rowid)
            self._payloads.pop(rowid, None)

    def update_row(self, old_row: dict, new_row: dict, rowid: int) -> None:
        # convenience: delete then insert (used by Table.update)
        self.delete(rowid)
        self.insert(new_row, rowid)

    def contains_key(self, key: Any) -> bool:
        with self._lock:
            return self._contains(self.normalize_input(key))

    def _contains(self, key: Optional[tuple]) -> bool:
        if key is None:
            return False
        return len(self.lookup(key)) > 0

    def is_covering_for(self, columns: Optional[Iterable[str]]) -> bool:
        if not columns:
            return False
        return set(columns).issubset(set(self.covering_cols))

    def payload(self, rowid: int) -> Optional[dict]:
        return self._payloads.get(rowid)

    # ---------------- abstract-ish ---------------- #
    def _insert(self, key: tuple, rowid: int) -> None:
        raise NotImplementedError

    def _delete(self, rowid: int) -> None:
        raise NotImplementedError

    def lookup(self, key: Any) -> list[int]:
        """Equality lookup. Return rowids (empty list if none)."""
        raise NotImplementedError

    def range_scan(
        self,
        lo: Any = None,
        hi: Any = None,
        lo_inclusive: bool = True,
        hi_inclusive: bool = True,
    ) -> list[int]:
        raise NotImplementedError

    def all_rowids(self) -> list[int]:
        raise NotImplementedError

    @property
    def type_name(self) -> str:
        return self.__class__.__name__


# --------------------------------------------------------------------------- #
# Hash index
# --------------------------------------------------------------------------- #
class HashIndex(BaseIndex):
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self._buckets: dict[tuple, set[int]] = {}
        self._key_of: dict[int, tuple] = {}

    def _insert(self, key: tuple, rowid: int) -> None:
        self._buckets.setdefault(key, set()).add(rowid)
        self._key_of[rowid] = key

    def _delete(self, rowid: int) -> None:
        key = self._key_of.pop(rowid, None)
        if key is None:
            return
        bucket = self._buckets.get(key)
        if bucket is None:
            return
        bucket.discard(rowid)
        if not bucket:
            del self._buckets[key]

    def lookup(self, key: Any) -> list[int]:
        nk = self.normalize_input(key)
        if nk is None:
            return []
        # Hash index supports equality on the FULL key only.
        if len(nk) < len(self.columns):
            return []  # signal: not usable for this partial key
        # Allow extra provided values? pad/truncate to index width.
        nk = nk[: len(self.columns)]
        with self._lock:
            return sorted(self._buckets.get(nk, ()))

    def range_scan(self, *a, **k) -> list[int]:  # not supported
        return []

    def all_rowids(self) -> list[int]:
        with self._lock:
            out: list[int] = []
            for s in self._buckets.values():
                out.extend(s)
            return sorted(set(out))

    @property
    def type_name(self) -> str:
        return "hash"


# --------------------------------------------------------------------------- #
# Ordered (sorted-array) index
# --------------------------------------------------------------------------- #
class OrderedIndex(BaseIndex):
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self._entries: list[_Entry] = []

    def _insert(self, key: tuple, rowid: int) -> None:
        bisect.insort(self._entries, _Entry(key, rowid))

    def _delete(self, rowid: int) -> None:
        self._entries = [e for e in self._entries if e.rowid != rowid]

    def _bounds_for(self, nk: tuple) -> tuple[_Entry, _Entry]:
        """Entries with key == nk occupy [left, right)."""
        left = bisect.bisect_left(self._entries, _Entry(nk, MIN_ROWID_BOUND))
        right = bisect.bisect_left(self._entries, _Entry(nk, MAX_ROWID_BOUND))
        return left, right

    def lookup(self, key: Any) -> list[int]:
        nk = self.normalize_input(key)
        if nk is None:
            return []
        n = len(self.columns)
        with self._lock:
            if len(nk) == n:
                left, right = self._bounds_for(nk)
                return [e.rowid for e in self._entries[left:right]]
            # prefix equality -> range scan over all keys starting with nk
            if 0 < len(nk) < n:
                lo_key = nk + (_NEFINF,) * (n - len(nk))
                hi_key = nk + (_POSINF,) * (n - len(nk))
                left = bisect.bisect_left(self._entries, _Entry(lo_key, MIN_ROWID_BOUND))
                right = bisect.bisect_left(self._entries, _Entry(hi_key, MIN_ROWID_BOUND))
                return [e.rowid for e in self._entries[left:right]]
            return []

    def range_scan(
        self,
        lo: Any = None,
        hi: Any = None,
        lo_inclusive: bool = True,
        hi_inclusive: bool = True,
    ) -> list[int]:
        n = len(self.columns)
        with self._lock:
            if lo is None:
                left = 0
            else:
                vals = lo if isinstance(lo, (tuple, list)) else (lo,)
                vals = list(vals) + [_NEFINF] * (n - len(vals))
                lo_key = tuple(self._norm(v) for v in vals)
                if lo_inclusive:
                    left = bisect.bisect_left(self._entries, _Entry(lo_key, MIN_ROWID_BOUND))
                else:
                    left = bisect.bisect_right(self._entries, _Entry(lo_key, MAX_ROWID_BOUND))

            if hi is None:
                right = len(self._entries)
            else:
                vals = hi if isinstance(hi, (tuple, list)) else (hi,)
                vals = list(vals) + [_POSINF] * (n - len(vals))
                hi_key = tuple(self._norm(v) for v in vals)
                if hi_inclusive:
                    right = bisect.bisect_right(self._entries, _Entry(hi_key, MAX_ROWID_BOUND))
                else:
                    right = bisect.bisect_left(self._entries, _Entry(hi_key, MIN_ROWID_BOUND))

            left = max(0, min(left, len(self._entries)))
            right = max(0, min(right, len(self._entries)))
            return [e.rowid for e in self._entries[left:right]]

    def all_rowids(self) -> list[int]:
        with self._lock:
            return [e.rowid for e in self._entries]

    @property
    def type_name(self) -> str:
        return "ordered"


# --------------------------------------------------------------------------- #
# Table
# --------------------------------------------------------------------------- #
class Table:
    def __init__(self, name: str, columns: Optional[Iterable[str]] = None):
        self.name = name
        self.columns = list(columns) if columns else []
        self.rows: list[Optional[dict]] = []
        self.indexes: dict[str, BaseIndex] = {}
        self._lock = threading.RLock()

    # ---------------- rows ---------------- #
    def insert(self, row: dict) -> int:
        with self._lock:
            rid = len(self.rows)
            r = dict(row)
            r["_rowid"] = rid
            self.rows.append(r)
            for idx in self.indexes.values():
                idx.insert(r, rid)
            return rid

    def bulk_insert(self, rows: Iterable[dict]) -> list[int]:
        return [self.insert(r) for r in rows]

    def get(self, rowid: int) -> Optional[dict]:
        with self._lock:
            return self.rows[rowid]

    def update(self, rowid: int, changes: dict) -> None:
        with self._lock:
            old = self.rows[rowid]
            if old is None:
                raise KeyError(f"row {rowid} does not exist")
            new = dict(old)
            new.update(changes)
            for idx in self.indexes.values():
                idx.delete(rowid)
            self.rows[rowid] = new
            for idx in self.indexes.values():
                idx.insert(new, rowid)

    def delete(self, rowid: int) -> None:
        with self._lock:
            if self.rows[rowid] is None:
                return
            for idx in self.indexes.values():
                idx.delete(rowid)
            self.rows[rowid] = None

    def live_rowids(self) -> list[int]:
        with self._lock:
            return [i for i, r in enumerate(self.rows) if r is not None]

    # ---------------- indexes ---------------- #
    def create_index(
        self,
        name: str,
        columns: Iterable[str],
        type: str = "ordered",  # "hash" | "ordered"
        unique: bool = False,
        include: Iterable[str] = (),
        predicate: Optional[Callable[[dict], bool]] = None,
    ) -> BaseIndex:
        with self._lock:
            if name in self.indexes:
                raise ValueError(f"index '{name}' already exists")
            cols = tuple(columns)
            if type == "hash":
                idx = HashIndex(name, cols, unique=unique, include=include, predicate=predicate)
            elif type == "ordered":
                idx = OrderedIndex(name, cols, unique=unique, include=include, predicate=predicate)
            else:
                raise ValueError(f"unknown index type {type!r}")
            # bulk-populate
            for rid, row in enumerate(self.rows):
                if row is not None:
                    idx.insert(row, rid)
            self.indexes[name] = idx
            return idx

    def drop_index(self, name: str) -> None:
        with self._lock:
            if name not in self.indexes:
                raise KeyError(name)
            del self.indexes[name]

    # ---------------- persistence (optional) ---------------- #
    def save(self, path: str) -> None:
        with self._lock:
            with open(path, "wb") as f:
                pickle.dump({"name": self.name, "columns": self.columns,
                             "rows": self.rows}, f)

    @classmethod
    def load(cls, path: str) -> "Table":
        with open(path, "rb") as f:
            data = pickle.load(f)
        t = cls(data["name"], data["columns"])
        t.rows = data["rows"]
        return t


# --------------------------------------------------------------------------- #
# Query helpers
# --------------------------------------------------------------------------- #
def _parse_where(where) -> list[tuple]:
    if where is None:
        return []
    if callable(where):
        return [("__callable__", None, where)]
    out = []
    for k, v in where.items():
        if "__" in k:
            col, op = k.split("__", 1)
        else:
            col, op = k, "eq"
        out.append((col, op, v))
    return out


def _eval_cond(row: dict, col: str, op: str, val: Any) -> bool:
    v = row.get(col)
    if op == "eq":
        return v == val
    if op == "ne":
        return v != val
    if op == "gt":
        return v is not None and v > val
    if op == "gte":
        return v is not None and v >= val
    if op == "lt":
        return v is not None and v < val
    if op == "lte":
        return v is not None and v <= val
    if op == "in":
        return v in val
    if op == "between":
        lo, hi = val
        return v is not None and lo <= v <= hi
    if op == "is":
        return (v is None) == (val is None)
    raise ValueError(f"unknown operator {op!r}")


def _matches(row: dict, conds: list[tuple]) -> bool:
    for col, op, val in conds:
        if col == "__callable__":
            if not val(row):
                return False
            continue
        if not _eval_cond(row, col, op, val):
            return False
    return True


def _choose_index(table: Table, conds: list[tuple]):
    """Return (index_name, index_obj, mode) or (None, None, 'scan')."""
    eq_cols = {c for (c, o, _) in conds if o == "eq" and c != "__callable__"}
    range_cols = {(c, o) for (c, o, _) in conds
                  if o in ("gt", "gte", "lt", "lte", "between")}

    # 1) best hash/ordered index fully covered by equality columns
    best_eq = None
    for name, idx in table.indexes.items():
        if set(idx.columns).issubset(eq_cols):
            score = (len(idx.columns), 1 if idx.type_name == "hash" else 0)
            if best_eq is None or score > best_eq[0]:
                best_eq = (score, name, idx)
    if best_eq is not None:
        return best_eq[1], best_eq[2], "eq"

    # 2) ordered index with equality prefix + (optional) range on next column
    best_ord = None
    for name, idx in table.indexes.items():
        if not isinstance(idx, OrderedIndex):
            continue
        prefix = 0
        for col in idx.columns:
            if col in eq_cols:
                prefix += 1
            else:
                break
        target = idx.columns[prefix] if prefix < len(idx.columns) else None
        has_range = target is not None and any(rc[0] == target for rc in range_cols)
        if prefix > 0 or has_range:
            score = (prefix, int(has_range), len(idx.columns))
            if best_ord is None or score > best_ord[0]:
                best_ord = (score, name, idx, prefix, target, has_range)
    if best_ord is not None:
        return best_ord[1], best_ord[2], ("range" if best_ord[5] else "prefix")

    return None, None, "scan"


def _index_rowids(table, idx, mode, conds) -> list[int]:
    eq_map = {c: v for (c, o, v) in conds if o == "eq" and c != "__callable__"}
    range_list = [(c, o, v) for (c, o, v) in conds
                  if o in ("gt", "gte", "lt", "lte", "between")]

    if mode == "eq":
        key = tuple(eq_map[c] for c in idx.columns)
        return idx.lookup(key)

    # ordered prefix / range
    assert isinstance(idx, OrderedIndex)
    # equality prefix columns
    prefix = []
    for col in idx.columns:
        if col in eq_map:
            prefix.append(col)
        else:
            break
    target = idx.columns[len(prefix)] if len(prefix) < len(idx.columns) else None
    rc = None
    if target is not None:
        rc = next((r for r in range_list if r[0] == target), None)

    if rc is None:
        # pure prefix scan
        if prefix:
            lo = tuple(eq_map[c] for c in prefix)
            return idx.range_scan(lo=lo, hi=lo)
        # leading range only
        if range_list:
            c, op, val = range_list[0]
            if c != idx.columns[0]:
                return idx.all_rowids()
            if op == "between":
                return idx.range_scan(lo=val[0], hi=val[1], lo_inclusive=True, hi_inclusive=True)
            inc_lo = op in ("gt", "gte")  # unused placeholder
            # handle single bound
            if op in ("gt", "gte"):
                return idx.range_scan(lo=val, lo_inclusive=(op == "gte"))
            if op in ("lt", "lte"):
                return idx.range_scan(hi=val, hi_inclusive=(op == "lte"))
        return idx.all_rowids()

    c, op, val = rc
    lo = None
    hi = None
    lo_inc = True
    hi_inc = True
    if op == "between":
        lo, hi = val
        lo_inc = hi_inc = True
    elif op in ("gt", "gte"):
        lo = val
        lo_inc = (op == "gte")
    elif op in ("lt", "lte"):
        hi = val
        hi_inc = (op == "lte")

    # combine with equality prefix for bounds
    if prefix:
        pre = tuple(eq_map[col] for col in prefix)
        if lo is not None:
            lo = pre + (lo,) if not isinstance(lo, (tuple, list)) else pre + tuple(lo)
        if hi is not None:
            hi = pre + (hi,) if not isinstance(hi, (tuple, list)) else pre + tuple(hi)
        # if only one bound provided, keep prefix equality on the other side
        if lo is None and prefix:
            lo = pre
            lo_inc = True
            # force scan of whole prefix requires hi bound posinf; range_scan handles None
        if hi is None and prefix and lo is not None:
            hi = None
    # If we only had equality prefix and no range bound on one side, range_scan(None) covers rest.

    # Special case: prefix-only scan (lo==hi==prefix) handled by None bounds above.
    if lo is None and hi is None:
        return idx.all_rowids()
    return idx.range_scan(lo=lo, hi=hi, lo_inclusive=lo_inc, hi_inclusive=hi_inc)


def select(
    table: Table,
    where=None,
    columns: Optional[Iterable[str]] = None,
    order_by: Optional[Iterable[str]] = None,
    limit: Optional[int] = None,
    explain: bool = False,
) -> Any:
    columns = list(columns) if columns is not None else None
    order_by = list(order_by) if order_by else None
    conds = _parse_where(where)

    with table._lock:
        idx_name, idx, mode = _choose_index(table, conds)
        plan = {
            "table": table.name,
            "access": "INDEX" if idx is not None else "FULL SCAN",
            "index": idx_name,
            "mode": mode if idx is not None else None,
            "covering": False,
        }

        if idx is not None:
            rowids = _index_rowids(table, idx, mode, conds)
            # ordered index returns sorted-by-key order; remember for ORDER BY
            index_ordered = (
                isinstance(idx, OrderedIndex)
                and order_by is not None
                and order_by == list(idx.columns)
            )
            covering = idx.is_covering_for(columns)
            plan["covering"] = covering
        else:
            rowids = table.live_rowids()
            index_ordered = False

        # residual filtering
        result_rows = []
        callable_pred = None
        for c in conds:
            if c[0] == "__callable__":
                callable_pred = c[2]
        for rid in rowids:
            row = table.rows[rid]
            if row is None:
                continue
            if not _matches(row, conds):
                continue
            if callable_pred is not None and not callable_pred(row):
                continue

            # build output
            if columns is None:
                out = dict(row)
                out.pop("_rowid", None)
            else:
                if (idx is not None and plan["covering"]
                        and rid in idx._payloads):
                    payload = idx._payloads[rid]
                    out = {}
                    for c in columns:
                        if c in payload:
                            out[c] = payload[c]
                        else:
                            # key column stored in entry key; fetch from row anyway
                            out[c] = row.get(c)
                else:
                    out = {c: row.get(c) for c in columns}
            out["_rowid"] = rid
            result_rows.append(out)

        if order_by and not index_ordered:
            result_rows.sort(key=lambda r: tuple(r.get(c) for c in order_by))
        if limit is not None:
            result_rows = result_rows[:limit]

        if explain:
            plan["rows_returned"] = len(result_rows)
            plan["candidates"] = len(rowids)
            return {"plan": plan, "rows": result_rows}
        return result_rows


# --------------------------------------------------------------------------- #
# Pretty printing helpers
# --------------------------------------------------------------------------- #
def show_plan(plan):
    print(f"  access path : {plan['access']}")
    print(f"  index       : {plan['index']}")
    print(f"  mode        : {plan['mode']}")
    print(f"  candidates  : {plan['candidates']}")
    print(f"  returned    : {plan['rows_returned']}")
    print(f"  covering    : {plan['covering']}")


