# Demo / tests
# --------------------------------------------------------------------------- #
def make_people(n: int) -> list[dict]:
    cities = ["Seoul", "Busan", "Incheon", "Daegu", "Daejeon"]
    out = []
    for i in range(n):
        out.append(
            {
                "id": i,
                "name": f"user{i}",
                "age": 18 + (i % 47),
                "city": cities[i % len(cities)],
                "salary": 3000 + (i * 37 % 7000),
            }
        )
    return out


def demo_basic():
    print("=" * 70)
    print("BASIC INDEX DEMO")
    print("=" * 70)
    t = Table("people", columns=["id", "name", "age", "city", "salary"])
    rows = make_people(5_000)
    t.bulk_insert(rows)

    # Primary key (unique hash)
    t.create_index("pk_id", ["id"], type="hash", unique=True)
    # Secondary ordered indexes
    t.create_index("idx_age", ["age"], type="ordered")
    t.create_index("idx_city_age", ["city", "age"], type="ordered")
    # Partial index: only high earners
    t.create_index(
        "idx_rich_city", ["city"], type="ordered",
        predicate=lambda r: r["salary"] >= 8000,
    )
    # Covering index: city + age, includes salary
    t.create_index(
        "idx_city_cover", ["city"], type="ordered", include=("age", "salary")
    )

    # Equality via hash index
    r = select(t, where={"id": 1234}, columns=["name", "age"])
    print("hash equality id=1234:", r)

    # Range via ordered index
    r = select(t, where={"age__gte": 60}, columns=["id", "age"], limit=5)
    print("range age>=60 (first 5):", r)

    # Composite prefix scan
    r = select(t, where={"city": "Seoul", "age__lt": 25},
               columns=["id", "age"], limit=5)
    print("composite city=Seoul age<25 (first 5):", r)

    # Partial index usage (rich only)
    r = select(t, where={"city": "Busan", "salary__gte": 9000},
               columns=["id", "salary"], limit=5)
    print("rich filter (first 5):", r)

    # Covering plan
    res = select(t, where={"city": "Incheon"}, columns=["age", "salary"],
                 limit=3, explain=True)
    show_plan(res["plan"])
    print("covering rows:", res["rows"][:2])

    # Unique constraint
    try:
        t.insert({"id": 1, "name": "dup", "age": 20, "city": "X", "salary": 1})
    except IntegrityError as e:
        print("unique constraint fired:", e)


def demo_concurrency():
    print("\n" + "=" * 70)
    print("CONCURRENCY DEMO")
    print("=" * 70)
    t = Table("c", columns=["id", "v"])
    t.create_index("pk", ["id"], type="hash", unique=True)
    errors = []

    def worker(start):
        try:
            for i in range(start, start + 200):
                t.insert({"id": i, "v": i * 2})
        except Exception as e:
            errors.append(e)

    ths = [threading.Thread(target=worker, args=(i * 200,)) for i in range(4)]
    for th in ths:
        th.start()
    for th in ths:
        th.join()
    print("rows:", len(t.live_rowids()), "errors:", len(errors))
    # Concurrent reads
    def reader():
        select(t, where={"id": 42}, columns=["v"])
    ths = [threading.Thread(target=reader) for _ in range(8)]
    for th in ths:
        th.start()
    for th in ths:
        th.join()
    print("concurrent reads OK")


def benchmark():
    print("\n" + "=" * 70)
    print("BENCHMARK (n=20000)")
    print("=" * 70)
    N = 20_000
    t = Table("bench", columns=["id", "name", "age", "city", "salary"])
    t.bulk_insert(make_people(N))
    t.create_index("pk_id", ["id"], type="hash", unique=True)
    t.create_index("idx_age", ["age"], type="ordered")
    t.create_index("idx_city_age", ["city", "age"], type="ordered")

    # full scan timing
    t0 = time.perf_counter()
    full = select(t, where={"age__gte": 60})
    dt_full = time.perf_counter() - t0

    t0 = time.perf_counter()
    idxr = select(t, where={"age__gte": 60})
    dt_idx = time.perf_counter() - t0

    print(f"full scan : {len(full):6d} rows in {dt_full*1000:8.2f} ms")
    print(f"indexed   : {len(idxr):6d} rows in {dt_idx*1000:8.2f} ms")
    print(f"speedup   : {dt_full/max(dt_idx,1e-9):.1f}x")

    # equality point lookup
    t0 = time.perf_counter()
    for i in range(1000):
        select(t, where={"id": i})
    dt = time.perf_counter() - t0
    print(f"1000 point lookups via hash index: {dt*1000:.2f} ms")

    # ORDER BY via index (no sort)
    t0 = time.perf_counter()
    r = select(t, order_by=["city", "age"], limit=10)
    dt = time.perf_counter() - t0
    print(f"ORDER BY city,age (no index declared) sample: {r[0]}  ({dt*1000:.2f} ms)")
    t.create_index("idx_city_age2", ["city", "age"], type="ordered")
    t0 = time.perf_counter()
    r = select(t, order_by=["city", "age"], limit=5, explain=True)
