Defensive programming in Python means anticipating invalid inputs, unexpected states, and environmental issues. Below are common edge cases with idiomatic handling and code examples.

## 1. `None` and missing values

```python
def get_length(obj):
    # Guard against None before attribute access
    if obj is None:
        raise ValueError("obj must not be None")
    # Also handle objects without __len__
    try:
        return len(obj)
    except TypeError as exc:
        raise TypeError(f"object of type {type(obj).__name__} has no len()") from exc

# Usage
print(get_length([1, 2, 3]))
try:
    get_length(None)
except ValueError as e:
    print("handled:", e)
```

## 2. Wrong or unexpected types (duck-typing vs strict checks)

```python
from collections.abc import Iterable

def total(values):
    # Accept any iterable, but reject strings (common footgun)
    if isinstance(values, (str, bytes)):
        raise TypeError("values must be an iterable of numbers, not a string/bytes")
    if not isinstance(values, Iterable):
        raise TypeError(f"expected iterable, got {type(values).__name__}")

    result = 0
    for item in values:
        if not isinstance(item, (int, float)):
            raise TypeError(f"non-numeric item: {item!r}")
        # Reject bool? bool is subclass of int; decide explicitly.
        if isinstance(item, bool):
            raise TypeError("bool is not a valid numeric item")
        result += item
    return result
```

## 3. Mutable default arguments

```python
# BAD
def append_bad(item, bucket=[]):
    bucket.append(item)
    return bucket

# GOOD
def append_good(item, bucket=None):
    if bucket is None:
        bucket = []
    bucket.append(item)
    return bucket
```

## 4. Empty collections and zero denominators

```python
def safe_average(nums):
    if not nums:  # handles None? no—validate first
        raise ValueError("nums must be non-empty")
    total = sum(nums)
    count = len(nums)
    if count == 0:
        raise ZeroDivisionError("cannot average empty sequence")
    return total / count

# Numeric edge: division by zero also for floats
def divide(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    return a / b
```

## 5. `NaN` and `Infinity`

```python
import math

def normalize(x):
    if not isinstance(x, (int, float)):
        raise TypeError("x must be a number")
    if isinstance(x, bool):
        raise TypeError("bool is not a valid number")
    if math.isnan(x):
        raise ValueError("NaN is not allowed")
    if math.isinf(x):
        raise ValueError("Infinity is not allowed")
    # safe operations below
    return x / (abs(x) + 1)
```

## 6. Floating-point equality

```python
def approx_equal(a, b, tol=1e-9):
    if not (isinstance(a, (int, float)) and isinstance(b, (int, float))):
        raise TypeError("a and b must be numbers")
    return math.isclose(a, b, rel_tol=tol, abs_tol=tol)

# Edge: comparing 0.1 + 0.2 == 0.3 is False
print(approx_equal(0.1 + 0.2, 0.3))  # True
```

## 7. Aliasing and mutable shared state

```python
def process_records(records):
    # Defensive copy to avoid mutating caller's data
    records = list(records)
    result = []
    for r in records:
        # shallow copy; use copy.deepcopy for nested mutables
        r = dict(r)
        r["processed"] = True
        result.append(r)
    return result

original = [{"id": 1}]
out = process_records(original)
print(original)  # unchanged
