    try:
        return int(text)
    except ValueError as exc:
        # Do not catch KeyboardInterrupt/SystemExit/Exception broadly
        raise ValueError(f"invalid integer: {text!r}") from exc

# Context: ensure cleanup with finally or context managers
def read_file(path):
    f = open(path, encoding="utf-8")
    try:
        return f.read()
    finally:
        f.close()
```

Better:

```python
from pathlib import Path

def read_file(path):
    path = Path(path)
    if not path.is_file():
        raise FileNotFoundError(path)
    return path.read_text(encoding="utf-8")
```

## 11. Resource and path safety

```python
from pathlib import Path

def safe_join(base, user_input):
    base = Path(base).resolve()
    target = (base / user_input).resolve()
    # Prevent path traversal
    if base not in target.parents and target != base:
        raise ValueError("path traversal detected")
    return target
```

## 12. Encoding and text/bytes boundaries

```python
def to_text(data):
    if isinstance(data, str):
        return data
    if isinstance(data, (bytes, bytearray)):
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("data is not valid UTF-8") from exc
    raise TypeError(f"expected str/bytes, got {type(data).__name__}")
```

## 13. Timezone-aware vs naive datetimes

```python
from datetime import datetime, timezone

def to_utc(dt):
    if not isinstance(dt, datetime):
        raise TypeError("dt must be datetime")
    if dt.tzinfo is None:
        # Decide policy: assume UTC or reject
        raise ValueError("naive datetime is not allowed; provide tzinfo")
    return dt.astimezone(timezone.utc)
```

## 14. Hashability and dictionary keys

```python
def count_items(items):
    counts = {}
    for item in items:
        # Lists/dicts are unhashable; convert or skip
        if isinstance(item, (list, dict, set)):
            raise TypeError(f"unhashable item type: {type(item).__name__}")
        counts[item] = counts.get(item, 0) + 1
    return counts
```

## 15. Concurrency: shared mutable state

```python
import threading

class Counter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    def increment(self):
        with self._lock:
            self._value += 1

    @property
    def value(self):
        with self._lock:
            return self._value
```

## 16. Recursion limits and deep structures

```python
import sys

def deep_sum(obj, _seen=None):
    if _seen is None:
        _seen = set()
    # Guard against cycles
    obj_id = id(obj)
    if isinstance(obj, (list, tuple, dict, set)):
        if obj_id in _seen:
            raise ValueError("circular reference detected")
        _seen.add(obj_id)
    try:
        if isinstance(obj, (int, float)) and not isinstance(obj, bool):
            return obj
        if isinstance(obj, (list, tuple)):
            return sum(deep_sum(x, _seen) for x in obj)
        if isinstance(obj, dict):
            return sum(deep_sum(v, _seen) for v in obj.values())
        return 0
    finally:
        if isinstance(obj, (list, tuple, dict, set)):
            _seen.discard(obj_id)
```

## 17. Assertions are not validation

```python
def divide_assert(a, b):
    # assert can be disabled with python -O
    assert b != 0, "b must not be zero"
    return a / b

# Better: explicit exception
def divide_safe(a, b):
    if b == 0:
        raise ZeroDivisionError("b must not be zero")
    return a / b
```

## 18. `__eq__` and `__hash__` consistency

```python
class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return self.x == other.x and self.y == other.y

    def __hash__(self):
        # Must be consistent with __eq__
        return hash((self.x, self.y))
```

## Practical defensive checklist

- Validate at boundaries (APIs, user input, file reads).
- Prefer explicit exceptions over silent failures.
- Do not rely on `assert` for runtime validation.
- Copy mutable inputs when ownership is unclear.
- Use context managers for resources.
- Handle `None`, empty, NaN, and unhashable cases explicitly.
- Avoid broad `except:`; catch specific exceptions.
- Be explicit about timezone awareness and encoding.

