Below is a complete, runnable Python script that demonstrates many classic design patterns in one cohesive “checkout” scenario. You can save it as `patterns_demo.py` and run it with `python patterns_demo.py`.

```python
"""
Design Patterns in Python - complete runnable demo.

Patterns demonstrated:
1. Singleton          -> AppConfig
2. Builder            -> OrderBuilder
3. Factory Method     -> PaymentProcessorFactory
4. Strategy           -> DiscountStrategy family
5. Decorator          -> Notifier decorators
6. Observer           -> EventBus
7. Command            -> PlaceOrderCommand + CommandHistory
8. Adapter            -> InventoryAdapter
9. Facade             -> CheckoutFacade
10. State             -> OrderState family
11. Template Method    -> ReportGenerator
12. Proxy             -> PaymentProcessorProxy
13. Chain of Resp.     -> RequestHandler chain
14. Composite         -> UIComponent tree
15. Iterator          -> OrderCollection
16. Memento           -> OrderMemento / OrderCaretaker
"""

import uuid
from abc import ABC, abstractmethod
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional


# ============================================================
# 1. Singleton
# ============================================================
class AppConfig:
    _instance: Optional["AppConfig"] = None

    def __new__(cls) -> "AppConfig":
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self) -> None:
        if getattr(self, "_initialized", False):
            return
        self.tax_rate = 0.10
        self.currency = "USD"
        self._initialized = True


# ============================================================
# Domain models
# ============================================================
@dataclass
class OrderItem:
    sku: str
    name: str
    price: float
    qty: int = 1


@dataclass
class Order:
    id: str
    customer: str = "guest"
    items: List[OrderItem] = field(default_factory=list)
    discount: "DiscountStrategy" = field(default_factory=lambda: NoDiscount())
    total: float = 0.0
    status: str = "NEW"
    state: Optional["OrderState"] = None

    def calculate_total(self) -> None:
        subtotal = sum(item.price * item.qty for item in self.items)
        self.total = round(self.discount.apply(subtotal), 2)

    def add_item(self, item: OrderItem) -> None:
        self.items.append(item)

    # State delegation
    def pay(self) -> None:
        if self.state is None:
            self.state = PendingState()
        self.state.pay(self)

    def ship(self) -> None:
        if self.state is None:
            self.state = PendingState()
        self.state.ship(self)

    def cancel(self) -> None:
        if self.state is None:
            self.state = PendingState()
        self.state.cancel(self)


# ============================================================
# 10. State
# ============================================================
class OrderState(ABC):
    @abstractmethod
    def name(self) -> str:
        ...

    def pay(self, order: Order) -> None:
        raise ValueError(f"Cannot pay in state {self.name()}")

    def ship(self, order: Order) -> None:
        raise ValueError(f"Cannot ship in state {self.name()}")

    def cancel(self, order: Order) -> None:
        raise ValueError(f"Cannot cancel in state {self.name()}")


class PendingState(OrderState):
    def name(self) -> str:
        return "PENDING"

    def pay(self, order: Order) -> None:
        print(f"[State] Order {order.id}: payment accepted")
        order.status = "PAID"
        order.state = PaidState()

    def cancel(self, order: Order) -> None:
        print(f"[State] Order {order.id}: cancelled while pending")
        order.status = "CANCELLED"
        order.state = CancelledState()


class PaidState(OrderState):
    def name(self) -> str:
        return "PAID"

    def ship(self, order: Order) -> None:
        print(f"[State] Order {order.id}: shipped")
        order.status = "SHIPPED"
        order.state = ShippedState()

    def cancel(self, order: Order) -> None:
        print(f"[State] Order {order.id}: refunded and cancelled")
        order.status = "CANCELLED"
        order.state = CancelledState()


class ShippedState(OrderState):
    def name(self) -> str:
        return "SHIPPED"


class CancelledState(OrderState):
    def name(self) -> str:
        return "CANCELLED"


# ============================================================
# 2. Builder
# ============================================================
class OrderBuilder:
    def __init__(self, order_id: Optional[str] = None) -> None:
        self._order = Order(id=order_id or str(uuid.uuid4())[:8])

    def for_customer(self, name: str) -> "OrderBuilder":
        self._order.customer = name
        return self

    def add_item(self, sku: str, name: str, price: float, qty: int = 1) -> "OrderBuilder":
        self._order.items.append(OrderItem(sku, name, price, qty))
        return self

    def with_discount(self, strategy: "DiscountStrategy") -> "OrderBuilder":
        self._order.discount = strategy
        return self

    def build(self) -> Order:
        self._order.calculate_total()
        if self._order.state is None:
            self._order.state = PendingState()
        return self._order


# ============================================================
# 3. Strategy
# ============================================================
class DiscountStrategy(ABC):
    @abstractmethod
    def apply(self, subtotal: float) -> float:
        ...


class NoDiscount(DiscountStrategy):
    def apply(self, subtotal: float) -> float:
        return subtotal


class PercentageDiscount(DiscountStrategy):
    def __init__(self, rate: float) -> None:
        self.rate = rate

    def apply(self, subtotal: float) -> float:
        return subtotal * (1 - self.rate)


class BulkDiscount(DiscountStrategy):
    def __init__(self, threshold: float, rate: float) -> None:
        self.threshold = threshold
        self.rate = rate

    def apply(self, subtotal: float) -> float:
        if subtotal >= self.threshold:
            return subtotal * (1 - self.rate)
        return subtotal


# ============================================================
# 4. Factory Method
# ============================================================
class PaymentProcessor(ABC):
    @abstractmethod
    def pay(self, order: Order) -> bool:
        ...


class CreditCardProcessor(PaymentProcessor):
    def pay(self, order: Order) -> bool:
        print(f"[Payment] Charging card: {order.total} {AppConfig().currency}")
        return True


class PayPalProcessor(PaymentProcessor):
    def pay(self, order: Order) -> bool:
        print(f"[Payment] PayPal charge: {order.total} {AppConfig().currency}")
        return True


class PaymentProcessorFactory:
    _registry: Dict[str, type] = {
        "card": CreditCardProcessor,
        "paypal": PayPalProcessor,
    }

    @classmethod
    def create(cls, method: str) -> PaymentProcessor:
        if method not in cls._registry:
            raise ValueError(f"Unknown payment method: {method}")
        return cls._registry[method]()


# ============================================================
# 12. Proxy
# ============================================================
class PaymentProcessorProxy(PaymentProcessor):
    def __init__(self, real: PaymentProcessor, role: str = "user") -> None:
        self._real = real
        self._role = role

    def pay(self, order: Order) -> bool:
        print(f"[Proxy] authorizing role='{self._role}'")
        if self._role != "admin":
            print("[Proxy] access denied")
            return False
        return self._real.pay(order)


# ============================================================
# 8. Adapter
# ============================================================
class LegacyInventory:
    def __init__(self, stock: Optional[Dict[str, int]] = None) -> None:
        self.stock = defaultdict(int, stock or {})

    def remove_item(self, sku: str, qty: int) -> bool:
        if self.stock[sku] < qty:
            print(f"[LegacyInventory] insufficient stock for {sku}")
            return False
        self.stock[sku] -= qty
        print(f"[LegacyInventory] removed {qty} x {sku}")
        return True


class InventoryService(ABC):
    @abstractmethod
    def reserve(self, sku: str, qty: int) -> bool:
        ...


class InventoryAdapter(InventoryService):
    def __init__(self, legacy: LegacyInventory) -> None:
        self.legacy = legacy

    def reserve(self, sku: str, qty: int) -> bool:
        return self.legacy.remove_item(sku, qty)


# ============================================================
# 5. Decorator
# ============================================================
class Notifier(ABC):
    @abstractmethod
    def send(self, message: str) -> None:
        ...


class BaseNotifier(Notifier):
    def send(self, message: str) -> None:
        print(f"[BaseNotifier] {message}")


class NotifierDecorator(Notifier):
    def __init__(self, wrapped: Notifier) -> None:
        self._wrapped = wrapped

    def send(self, message: str) -> None:
        self._wrapped.send(message)


class EmailDecorator(NotifierDecorator):
    def send(self, message: str) -> None:
        super().send(message)
        print(f"[Email] {message}")


class SMSDecorator(NotifierDecorator):
    def send(self, message: str) -> None:
        super().send(message)
        print(f"[SMS] {message}")


class SlackDecorator(NotifierDecorator):
    def send(self, message: str) -> None:
        super().send(message)
        print(f"[Slack] {message}")


# ============================================================
# 6. Observer
# ============================================================
class EventBus:
    def __init__(self) -> None:
        self._listeners: Dict[str, List[Callable[[str, Any], None]]] = defaultdict(list)

    def subscribe(self, event: str, listener: Callable[[str, Any], None]) -> None:
        self._listeners[event].append(listener)

    def publish(self, event: str, payload: Any) -> None:
        for listener in list(self._listeners[event]):
            listener(event, payload)


def inventory_observer(event: str, payload: Any) -> None:
    print(f"[Observer:Inventory] {event} -> {payload}")


def analytics_observer(event: str, payload: Any) -> None:
    print(f"[Observer:Analytics] {event} -> {payload}")


# ============================================================
# 7. Command
# ============================================================
class Command(ABC):
    @abstractmethod
    def execute(self) -> bool:
        ...

    @abstractmethod
    def undo(self) -> None:
        ...


class CommandHistory:
    def __init__(self) -> None:
        self._stack: List[Command] = []

    def push(self, command: Command) -> None:
        self._stack.append(command)

    def undo_last(self) -> None:
        if self._stack:
            self._stack.pop().undo()


class PlaceOrderCommand(Command):
    def __init__(
        self,
        order: Order,
        inventory: InventoryService,
        payment: PaymentProcessor,
        event_bus: EventBus,
    ) -> None:
        self.order = order
        self.inventory = inventory
        self.payment = payment
        self.event_bus = event_bus

    def execute(self) -> bool:
        for item in self.order.items:
            if not self.inventory.reserve(item.sku, item.qty):
                print("[Command] inventory reservation failed")
                return False

        if not self.payment.pay(self.order):
            print("[Command] payment failed")
            return False

        self.order.pay()  # state transition: PENDING -> PAID
        self.event_bus.publish("order.placed", {"order_id": self.order.id, "total": self.order.total})
        return True

    def undo(self) -> None:
        print(f"[Command] Undoing order {self.order.id}")
        self.order.cancel()
        self.event_bus.publish("order.cancelled", {"order_id": self.order.id})


# ============================================================
# 9. Facade
# ============================================================
class CheckoutFacade:
    def __init__(
        self,
        inventory: InventoryService,
        notifier: Notifier,
        event_bus: EventBus,
        history: CommandHistory,
    ) -> None:
        self.inventory = inventory
        self.notifier = notifier
        self.event_bus = event_bus
        self.history = history

    def checkout(
        self,
        builder: OrderBuilder,
        payment_method: str = "card",
        role: str = "admin",
    ) -> Order:
        order = builder.build()
        payment = PaymentProcessorProxy(PaymentProcessorFactory.create(payment_method), role)
        command = PlaceOrderCommand(order, self.inventory, payment, self.event_bus)
        success = command.execute()

        if success:
            self.history.push(command)
            self.notifier.send(f"Order {order.id} confirmed (total={order.total})")
        else:
            self.notifier.send(f"Order {order.id} FAILED")
        return order

    def cancel_last_order(self) -> None:
        self.history.undo_last()


# ============================================================
# 11. Template Method
# ============================================================
class ReportGenerator(ABC):
    def generate(self, title: str, rows: List[Dict[str, Any]]) -> str:
        lines = [f"=== {title} ===", self._format_header()]
        for row in rows:
            lines.append(self._format_row(row))
        lines.append(self._footer())
        report = "\n".join(lines)
        print(report)
        return report

    @abstractmethod
    def _format_header(self) -> str:
        ...

    @abstractmethod
    def _format_row(self, row: Dict[str, Any]) -> str:
        ...

    def _footer(self) -> str:
        return "--- end ---"


class SalesReport(ReportGenerator):
    def _format_header(self) -> str:
        return "sku | qty | line_total"

    def _format_row(self, row: Dict[str, Any]) -> str:
        return f"{row['sku']} | {row['qty']} | {row['line_total']}"


class InventoryReport(ReportGenerator):
    def _format_header(self) -> str:
        return "sku | remaining"

    def _format_row(self, row: Dict[str, Any]) -> str:
        return f"{row['sku']} | {row['remaining']}"


# ============================================================
# 13. Chain of Responsibility
# ============================================================
class RequestHandler(ABC):
    def __init__(self, nxt: Optional["RequestHandler"] = None) -> None:
        self._next = nxt

    def set_next(self, handler: "RequestHandler") -> "RequestHandler":
        self._next = handler
        return handler

    def handle(self, request: Dict[str, Any]) -> Any:
        if self._next is not None:
            return self._next.handle(request)
        raise ValueError("Unhandled request")


class ValidationHandler(RequestHandler):
    def handle(self, request: Dict[str, Any]) -> Any:
        if not request.get("items"):
            raise ValueError("Validation failed: no items")
        print("[Chain] validation passed")
        return super().handle(request)


class StockHandler(RequestHandler):
    def handle(self, request: Dict[str, Any]) -> Any:
        print("[Chain] stock reserved")
        return super().handle(request)


class PaymentHandler(RequestHandler):
    def handle(self, request: Dict[str, Any]) -> Any:
        print("[Chain] payment captured")
        return {"status": "ok"}


# ============================================================
# 14. Composite
# ============================================================
class UIComponent(ABC):
    @abstractmethod
    def render(self, indent: int = 0) -> str:
        ...


class Button(UIComponent):
    def __init__(self, label: str) -> None:
        self.label = label

    def render(self, indent: int = 0) -> str:
        return " " * indent + f"[Button: {self.label}]"


class Label(UIComponent):
    def __init__(self, text: str) -> None:
        self.text = text

    def render(self, indent: int = 0) -> str:
        return " " * indent + f"Label({self.text})"


class Panel(UIComponent):
    def __init__(self, name: str) -> None:
        self.name = name
        self.children: List[UIComponent] = []

    def add(self, component: UIComponent) -> None:
        self.children.append(component)

    def render(self, indent: int = 0) -> str:
        lines = [" " * indent + f"Panel({self.name})"]
        for child in self.children:
            lines.append(child.render(indent + 2))
        return "\n".join(lines)


# ============================================================
# 15. Iterator
# ============================================================
class OrderCollection:
    def __init__(self) -> None:
        self._orders: List[Order] = []

    def add(self, order: Order) -> None:
        self._orders.append(order)

    def __iter__(self) -> Any:
        return iter(self._orders)


# ============================================================
# 16. Memento
# ============================================================
@dataclass
class OrderMemento:
    status: str
    total: float


class OrderCaretaker:
    def __init__(self, order: Order) -> None:
        self.order = order
        self._history: List[OrderMemento] = []

    def save(self) -> None:
        self._history.append(OrderMemento(self.order.status, self.order.total))

    def restore(self) -> None:
        if not self._history:
            return
        memento = self._history.pop()
        self.order.status = memento.status
        self.order.total = memento.total
        state_map = {
            "NEW": PendingState(),
            "PENDING": PendingState(),
            "PAID": PaidState(),
            "SHIPPED": ShippedState(),
            "CANCELLED": CancelledState(),
        }
        self.order.state = state_map.get(self.order.status, PendingState())


# ============================================================
# Demo
# ============================================================
def main() -> None:
    config = AppConfig()
    print("Config:", config.currency, config.tax_rate)

    # Inventory (Adapter)
    legacy = LegacyInventory(stock={"SKU-1": 10, "SKU-2": 5})
    inventory = InventoryAdapter(legacy)

    # Notifier (Decorator)
    notifier = SlackDecorator(SMSDecorator(EmailDecorator(BaseNotifier())))

    # Observer
    event_bus = EventBus()
    event_bus.subscribe("order.placed", inventory_observer)
    event_bus.subscribe("order.placed", analytics_observer)
    event_bus.subscribe("order.cancelled", analytics_observer)

    history = CommandHistory()
    facade = CheckoutFacade(inventory, notifier, event_bus, history)

    # Builder + Strategy + Factory + State + Command + Facade
    builder = (
        OrderBuilder()
        .for_customer("Alice")
        .add_item("SKU-1", "Widget", 10.0, 2)
        .add_item("SKU-2", "Gadget", 20.0, 1)
        .with_discount(PercentageDiscount(0.1))
    )
    order = facade.checkout(builder, payment_method="card", role="admin")
    print("Order status:", order.status, "| total:", order.total)

    # State transitions
    order.ship()
    print("After ship:", order.status)

    # Memento
    caretaker = OrderCaretaker(order)
    caretaker.save()
    order.total = 999.99
    order.status = "PAID"
    caretaker.restore()
    print("After memento restore -> status:", order.status, "total:", order.total)

    # Command undo
    print("\n--- Undo last order ---")
    facade.cancel_last_order()
    print("Order status after undo:", order.status)

    # Proxy denial demo
    print("\n--- Proxy denial ---")
    proxy = PaymentProcessorProxy(CreditCardProcessor(), role="user")
    ok = proxy.pay(order)
    print("Proxy pay result:", ok)

    # Strategy demo
    print("\n--- Strategy ---")
    for strategy in (NoDiscount(), PercentageDiscount(0.2), BulkDiscount(100, 0.15)):
        print(strategy.__class__.__name__, "->", round(strategy.apply(120), 2))

    # Template Method
    print("\n--- Reports ---")
    SalesReport().generate(
        "Sales",
        [{"sku": "SKU-1", "qty": 2, "line_total": 20.0}],
    )
    InventoryReport().generate(
        "Inventory",
        [{"sku": "SKU-1", "remaining": 8}],
    )

    # Chain of Responsibility
    print("\n--- Chain ---")
    validation = ValidationHandler()
    stock = StockHandler()
    payment = PaymentHandler()
    validation.set_next(stock).set_next(payment)
    result = validation.handle({"items": [{"sku": "SKU-1", "qty": 1}], "payment_method": "card"})
    print("Chain result:", result)

    # Composite
    print("\n--- Composite UI ---")
    root = Panel("Main")
    root.add(Label("Welcome"))
    root.add(Button("Buy"))
    inner = Panel("Footer")
    inner.add(Label("© 2025"))
    root.add(inner)
    print(root.render())

    # Iterator
    print("\n--- Iterator ---")
    collection = OrderCollection()
    collection.add(order)
    for o in collection:
        print("Iterated order:", o.id, o.status)

    # Singleton identity check
    print("\nSingleton same instance:", AppConfig() is config)


if __name__ == "__main__":
    main()
```

### How the pieces fit together
- `OrderBuilder` creates an `Order` while applying a `DiscountStrategy`.
- `CheckoutFacade` hides coordination of inventory, payment, notification, events, and command history.
- `PlaceOrderCommand` performs the business action and can be undone.
- `PaymentProcessorProxy` adds authorization around a real processor created by `PaymentProcessorFactory`.
- `LegacyInventory` is reused through `InventoryAdapter`.
- `EventBus` notifies observers such as inventory and analytics.
- `Order` delegates behavior to `OrderState` objects.
- `Notifier` decorators stack email, SMS, and Slack behavior.
- Utility patterns (Template Method, Chain of Responsibility, Composite, Iterator, Memento) are demonstrated with small focused examples.

Run the file to see all patterns exercised end-to-end.

Here are common Python-specific pitfalls when applying classic design patterns. Python’s first-class functions, duck typing, modules, and dataclasses often make the full GoF machinery unnecessary.

## 1. Turning simple strategies into deep class hierarchies

**Pitfall:** Strategy becomes boilerplate, stateful objects, and inheritance noise.

```python
from abc import ABC, abstractmethod

class DiscountStrategy(ABC):
    @abstractmethod
    def apply(self, price: float) -> float: ...

class PercentageDiscount(DiscountStrategy):
    def __init__(self, pct: float):
        self.pct = pct

    def apply(self, price: float) -> float:
        return price * (1 - self.pct)

checkout = Checkout(PercentageDiscount(0.2))
```

**Better:** pass callables or use closures.

```python
def percentage_discount(pct: float):
    def apply(price: float) -> float:
        return price * (1 - pct)
    return apply

checkout = Checkout(percentage_discount(0.2))
# Or even simpler:
checkout = Checkout(lambda price: price * 0.8)
```

## 2. Singleton as global mutable state

**Pitfall:** hard to test, reset, subclass, or use in concurrent code.

```python
import threading

class Singleton:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        with cls._lock:
            if cls._instance is None:
                cls._instance = super().__new__(cls)
        return cls._instance
```

**Better:** module-level instance or explicit dependency injection.

```python
# config.py
settings = Settings.from_env()

# app.py
def build_app(config: Settings) -> App:
    return App(config)
```

For tests, pass a fake config instead of mutating global singleton state.

## 3. Decorators that destroy function metadata

**Pitfall:** wrappers lose `__name__`, `__doc__`, and signature inspection.

```python
def log(fn):
    def wrapper(*args, **kwargs):
        print("calling", fn.__name__)
        return fn(*args, **kwargs)
    return wrapper

@log
def add(x: int, y: int) -> int:
    """Add two numbers."""
    return x + y

print(add.__name__)  # wrapper
print(add.__doc__)   # None
```

**Fix:** use `functools.wraps`.

```python
from functools import wraps

def log(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        print("calling", fn.__name__)
        return fn(*args, **kwargs)
    return wrapper
```

## 4. Observer leaks through strong references

**Pitfall:** subject keeps observer alive forever.

```python
class Subject:
    def __init__(self):
        self._observers = []

    def subscribe(self, callback):
        self._observers.append(callback)

    def notify(self, event):
        for cb in self._observers:
            cb(event)

class View:
    def __init__(self, subject):
        subject.subscribe(self.on_event)  # subject now owns self indirectly
```

**Better:** use weak references, especially for bound methods.

```python
import weakref

class Subject:
    def __init__(self):
        self._observers = []

    def subscribe(self, callback):
        try:
            ref = weakref.WeakMethod(callback)
        except TypeError:
            ref = weakref.ref(callback)
        self._observers.append(ref)

    def notify(self, event):
        alive = []
        for ref in self._observers:
            cb = ref()
            if cb is not None:
                cb(event)
                alive.append(ref)
        self._observers = alive
```

Also provide `unsubscribe()` when ownership is explicit.

## 5. Proxy `__getattr__` not handling special methods

**Pitfall:** `__getattr__` is bypassed for dunder methods such as `__len__`, `__iter__`, `__getitem__`.

```python
class Proxy:
    def __init__(self, target):
        self._target = target

    def __getattr__(self, name):
        return getattr(self._target, name)

p = Proxy([1, 2, 3])
print(len(p))  # TypeError: object of type 'Proxy' has no len()
```

**Fix:** explicitly delegate special methods.

```python
class Proxy:
    def __init__(self, target):
        self._target = target

    def __getattr__(self, name):
        if name.startswith("_"):
            raise AttributeError(name)
        return getattr(self._target, name)

    def __len__(self):
        return len(self._target)

    def __iter__(self):
        return iter(self._target)
```

## 6. Factories with hardcoded string branches

**Pitfall:** violates open/closed principle and becomes a maintenance magnet.

```python
def create_payment(method: str):
    if method == "card":
        return CardPayment()
    if method == "paypal":
        return PayPalPayment()
    raise ValueError(f"unknown payment method: {method}")
```

**Better:** use a registry.

```python
_PAYMENT_FACTORIES = {}

def register_payment(name):
    def decorator(cls):
        _PAYMENT_FACTORIES[name] = cls
        return cls
    return decorator

@register_payment("card")
class CardPayment:
    ...

@register_payment("paypal")
class PayPalPayment:
    ...

def create_payment(method: str, **kwargs):
    try:
        return _PAYMENT_FACTORIES[method](**kwargs)
    except KeyError as exc:
        raise ValueError(f"unknown payment method: {method}") from exc
```

## 7. Builder pattern where Python kwargs/dataclasses suffice

**Pitfall:** excessive fluent boilerplate for simple optional configuration.

```python
class HttpRequestBuilder:
    def __init__(self):
        self.method = "GET"
        self.url = None
        self.headers = {}

    def with_method(self, method):
        self.method = method
        return self

    def with_url(self, url):
        self.url = url
        return self
```

**Better:** use dataclasses or keyword arguments.

```python
from dataclasses import dataclass
from typing import Optional, Dict

@dataclass
class HttpRequest:
    url: str
    method: str = "GET"
    headers: Optional[Dict[str, str]] = None
```

Use a builder only for genuinely complex construction, validation, or multi-step assembly.

## 8. Prototype with shallow copies

**Pitfall:** nested mutable state is shared between original and copy.

```python
import copy

original = {"items": [1, 2, 3]}
clone = copy.copy(original)

clone["items"].append(4)
print(original["items"])  # [1, 2, 3, 4]  unexpected
```

**Fix:** use `deepcopy` or implement `__copy__` / `__deepcopy__` deliberately.

```python
import copy

clone = copy.deepcopy(original)
clone["items"].append(4)
print(original["items"])  # [1, 2, 3]
```

## 9. Flyweight with mutable shared instances

**Pitfall:** flyweights must be immutable; otherwise one consumer mutates shared state.

```python
class Glyph:
    _cache = {}

    def __new__(cls, char, font_size):
        key = (char, font_size)
        if key not in cls._cache:
            cls._cache[key] = super().__new__(cls)
        return cls._cache[key]

    def __init__(self, char, font_size):
        self.char = char
        self.font_size = font_size
        self.color = "black"  # mutable shared property! Bad
```

**Better:** make flyweights immutable or copy on handout.

```python
from dataclasses import dataclass

@dataclass(frozen=True)
class Glyph:
    char: str
    font_size: int
```

If per-use mutable state is needed, store it outside the flyweight, e.g. in a rendering context.

## 10. Template Method creating fragile base classes

**Pitfall:** base class dictates algorithm shape; subclasses become tightly coupled to internal step ordering.

```python
class DataPipeline:
    def run(self):
        data = self.extract()
        data = self.transform(data)
        self.load(data)

    def extract(self):
        raise NotImplementedError

    def transform(self, data):
        return data
```

A later change to `run()` can break every subclass.

**Better:** prefer composition with injectable steps.

```python
from typing import Callable, Iterable, Any

def run_pipeline(
    extract: Callable[[], Iterable[Any]],
    transform: Callable[[Iterable[Any]], Iterable[Any]],
    load: Callable[[Iterable[Any]], None],
):
    data = extract()
    data = transform(data)
    load(data)
```

## 11. Chain of Responsibility swallowing errors

**Pitfall:** broad `try/except` makes debugging impossible and hides handler failures.

```python
class Handler:
    def __init__(self, nxt=None):
        self.next = nxt

    def handle(self, request):
        try:
            return self.do_handle(request)
        except Exception:
            if self.next:
                return self.next.handle(request)
            raise
```

**Better:** make pass-through explicit and log failures.

```python
import logging

logger = logging.getLogger(__name__)

class Handler:
    def __init__(self, nxt=None):
        self.next = nxt

    def handle(self, request):
        if self.can_handle(request):
            return self.do_handle(request)
        if self.next is not None:
            return self.next.handle(request)
        raise ValueError(f"no handler for request: {request!r}")

    def can_handle(self, request) -> bool:
        return False

    def do_handle(self, request):
        raise NotImplementedError
```

## 12. Adapter via subclassing instead of composition

**Pitfall:** multiple inheritance and MRO confusion.

```python
class LegacyAdapter(LegacyService, NewInterface):
    def new_operation(self):
        return self.legacy_operation()
```

**Better:** wrap and delegate.

```python
class LegacyAdapter:
    def __init__(self, legacy_service):
        self._legacy = legacy_service

    def new_operation(self):
        return self._legacy.legacy_operation()
```

## 13. Facade becoming a god object

**Pitfall:** facade accumulates business logic instead of simply coordinating subsystems.

```python
class CheckoutFacade:
    def checkout(self, cart, user):
        # validates, charges, emails, updates inventory, etc.
        ...
```

**Better:** keep facade thin and delegate.

```python
class CheckoutFacade:
    def __init__(self, payment, inventory, mailer):
        self.payment = payment
        self.inventory = inventory
        self.mailer = mailer

    def checkout(self, cart, user):
        self.inventory.reserve(cart)
        receipt = self.payment.charge(user, cart.total)
        self.mailer.send_receipt(user, receipt)
        return receipt
```

## Practical takeaway

In Python, prefer:

- functions/callables over strategy class hierarchies  
- module instances or dependency injection over singletons  
- `dataclasses`, keyword args over builders  
- composition over inheritance  
- `functools.wraps` for decorators  
- weak references for observers  
- registries over large `if/elif` factories  

Classic patterns are still useful, but in Python they should usually be lighter, smaller, and more function-oriented.

# Exercise: Flexible Shipping Cost Calculator (Strategy Pattern)

**Task:**  
You’re building a checkout module. Shipping cost depends on the carrier:
- **Standard**: `weight * 0.5 + distance * 0.1`
- **Express**: `weight * 1.0 + distance * 0.25 + 5.0` (flat surcharge)
- **Overnight**: `weight * 2.0 + distance * 0.5 + 10.0` (base + rush fee)

Requirements:
1. Add a new carrier later (e.g., Drone) **without editing existing carrier code**.
2. Switch carrier at runtime.
3. Write a small demo that quotes all carriers for a 3 kg, 100 km shipment.

---

## Step-by-step solution

### Step 1 — Spot the design smell
A naive implementation uses `if/elif`:

```python
def shipping_cost(carrier, weight, distance):
    if carrier == "standard":
        return weight * 0.5 + distance * 0.1
    elif carrier == "express":
        return weight * 1.0 + distance * 0.25 + 5.0
    ...
```

Every new carrier forces editing this function → violates the Open/Closed Principle.

### Step 2 — Define the strategy interface
Use a `Protocol` (structural typing) so any class with the right method qualifies—no inheritance required.

```python
from typing import Protocol

class ShippingStrategy(Protocol):
    def calculate(self, weight_kg: float, distance_km: float) -> float: ...
    @property
    def name(self) -> str: ...
```

### Step 3 — Implement concrete strategies
Each carrier encapsulates its own formula.

```python
class StandardShipping:
    @property
    def name(self) -> str:
        return "Standard"
    def calculate(self, weight_kg, distance_km):
        return weight_kg * 0.5 + distance_km * 0.1

class ExpressShipping:
    @property
    def name(self) -> str:
        return "Express"
    def calculate(self, weight_kg, distance_km):
        return weight_kg * 1.0 + distance_km * 0.25 + 5.0

class OvernightShipping:
    @property
    def name(self) -> str:
        return "Overnight"
    def calculate(self, weight_kg, distance_km):
        return weight_kg * 2.0 + distance_km * 0.5 + 10.0
```

### Step 4 — Context class delegates to the strategy
```python
@dataclass
class Shipment:
    weight_kg: float
    distance_km: float
    strategy: ShippingStrategy

    def quote(self) -> float:
        return round(self.strategy.calculate(self.weight_kg, self.distance_km), 2)
```

Runtime switching is just reassigning `strategy`.

### Step 5 — Add extensibility with a registry (optional but practical)
Instead of hard-coding carrier names in business logic, register strategies in a dict. Adding “Drone” later means only registering it—zero changes to existing classes.

```python
REGISTRY: dict[str, type[ShippingStrategy]] = {
    "standard": StandardShipping,
    "express": ExpressShipping,
    "overnight": OvernightShipping,
}

def make_strategy(key: str) -> ShippingStrategy:
    if key not in REGISTRY:
        raise ValueError(f"Unknown carrier: {key}")
    return REGISTRY[key]()
```

### Step 6 — Demo
```python
def main():
    shipment = Shipment(weight_kg=3.0, distance_km=100.0, strategy=StandardShipping())
    for key in ("standard", "express", "overnight"):
        shipment.strategy = make_strategy(key)
        print(f"{shipment.strategy.name:10} -> ${shipment.quote()}")
```

---

## Final solution (complete, runnable)

```python
# shipping_strategy.py
from __future__ import annotations
from dataclasses import dataclass
from typing import Protocol


class ShippingStrategy(Protocol):
    @property
    def name(self) -> str: ...
    def calculate(self, weight_kg: float, distance_km: float) -> float: ...


class StandardShipping:
    @property
    def name(self) -> str:
        return "Standard"

    def calculate(self, weight_kg: float, distance_km: float) -> float:
        return weight_kg * 0.5 + distance_km * 0.1


class ExpressShipping:
    @property
    def name(self) -> str:
        return "Express"

    def calculate(self, weight_kg: float, distance_km: float) -> float:
        return weight_kg * 1.0 + distance_km * 0.25 + 5.0


class OvernightShipping:
    @property
    def name(self) -> str:
        return "Overnight"

    def calculate(self, weight_kg: float, distance_km: float) -> float:
        return weight_kg * 2.0 + distance_km * 0.5 + 10.0


# ---- Context ----
@dataclass
class Shipment:
    weight_kg: float
    distance_km: float
    strategy: ShippingStrategy

    def quote(self) -> float:
        return round(self.strategy.calculate(self.weight_kg, self.distance_km), 2)


# ---- Registry (Open/Closed friendly) ----
REGISTRY: dict[str, type[ShippingStrategy]] = {
    "standard": StandardShipping,
    "express": ExpressShipping,
    "overnight": OvernightShipping,
}


def make_strategy(key: str) -> ShippingStrategy:
    if key not in REGISTRY:
        raise ValueError(f"Unknown carrier: {key}")
    return REGISTRY[key]()


def main() -> None:
    shipment = Shipment(weight_kg=3.0, distance_km=100.0, strategy=StandardShipping())
    for key in ("standard", "express", "overnight"):
        shipment.strategy = make_strategy(key)
        print(f"{shipment.strategy.name:10} -> ${shipment.quote()}")


if __name__ == "__main__":
    main()
```

### Demonstrate “add without modifying” (Drone example)
```python
class DroneShipping:
    @property
    def name(self) -> str:
        return "Drone"
    def calculate(self, weight_kg, distance_km):
        return weight_kg * 0.8 + distance_km * 0.05 + 2.0

REGISTRY["drone"] = DroneShipping  # no existing code changed
```

### Why this is good Python
- **Protocol** instead of ABC gives duck typing + static checking (mypy/pyright).
- **dataclass** keeps the context lightweight.
- **Registry** maps names to classes, enabling config-driven selection (e.g., from a DB or env var).
- Adding carriers never touches `Shipment` or `quote()`.

### Quick mental test
For 3 kg / 100 km:
- Standard: `1.5 + 10.0 = 11.5`
- Express: `3.0 + 25.0 + 5.0 = 33.0`
- Overnight: `6.0 + 50.0 + 10.0 = 66.0`

Matches the printed output.

## Design Patterns in Python (Interview-Style Answer)

**Design patterns** are reusable, language-agnostic solutions to recurring design problems. In Python, many classic GoF patterns are simplified because Python supports first-class functions, duck typing, dynamic attributes, and built-in decorators. Still, the *intent* (decoupling, extensibility, clarity) is the same.

### Categories
1. **Creational** – how objects are created (`Singleton`, `Factory`, `Builder`)
2. **Structural** – how classes/objects compose (`Adapter`, `Decorator`, `Facade`)
3. **Behavioral** – how responsibilities/communication are assigned (`Observer`, `Strategy`, `Command`)

Below is a compact, runnable “core” implementation of several common patterns with idiomatic Python.

```python
"""
design_patterns_demo.py

Demonstrates common Gang-of-Four patterns in Python.
Run: python design_patterns_demo.py
"""
from __future__ import annotations

import threading
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Callable, List, Optional


# ============================================================
# 1) SINGLETON (Creational)
# Thread-safe lazy initialization.
# ============================================================
class DatabaseConnection:
    _instance: Optional["DatabaseConnection"] = None
    _lock = threading.Lock()

    def __new__(cls, *args, **kwargs):
        # Double-checked locking for thread safety.
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self, dsn: str = "sqlite:///app.db"):
        # __init__ may be called repeatedly; guard against re-init.
        if getattr(self, "_initialized", False):
            return
        self.dsn = dsn
        self._initialized = True


# ============================================================
# 2) FACTORY METHOD (Creational)
# Centralizes object creation behind a stable interface.
# ============================================================
class Notification(ABC):
    @abstractmethod
    def send(self, message: str) -> str: ...


class EmailNotification(Notification):
    def send(self, message: str) -> str:
        return f"[EMAIL] {message}"


class SmsNotification(Notification):
    def send(self, message: str) -> str:
        return f"[SMS] {message}"


class NotificationFactory:
    _registry = {
        "email": EmailNotification,
        "sms": SmsNotification,
    }

    @classmethod
    def create(cls, channel: str) -> Notification:
        if channel not in cls._registry:
            raise ValueError(f"Unknown channel: {channel}")
        return cls._registry[channel]()

    @classmethod
    def register(cls, channel: str, klass: type[Notification]) -> None:
        """Open for extension without modifying factory code."""
        cls._registry[channel] = klass


# ============================================================
# 3) BUILDER (Creational)
# Step-by-step construction of a complex immutable object.
# ============================================================
@dataclass(frozen=True)
class HttpRequest:
    method: str
    url: str
    headers: dict = field(default_factory=dict)
    body: Optional[str] = None
    timeout: int = 30


class HttpRequestBuilder:
    def __init__(self):
        self._method = "GET"
        self._url = ""
        self._headers: dict = {}
        self._body: Optional[str] = None
        self._timeout = 30

    def method(self, method: str) -> "HttpRequestBuilder":
        self._method = method.upper()
        return self

    def url(self, url: str) -> "HttpRequestBuilder":
        self._url = url
        return self

    def header(self, key: str, value: str) -> "HttpRequestBuilder":
        self._headers[key] = value
        return self

    def body(self, body: str) -> "HttpRequestBuilder":
        self._body = body
        return self

    def timeout(self, seconds: int) -> "HttpRequestBuilder":
        self._timeout = seconds
        return self

    def build(self) -> HttpRequest:
        if not self._url:
            raise ValueError("URL is required")
        return HttpRequest(
            method=self._method,
            url=self._url,
            headers=dict(self._headers),
            body=self._body,
            timeout=self._timeout,
        )


# ============================================================
# 4) ADAPTER (Structural)
# Makes an incompatible interface look like the expected one.
# ============================================================
class PaymentGateway(ABC):
    @abstractmethod
    def charge(self, amount: float) -> bool: ...


class LegacyStripeApi:
    """Third-party API we cannot change."""
    def make_payment(self, cents: int) -> dict:
        return {"status": "ok", "charged_cents": cents}


class StripeAdapter(PaymentGateway):
    def __init__(self, legacy: LegacyStripeApi):
        self._legacy = legacy

    def charge(self, amount: float) -> bool:
        result = self._legacy.make_payment(int(amount * 100))
        return result.get("status") == "ok"


# ============================================================
# 5) DECORATOR (Structural)
# Adds behavior dynamically while keeping the same interface.
# ============================================================
class TextProcessor(ABC):
    @abstractmethod
    def process(self, text: str) -> str: ...


class PlainText(TextProcessor):
    def process(self, text: str) -> str:
        return text


class TextDecorator(TextProcessor):
    def __init__(self, wrapped: TextProcessor):
        self._wrapped = wrapped

    def process(self, text: str) -> str:
        return self._wrapped.process(text)


class UpperCaseDecorator(TextDecorator):
    def process(self, text: str) -> str:
        return self._wrapped.process(text).upper()


class TrimDecorator(TextDecorator):
    def process(self, text: str) -> str:
        return self._wrapped.process(text).strip()


# ============================================================
# 6) FACADE (Structural)
# Simplifies a complex subsystem behind one entry point.
# ============================================================
class InventoryService:
    def reserve(self, sku: str, qty: int) -> bool:
        return True


class PaymentService:
    def pay(self, amount: float) -> bool:
        return True


class ShippingService:
    def schedule(self, sku: str) -> str:
        return f"shipment-{sku}"


class OrderFacade:
    def __init__(self):
        self._inventory = InventoryService()
        self._payment = PaymentService()
        self._shipping = ShippingService()

    def place_order(self, sku: str, qty: int, price: float) -> str:
        if not self._inventory.reserve(sku, qty):
            raise RuntimeError("Out of stock")
        if not self._payment.pay(price * qty):
            raise RuntimeError("Payment failed")
        return self._shipping.schedule(sku)


# ============================================================
# 7) OBSERVER (Behavioral)
# Publish/subscribe; subjects notify observers of state changes.
# ============================================================
class Subject:
    def __init__(self):
        self._observers: List[Callable[[str], None]] = []

    def attach(self, observer: Callable[[str], None]) -> None:
        self._observers.append(observer)

    def detach(self, observer: Callable[[str], None]) -> None:
        self._observers.remove(observer)

    def notify(self, event: str) -> None:
        for observer in list(self._observers):
            observer(event)


class EventBus(Subject):
    def emit(self, event: str) -> None:
        print(f"EventBus emitting: {event}")
        self.notify(event)


# ============================================================
# 8) STRATEGY (Behavioral)
# Swap algorithms at runtime.
# ============================================================
class SortStrategy(ABC):
    @abstractmethod
    def sort(self, data: List[int]) -> List[int]: ...


class BubbleSort(SortStrategy):
    def sort(self, data: List[int]) -> List[int]:
        arr = list(data)
        n = len(arr)
        for i in range(n):
            for j in range(n - i - 1):
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
        return arr


class PythonSort(SortStrategy):
    def sort(self, data: List[int]) -> List[int]:
        return sorted(data)


class Sorter:
    def __init__(self, strategy: SortStrategy):
        self._strategy = strategy

    def set_strategy(self, strategy: SortStrategy) -> None:
        self._strategy = strategy

    def sort(self, data: List[int]) -> List[int]:
        return self._strategy.sort(data)


# ============================================================
# 9) COMMAND (Behavioral)
# Encapsulate a request as an object; supports undo/redo.
# ============================================================
class Command(ABC):
    @abstractmethod
    def execute(self) -> None: ...

    @abstractmethod
    def undo(self) -> None: ...


class TextEditor:
    def __init__(self):
        self.text = ""

    def append(self, s: str) -> None:
        self.text += s

    def delete(self, n: int) -> str:
        removed = self.text[-n:]
        self.text = self.text[:-n]
        return removed


class AppendCommand(Command):
    def __init__(self, editor: TextEditor, text: str):
        self._editor = editor
        self._text = text

    def execute(self) -> None:
        self._editor.append(self._text)

    def undo(self) -> None:
        self._editor.delete(len(self._text))


class CommandHistory:
    def __init__(self):
        self._done: List[Command] = []
        self._undone: List[Command] = []

    def run(self, cmd: Command) -> None:
        cmd.execute()
        self._done.append(cmd)
        self._undone.clear()

    def undo(self) -> None:
        if not self._done:
            return
        cmd = self._done.pop()
        cmd.undo()
        self._undone.append(cmd)

    def redo(self) -> None:
        if not self._undone:
            return
        cmd = self._undone.pop()
        cmd.execute()
        self._done.append(cmd)


# ============================================================
# Demo
# ============================================================
def main() -> None:
    # Singleton
    a = DatabaseConnection("postgres://x")
    b = DatabaseConnection("ignored")
    assert a is b and a.dsn == "postgres://x"

    # Factory
    n = NotificationFactory.create("email")
    print(n.send("Hello"))

    # Builder
    req = (
        HttpRequestBuilder()
        .method("POST")
        .url("https://api.example.com/users")
        .header("Content-Type", "application/json")
        .body('{"name":"Ada"}')
        .timeout(10)
        .build()
    )
    print(req)

    # Adapter
    gateway: PaymentGateway = StripeAdapter(LegacyStripeApi())
    print("charged:", gateway.charge(12.34))

    # Decorator
    processor: TextProcessor = TrimDecorator(UpperCaseDecorator(PlainText()))
    print(repr(processor.process("  hello world  ")))

    # Facade
    order_id = OrderFacade().place_order("SKU-1", 2, 9.99)
    print("order:", order_id)

    # Observer
    bus = EventBus()
    bus.attach(lambda e: print("observer got:", e))
    bus.emit("user.created")

    # Strategy
    sorter = Sorter(BubbleSort())
    print(sorter.sort([5, 2, 9, 1]))
    sorter.set_strategy(PythonSort())
    print(sorter.sort([5, 2, 9, 1]))

    # Command
    editor = TextEditor()
    history = CommandHistory()
    history.run(AppendCommand(editor, "Hello"))
    history.run(AppendCommand(editor, " World"))
    print("text:", repr(editor.text))
    history.undo()
    print("after undo:", repr(editor.text))
    history.redo()
    print("after redo:", repr(editor.text))


if __name__ == "__main__":
    main()
```

### Interview Talking Points
- **Python simplifies patterns**: A “strategy” can be a plain callable; “decorator” can be a function wrapper; “singleton” is often just a module-level instance. Use classes when you need state, polymorphism, or test seams.
- **Don’t over-engineer**: Apply a pattern when it removes real coupling or duplication, not speculatively.
- **Testability**: Patterns like Factory/Strategy/Command make dependencies injectable and behavior swappable in tests.
- **Concurrency**: Singletons need locking if initialized lazily; otherwise prefer explicit construction + dependency injection.

If you want, I can zoom into one pattern (e.g., a production-grade `Observer` with weak references and async dispatch, or a `Builder` with validation) next.

```python
#!/usr/bin/env python3
"""Comprehensive, runnable demonstration of Python error handling."""

import json
import logging
import os
import sys
import tempfile
import time
from contextlib import contextmanager
from functools import wraps
from pathlib import Path
from typing import Iterable, Iterator

# ---------- Logging ----------
logging.basicConfig(
    level=logging.DEBUG,
    format="%(asctime)s | %(levelname)-8s | %(name)s | %(message)s",
)
logger = logging.getLogger("demo")


# ---------- Custom exception hierarchy ----------
class AppError(Exception):
    """Base class for all application-specific errors."""
    def __init__(self, message: str, *, code: int = 1, cause=None):
        super().__init__(message)
        self.code = code
        self.cause = cause


class ConfigError(AppError):
    """Raised when configuration is missing or invalid."""


class DataError(AppError):
    """Raised when input data cannot be parsed."""


class ProcessingError(AppError):
    """Raised when a record cannot be processed."""


# ---------- try / except / else / finally ----------
def safe_divide(a: float, b: float):
    """Demonstrates else and finally blocks."""
    try:
        result = a / b
    except ZeroDivisionError:
        logger.warning("Division by zero")
        return None
    else:
        # Runs only if no exception occurred
        logger.debug("Division succeeded: %s", result)
        return result
    finally:
        # Always runs (cleanup, metrics, etc.)
        logger.debug("safe_divide finished")


# ---------- Retry decorator ----------
def retry(attempts: int = 3, delay: float = 0.05, exceptions: tuple = (Exception,)):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for i in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    logger.warning("Attempt %d/%d failed: %s", i, attempts, exc)
                    if i < attempts:
                        time.sleep(delay)
            logger.error("All %d attempts failed", attempts)
            raise last_exc
        return wrapper
    return decorator


# ---------- Context manager (guaranteed cleanup) ----------
@contextmanager
def managed_file(path: Path, mode: str = "r", encoding: str = "utf-8") -> Iterator:
    """Open a file, guarantee closure, and translate OS errors."""
    try:
        f = open(path, mode, encoding=encoding)
    except OSError as exc:
        raise ConfigError(f"Cannot open {path}: {exc}", cause=exc) from exc
    try:
        yield f
    finally:
        try:
            f.close()
        except Exception:  # pragma: no cover
            logger.exception("Error closing file %s", path)


# ---------- Pipeline steps ----------
def load_config(path: Path) -> dict:
    if not path.exists():
        raise ConfigError(f"Config file not found: {path}", code=2)

    try:
        with managed_file(path) as f:
            data = json.load(f)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ConfigError(f"Invalid config JSON: {exc}", code=3, cause=exc) from exc

    if not isinstance(data, dict):
        raise ConfigError("Config must be a JSON object", code=4)

    required = {"input", "output"}
    missing = required - data.keys()
    if missing:
        raise ConfigError(f"Missing config keys: {sorted(missing)}", code=5)

    return data


def parse_data(raw: str) -> list[dict]:
    records = []
    for lineno, line in enumerate(raw.splitlines(), 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue

        parts = line.split(",")
        if len(parts) != 3:
            raise DataError(f"Line {lineno}: expected 3 fields, got {len(parts)}")

        try:
            name, value, weight = parts
            value = float(value)
            weight = float(weight)
        except ValueError as exc:
            raise DataError(f"Line {lineno}: numeric parse error") from exc

        if weight <= 0:
            raise DataError(f"Line {lineno}: weight must be positive")

        records.append({"name": name, "value": value, "weight": weight})

    if not records:
        raise DataError("No data records found")
    return records


@retry(attempts=2, delay=0.01, exceptions=(ProcessingError,))
def process_record(record: dict) -> dict:
    """May raise ProcessingError; retry decorator handles transient failures."""
    if record["value"] < 0:
        raise ProcessingError(f"Negative value for {record['name']}")
    return {**record, "score": record["value"] * record["weight"]}


def write_output(path: Path, records: Iterable[dict]) -> None:
    try:
        with managed_file(path, "w") as f:
            json.dump(list(records), f, indent=2)
    except (TypeError, ValueError) as exc:
        raise ProcessingError(f"Serialization failed: {exc}") from exc


def run_pipeline(config_path: Path) -> int:
    """Run the pipeline; return an exit code (0 = success)."""
    try:
        config = load_config(config_path)
    except ConfigError as exc:
        logger.error("Configuration error (code=%s): %s", exc.code, exc)
        return exc.code
    except AppError as exc:
        logger.error("Application error: %s", exc)
        return 1

    input_path = Path(config["input"])
    output_path = Path(config["output"])

    try:
        with managed_file(input_path) as f:
            raw = f.read()
    except ConfigError as exc:
        logger.error("Input read failed: %s", exc)
        return exc.code

    try:
        records = parse_data(raw)
    except DataError as exc:
        logger.error("Data error: %s", exc)
        return 10

    processed = []
    for rec in records:
        try:
            processed.append(process_record(rec))
        except ProcessingError as exc:
            # Log and skip bad records instead of aborting everything
            logger.warning("Skipping record %s: %s", rec.get("name"), exc)

    if not processed:
        logger.error("No records processed successfully")
        return 20

    try:
        write_output(output_path, processed)
    except ProcessingError as exc:
        logger.error("Output write failed: %s", exc)
        return 30

    logger.info("Pipeline completed: %d records -> %s", len(processed), output_path)
    return 0


def main(argv=None) -> int:
    argv = sys.argv[1:] if argv is None else argv

    with tempfile.TemporaryDirectory() as td:
        base = Path(td)
        config_path = base / "config.json"
        input_path = base / "input.csv"
        output_path = base / "output.json"

        # Valid sample data
        config_path.write_text(json.dumps({
            "input": str(input_path),
            "output": str(output_path),
        }))
        input_path.write_text(
            "alpha,10,2\n"
            "beta,4,1.5\n"
            "# comment line\n"
            "gamma,5,0.5\n"
        )

        # 1) Missing config
        logger.info("== Case 1: missing config ==")
        rc = run_pipeline(base / "nope.json")
        logger.info("Exit code: %d\n", rc)

        # 2) Invalid data
        logger.info("== Case 2: invalid data ==")
        bad_input = base / "bad.csv"
        bad_input.write_text("only_one_field\n")
        bad_config = base / "bad_config.json"
        bad_config.write_text(json.dumps({"input": str(bad_input), "output": str(output_path)}))
        rc = run_pipeline(bad_config)
        logger.info("Exit code: %d\n", rc)

        # 3) Success path
        logger.info("== Case 3: success ==")
        rc = run_pipeline(config_path)
        logger.info("Exit code: %d", rc)
        if output_path.exists():
            logger.info("Output:\n%s", output_path.read_text())

        # 4) Exception chaining demonstration
        logger.info("== Case 4: exception chaining ==")
        try:
            raise ValueError("original cause")
        except ValueError as exc:
            try:
                raise ConfigError("wrapped error") from exc
            except ConfigError as chained:
                logger.error("Caught %s; __cause__=%r", chained, chained.__cause__)

        # 5) else / finally demo
        logger.info("== Case 5: safe_divide ==")
        logger.info("Result: %s", safe_divide(10, 2))
        logger.info("Result: %s", safe_divide(10, 0))

    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
        sys.exit(130)
    except Exception:
        logger.exception("Unhandled exception")
        sys.exit(1)
```

### Key ideas demonstrated

- **Specific catches**: catch `ConfigError`, `DataError`, etc. rather than bare `Exception`.
- **Custom hierarchy**: `AppError` base makes “catch all app errors” easy while still allowing specific handling.
- **Exception chaining**: `raise NewError(...) from exc` preserves the original traceback; inspect via `__cause__`.
- **`else` and `finally`**: `else` runs only on success; `finally` always runs (cleanup).
- **Context manager**: `managed_file` guarantees file closure and converts `OSError` into domain errors.
- **Retry decorator**: retries transient failures, then re-raises the last exception.
- **Graceful degradation**: bad records are logged and skipped instead of aborting the whole pipeline.
- **Exit codes**: functions return integers, and `main` maps them to process exit status.
- **Top-level safety net**: `KeyboardInterrupt` and unexpected exceptions are handled in `__main__`, with logging.

