    print(load_settings(valid))

    bad_examples = [
        "host = example.com\nport = 8080\ndebug = maybe",
        "host = example.com\nport = 8080\nunknown = value",
        "host = example.com\nport = 8080\nport = 9000",
        "host = example.com",
        "host =\nport = 8080",
    ]

    for example in bad_examples:
        try:
            load_settings(example)
        except SettingsError as exc:
            print("Caught:", exc)
```

