Below is a **complete, runnable, from-scratch event loop** in pure Python. It implements the ideas behind `asyncio`:

- a **timer heap** (`heapq`) for `call_later` / `sleep`
- a **selector** (`selectors`) for non-blocking I/O readiness
- a **ready queue** (`collections.deque`) for callbacks
- **`Future`** objects with done-callbacks
- **`Task`** objects that drive generator/`async def` coroutines
- `run_forever()` / `run_until_complete()`

It supports `async def`, `await`, `loop.sleep`, `loop.call_later`, and `loop.add_reader`. It is educational (not thread-safe, no cancellation edge-cases) — use real `asyncio` in production.

```python
import collections
import heapq
import itertools
import selectors
import socket
import sys
import time
import traceback
import types


# --------------------------------------------------------------------------- #
# Exceptions
# --------------------------------------------------------------------------- #
class CancelledError(Exception):
    pass


class InvalidStateError(Exception):
    pass


# --------------------------------------------------------------------------- #
# Handle: a single scheduled callback
# --------------------------------------------------------------------------- #
class Handle:
    def __init__(self, callback, args, loop):
        self._callback = callback
        self._args = args
        self._loop = loop
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    @property
    def cancelled(self):
        return self._cancelled

    def _run(self):
        if self._cancelled:
            return
        try:
            self._callback(*self._args)
        except Exception as exc:
            self._loop._handle_exception(exc)


# --------------------------------------------------------------------------- #
# Future
# --------------------------------------------------------------------------- #
class Future:
    def __init__(self, loop):
        self._loop = loop
        self._state = "PENDING"   # PENDING / FINISHED / CANCELLED
        self._result = None
        self._exception = None
        self._callbacks = []

    def done(self):
        return self._state != "PENDING"

    def cancelled(self):
        return self._state == "CANCELLED"

    def result(self):
        if self._state == "CANCELLED":
            raise CancelledError()
        if self._exception is not None:
            raise self._exception
        return self._result

    def exception(self):
        if self._state == "CANCELLED":
            raise CancelledError()
        return self._exception

    def set_result(self, result):
        if self._state != "PENDING":
            raise InvalidStateError("Future already done")
        self._state = "FINISHED"
        self._result = result
        self._schedule_callbacks()

    def set_exception(self, exc):
        if self._state != "PENDING":
            raise InvalidStateError("Future already done")
        if not isinstance(exc, BaseException):
            raise TypeError("exc must be an exception")
        self._state = "FINISHED"
        self._exception = exc
        self._schedule_callbacks()

    def cancel(self):
        if self._state != "PENDING":
            return False
        self._state = "CANCELLED"
        self._schedule_callbacks()
        return True

    def add_done_callback(self, cb):
        if self._state != "PENDING":
            self._loop.call_soon(cb, self)
        else:
            self._callbacks.append(cb)

    def _schedule_callbacks(self):
        cbs = self._callbacks
        self._callbacks = []
        for cb in cbs:
            self._loop.call_soon(cb, self)

    def __await__(self):
        if not self.done():
            yield self
        return self.result()


# --------------------------------------------------------------------------- #
# Task: drives a coroutine / generator to completion
# --------------------------------------------------------------------------- #
def _coro_from_awaitable(obj):
    return (yield from obj.__await__())


class Task(Future):
    def __init__(self, coro, loop):
        super().__init__(loop)
        self._coro = coro
        self._loop.call_soon(self._step)   # schedule first step

    def _step(self, fut=None):
        if self.done():
            try:
                self._coro.close()
            except Exception:
                pass
            return

        try:
            if fut is None:
                result = self._coro.send(None)
            elif fut.cancelled():
                result = self._coro.throw(CancelledError())
            elif fut.exception() is not None:
                result = self._coro.throw(fut.exception())
            else:
                result = self._coro.send(fut.result())
        except StopIteration as exc:
            self.set_result(exc.value)
        except BaseException as exc:
            self.set_exception(exc)
        else:
            try:
                next_fut = self._loop._ensure_future(result)
            except Exception as exc:
                self.set_exception(exc)
                return
            next_fut.add_done_callback(self._step)

    def cancel(self):
        if self.done():
            return False
        super().cancel()
        try:
            self._loop.call_soon(self._coro.close)
        except Exception:
            pass
        return True


# --------------------------------------------------------------------------- #
# Event loop
# --------------------------------------------------------------------------- #
class EventLoop:
    def __init__(self):
        self._selector = selectors.DefaultSelector()
        self._ready = collections.deque()
        self._scheduled = []          # heap of (when, seq, handle)
        self._counter = itertools.count()
        self._running = False
        self._closed = False
        self._fd_handles = {}         # fd -> {'read': (cb, args) or None, 'write': ...}
        self._exc_handler = None

    # -- public API --------------------------------------------------------- #
    def time(self):
        return time.monotonic()

    def call_soon(self, callback, *args):
        h = Handle(callback, args, self)
        self._ready.append(h)
        return h

    def call_later(self, delay, callback, *args):
        return self.call_at(self.time() + delay, callback, *args)

    def call_at(self, when, callback, *args):
        h = Handle(callback, args, self)
        heapq.heappush(self._scheduled, (when, next(self._counter), h))
        return h

    def create_future(self):
        return Future(self)

    def create_task(self, coro):
        return Task(coro, self)

    def _ensure_future(self, obj):
        if isinstance(obj, Future):
            return obj
        if hasattr(obj, "send") and hasattr(obj, "throw"):
            return Task(obj, self)
        aw = getattr(obj, "__await__", None)
        if aw is not None:
            return Task(_coro_from_awaitable(obj), self)
        raise TypeError(f"Object {obj!r} is not awaitable")

    def add_reader(self, fd, callback, *args):
        self._ensure_fd(fd)
        entry = self._fd_handles[fd]
        entry["read"] = (callback, args)
        self._update_selector(fd, entry)

    def remove_reader(self, fd):
        entry = self._fd_handles.get(fd)
        if entry is None:
            return
        entry["read"] = None
        if entry["write"] is None:
            self._unregister_fd(fd)
        else:
            self._update_selector(fd, entry)

    def add_writer(self, fd, callback, *args):
        self._ensure_fd(fd)
        entry = self._fd_handles[fd]
        entry["write"] = (callback, args)
        self._update_selector(fd, entry)

    def remove_writer(self, fd):
        entry = self._fd_handles.get(fd)
        if entry is None:
            return
        entry["write"] = None
        if entry["read"] is None:
            self._unregister_fd(fd)
        else:
            self._update_selector(fd, entry)

    def run_forever(self):
        if self._running:
            raise RuntimeError("Loop already running")
        if self._closed:
            raise RuntimeError("Loop is closed")
        self._running = True
        try:
            while self._running:
                self._run_once()
        finally:
            self._running = False

    def run_until_complete(self, future):
        future = self._ensure_future(future)
        if future.done():
            return future.result()

        def _stop(_):
            self.stop()

        future.add_done_callback(_stop)
        self.run_forever()
        if not future.done():
            raise RuntimeError("Event loop stopped before future completed")
        return future.result()

    def stop(self):
        self._running = False

    def close(self):
        if self._closed:
            return
        self._closed = True
        for fd in list(self._selector.get_map()):
            try:
                self._selector.unregister(fd)
            except Exception:
                pass
        self._selector.close()
        self._fd_handles.clear()

    def set_exception_handler(self, handler):
        self._exc_handler = handler

    def _handle_exception(self, exc):
        if self._exc_handler is not None:
            self._exc_handler(self, {"exception": exc})
        else:
            traceback.print_exception(type(exc), exc, exc.__traceback__, file=sys.stderr)

    # -- internals ---------------------------------------------------------- #
    def _ensure_fd(self, fd):
        if fd not in self._fd_handles:
            self._fd_handles[fd] = {"read": None, "write": None}

    def _update_selector(self, fd, entry):
        events = 0
        if entry["read"] is not None:
            events |= selectors.EVENT_READ
        if entry["write"] is not None:
            events |= selectors.EVENT_WRITE
        try:
            self._selector.modify(fd, events, entry)
        except KeyError:
            if events:
                self._selector.register(fd, events, entry)

    def _unregister_fd(self, fd):
        try:
            self._selector.unregister(fd)
        except (KeyError, ValueError):
            pass
        self._fd_handles.pop(fd, None)

    def _process_ready(self):
        n = len(self._ready)
        for _ in range(n):
            handle = self._ready.popleft()
            handle._run()

    def _run_once(self):
        if self._closed:
            raise RuntimeError("Loop is closed")

        if not self._ready and not self._scheduled and not self._selector.get_map():
            self._running = False
            return

        # 1. run everything already scheduled as "ready"
        self._process_ready()

        # 2. compute select timeout
        if self._scheduled:
            timeout = max(0.0, self._scheduled[0][0] - self.time())
        else:
            timeout = None
        if self._ready:
            timeout = 0.0
        if not self._ready and not self._scheduled and self._selector.get_map():
            timeout = None

        # 3. wait for I/O
        try:
            events = self._selector.select(timeout)
        except InterruptedError:
            events = []

        # 4. I/O readiness -> ready queue
        for key, mask in events:
            entry = key.data
            if mask & selectors.EVENT_READ and entry.get("read"):
                cb, args = entry["read"]
                self._ready.append(Handle(cb, args, self))
            if mask & selectors.EVENT_WRITE and entry.get("write"):
                cb, args = entry["write"]
                self._ready.append(Handle(cb, args, self))

        # 5. expired timers -> ready queue
        now = self.time()
        while self._scheduled and self._scheduled[0][0] <= now:
            when, seq, handle = heapq.heappop(self._scheduled)
            if not handle.cancelled:
                self._ready.append(handle)


# --------------------------------------------------------------------------- #
# Module-level helpers (like asyncio's)
# --------------------------------------------------------------------------- #
_loop = None


def get_event_loop():
    global _loop
    if _loop is None:
        _loop = EventLoop()
    return _loop


def set_event_loop(loop):
    global _loop
    _loop = loop


def new_event_loop():
    return EventLoop()


def sleep(delay, result=None, *, loop=None):
    if loop is None:
        loop = get_event_loop()
    fut = loop.create_future()
    loop.call_later(delay, fut.set_result, result)
    return fut


# --------------------------------------------------------------------------- #
# Demo
# --------------------------------------------------------------------------- #
def sock_recv(sock, n, loop=None):
    """Asynchronously receive up to n bytes from sock."""
    if loop is None:
        loop = get_event_loop()
    fut = loop.create_future()

    def _on_read():
        loop.remove_reader(sock)
        try:
            data = sock.recv(n)
        except Exception as exc:
            fut.set_exception(exc)
        else:
            fut.set_result(data)

    loop.add_reader(sock, _on_read)
    return fut


async def io_demo(loop):
    a, b = socket.socketpair()
    a.setblocking(False)
    b.setblocking(False)

    def _send():
        b.send(b"hello event loop")

    loop.call_later(0.2, _send)

    data = await sock_recv(a, 1024)
    print("received over socket:", data.decode())

    a.close()
    b.close()


async def main():
    print("Coroutine demo: sleeping 0.3s ...")
    await sleep(0.3)
    print("awake! now running I/O demo ...")
    await io_demo(get_event_loop())
    print("all done")


if __name__ == "__main__":
    loop = EventLoop()
    set_event_loop(loop)
    try:
        loop.run_until_complete(main())
    finally:
        loop.close()
```

### Event loops in Python: interview-style explanation

An event loop is the heart of asynchronous programming in Python (e.g. `asyncio`). It is essentially a **single-threaded scheduler** plus an **I/O multiplexer**.

Its responsibilities:

1. **Maintain a ready queue** of callbacks.
2. **Maintain a timer heap** for `call_later` / `sleep`.
3. **Watch file descriptors** using `select`, `poll`, `epoll`, or `kqueue`.
4. **Run callbacks one at a time** — no true parallelism, only concurrency.
5. **Bridge coroutines to callbacks**: a coroutine suspends at `await future`; the loop resumes it when the future completes.

The core cycle is:

```text
while running:
    run all currently-ready callbacks
    process expired timers
    if there is still work:
        wait for I/O or timer expiration
        enqueue I/O/timer callbacks
```

Important design ideas:

- **Handle**: a scheduled callback with cancellation support.
- **Future**: a placeholder for a result; supports `add_done_callback`.
- **Task**: wraps a coroutine; drives it with `.send(None)` and schedules resumption when an awaited `Future` completes.
- **Selectors**: avoid busy-waiting by blocking until an FD becomes readable/writable or a timer expires.

Below is a clean, teaching implementation of that core.

---

### Minimal event loop implementation

```python
import heapq
import itertools
import selectors
import time
import traceback
from collections import deque


class CancelledError(Exception):
    """Raised when an operation is cancelled."""


class Handle:
    """
    A scheduled callback.

    The event loop stores Handle objects in the ready queue and timer heap.
    """

    def __init__(self, loop, callback, args=(), kwargs=None, when=None):
        self._loop = loop
        self._callback = callback
        self._args = args
        self._kwargs = kwargs if kwargs is not None else {}
        self._when = when          # monotonic time for timers; None for ready callbacks
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        if self._cancelled:
            return
        try:
            self._callback(*self._args, **self._kwargs)
        except Exception:
            # A normal event loop logs and continues instead of crashing.
            traceback.print_exc()

    @property
    def cancelled(self):
        return self._cancelled


class Future:
    """
    A future represents an eventual result.

    It can be awaited by a coroutine. The event loop resumes the
    awaiting coroutine when set_result() or set_exception() is called.
    """

    def __init__(self, loop=None):
        self._loop = loop if loop is not None else get_event_loop()
        self._result = None
        self._exception = None
        self._done = False
        self._cancelled = False
        self._callbacks = []

    def __await__(self):
        # If not done, yield this Future to the driving Task.
        if not self._done:
            yield self
        if self._cancelled:
            raise CancelledError()
        if self._exception is not None:
            raise self._exception
        return self._result

    def done(self):
        return self._done

    def cancelled(self):
        return self._cancelled

    def result(self):
        if self._cancelled:
            raise CancelledError()
        if not self._done:
            raise RuntimeError("result is not ready")
        if self._exception is not None:
            raise self._exception
        return self._result

    def exception(self):
        if self._cancelled:
            raise CancelledError()
        if not self._done:
            raise RuntimeError("exception is not ready")
        return self._exception

    def add_done_callback(self, callback):
        """
        callback(future) will be scheduled when the future completes.
        If already done, schedule it immediately.
        """
        if self._done:
            self._loop.call_soon(callback, self)
        else:
            self._callbacks.append(callback)

    def set_result(self, result):
        if self._done:
            return  # ignore late completion, e.g. cancelled future
        self._result = result
        self._done = True
        self._schedule_callbacks()

    def set_exception(self, exception):
        if self._done:
            return
        self._exception = exception
        self._done = True
        self._schedule_callbacks()

    def cancel(self):
        if self._done:
            return False
        self._cancelled = True
        self._done = True
        self._schedule_callbacks()
        return True

    def _schedule_callbacks(self):
        for callback in self._callbacks:
            self._loop.call_soon(callback, self)
        self._callbacks.clear()


class Task(Future):
    """
    Drives a coroutine to completion.

    A Task is itself a Future, so it can be awaited by other coroutines.
    """

    def __init__(self, coro, *, loop):
        super().__init__(loop=loop)
        self._coro = coro
        # Start lazily: the loop will call _step as a ready callback.
        self._loop.call_soon(self._step)

    def _step(self, exception=None):
        if self._done:
            # The coroutine was cancelled or completed already.
            try:
                self._coro.close()
            except Exception:
                traceback.print_exc()
            return

        try:
            if exception is None:
                result = self._coro.send(None)
            else:
                result = self._coro.throw(exception)
        except StopIteration as exc:
            self.set_result(exc.value)
            return
        except BaseException as exc:  # includes CancelledError
            self.set_exception(exc)
            return

        # The coroutine yielded an awaitable/future.
        if isinstance(result, Future):
            result.add_done_callback(self._wakeup)
        elif result is None:
            # Bare scheduling point; resume soon.
            self._loop.call_soon(self._step)
        else:
            # Support awaiting arbitrary awaitables by converting them.
            try:
                future = self._loop.ensure_future(result)
            except TypeError:
                self._loop.call_soon(self._step)
            else:
                future.add_done_callback(self._wakeup)

    def _wakeup(self, future):
        """
        Called when an awaited future completes.
        Retrieve its result/exception and resume the coroutine.
        """
        try:
            future.result()
        except BaseException as exc:
            self._loop.call_soon(self._step, exc)
        else:
            self._loop.call_soon(self._step)

    def cancel(self):
        if self._done:
            return False
        self._cancelled = True
        self._done = True
        try:
            self._coro.close()
        except Exception:
            traceback.print_exc()
        self._schedule_callbacks()
        return True


class EventLoop:
    def __init__(self):
        self._ready = deque()          # Handle objects ready to run
        self._scheduled = []            # heap of (when, sequence, handle)
        self._selector = selectors.DefaultSelector()
        self._read_callbacks = {}       # fd -> (callback, args)
        self._write_callbacks = {}      # fd -> (callback, args)
        self._running = False
        self._closed = False
        self._sequence = itertools.count()

    # ------------------------------------------------------------------ #
    # Time
    # ------------------------------------------------------------------ #

    def time(self):
        return time.monotonic()

    # ------------------------------------------------------------------ #
    # Scheduling
    # ------------------------------------------------------------------ #

    def call_soon(self, callback, *args, **kwargs):
        if self._closed:
            raise RuntimeError("event loop is closed")
        handle = Handle(self, callback, args, kwargs)
        self._ready.append(handle)
        return handle

    def call_later(self, delay, callback, *args, **kwargs):
        if delay < 0:
            delay = 0
        return self.call_at(self.time() + delay, callback, *args, **kwargs)

    def call_at(self, when, callback, *args, **kwargs):
        if self._closed:
            raise RuntimeError("event loop is closed")
        handle = Handle(self, callback, args, kwargs, when=when)
        seq = next(self._sequence)
        heapq.heappush(self._scheduled, (when, seq, handle))
        return handle

    # ------------------------------------------------------------------ #
    # Futures and tasks
    # ------------------------------------------------------------------ #

    def create_future(self):
        return Future(loop=self)

    def ensure_future(self, obj):
        if isinstance(obj, Future):
            if obj._loop is not self:
                raise ValueError("future belongs to another event loop")
            return obj
        if hasattr(obj, "__await__"):
            return Task(obj, loop=self)
        raise TypeError(f"object {obj!r} is not a future or awaitable")

    def create_task(self, coro):
        return self.ensure_future(coro)

    # ------------------------------------------------------------------ #
    # File-descriptor watching
    # ------------------------------------------------------------------ #

    def _to_fd(self, fileobj):
        return fileobj.fileno() if hasattr(fileobj, "fileno") else int(fileobj)

    def add_reader(self, fileobj, callback, *args):
        fd = self._to_fd(fileobj)
        self._read_callbacks[fd] = (callback, args)

        events = selectors.EVENT_READ
        if fd in self._write_callbacks:
            events |= selectors.EVENT_WRITE

        try:
            self._selector.modify(fd, events, fd)
        except KeyError:
            self._selector.register(fd, events, fd)

    def remove_reader(self, fileobj):
        fd = self._to_fd(fileobj)
        self._read_callbacks.pop(fd, None)

        if fd in self._write_callbacks:
            try:
                self._selector.modify(fd, selectors.EVENT_WRITE, fd)
            except KeyError:
                pass
        else:
            try:
                self._selector.unregister(fd)
            except (KeyError, ValueError):
                pass

    def add_writer(self, fileobj, callback, *args):
        fd = self._to_fd(fileobj)
        self._write_callbacks[fd] = (callback, args)

        events = selectors.EVENT_WRITE
        if fd in self._read_callbacks:
            events |= selectors.EVENT_READ

        try:
            self._selector.modify(fd, events, fd)
        except KeyError:
            self._selector.register(fd, events, fd)

    def remove_writer(self, fileobj):
        fd = self._to_fd(fileobj)
        self._write_callbacks.pop(fd, None)

        if fd in self._read_callbacks:
            try:
                self._selector.modify(fd, selectors.EVENT_READ, fd)
            except KeyError:
                pass
        else:
            try:
                self._selector.unregister(fd)
            except (KeyError, ValueError):
                pass

    # ------------------------------------------------------------------ #
    # Running
    # ------------------------------------------------------------------ #

    def _process_expired_timers(self):
        now = self.time()
        while self._scheduled and self._scheduled[0][0] <= now:
            _, _, handle = heapq.heappop(self._scheduled)
            if handle.cancelled:
                continue
            self._ready.append(handle)

    def _run_once(self):
        if self._closed:
            raise RuntimeError("event loop is closed")

        # 1. Move expired timers into the ready queue.
        self._process_expired_timers()

        # 2. Run all callbacks that were ready at the start of this pass.
        #    New callbacks scheduled during execution run in a later pass.
        n = len(self._ready)
        for _ in range(n):
            if not self._running:
                return
            handle = self._ready.popleft()
            handle.run()

        if not self._running:
            return

        # 3. Decide how long to wait for I/O.
        if self._ready:
            timeout = 0
        elif self._scheduled:
            timeout = self._scheduled[0][0] - self.time()
            if timeout < 0:
                timeout = 0
        else:
            timeout = None

        # Avoid blocking forever when there is no real work left.
        if (not self._scheduled and not self._ready and
                not self._read_callbacks and not self._write_callbacks):
            self._running = False
            return

        # 4. Wait for I/O readiness (or timer expiration).
        try:
            events = self._selector.select(timeout)
        except InterruptedError:
            return

        # 5. Convert I/O readiness into ready callbacks.
        for key, mask in events:
            fd = key.data

            if mask & selectors.EVENT_READ:
                entry = self._read_callbacks.get(fd)
                if entry is not None:
                    callback, args = entry
                    self.call_soon(callback, *args)

            if mask & selectors.EVENT_WRITE:
                entry = self._write_callbacks.get(fd)
                if entry is not None:
                    callback, args = entry
                    self.call_soon(callback, *args)

    def run_forever(self):
        if self._closed:
            raise RuntimeError("event loop is closed")
        self._running = True
        while self._running:
            self._run_once()

    def run_until_complete(self, awaitable):
        future = self.ensure_future(awaitable)

        if future.done():
            self._return_future_result(future)
            return future.result() if not future.cancelled() else None

        # Stop the loop when this future completes.
        future.add_done_callback(lambda f: self.stop())
        self.run_forever()

        if future.cancelled():
            raise CancelledError()
        if future.exception() is not None:
            raise future.exception()
        return future.result()

    def _return_future_result(self, future):
        # Helper kept explicit for readability.
        return future

    def stop(self):
        self._running = False

    def close(self):
        if self._closed:
            return
        self._closed = True
        self._running = False

        for fd in list(self._selector.get_map()):
            try:
                self._selector.unregister(fd)
            except (KeyError, ValueError):
                pass
        self._selector.close()
        self._read_callbacks.clear()
        self._write_callbacks.clear()
        self._ready.clear()
        self._scheduled.clear()


# ---------------------------------------------------------------------- #
# Module-level loop management
# ---------------------------------------------------------------------- #

_global_loop = None


def get_event_loop():
    global _global_loop
    if _global_loop is None:
        _global_loop = EventLoop()
    return _global_loop


def new_event_loop():
    return EventLoop()


def set_event_loop(loop):
    global _global_loop
    _global_loop = loop


# ---------------------------------------------------------------------- #
# Convenience coroutine helper
# ---------------------------------------------------------------------- #

def sleep(delay, result=None, *, loop=None):
    """
    Coroutine-friendly sleep.

    Returns a Future that completes after `delay` seconds.
    """
    loop = loop if loop is not None else get_event_loop()
    future = loop.create_future()
    loop.call_later(delay, future.set_result, result)
    return future
```

