### Example usage

```python
import time


async def worker(name, delay):
    print(f"{name}: starting")
    await sleep(delay)
    print(f"{name}: finished after {delay}s")
    return name


async def main():
    # Schedule two coroutines concurrently.
    task1 = get_event_loop().create_task(worker("A", 1.0))
    task2 = get_event_loop().create_task(worker("B", 0.5))

    result1 = await task1
    result2 = await task2
    print("results:", result1, result2)


loop = get_event_loop()
start = time.monotonic()
loop.run_until_complete(main())
print(f"total time: {time.monotonic() - start:.2f}s")
```

Expected output:

```text
A: starting
B: starting
B: finished after 0.5s
A: finished after 1.0s
results: A B
total time: 1.00s
```

