### What this implementation deliberately omits

A production event loop also includes:

- thread-safe scheduling (`call_soon_threadsafe`);
- exception handling policies;
- child watchers / subprocess support;
- signal handling;
- task cancellation propagation into suspended coroutines;
- backpressure, flow control, and protocol transports;
- optimized fast paths for sockets and timers.

But the code above contains the real architectural core: **ready queue + timer heap + selector + Future/Task bridging**.

## Factory Pattern in Python (complete, runnable example)

Python supports multiple “factory” styles. This single script demonstrates the three most common variants:

1. **Simple Factory** – one factory class creates objects by name/key.
2. **Factory Method** – subclasses decide which concrete product to create.
3. **Abstract Factory** – creates families of related objects.

```python
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Dict, Type
import threading


# ============================================================
# 1. SIMPLE FACTORY
# ============================================================

class Shape(ABC):
    @abstractmethod
    def area(self) -> float:
        raise NotImplementedError


@dataclass
class Circle(Shape):
    radius: float

    def area(self) -> float:
        return 3.141592653589793 * self.radius * self.radius


@dataclass
class Square(Shape):
    side: float

    def area(self) -> float:
        return self.side * self.side


@dataclass
class Triangle(Shape):
    base: float
    height: float

    def area(self) -> float:
        return 0.5 * self.base * self.height


class ShapeFactory:
    """Registry-based simple factory."""

    _registry: Dict[str, Type[Shape]] = {}
    _lock = threading.Lock()

    @classmethod
    def register(cls, name: str, product: Type[Shape]) -> None:
        with cls._lock:
            cls._registry[name.lower()] = product

    @classmethod
    def create(cls, name: str, **kwargs) -> Shape:
        key = name.lower()
        with cls._lock:
            if key not in cls._registry:
                raise ValueError(f"Unknown shape: {name!r}")
            product_cls = cls._registry[key]
        return product_cls(**kwargs)

    @classmethod
    def available(cls) -> list[str]:
        return sorted(cls._registry)


# Register products (can also be done with a decorator in real code)
ShapeFactory.register("circle", Circle)
ShapeFactory.register("square", Square)
ShapeFactory.register("triangle", Triangle)


# ============================================================
# 2. FACTORY METHOD
# ============================================================

class Document(ABC):
    @abstractmethod
    def save(self, path: str) -> str:
        raise NotImplementedError


class PdfDocument(Document):
    def save(self, path: str) -> str:
        return f"PDF written to {path}"


class WordDocument(Document):
    def save(self, path: str) -> str:
        return f"Word document written to {path}"


class MarkdownDocument(Document):
    def save(self, path: str) -> str:
        return f"Markdown written to {path}"


class Application(ABC):
    """Creator base class: subclasses override factory_method()."""

    @abstractmethod
    def factory_method(self) -> Document:
        raise NotImplementedError

    def new_document(self) -> Document:
        # Common workflow; subclass only customizes creation.
        doc = self.factory_method()
        return doc


class PdfApplication(Application):
    def factory_method(self) -> Document:
        return PdfDocument()


class WordApplication(Application):
    def factory_method(self) -> Document:
        return WordDocument()


class MarkdownApplication(Application):
    def factory_method(self) -> Document:
        return MarkdownDocument()


# ============================================================
# 3. ABSTRACT FACTORY
# ============================================================

class Button(ABC):
    @abstractmethod
    def render(self) -> str:
        raise NotImplementedError


class Checkbox(ABC):
    @abstractmethod
    def render(self) -> str:
        raise NotImplementedError


class WinButton(Button):
    def render(self) -> str:
        return "<button class='win'>OK</button>"


class MacButton(Button):
    def render(self) -> str:
        return "<button class='mac'>OK</button>"


class WinCheckbox(Checkbox):
    def render(self) -> str:
        return "<input type='checkbox' class='win'>"


class MacCheckbox(Checkbox):
    def render(self) -> str:
        return "<input type='checkbox' class='mac'>"


class GUIFactory(ABC):
    @abstractmethod
    def create_button(self) -> Button:
        raise NotImplementedError

    @abstractmethod
    def create_checkbox(self) -> Checkbox:
        raise NotImplementedError


class WindowsFactory(GUIFactory):
    def create_button(self) -> Button:
        return WinButton()

    def create_checkbox(self) -> Checkbox:
        return WinCheckbox()


class MacFactory(GUIFactory):
    def create_button(self) -> Button:
        return MacButton()

    def create_checkbox(self) -> Checkbox:
        return MacCheckbox()


def build_ui(factory: GUIFactory) -> tuple[str, str]:
    return factory.create_button().render(), factory.create_checkbox().render()


# ============================================================
# DEMO
# ============================================================

def main() -> None:
    print("=== Simple Factory ===")
    for name, args in [
        ("circle", {"radius": 2.0}),
        ("square", {"side": 3.0}),
        ("triangle", {"base": 4.0, "height": 5.0}),
    ]:
        shape = ShapeFactory.create(name, **args)
        print(f"{name}: area = {shape.area():.2f}")

    print("Available shapes:", ShapeFactory.available())

    try:
        ShapeFactory.create("hexagon", side=1.0)
    except ValueError as exc:
        print("Expected error:", exc)

    print("\n=== Factory Method ===")
    for app in (PdfApplication(), WordApplication(), MarkdownApplication()):
        doc = app.new_document()
        print(doc.save("output"))

    print("\n=== Abstract Factory ===")
    for factory_cls in (WindowsFactory, MacFactory):
        factory = factory_cls()
        button, checkbox = build_ui(factory)
        print(factory_cls.__name__, "->", button, "|", checkbox)


if __name__ == "__main__":
    main()
```

### Key ideas

- **Simple Factory** centralizes construction logic. The registry makes it extensible without modifying the factory class.
- **Factory Method** moves the creation decision into subclasses, following the Open/Closed Principle.
- **Abstract Factory** guarantees that products from the same family (e.g., Windows button + Windows checkbox) are created together.
- Using `ABC`, type hints, dataclasses, and a thread-safe registry keeps the implementation idiomatic and production-friendly.

## Factory pattern in Python

### 1. The core idea

The **factory pattern** moves *object creation* behind an interface so that callers don’t need to know concrete classes or construction details. Instead of `obj = ConcreteClass(...)`, you call `obj = Factory.create(...)` (or just a function). Benefits:

- **Decoupling**: client code depends on abstractions, not concrete types.
- **Centralized construction**: validation, defaults, logging, caching live in one place.
- **Extensibility**: add new product types without changing client code.
- **Control**: enforce invariants, singleton-ish pools, or lazy initialization.

Python makes factories unusually cheap because functions are first-class and classes are runtime objects.

---

### 2. The simplest form: a function factory

Often the best “factory” in Python is just a function (or `classmethod`) that returns an instance.

```python
from dataclasses import dataclass
from typing import Literal

@dataclass
class Circle:
    radius: float

@dataclass
class Square:
    side: float

ShapeKind = Literal["circle", "square"]

def make_shape(kind: ShapeKind, size: float):
    if kind == "circle":
        return Circle(radius=size)
    if kind == "square":
        return Square(side=size)
    raise ValueError(f"unknown shape: {kind}")

s = make_shape("circle", 3.0)   # Circle(radius=3.0)
```

**When to use:** small, closed sets of types; configuration-driven instantiation.

---

### 3. Factory Method (GoF): subclasses decide the product

A base class defines a *creation method*; subclasses override it. Useful when the framework owns the algorithm but delegates “what to build.”

```python
from abc import ABC, abstractmethod

class Document(ABC):
    @abstractmethod
    def render(self) -> str: ...

class PdfDocument(Document):
    def render(self): return "<pdf/>"

class HtmlDocument(Document):
    def render(self): return "<html/>"

class Application(ABC):
    @abstractmethod
    def create_document(self) -> Document: ...   # factory method

    def new_document(self) -> Document:
        doc = self.create_document()
        doc.render()   # framework uses it
        return doc

class PdfApp(Application):
    def create_document(self): return PdfDocument()

class HtmlApp(Application):
    def create_document(self): return HtmlDocument()

app = PdfApp()
doc = app.new_document()
```

---

### 4. Abstract Factory: families of related objects

When you need *consistent* groups (e.g., dark vs. light UI widgets), an abstract factory builds a whole family.

```python
from abc import ABC, abstractmethod

class Button(ABC):
    @abstractmethod
    def draw(self): ...

class Checkbox(ABC):
    @abstractmethod
    def draw(self): ...

class DarkButton(Button):
    def draw(self): return "dark button"

class DarkCheckbox(Checkbox):
    def draw(self): return "dark checkbox"

class LightButton(Button):
    def draw(self): return "light button"

class LightCheckbox(Checkbox):
    def draw(self): return "light checkbox"

class UIFactory(ABC):
    @abstractmethod
    def button(self) -> Button: ...
    @abstractmethod
    def checkbox(self) -> Checkbox: ...

class DarkFactory(UIFactory):
    def button(self): return DarkButton()
    def checkbox(self): return DarkCheckbox()

class LightFactory(UIFactory):
    def button(self): return LightButton()
    def checkbox(self): return LightCheckbox()

def build_ui(factory: UIFactory):
    return [factory.button().draw(), factory.checkbox().draw()]

build_ui(DarkFactory())   # ['dark button', 'dark checkbox']
```

---

### 5. Pythonic factories (the “practical” versions)

#### A. Registry / dispatch table

Avoid long `if/elif` chains; map keys to classes/callables.

```python
class Parser:
    def parse(self, data): ...

class JsonParser(Parser):
    def parse(self, data): return "json"

class XmlParser(Parser):
    def parse(self, data): return "xml"

_REGISTRY = {}

def register(kind):
    def deco(cls):
        _REGISTRY[kind] = cls
        return cls
    return deco

@register("json")
class JsonParser(Parser): ...

@register("xml")
class XmlParser(Parser): ...

def make_parser(kind, *a, **kw):
    if kind not in _REGISTRY:
        raise ValueError(kind)
    return _REGISTRY[kind](*a, **kw)
```

This is extensible: third-party code can `register("yaml")(YamlParser)` without editing the factory.

#### B. `__init_subclass__` auto-registration

```python
class Plugin:
    _registry = {}
    def __init_subclass__(cls, kind=None, **kw):
        super().__init_subclass__(**kw)
        if kind:
            Plugin._registry[kind] = cls

    @classmethod
    def create(cls, kind, *a, **kw):
        return cls._registry[kind](*a, **kw)

class FooPlugin(Plugin, kind="foo"):
    pass

Plugin.create("foo")   # FooPlugin()
```

#### C. `classmethod` as factory (alternative constructors)

```python
class User:
    def __init__(self, name, age):
        self.name, self.age = name, age

    @classmethod
    def from_dict(cls, d):
        return cls(d["name"], d["age"])

    @classmethod
    def guest(cls):
        return cls("anonymous", 0)

User.from_dict({"name": "Ada", "age": 30})
```

This is the most common “factory” you’ll actually write in Python.

#### D. `__new__` / metaclass (advanced, rarely needed)

You can intercept construction at the class level:

```python
class Singleton:
    _instance = None
    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance
```

Use sparingly; prefer an explicit factory function.

---

### 6. Typical use cases

| Scenario | Factory flavor |
|---|---|
| Parse config, pick backend (JSON/YAML/TOML) | Registry function |
| DB connections (Postgres vs SQLite) | Abstract factory / classmethod |
| Creating domain objects from DTOs/API payloads | `from_dict`/`from_row` classmethods |
| Plugin systems | Auto-registration via `__init_subclass__` |
| GUI themes (dark/light) | Abstract factory |
| Object pools / cached instances | Factory function with cache (`functools.lru_cache` on classmethod) |
| Testing (swap real service for fake) | Factory that accepts a registry/prototype |

---

### 7. Practical tips

- **Prefer functions/classmethods** over heavy GoF hierarchies; Python’s dynamism removes much boilerplate.
- **Type it**: use `Protocol`/`ABC` for the product interface and `Literal`/`Enum` for kinds.
- **Validate at the boundary**: factory is the right place to reject bad `kind` values.
- **Don’t over-engineer**: if you have two types and no growth, a plain constructor is fine.
- **Combine with DI**: factories pair well with dependency-injection containers; the container calls the factory.

---

### Minimal end-to-end example

```python
from typing import Protocol

class Notifier(Protocol):
    def send(self, msg: str) -> None: ...

class EmailNotifier:
    def send(self, msg): print("email:", msg)

class SmsNotifier:
    def send(self, msg): print("sms:", msg)

def notifier_for(channel: str) -> Notifier:
    return {"email": EmailNotifier, "sms": SmsNotifier}[channel]()

n = notifier_for("email")
n.send("hi")   # email: hi
```

That’s the essence: **hide “which class” behind a name, return an object satisfying a contract.**

## Mistaken version

```python
class Dog:
    def speak(self):
        return "Woof"

class Cat:
    def speak(self):
        return "Meow"

def make_animal(kind: str):
    # Typical mistake: hard-coded if/elif chain + direct concrete instantiation
    if kind == "dog":
        return Dog()
    elif kind == "cat":
        return Cat()
    else:
        raise ValueError("Unknown animal")
```

### Why this is wrong

1. **Violates the Open/Closed Principle**  
   Every new animal type forces you to edit `make_animal`. The factory is not “open for extension, closed for modification.”

2. **No shared abstraction**  
   `Dog` and `Cat` do not inherit from a common base, so there is nothing guaranteeing that every returned object can `.speak()`. Type checkers and IDEs cannot help.

3. **Stringly-typed, fragile dispatch**  
   A typo like `"dogs"` silently falls through to the `else` branch at runtime. There is no registry to inspect or validate against.

4. **Tight coupling**  
   The factory knows every concrete class by name. You cannot add a plugin animal in another module without importing and editing this file.

5. **Poor diagnostics**  
   The error message does not say which kinds are valid, so debugging is harder.

---

## Corrected version

```python
from abc import ABC, abstractmethod

# 1. Shared abstraction: every product must implement speak().
class Animal(ABC):
    @abstractmethod
    def speak(self) -> str:
        ...

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}()"


# 2. A registry-based factory. New animals register themselves;
#    the factory never needs to be edited again.
class AnimalFactory:
    _registry: dict[str, type[Animal]] = {}

    @classmethod
    def register(cls, kind: str):
        """Decorator that registers a concrete Animal subclass."""
        def decorator(product_cls: type[Animal]) -> type[Animal]:
            if not (isinstance(product_cls, type) and issubclass(product_cls, Animal)):
                raise TypeError(f"{product_cls!r} must be an Animal subclass")
            if kind in cls._registry:
                raise ValueError(f"Animal kind already registered: {kind!r}")
            cls._registry[kind] = product_cls
            return product_cls
        return decorator

    @classmethod
    def create(cls, kind: str, *args, **kwargs) -> Animal:
        """Create an instance by kind, forwarding constructor args."""
        if kind not in cls._registry:
            known = ", ".join(sorted(cls._registry)) or "<none>"
            raise ValueError(f"Unknown animal kind: {kind!r}. Known kinds: {known}")
        return cls._registry[kind](*args, **kwargs)

    @classmethod
    def available(cls) -> tuple[str, ...]:
        return tuple(sorted(cls._registry))


# 3. Concrete products register themselves.
@AnimalFactory.register("dog")
class Dog(Animal):
    def speak(self) -> str:
        return "Woof"


@AnimalFactory.register("cat")
class Cat(Animal):
    def speak(self) -> str:
        return "Meow"


# Optional: a plugin in another module can do the same thing without
# touching AnimalFactory's source code:
# @AnimalFactory.register("fox")
# class Fox(Animal): ...


if __name__ == "__main__":
    for kind in ("dog", "cat"):
        animal = AnimalFactory.create(kind)
        print(animal, "->", animal.speak())

    print("Available kinds:", AnimalFactory.available())

    try:
        AnimalFactory.create("lizard")
    except ValueError as exc:
        print("Expected error:", exc)
```

### What changed and why

| Problem in the mistake | Fix in the corrected code | Why it helps |
|---|---|---|
| Hard-coded `if/elif` chain | `_registry` dict populated via decorator | Adding a type is now *data*, not *code changes* in the factory. |
| No common interface | `Animal(ABC)` with `@abstractmethod speak` | Every product is guaranteed to implement the contract; type checkers can verify usage. |
| Concrete classes named explicitly inside factory | Factory stores `type[Animal]` values only | Factory depends on the abstraction, not on `Dog`/`Cat`. |
| Vague error message | `ValueError` listing known kinds | Easier debugging and validation. |
| No way to discover valid kinds | `available()` classmethod | Useful for CLI options, docs, or UIs. |
| Constructor arguments ignored | `*args, **kwargs` forwarded | Factory can create configured products, e.g. `create("dog", name="Rex")`. |

### An even more “Pythonic” alternative

If you control all subclasses in one package, you can avoid explicit decorators by using `__init_subclass__`:

```python
class Animal(ABC):
    _registry: dict[str, type["Animal"]] = {}

    def __init_subclass__(cls, kind: str | None = None, **kwargs):
        super().__init_subclass__(**kwargs)
        if kind is not None:
            Animal._registry[kind] = cls

    @classmethod
    def create(cls, kind: str) -> "Animal":
        if kind not in cls._registry:
            raise ValueError(f"Unknown kind: {kind!r}")
        return cls._registry[kind]()

@Animal.register  # not needed; registration happens at class definition
class Dog(Animal, kind="dog"):
    def speak(self): return "Woof"
```

### Key takeaway

A factory’s job is **decoupling “what to create” from “how creation happens.”**  
The mistaken version couples the factory to every concrete class; the corrected version lets products register themselves against a shared abstraction, making the system extensible without editing central code.

## Practical exercise

**Exercise:**  
Implement a **Notification Factory** in Python.  
You have three notification channels — `email`, `sms`, and `push` — each with its own sender class.  
Write a factory that, given a channel name string, returns the correct sender object.  
The sender objects must share a common interface (`send(message)`).  
Unknown channel names must raise a clear error.  
Bonus: make it easy to add a new channel later without modifying the factory’s core logic.

---

## Step-by-step solution

### Step 1 — Define the common interface
Use an abstract base class (`ABC`) so every notifier implements `send`.

```python
from abc import ABC, abstractmethod
from dataclasses import dataclass


class Notifier(ABC):
    @abstractmethod
    def send(self, message: str) -> str:
        """Send a message and return a status string."""
        ...
```

### Step 2 — Implement concrete notifiers
Each class has channel-specific behavior but the same public method.

```python
@dataclass
class EmailNotifier(Notifier):
    recipient: str = "user@example.com"

    def send(self, message: str) -> str:
        return f"[EMAIL to {self.recipient}] {message}"


@dataclass
class SMSNotifier(Notifier):
    phone: str = "+1-555-0100"

    def send(self, message: str) -> str:
        # SMS often has length limits; truncate for realism
        text = message[:160]
        return f"[SMS to {self.phone}] {text}"


@dataclass
class PushNotifier(Notifier):
    device_token: str = "abc123"

    def send(self, message: str) -> str:
        return f"[PUSH to {device_token}] {message}"
```

### Step 3 — Build a simple factory
A dictionary mapping names to classes keeps the factory small and readable.

```python
class SimpleNotifierFactory:
    _registry = {
        "email": EmailNotifier,
        "sms": SMSNotifier,
        "push": PushNotifier,
    }

    @classmethod
    def create(cls, channel: str, **kwargs) -> Notifier:
        if channel not in cls._registry:
            raise ValueError(f"Unknown notification channel: {channel!r}")
        return cls._registry[channel](**kwargs)
```

### Step 4 — (Bonus) Make it extensible with a decorator registry
Instead of editing the factory every time, let new notifiers register themselves.

```python
class ExtensibleFactory:
    _registry: dict[str, type[Notifier]] = {}

    @classmethod
    def register(cls, name: str):
        def decorator(notifier_cls: type[Notifier]):
            if name in cls._registry:
                raise ValueError(f"Channel {name!r} already registered")
            cls._registry[name] = notifier_cls
            return notifier_cls
        return decorator

    @classmethod
    def create(cls, channel: str, **kwargs) -> Notifier:
        if channel not in cls._registry:
            raise ValueError(f"Unknown notification channel: {channel!r}")
        return cls._registry[channel](**kwargs)
```

Register the built-in channels (and any future ones) without changing `create`:

```python
@ExtensibleFactory.register("email")
class EmailNotifier2(EmailNotifier):
    pass

@ExtensibleFactory.register("sms")
class SMSNotifier2(SMSNotifier):
    pass

@ExtensibleFactory.register("push")
class PushNotifier2(PushNotifier):
    pass
```

### Step 5 — Usage and small demo

```python
if __name__ == "__main__":
    for channel in ("email", "sms", "push"):
        notifier = SimpleNotifierFactory.create(channel)
        print(notifier.send("Hello from the factory!"))

    # Unknown channel
    try:
        SimpleNotifierFactory.create("carrier_pigeon")
    except ValueError as e:
        print("Error:", e)
```

