Below is a complete, runnable Python script that implements two classic hash-table designs from scratch:

1. **Separate chaining** – each bucket is a list.
2. **Open addressing with linear probing** – one flat array plus a `_DELETED` sentinel.

Both support `put/get/remove`, dynamic resizing based on load factor, and the usual Python dunder methods. The script ends with a demo that exercises collisions, updates, deletions, resizing, and a quick comparison with `dict`.

```python
#!/usr/bin/env python3
"""Educational hash-table implementations in pure Python."""

from __future__ import annotations

import collections.abc as cabc
import time


# ---------------------------------------------------------------------------
# 1. Separate chaining
# ---------------------------------------------------------------------------
class ChainingHashTable:
    """Hash table using separate chaining (list per bucket)."""

    def __init__(self, initial_capacity: int = 8, load_factor: float = 0.75):
        if initial_capacity < 1:
            raise ValueError("initial_capacity must be >= 1")
        if not (0 < load_factor < 1):
            raise ValueError("load_factor must be between 0 and 1")
        self._capacity = initial_capacity
        self._load_factor = load_factor
        self._size = 0
        self._buckets: list[list[tuple[object, object]]] = [
            [] for _ in range(self._capacity)
        ]

    # -- helpers -----------------------------------------------------------
    def _index(self, key) -> int:
        return hash(key) % self._capacity

    def _resize(self, new_capacity: int) -> None:
        old_buckets = self._buckets
        self._capacity = new_capacity
        self._buckets = [[] for _ in range(new_capacity)]
        self._size = 0
        for bucket in old_buckets:
            for k, v in bucket:
                self.put(k, v)  # re-hash every existing entry

    # -- public API --------------------------------------------------------
    def put(self, key, value) -> None:
        if not isinstance(key, cabc.Hashable):
            raise TypeError(f"unhashable type: {type(key).__name__}")
        idx = self._index(key)
        bucket = self._buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))
        self._size += 1
        if self._size / self._capacity > self._load_factor:
            self._resize(self._capacity * 2)

    def get(self, key, default=None):
        idx = self._index(key)
        for k, v in self._buckets[idx]:
            if k == key:
                return v
        return default

    def remove(self, key):
        idx = self._index(key)
        bucket = self._buckets[idx]
        for i, (k, v) in enumerate(bucket):
            if k == key:
                del bucket[i]
                self._size -= 1
                return v
        raise KeyError(key)

    # -- dunder / convenience ---------------------------------------------
    def __len__(self) -> int:
        return self._size

    def __contains__(self, key) -> bool:
        idx = self._index(key)
        return any(k == key for k, _ in self._buckets[idx])

    def __getitem__(self, key):
        idx = self._index(key)
        for k, v in self._buckets[idx]:
            if k == key:
                return v
        raise KeyError(key)

    def __setitem__(self, key, value) -> None:
        self.put(key, value)

    def __delitem__(self, key) -> None:
        self.remove(key)

    def __iter__(self):
        for bucket in self._buckets:
            for k, _ in bucket:
                yield k

    def items(self):
        for bucket in self._buckets:
            yield from bucket

    def keys(self):
        return list(self)

    def __repr__(self) -> str:
        return f"ChainingHashTable(size={self._size}, cap={self._capacity})"


# ---------------------------------------------------------------------------
# 2. Open addressing (linear probing)
# ---------------------------------------------------------------------------
_DELETED = object()


class OpenAddressingHashTable:
    """Hash table using open addressing with linear probing."""

    def __init__(self, initial_capacity: int = 8, load_factor: float = 0.70):
        if initial_capacity < 1:
            raise ValueError("initial_capacity must be >= 1")
        if not (0 < load_factor < 1):
            raise ValueError("load_factor must be between 0 and 1")
        self._capacity = initial_capacity
        self._load_factor = load_factor
        self._size = 0
        self._table: list[None | tuple | object] = [None] * self._capacity

    # -- helpers -----------------------------------------------------------
    def _index(self, key) -> int:
        return hash(key) % self._capacity

    def _resize(self, new_capacity: int) -> None:
        old_table = self._table
        self._capacity = new_capacity
        self._table = [None] * new_capacity
        self._size = 0
        for entry in old_table:
            if entry is not None and entry is not _DELETED:
                self.put(entry[0], entry[1])

    # -- public API --------------------------------------------------------
    def put(self, key, value) -> None:
        if not isinstance(key, cabc.Hashable):
            raise TypeError(f"unhashable type: {type(key).__name__}")

        # resize *before* we might fill the table
        if (self._size + 1) / self._capacity > self._load_factor:
            self._resize(self._capacity * 2)

        idx = self._index(key)
        first_deleted = None
        while True:
            entry = self._table[idx]
            if entry is None:
                break
            if entry is _DELETED:
                if first_deleted is None:
                    first_deleted = idx
            elif entry[0] == key:
                self._table[idx] = (key, value)
                return
            idx = (idx + 1) % self._capacity

        slot = first_deleted if first_deleted is not None else idx
        # if we reuse a deleted slot, the number of *live* entries grows
        if self._table[slot] is _DELETED:
            self._size += 1  # net add (replacing tombstone with live)
        elif self._table[slot] is None:
            self._size += 1
        self._table[slot] = (key, value)

    def get(self, key, default=None):
        idx = self._index(key)
        while True:
            entry = self._table[idx]
            if entry is None:
                return default
            if entry is not _DELETED and entry[0] == key:
                return entry[1]
            idx = (idx + 1) % self._capacity

    def remove(self, key):
        idx = self._index(key)
        while True:
            entry = self._table[idx]
            if entry is None:
                raise KeyError(key)
            if entry is not _DELETED and entry[0] == key:
                self._table[idx] = _DELETED
                self._size -= 1
                return entry[1]
            idx = (idx + 1) % self._capacity

    # -- dunder / convenience ---------------------------------------------
    def __len__(self) -> int:
        return self._size

    def __contains__(self, key) -> bool:
        idx = self._index(key)
        while True:
            entry = self._table[idx]
            if entry is None:
                return False
            if entry is not _DELETED and entry[0] == key:
                return True
            idx = (idx + 1) % self._capacity

    def __getitem__(self, key):
        v = self.get(key, _MISSING := object())
        if v is _MISSING:
            raise KeyError(key)
        return v

    def __setitem__(self, key, value) -> None:
        self.put(key, value)

    def __delitem__(self, key) -> None:
        self.remove(key)

    def __iter__(self):
        for entry in self._table:
            if entry is not None and entry is not _DELETED:
                yield entry[0]

    def items(self):
        for entry in self._table:
            if entry is not None and entry is not _DELETED:
                yield entry

    def __repr__(self) -> str:
        return f"OpenAddressingHashTable(size={self._size}, cap={self._capacity})"


# ---------------------------------------------------------------------------
# Demo / smoke test
# ---------------------------------------------------------------------------
def main() -> None:
    print("=== Separate chaining ===")
    t = ChainingHashTable()
    for i in range(20):
        t[f"key{i}"] = i * i
    print("len:", len(t))
    print("get key7:", t.get("key7"))
    print("contains key99:", "key99" in t)
    del t["key3"]
    print("after del key3, len:", len(t))
    print("items sample:", list(t.items())[:5])

    # Force collisions by using a tiny table
    small = ChainingHashTable(initial_capacity=2)
    for i in range(6):
        small[i] = i
    print("small chaining size/cap:", len(small), small._capacity)

    print("\n=== Open addressing ===")
    o = OpenAddressingHashTable()
    for i in range(20):
        o[f"key{i}"] = i * i
    print("len:", len(o))
    print("get key7:", o.get("key7"))
    print("contains key99:", "key99" in o)
    del o["key3"]
    print("after del key3, len:", len(o))
    print("get key3 (missing):", o.get("key3", "MISSING"))
    print("items sample:", list(o.items())[:5])

    small2 = OpenAddressingHashTable(initial_capacity=2)
    for i in range(6):
        small2[i] = i
    print("small open size/cap:", len(small2), small2._capacity)
    print("all values present:", all(small2[i] == i for i in range(6)))

    # Unhashable key check
    for tbl in (t, o):
        try:
            tbl[[1, 2]] = 3
        except TypeError as e:
            print("TypeError OK:", e)

    # Quick timing comparison with built-in dict
    print("\n=== Timing (insert + lookup) ===")
    n = 200_000
    for name, make in [("dict", dict), ("chaining", ChainingHashTable), ("open", OpenAddressingHashTable)]:
        tbl = make()
        t0 = time.perf_counter()
        for i in range(n):
            tbl[i] = i
        for i in range(n):
            _ = tbl[i]
        dt = time.perf_counter() - t0
        print(f"{name:10s}: {dt:.3f}s for {n} ops")

    print("\nAll checks passed.")


if __name__ == "__main__":
    main()
```

### Key ideas explained

- **Hashing**: `hash(key) % capacity` maps a key to a bucket index. Python’s built-in `hash()` is randomized per process for strings/bytes to prevent collision attacks.
- **Collisions**:
  - *Chaining* stores colliding keys in a list at that bucket.
  - *Open addressing* walks forward (linear probing) until an empty or deleted slot is found.
- **Load factor**: When `size / capacity` exceeds the threshold, the table is resized (usually doubled) and every entry is re-hashed. Rehashing is why individual inserts are amortized O(1).
- **Deletions in open addressing**: We cannot simply clear a slot, because that would break probe chains. Instead we place a `_DELETED` tombstone. Tombstones are cleaned up during the next resize.
- **Hashability**: Keys must be hashable and equality-comparable (`__hash__` + `__eq__`). Mutable objects like `list` are rejected.
- **Real-world note**: CPython’s `dict` uses a more sophisticated open-addressing scheme (randomized probing, compact combined table, and shared keys in 3.6+) and is implemented in C; this code is for learning and experimentation.

Here’s a thorough, runnable example that demonstrates several layers of immutability in Python:

- **Low-level immutable class** via `__slots__` + `__setattr__` guards  
- **`@dataclass(frozen=True)`** with validation  
- **Deep immutability** (tuples of immutable objects)  
- **Functional updates** (methods return *new* instances instead of mutating)  
- **Hashability** so objects work in `set`/`dict` keys  
- **Pitfalls** (mutable containers inside “frozen” objects)

Save as `immutable_demo.py` and run with `python immutable_demo.py`.

```python
# immutable_demo.py
from __future__ import annotations

from dataclasses import dataclass, field, replace
from typing import Tuple, FrozenSet, Iterable
import copy


# --------------------------------------------------------------------------- #
# 1. Low-level immutable object: slots + setattr guard                         #
# --------------------------------------------------------------------------- #
class Point:
    """An immutable 2-D point. Uses __slots__ to prevent arbitrary attributes."""
    __slots__ = ("x", "y")

    def __init__(self, x: float, y: float):
        # Bypass the guard during construction
        object.__setattr__(self, "x", x)
        object.__setattr__(self, "y", y)

    # --- mutation is forbidden ------------------------------------------------
    def __setattr__(self, name, value):
        raise AttributeError(f"Cannot set attribute {name!r} on immutable {type(self).__name__}")

    def __delattr__(self, name):
        raise AttributeError(f"Cannot delete attribute {name!r} on immutable {type(self).__name__}")

    # --- value semantics ------------------------------------------------------
    def __repr__(self) -> str:
        return f"Point({self.x!r}, {self.y!r})"

    def __eq__(self, other) -> bool:
        return type(self) is type(other) and (self.x, self.y) == (other.x, other.y)

    def __hash__(self) -> int:
        return hash((self.x, self.y))

    # --- functional updates (return NEW instances) ----------------------------
    def translate(self, dx: float = 0.0, dy: float = 0.0) -> "Point":
        return Point(self.x + dx, self.y + dy)

    def scale(self, factor: float) -> "Point":
        return Point(self.x * factor, self.y * factor)


# --------------------------------------------------------------------------- #
# 2. Frozen dataclass with validation                                         #
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Money:
    """Immutable money value. 'frozen=True' blocks reassignment of fields."""
    amount: int          # minor units (e.g. cents)
    currency: str

    def __post_init__(self):
        if self.amount < 0:
            raise ValueError("amount must be non-negative")
        if not (isinstance(self.currency, str) and len(self.currency) == 3):
            raise ValueError("currency must be a 3-letter code")

    def add(self, other: "Money") -> "Money":
        if self.currency != other.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")
        return Money(self.amount + other.amount, self.currency)

    def with_amount(self, new_amount: int) -> "Money":
        # Functional update; dataclass 'replace' is also available
        return replace(self, amount=new_amount)


# --------------------------------------------------------------------------- #
# 3. Deep immutability: an immutable polygon                                  #
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Polygon:
    """An immutable polygon. Points are stored as a tuple (immutable sequence)."""
    points: Tuple[Point, ...]

    def __post_init__(self):
        # Coerce any iterable into a tuple. Because the dataclass is frozen,
        # we must use object.__setattr__ to replace the field.
        object.__setattr__(self, "points", tuple(self.points))

        if len(self.points) < 3:
            raise ValueError("a polygon needs at least 3 points")

        for p in self.points:
            if not isinstance(p, Point):
                raise TypeError(f"expected Point, got {type(p).__name__}")

    def translated(self, dx: float = 0.0, dy: float = 0.0) -> "Polygon":
        return Polygon(tuple(p.translate(dx, dy) for p in self.points))

    def closed(self) -> bool:
        return self.points[0] == self.points[-1]


# --------------------------------------------------------------------------- #
# 4. Immutable set-like collection (frozenset of immutable tags)               #
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class TaggedItem:
    name: str
    tags: FrozenSet[str] = field(default_factory=frozenset)

    def with_tag(self, tag: str) -> "TaggedItem":
        return replace(self, tags=self.tags | {tag})

    def without_tag(self, tag: str) -> "TaggedItem":
        return replace(self, tags=self.tags - {tag})


# --------------------------------------------------------------------------- #
# Demo / tests                                                                #
# --------------------------------------------------------------------------- #
def main():
    # --- Point ---------------------------------------------------------------
    p = Point(3.0, 4.0)
    q = p.translate(1, -1)
    print("p =", p)
    print("q =", q)
    print("p unchanged after translate:", p)

    try:
        p.x = 99
    except AttributeError as exc:
        print("mutation blocked:", exc)

    # Hashability: usable as dict keys / set members
    points_set = {p, q, Point(3.0, 4.0)}
    print("set size (duplicate collapsed):", len(points_set))

    # --- Money ---------------------------------------------------------------
    a = Money(1000, "USD")   # $10.00
    b = Money(250, "USD")    # $2.50
    total = a.add(b)
    print("total =", total)
    print("a unchanged:", a)

    try:
        a.amount = 0
    except Exception as exc:     # FrozenInstanceError is a subclass of AttributeError
        print("frozen dataclass blocks assignment:", type(exc).__name__, exc)

    try:
        Money(-1, "USD")
    except ValueError as exc:
        print("validation blocked:", exc)

    # Functional update
    discounted = total.with_amount(int(total.amount * 0.9))
    print("discounted:", discounted)

    # --- Polygon (deep immutability) ----------------------------------------
    poly = Polygon((Point(0, 0), Point(10, 0), Point(10, 10), Point(0, 10)))
    moved = poly.translated(5, 5)
    print("original first point:", poly.points[0])
    print("moved first point:   ", moved.points[0])

    # Even though points is a tuple, elements are themselves immutable
    try:
        poly.points[0].x = 1
    except AttributeError as exc:
        print("deep mutation blocked:", exc)

    # --- TaggedItem (frozenset) ---------------------------------------------
    item = TaggedItem("widget", frozenset({"blue", "small"}))
    item2 = item.with_tag("sale")
    print("item  (original):", item)
    print("item2 (new):     ", item2)
    print("original unchanged:", item)

    # --- Copying semantics ---------------------------------------------------
    # Immutable objects don't need defensive copies
    alias = poly
    print("alias is poly (same object, safe):", alias is poly)

    # But if you *want* a shallow copy of a mutable wrapper, copy works fine
    mutable_wrapper = {"poly": poly}
    copied = copy.copy(mutable_wrapper)
    print("copied dict shares immutable poly:", copied["poly"] is poly)


if __name__ == "__main__":
    main()
```

### Key takeaways

1. **True immutability is by contract, not by the compiler.** Python has no `const` keyword; we enforce it with `__slots__`, overridden `__setattr__`/`__delattr__`, and `frozen=True` dataclasses.
2. **Deep immutability matters.** A frozen dataclass holding a `list` is still effectively mutable. Use `tuple`, `frozenset`, and immutable elements throughout.
3. **Functional updates** (`translate`, `add`, `with_tag`, `replace(...)`) are the idiomatic way to “modify” immutable objects—return a new instance instead of mutating.
4. **Hashability** comes for free once you implement `__eq__` + `__hash__` (or use frozen dataclasses), letting immutable objects act as `dict` keys and `set` members.
5. **Validation** belongs in `__init__` / `__post_init__`, guaranteeing every instance is valid for its entire lifetime.
6. **No defensive copying needed.** Because the state can never change, sharing references is always safe (great for concurrency and caching).

## Immutability in Python (interview-style)

### What it means
An **immutable object** is one whose state cannot change after it is created.  
In Python the built-in immutable types include `int`, `str`, `bytes`, `tuple`, `frozenset`. Mutable ones include `list`, `dict`, `set`.

Why it matters:
- **Hashability** → can be used as `dict` keys / `set` elements.
- **Thread safety** → no locks needed for reads.
- **Predictability** → no “action at a distance” when an object is shared.
- **Caching / memoization** → immutable results are safe to cache.

Important subtlety: *a tuple is immutable, but its elements may be mutable*:
```python
t = ([1, 2],)
t[0].append(3)   # t is still the same tuple object, but its contents changed
```
So “immutable” in Python usually means **shallow** immutability unless you explicitly deep-freeze.

### How to implement immutability
Common approaches:
1. **Freeze after construction** – build in `__init__`, then forbid mutation.
2. **Functional updates** – “mutating” returns a *new* object instead of changing the old one.
3. **Persistent data structures** – structural sharing (e.g., cons-lists) to make copies cheap.
4. **Recursive deep-freeze** – convert `list→tuple`, `dict→FrozenDict`, etc.

Below is a small, self-contained “core” implementation: a `FrozenDict`, a persistent immutable list (`IList`), and a recursive `freeze()` helper.

```python
from __future__ import annotations
from typing import Any, Iterable, Iterator, Tuple


# ---------------------------------------------------------------------------
# 1) FrozenDict: immutable mapping with functional update
# ---------------------------------------------------------------------------
class FrozenDict:
    """An immutable dictionary. Mutations return a new FrozenDict."""

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        # Always store a private copy so callers can't mutate our internals.
        self._data: dict[Any, Any] = dict(*args, **kwargs)

    # ---- read-only access --------------------------------------------------
    def __getitem__(self, key: Any) -> Any:
        return self._data[key]

    def get(self, key: Any, default: Any = None) -> Any:
        return self._data.get(key, default)

    def __len__(self) -> int:
        return len(self._data)

    def __contains__(self, key: Any) -> bool:
        return key in self._data

    def __iter__(self) -> Iterator[Any]:
        return iter(self._data)

    def items(self) -> Iterable[Tuple[Any, Any]]:
        return self._data.items()

    def keys(self) -> Iterable[Any]:
        return self._data.keys()

    def values(self) -> Iterable[Any]:
        return self._data.values()

    # ---- mutation is forbidden --------------------------------------------
    def __setitem__(self, key: Any, value: Any) -> None:
        raise TypeError("FrozenDict is immutable")

    def __delitem__(self, key: Any) -> None:
        raise TypeError("FrozenDict is immutable")

    # ---- functional update: returns a NEW object ---------------------------
    def with_(self, **updates: Any) -> "FrozenDict":
        """Return a new FrozenDict with the given keys overwritten."""
        new_data = dict(self._data)
        new_data.update(updates)
        return FrozenDict(new_data)

    def without(self, *keys: Any) -> "FrozenDict":
        """Return a new FrozenDict with the given keys removed."""
        new_data = {k: v for k, v in self._data.items() if k not in keys}
        return FrozenDict(new_data)

    # ---- value semantics ---------------------------------------------------
    def __eq__(self, other: Any) -> bool:
        if isinstance(other, FrozenDict):
            return self._data == other._data
        if isinstance(other, dict):
            return self._data == other
        return NotImplemented

    def __hash__(self) -> int:
        # Hashable only if all values are hashable; otherwise raise naturally.
        return hash(frozenset(self._data.items()))

    def __repr__(self) -> str:
        return f"FrozenDict({self._data!r})"


# ---------------------------------------------------------------------------
# 2) IList: persistent (structural-sharing) immutable list
#    Prepend is O(1); the rest is shared rather than copied.
# ---------------------------------------------------------------------------
class IList:
    """Immutable singly-linked list. Empty list is represented by None."""

    __slots__ = ("_head", "_tail")

    def __init__(self, head: Any, tail: "IList | None") -> None:
        self._head = head
        self._tail = tail

    # ---- constructors ------------------------------------------------------
    @classmethod
    def empty(cls) -> None:
        return None

    @classmethod
    def from_iterable(cls, items: Iterable[Any]) -> "IList | None":
        # Build by prepending in reverse to keep O(n) total.
        result: "IList | None" = None
        for item in reversed(list(items)):
            result = cls(item, result)
        return result

    # ---- read-only access --------------------------------------------------
    def head(self) -> Any:
        if self._tail is None and self._head is None:  # not strictly needed
            raise IndexError("head of empty list")
        return self._head

    def tail(self) -> "IList | None":
        return self._tail

    def is_empty(self) -> bool:
        return False  # instance is never empty; None represents empty

    def __len__(self) -> int:
        n, cur = 0, self
        while cur is not None:
            n += 1
            cur = cur._tail
        return n

    def __getitem__(self, index: int) -> Any:
        if index < 0:
            index += len(self)
        cur = self
        i = 0
        while cur is not None:
            if i == index:
                return cur._head
            cur = cur._tail
            i += 1
        raise IndexError("index out of range")

    def __iter__(self) -> Iterator[Any]:
        cur = self
        while cur is not None:
            yield cur._head
            cur = cur._tail

    # ---- functional "mutation" --------------------------------------------
    def cons(self, value: Any) -> "IList":
        """Prepend value, returning a new list (O(1), shares tail)."""
        return IList(value, self)

    def append(self, value: Any) -> "IList":
        """Return a new list with value appended (O(n))."""
        if self._tail is None and False:
            pass
        # Rebuild from the end; simple, clear, not optimal for huge lists.
        return IList.from_iterable(list(self) + [value])

    def __repr__(self) -> str:
        return "IList(" + ", ".join(repr(x) for x in self) + ")"


# Make None behave as the empty list for convenience.
def is_empty(lst: "IList | None") -> bool:
    return lst is None


# ---------------------------------------------------------------------------
# 3) Recursive deep-freeze: turn mutable containers into immutable ones
# ---------------------------------------------------------------------------
def freeze(obj: Any) -> Any:
    """Recursively convert mutable containers to immutable equivalents."""
    if isinstance(obj, dict):
        return FrozenDict({k: freeze(v) for k, v in obj.items()})
    if isinstance(obj, list):
        return tuple(freeze(x) for x in obj)
    if isinstance(obj, set):
        return frozenset(freeze(x) for x in obj)
    if isinstance(obj, tuple):
        return tuple(freeze(x) for x in obj)
    # strings, numbers, None, already-immutable objects pass through
    return obj


# ---------------------------------------------------------------------------
# Demo / smoke tests
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    # FrozenDict
    d = FrozenDict({"a": [1, 2], "b": 3})
    print(d)                       # FrozenDict({'a': [1, 2], 'b': 3})
    d2 = d.with_(b=99, c=7)       # functional update
    print(d2)                      # original `d` unchanged
    print(d == {"a": [1, 2], "b": 3})
    try:
        d["a"] = 0
    except TypeError as e:
        print("mutation blocked:", e)

    # Deep freeze
    frozen = freeze({"nums": [1, 2, 3], "tags": {"x", "y"}})
    print(frozen)                 # FrozenDict({... tuples/frozensets ...})
    print(hash(frozen))           # hashable because fully frozen

    # Persistent list
    lst = IList.from_iterable([1, 2, 3])
    lst2 = lst.cons(0)            # shares tail with lst
    print(lst)                    # IList(1, 2, 3)
    print(lst2)                   # IList(0, 1, 2, 3)
    print(list(lst))              # original unchanged
    print(lst[1], lst2[0])
```

### Notes / interview talking points
- `FrozenDict.__hash__` relies on values being hashable; calling `hash()` on a `FrozenDict` containing an un-hashable value will raise — exactly the contract Python expects.
- The persistent list uses **structural sharing**: `cons` is O(1) and shares the tail, so memory stays O(n) across versions. Full `append` is O(n) in this simple version; a production version (e.g., a balanced finger tree) keeps both ends O(log n).
- `freeze()` is **shallow-to-deep**: it only converts containers it recognizes; custom mutable objects need their own `__freeze__` protocol.
- True language-level immutability (like Rust’s `let` or Haskell) isn’t native to Python; we *model* it with discipline + these patterns.

If you want, I can extend this into a `@immutable` decorator that freezes an instance after `__init__`, or show how to integrate with `dataclasses(frozen=True)`.

```python
"""
immutable_structures.py

A small, self-contained library of *persistent* (immutable) data structures.

Design notes
------------
* Every "mutation" returns a NEW object; the original is never changed.
* Structural sharing is used where it is cheap and simple:
    - PList  : cons-list (O(1) prepend, O(n) append/index)
    - PDict  : copy-on-write dict (O(n) update, simple and predictable)
    - PSet   : frozenset-backed (leverages C-level immutability)
* All three are hashable and can be used as dict keys / set members.

Run with:  python immutable_structures.py
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from types import MappingProxyType
from typing import Any, Callable, Iterator


# --------------------------------------------------------------------------- #
# 1. Persistent linked list
# --------------------------------------------------------------------------- #
class PList:
    """Immutable singly-linked list with structural sharing."""

    __slots__ = ("_head", "_tail", "_len", "_hash", "_empty")

    def __init__(self, head: Any = None, tail: "PList | None" = None, *, empty: bool = False):
        object.__setattr__(self, "_empty", empty)
        if empty:
            object.__setattr__(self, "_head", None)
            object.__setattr__(self, "_tail", None)
            object.__setattr__(self, "_len", 0)
        else:
            if tail is None:
                tail = PList(empty=True)
            object.__setattr__(self, "_head", head)
            object.__setattr__(self, "_tail", tail)
            object.__setattr__(self, "_len", 1 + tail._len)
        object.__setattr__(self, "_hash", None)

    # --- immutability guard ------------------------------------------------ #
    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("PList is immutable")

    # --- factories --------------------------------------------------------- #
    @classmethod
    def empty(cls) -> "PList":
        return cls.EMPTY  # set below after class creation

    @classmethod
    def from_iterable(cls, iterable: Iterable[Any]) -> "PList":
        items = list(iterable)
        result = cls.empty()
        for x in reversed(items):
            result = cls(x, result)
        return result

    # --- basic access ------------------------------------------------------ #
    @property
    def is_empty(self) -> bool:
        return self._empty

    @property
    def head(self) -> Any:
        if self._empty:
            raise IndexError("head of empty PList")
        return self._head

    @property
    def tail(self) -> "PList":
        if self._empty:
            raise IndexError("tail of empty PList")
        return self._tail

    def __len__(self) -> int:
        return self._len

    def __iter__(self) -> Iterator[Any]:
        node = self
        while not node._empty:
            yield node._head
            node = node._tail

    def __getitem__(self, index: Any) -> Any:
        if isinstance(index, slice):
            return PList.from_iterable(list(self)[index])
        idx = index if index >= 0 else self._len + index
        if idx < 0 or idx >= self._len:
            raise IndexError("PList index out of range")
        node = self
        for _ in range(idx):
            node = node._tail
        return node._head

    # --- persistent operations -------------------------------------------- #
    def cons(self, value: Any) -> "PList":
        """Prepend (O(1), shares the old list)."""
        return PList(value, self)

    def prepend(self, value: Any) -> "PList":
        return self.cons(value)

    def append(self, value: Any) -> "PList":
        if self._empty:
            return PList(value)
        return PList.from_iterable(list(self) + [value])

    def concat(self, other: "PList | Iterable[Any]") -> "PList":
        if not isinstance(other, PList):
            other = PList.from_iterable(other)
        if self._empty:
            return other
        if other._empty:
            return self
        return PList.from_iterable(list(self) + list(other))

    def map(self, f: Callable[[Any], Any]) -> "PList":
        return PList.from_iterable(f(x) for x in self)

    def filter(self, pred: Callable[[Any], bool]) -> "PList":
        return PList.from_iterable(x for x in self if pred(x))

    def to_tuple(self) -> tuple[Any, ...]:
        return tuple(self)

    # --- value semantics --------------------------------------------------- #
    def __eq__(self, other: Any) -> bool:
        if self is other:
            return True
        if isinstance(other, PList):
            if self._len != other._len:
                return False
            return all(a == b for a, b in zip(self, other))
        if isinstance(other, (list, tuple)):
            if len(other) != self._len:
                return False
            return all(a == b for a, b in zip(self, other))
        return NotImplemented

    def __hash__(self) -> int:
        if self._hash is None:
            object.__setattr__(self, "_hash", hash(tuple(self)))
        return self._hash

    def __repr__(self) -> str:
        return f"PList({list(self)!r})"


# set the empty singleton after the class exists
PList.EMPTY = PList(empty=True)


# --------------------------------------------------------------------------- #
# 2. Persistent dict (copy-on-write)
# --------------------------------------------------------------------------- #
class PDict:
    """Immutable dict. Updates return a new PDict."""

    __slots__ = ("_data", "_hash")

    def __init__(self, data: Mapping[Any, Any] | None = None, **kwargs: Any):
        d: dict[Any, Any] = {}
        if data is not None:
            d.update(data)
        if kwargs:
            d.update(kwargs)
        object.__setattr__(self, "_data", d)
        object.__setattr__(self, "_hash", None)

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("PDict is immutable")

    # --- access ----------------------------------------------------------- #
    def get(self, key: Any, default: Any = None) -> Any:
        return self._data.get(key, default)

    def __getitem__(self, key: Any) -> Any:
        if key not in self._data:
            raise KeyError(key)
        return self._data[key]

    def __contains__(self, key: Any) -> bool:
        return key in self._data

    def __len__(self) -> int:
        return len(self._data)

    def __iter__(self) -> Iterator[Any]:
        return iter(self._data)

    def keys(self):
        return self._data.keys()

    def values(self):
        return self._data.values()

    def items(self):
        return self._data.items()

    # --- persistent operations -------------------------------------------- #
    def assoc(self, key: Any, value: Any) -> "PDict":
        new = dict(self._data)
        new[key] = value
        return PDict(new)

    def dissoc(self, key: Any) -> "PDict":
        if key not in self._data:
            return self
        new = dict(self._data)
        del new[key]
        return PDict(new)

    def merge(self, other: "PDict | Mapping[Any, Any]") -> "PDict":
        new = dict(self._data)
        src = other._data if isinstance(other, PDict) else other
        new.update(src)
        return PDict(new)

    # --- value semantics --------------------------------------------------- #
    def __eq__(self, other: Any) -> bool:
        if self is other:
            return True
        if isinstance(other, PDict):
            return self._data == other._data
        if isinstance(other, Mapping):
            return self._data == dict(other)
        return NotImplemented

    def __hash__(self) -> int:
        if self._hash is None:
            object.__setattr__(self, "_hash", hash(frozenset(self._data.items())))
        return self._hash

    def __repr__(self) -> str:
        return f"PDict({self._data!r})"


# --------------------------------------------------------------------------- #
# 3. Persistent set (frozenset-backed)
# --------------------------------------------------------------------------- #
class PSet:
    """Immutable set with value semantics."""

    __slots__ = ("_data",)

    def __init__(self, iterable: Iterable[Any] | None = None):
        fs = frozenset(iterable) if iterable is not None else frozenset()
        object.__setattr__(self, "_data", fs)

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("PSet is immutable")

    def __contains__(self, value: Any) -> bool:
        return value in self._data

    def __iter__(self) -> Iterator[Any]:
        return iter(self._data)

    def __len__(self) -> int:
        return len(self._data)

    def add(self, value: Any) -> "PSet":
        return PSet(self._data | {value})

    def remove(self, value: Any) -> "PSet":
        if value not in self._data:
            raise KeyError(value)
        return PSet(self._data - {value})

    def discard(self, value: Any) -> "PSet":
        return PSet(self._data - {value})

    def union(self, other: "PSet | Iterable[Any]") -> "PSet":
        other_fs = other._data if isinstance(other, PSet) else frozenset(other)
        return PSet(self._data | other_fs)

    def intersection(self, other: "PSet | Iterable[Any]") -> "PSet":
        other_fs = other._data if isinstance(other, PSet) else frozenset(other)
        return PSet(self._data & other_fs)

    def difference(self, other: "PSet | Iterable[Any]") -> "PSet":
        other_fs = other._data if isinstance(other, PSet) else frozenset(other)
        return PSet(self._data - other_fs)

    def __eq__(self, other: Any) -> bool:
        if self is other:
            return True
        if isinstance(other, PSet):
            return self._data == other._data
        if isinstance(other, (set, frozenset)):
            return self._data == frozenset(other)
        return NotImplemented

    def __hash__(self) -> int:
        return hash(self._data)

    def __repr__(self) -> str:
        return f"PSet({set(self._data)!r})"


# --------------------------------------------------------------------------- #
# Demo / smoke tests
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Point:
    x: float
    y: float


def demo() -> None:
    print("=== PList ===")
    xs = PList.from_iterable([1, 2, 3])
    ys = xs.cons(0).append(4)
    print("xs =", xs)
    print("ys =", ys)
    assert list(xs) == [1, 2, 3]
    assert list(ys) == [0, 1, 2, 3, 4]
    assert xs[1] == 2
    assert ys[-1] == 4
    assert xs.map(lambda x: x * 10) == PList.from_iterable([10, 20, 30])
    assert xs.filter(lambda x: x > 1) == PList.from_iterable([2, 3])

    print("\n=== PDict ===")
    cart = PDict({"apples": 2})
    cart2 = cart.assoc("oranges", 3).assoc("apples", 5)
    print("cart  =", cart)
    print("cart2 =", cart2)
    assert cart == PDict({"apples": 2})
    assert cart2["apples"] == 5 and cart2["oranges"] == 3
    assert "bananas" not in cart2

    cart3 = cart2.dissoc("oranges")
    assert cart3 == PDict({"apples": 5})
    assert cart2 == PDict({"apples": 5, "oranges": 3})  # original unchanged

    merged = cart.merge({"bananas": 1})
    assert merged == PDict({"apples": 2, "bananas": 1})

    print("\n=== PSet ===")
    s = PSet([1, 2])
    s2 = s.add(3).remove(1)
    print("s  =", s)
    print("s2 =", s2)
    assert s == PSet([1, 2])
    assert s2 == PSet([2, 3])
    assert s.union(s2) == PSet([1, 2, 3])

    print("\n=== hashability (usable as dict keys) ===")
    lookup = {xs: "the original list", ys: "extended list"}
    assert lookup[xs] == "the original list"
    point_set = {Point(1.0, 2.0), Point(1.0, 2.0)}
    assert len(point_set) == 1

    print("\n=== built-in immutable helpers ===")
    readonly_view = MappingProxyType({"a": 1})
    print("MappingProxyType:", readonly_view)
    try:
        readonly_view["a"] = 2
    except TypeError as e:
        print("rejected mutation:", e)

    print("\nAll assertions passed.")


if __name__ == "__main__":
    demo()
```

## Exercise

Build two immutable value objects in Python:

1. **`Rectangle`** with `width` and `height` (positive numbers).
2. **`Canvas`** with a tuple of `Rectangle`s and a frozenset of string tags.

Requirements:

- Instances must be **hashable** and support **structural equality**.
- All mutation must happen by **returning new instances** (copy-on-write).
- Nested containers must themselves be immutable (`tuple`, `frozenset`).
- Invalid data must be rejected at construction time.
- Provide helper methods:
  - `Rectangle.scale(factor)` → new scaled rectangle
  - `Canvas.add_rectangle(rect)` → new canvas with rect appended
  - `Canvas.with_tag(tag)` → new canvas with tag added

---

## Step-by-step solution

### Step 1 — Choose the right building blocks

Python’s standard immutable containers are:

- `tuple` instead of `list`
- `frozenset` instead of `set`
- `dataclasses.dataclass(frozen=True)` for immutable records
- `dataclasses.replace` for copy-on-write updates

A frozen dataclass automatically generates `__eq__` and, when safe, `__hash__`. Because all fields here are tuples, frozensets, numbers, and strings, hashing works.

### Step 2 — Define `Rectangle`

Use `frozen=True` and validate in `__post_init__`.

```python
from dataclasses import dataclass, replace

@dataclass(frozen=True, slots=True)
class Rectangle:
    width: float
    height: float

    def __post_init__(self) -> None:
        if self.width <= 0 or self.height <= 0:
            raise ValueError("Rectangle dimensions must be positive")

    def area(self) -> float:
        return self.width * self.height

    def scale(self, factor: float) -> "Rectangle":
        if factor <= 0:
            raise ValueError("scale factor must be positive")
        return replace(self, width=self.width * factor, height=self.height * factor)
```

Why this works:

- `frozen=True` prevents `rect.width = ...`.
- `slots=True` reduces memory and prevents arbitrary attribute creation.
- `replace` creates a new object instead of mutating.

### Step 3 — Define `Canvas`

Accept broad inputs, but normalize them to immutable containers.

```python
from collections.abc import Iterable

@dataclass(frozen=True, slots=True)
class Canvas:
    rectangles: tuple[Rectangle, ...] = ()
    tags: frozenset[str] = frozenset()

    def __post_init__(self) -> None:
        # Normalize any iterable input into immutable containers.
        object.__setattr__(self, "rectangles", tuple(self.rectangles))
        object.__setattr__(self, "tags", frozenset(self.tags))

        # Validate contents.
        if not all(isinstance(r, Rectangle) for r in self.rectangles):
            raise TypeError("rectangles must contain Rectangle instances")
        if not all(isinstance(t, str) for t in self.tags):
            raise TypeError("tags must be strings")

    def add_rectangle(self, rect: Rectangle) -> "Canvas":
        if not isinstance(rect, Rectangle):
            raise TypeError("rect must be a Rectangle")
        return replace(self, rectangles=self.rectangles + (rect,))

    def with_tag(self, tag: str) -> "Canvas":
        if not isinstance(tag, str):
            raise TypeError("tag must be a string")
        return replace(self, tags=self.tags | {tag})

    def total_area(self) -> float:
        return sum(r.area() for r in self.rectangles)
```

Important detail:

Inside a frozen dataclass, you cannot normally assign fields. During `__post_init__`, we use `object.__setattr__` only to normalize inputs before the object is considered fully constructed. After construction, direct assignment remains blocked.

### Step 4 — Demonstrate usage and safety

```python
r1 = Rectangle(2, 3)
r2 = r1.scale(2)          # new object; r1 is unchanged
print(r1, r2)             # Rectangle(width=2, height=3) Rectangle(width=4, height=6)

c1 = Canvas([r1], {"draft"})
c2 = c1.add_rectangle(r2).with_tag("final")

print(c1.rectangles)       # (Rectangle(...),)
print(c2.rectangles)       # (Rectangle(...), Rectangle(...))
print(c1.tags)             # frozenset({'draft'})
print(c2.tags)             # frozenset({'final', 'draft'})

# Hashability / equality
print(hash(c1) == hash(Canvas([r1], {"draft"})))  # True
print(c1 == Canvas([r1], {"draft"}))              # True

# Mutation is blocked
try:
    r1.width = 10
except Exception as e:
    print(type(e).__name__, e)  # FrozenInstanceError ...

try:
    c1.rectangles.append(r2)
except Exception as e:
    print(type(e).__name__, e)  # AttributeError ...
```

### Step 5 — Why this matters

- **Safety**: no accidental shared mutable state.
- **Reasoning**: object identity and value are easier to track.
- **Concurrency**: immutable values can be shared across threads without locks.
- **Caching/memoization**: hashable objects can be dictionary keys.

Limitation: copy-on-write creates new objects. For large structures or frequent updates, persistent data structures from libraries such as `pyrsistent` or `immutables` may be more efficient.

