## Final solution

```python
from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass, replace


@dataclass(frozen=True, slots=True)
class Rectangle:
    width: float
    height: float

    def __post_init__(self) -> None:
        if self.width <= 0 or self.height <= 0:
            raise ValueError("Rectangle dimensions must be positive")

    def area(self) -> float:
        return self.width * self.height

    def scale(self, factor: float) -> Rectangle:
        if factor <= 0:
            raise ValueError("scale factor must be positive")
        return replace(self, width=self.width * factor, height=self.height * factor)


@dataclass(frozen=True, slots=True)
class Canvas:
    rectangles: tuple[Rectangle, ...] = ()
    tags: frozenset[str] = frozenset()

    def __post_init__(self) -> None:
        object.__setattr__(self, "rectangles", tuple(self.rectangles))
        object.__setattr__(self, "tags", frozenset(self.tags))

        if not all(isinstance(r, Rectangle) for r in self.rectangles):
            raise TypeError("rectangles must contain Rectangle instances only")
        if not all(isinstance(t, str) for t in self.tags):
            raise TypeError("tags must contain strings only")

    def add_rectangle(self, rect: Rectangle) -> Canvas:
        if not isinstance(rect, Rectangle):
            raise TypeError("rect must be a Rectangle")
        return replace(self, rectangles=self.rectangles + (rect,))

    def with_tag(self, tag: str) -> Canvas:
        if not isinstance(tag, str):
            raise TypeError("tag must be a string")
        return replace(self, tags=self.tags | {tag})

    def total_area(self) -> float:
        return sum(rect.area() for rect in self.rectangles)


if __name__ == "__main__":
    rect = Rectangle(3, 4)
    bigger = rect.scale(2)

    canvas = Canvas([rect], {"sketch"})
    canvas = canvas.add_rectangle(bigger).with_tag("reviewed")

    print(rect)
    print(bigger)
    print(canvas)
    print("total area:", canvas.total_area())
    print("hashable:", hash(canvas))
    print("equal:", canvas == Canvas([rect, bigger], {"sketch", "reviewed"}))
```

Immutable data structures are objects whose state cannot change after creation. In Python, instead of mutating them, every “update” returns a new object while sharing unchanged parts internally. This gives you hashability, safe sharing across threads/tasks, predictable behavior in caches and sets, and easier reasoning about data flow.

Python already has several immutable built-ins: `str`, `bytes`, `tuple`, `frozenset`, `frozenset`-based ranges, `namedtuple`, and `types.MappingProxyType`. For records, `@dataclass(frozen=True)` and `typing.NamedTuple` are common. Those are mostly *flat* or copy-on-write-ish, not necessarily persistent. The more powerful idea is **persistent** data structures: new versions share most of their structure with old versions, so updates are cheap and old versions remain valid.

Below is a clean implementation of a persistent singly-linked list. It demonstrates the core mechanics: structural sharing, no mutation, cached metadata, equality, hashing, and functional updates.

```python
from __future__ import annotations

from typing import Any, Callable, Iterable, Iterator, TypeVar

T = TypeVar("T")


class _EmptyList:
    """Sentinel representing the empty persistent list.

    Using a dedicated empty object avoids ambiguity with ``None`` or
    falsy values that may legitimately be stored in the list.
    """

    __slots__ = ()

    def __len__(self) -> int:
        return 0

    def __iter__(self) -> Iterator[Any]:
        return iter(())

    def __eq__(self, other: object) -> bool:
        # The empty list is equal only to another empty list.
        return isinstance(other, _EmptyList)

    def __hash__(self) -> int:
        return hash(("empty",))

    def __repr__(self) -> str:
        return "ImmutableList([])"

    # Functional operations
    def cons(self, value: T) -> "ImmutableList[T]":
        """Return a new list with ``value`` prepended."""
        return ImmutableList(value, self)

    def head(self) -> Any:
        raise IndexError("head of empty list")

    def tail(self) -> "_EmptyList":
        raise IndexError("tail of empty list")

    def to_tuple(self) -> tuple[Any, ...]:
        return ()


# Singleton empty list. Reusing one object is safe because it is immutable.
EMPTY: _EmptyList = _EmptyList()


class ImmutableList:
    """A persistent (immutable) singly-linked list.

    Each node stores one value and a reference to the rest of the list.
    Prepending is O(1) and shares the old tail. Other operations may cost
    O(n), but they never mutate an existing list.
    """

    __slots__ = ("_value", "_rest", "_length", "_cached_hash")

    def __init__(self, value: T, rest: ImmutableList[T] | _EmptyList = EMPTY):
        self._value = value
        self._rest = rest
        # Cache length once: every node's length is 1 + tail length.
        self._length = 1 + len(rest)
        self._cached_hash: int | None = None

    # ------------------------------------------------------------------ #
    # Construction / basic access
    # ------------------------------------------------------------------ #

    def cons(self, value: T) -> "ImmutableList[T]":
        """Return a new list with ``value`` prepended. O(1)."""
        return ImmutableList(value, self)

    @property
    def head(self) -> T:
        """First element. O(1)."""
        return self._value

    @property
    def tail(self) -> "ImmutableList[T] | _EmptyList":
        """Rest of the list. O(1)."""
        return self._rest

    def is_empty(self) -> bool:
        return False

    # ------------------------------------------------------------------ #
    # Container protocol
    # ------------------------------------------------------------------ #

    def __len__(self) -> int:
        return self._length

    def __iter__(self) -> Iterator[T]:
        node: ImmutableList[T] | _EmptyList = self
        while node is not EMPTY:
            assert isinstance(node, ImmutableList)
            yield node._value
            node = node._rest

    def __getitem__(self, index: int) -> T:
        if index < 0:
            index += self._length
        if index < 0 or index >= self._length:
            raise IndexError("index out of range")

        node: ImmutableList[T] | _EmptyList = self
        for _ in range(index):
            assert isinstance(node, ImmutableList)
            node = node._rest
        assert isinstance(node, ImmutableList)
        return node._value

    def __contains__(self, value: object) -> bool:
        return any(existing == value for existing in self)

    def __repr__(self) -> str:
        return f"ImmutableList({list(self)!r})"

    # ------------------------------------------------------------------ #
    # Value semantics
    # ------------------------------------------------------------------ #

    def __eq__(self, other: object) -> bool:
        if self is other:
            return True
        if not isinstance(other, (ImmutableList, _EmptyList)):
            return NotImplemented
        if len(self) != len(other):
            return False
        # Compare element by element. Lengths are already known to match.
        return all(a == b for a, b in zip(self, other))

    def __hash__(self) -> int:
        # Lazily cache the hash. Elements must be hashable.
        if self._cached_hash is None:
            # Hashing the tail recursively is fine because the structure
            # is immutable; the result cannot change.
            self._cached_hash = hash((self._value, self._rest))
        return self._cached_hash

    # ------------------------------------------------------------------ #
    # Functional transformations (return new lists)
    # ------------------------------------------------------------------ #

    def append(self, value: T) -> "ImmutableList[T]":
        """Return a new list with ``value`` added at the end. O(n)."""
        # Rebuild from the tail upward; the original list is untouched.
        result: ImmutableList[T] | _EmptyList = EMPTY.cons(value)
        # Walk backwards conceptually by collecting then cons-ing.
        collected: list[T] = list(self)
        # Build in reverse to keep O(n) total work.
        new_list: ImmutableList[T] | _EmptyList = EMPTY
        for item in reversed(collected + [value]):
            new_list = new_list.cons(item) if isinstance(new_list, _EmptyList) else ImmutableList(item, new_list)
        # The above branch is defensive; simplify:
        new_list = EMPTY
        for item in reversed(collected + [value]):
            new_list = ImmutableList(item, new_list)
        return new_list  # type: ignore[return-value]

    def map(self, fn: Callable[[T], Any]) -> "ImmutableList[Any]":
        """Return a new list with ``fn`` applied to every element. O(n)."""
        return ImmutableList._from_iterable(fn(x) for x in reversed(list(self)))

    @staticmethod
    def _from_iterable(values: Iterable[T]) -> "ImmutableList[T] | _EmptyList":
        result: ImmutableList[T] | _EmptyList = EMPTY
        for value in values:
            result = ImmutableList(value, result)
        return result

    def filter(self, pred: Callable[[T], bool]) -> "ImmutableList[T]":
        """Return a new list containing only elements satisfying ``pred``. O(n)."""
        return ImmutableList._from_iterable(x for x in reversed(list(self)) if pred(x))

    def to_tuple(self) -> tuple[Any, ...]:
        return tuple(self)

    # ------------------------------------------------------------------ #
    # Convenience constructors
    # ------------------------------------------------------------------ #

    @classmethod
    def from_iterable(cls, values: Iterable[T]) -> "ImmutableList[T] | _EmptyList":
        """Build a list from an iterable. O(n)."""
        return cls._from_iterable(values)


# Make EMPTY's type hint-friendly alias.
EmptyList = _EmptyList
```

### Example usage

```python
original = ImmutableList.from_iterable([1, 2, 3])

# Prepending does not mutate the original.
extended = original.cons(0)
print(original)   # ImmutableList([1, 2, 3])
print(extended)   # ImmutableList([0, 1, 2, 3])

# Hashable, so usable in sets and as dict keys.
lookup = {original: "original", extended: "extended"}
print(lookup[original])  # "original"

# Functional transformations return new lists.
doubled = original.map(lambda x: x * 2)
evens = original.filter(lambda x: x % 2 == 0)
print(doubled)  # ImmutableList([2, 4, 6])
print(evens)    # ImmutableList([2])

# Structural sharing: tail of extended is exactly original.
assert extended.tail is original
```

### Complexity and design notes

| Operation | Time | Notes |
|---|---:|---|
| `cons` | O(1) | New node points at old tail. |
| `head`, `tail`, `len` | O(1) | Cached length. |
| `indexing` | O(k) | Walk from head. |
| `append` | O(n) | Rebuilds the list; structural sharing of the old node chain is not possible at the end for a singly-linked list. |
| `map`, `filter` | O(n) | New list; old list unchanged. |
| `eq`, `hash` | O(n) | Hash is cached after first computation. |

### Interview talking points

- **Why immutability matters**: hashability, safe concurrency, reproducible state, undo/redo by keeping versions, simpler caching.
- **Persistent vs. immutable**: all persistent structures are immutable, but persistent ones reuse old structure to make updates efficient.
- **Trade-offs**: singly-linked lists are great for stacks and prepending, but poor for random access and end-appending. A real-world choice would be a **persistent vector** (typically a 32-way branching trie) for O(log n) indexing and appending, or a **persistent hash map** for dictionaries.
- **Python-specific pitfalls**: elements must be hashable for the whole structure to be hashable; `__eq__`/`__hash__` must stay consistent; recursive structures can cause infinite recursion or stack overflow in naive implementations.
- **Records**: for small named values, prefer `typing.NamedTuple`, `@dataclass(frozen=True)`, or `attrs`. Implement custom persistent collections only when you need versioned updates with structural sharing.

# Inheritance in Python

Inheritance lets a class (the **subclass**) reuse and extend the behavior of another class (the **base class** / **superclass**). Python supports single inheritance, multiple inheritance, method overriding, `super()`, and abstract methods via the `abc` module.

## 1. Basic Single Inheritance

```python
class Animal:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def speak(self):
        return f"{self.name} makes a sound"

    def __repr__(self):
        return f"Animal(name={self.name!r}, age={self.age})"


class Dog(Animal):                     # Dog is-a Animal
    def __init__(self, name, age, breed):
        super().__init__(name, age)     # delegate to Animal.__init__
        self.breed = breed

    def speak(self):                   # override
        return f"{self.name} barks: Woof!"

    def fetch(self, item):             # new behavior
        return f"{self.name} fetches {item}"


class Cat(Animal):
    def __init__(self, name, age, indoor=True):
        super().__init__(name, age)
        self.indoor = indoor

    def speak(self):
        return f"{self.name} meows: Meow!"


if __name__ == "__main__":
    dog = Dog("Rex", 4, "Labrador")
    cat = Cat("Whiskers", 7)
    print(dog)                # Animal(name='Rex', age=4)  (inherited __repr__)
    print(dog.speak())        # Rex barks: Woof!
    print(dog.fetch("ball"))  # Rex fetches ball
    print(cat.speak())        # Whiskers meows: Meow!

    # isinstance / issubclass checks
    print(isinstance(dog, Animal))   # True
    print(issubclass(Dog, Animal))    # True
    print(type(dog).__mro__)        # (Dog, Animal, object)
```

## 2. `super()` and Cooperative Multiple Inheritance

```python
class A:
    def __init__(self, x, **kwargs):
        super().__init__(**kwargs)
        self.x = x

class B(A):
    def __init__(self, y, **kwargs):
        super().__init__(**kwargs)
        self.y = y

class C(B, A):                 # diamond; MRO handles it
    def __init__(self, z, **kwargs):
        super().__init__(**kwargs)
        self.z = z

# Usage with cooperative forwarding
c = C(x=1, y=2, z=3)
print(c.x, c.y, c.z)           # 1 2 3
print(C.__mro__)
```

## 3. Abstract Base Classes (enforcing an interface)

```python
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self):
        ...

    @abstractmethod
    def perimeter(self):
        ...

    def describe(self):          # concrete, shared
        return f"Shape with area={self.area():.2f}, perimeter={self.perimeter():.2f}"


class Rectangle(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h

    def area(self):
        return self.w * self.h

    def perimeter(self):
        return 2 * (self.w + self.h)


class Circle(Shape):
    import math
    def __init__(self, r):
        self.r = r

    def area(self):
        return math.pi * self.r ** 2

    def perimeter(self):
        return 2 * math.pi * self.r


if __name__ == "__main__":
    r = Rectangle(4, 5)
    c = Circle(3)
    print(r.describe())        # Shape with area=20.00, perimeter=18.00
    print(c.describe())        # Shape with area=28.27, perimeter=18.85
    try:
        Shape()                # TypeError: can't instantiate abstract class
    except TypeError as e:
        print("OK:", e)
```

## 4. Mixins (multiple inheritance for behavior)

```python
class JsonMixin:
    def to_json(self):
        import json
        return json.dumps(self.__dict__)

class ReprMixin:
    def __repr__(self):
        attrs = ", ".join(f"{k}={v!r}" for k, v in self.__dict__.items())
        return f"{type(self).__name__}({attrs})"

class User(JsonMixin, ReprMixin):
    def __init__(self, name, email):
        self.name = name
        self.email = email

u = User("alice", "a@x.com")
print(u)              # User(email='a@x.com', name='alice')
print(u.to_json())    # {"name": "alice", "email": "a@x.com"}
```

## 5. Method Resolution Order (MRO) / C3 linearization

```python
class X: pass
class Y(X): pass
class Z(X): pass
class W(Y, Z): pass

print(W.__mro__)  # (W, Y, Z, X, object)
print(W.mro())    # same as list
```

Python computes MRO at class creation time; you can inspect it with `ClassName.__mro__` or `ClassName.mro()`.

## 6. Overriding built-in dunder methods

```python
class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)
    def __eq__(self, other):
        return (self.x, self.y) == (other.x, other.y)
    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

v1 = Vector(1,2); v2 = Vector(3,4)
print(v1 + v2)   # Vector(4, 6)
print(v1 == Vector(1,2))  # True
```

## 7. `__slots__` with inheritance (memory optimization)

```python
class Point:
    __slots__ = ("x", "y")
    def __init__(self, x, y):
        self.x, self.y = x, y

class ColorPoint(Point):
    __slots__ = ("color",)        # must NOT repeat parent slots
    def __init__(self, x, y, color):
        super().__init__(x, y)
        self.color = color
```

Note: A subclass that defines `__slots__` cannot create arbitrary attributes; to allow them, include `"__dict__"` in slots.

## 8. `@classmethod`, `@staticmethod`, and inheritance

```python
class Base:
    species = "unknown"
    @classmethod
    def create(cls, **kw):
        return cls(**kw)          # creates instance of actual subclass
    @staticmethod
    def helper(v):
        return v * 2

class Sub(Base):
    species = "sub"

s = Sub.create()                  # works if Sub has matching __init__
```

## 9. Calling parent while overriding (customizing, not replacing)

```python
class LoggingList(list):
    def append(self, item):
        print(f"appending {item!r}")
        super().append(item)      # delegate to list.append
```

## 10. Composition vs Inheritance (when to prefer which)

- Use inheritance for **"is-a"** relationships and to reuse polymorphic behavior.
- Use composition for **"has-a"** relationships; it's more flexible and avoids fragile base classes.

```python
# Composition example
class Engine:
    def start(self): return "engine started"

class Car:
    def __init__(self):
        self.engine = Engine()    # has-a
    def start(self):
        return self.engine.start()
```

## Best Practices Summary

1. Prefer composition unless there's a clear is-a relationship.
2. Keep inheritance hierarchies shallow.
3. Use `super()` instead of hardcoding parent class names.
4. In multiple inheritance, follow cooperative multiple inheritance (accept `**kwargs`).
5. Use ABCs to document required interfaces.
6. Be careful with `__init__` chains and `__slots__`.
7. Don't override `__init__` without calling `super().__init__()` unless intentional.
8. Document the MRO expectations for collaborators.

