## Minimal reimplementation of the core machinery

Below is a toy object model showing **class creation, C3 MRO, attribute lookup, method binding, instantiation, `super()`, `isinstance`/`issubclass`**. It mirrors how CPython thinks about it, but in readable Python.

```python
"""Miniature reimplementation of Python's inheritance core."""

from typing import Any, Callable, Dict, List


# ---------------------------------------------------------------- helpers ----
def _is_instance(obj: Any) -> bool:
    return isinstance(obj, dict) and "__class__" in obj and "__dict__" in obj


def set_instance_attr(obj: Dict, key: str, value: Any) -> None:
    obj.setdefault("__dict__", {})[key] = value


def _same(a, b) -> bool:
    return a is b


# ------------------------------------------------------------------ MRO -----
def _c3_linearize(cls: Dict) -> List[Dict]:
    """C3 linearisation: cls first, then bases in order, consistent."""
    if not cls["bases"]:
        return [cls]

    # Linearisations of every base + the list of bases themselves.
    seqs = [_c3_linearize(b) for b in cls["bases"]]
    seqs.append(list(cls["bases"]))

    result = [cls]
    work = [list(s) for s in seqs]
    while any(work):
        candidate = None
        for seq in work:
            if not seq:
                continue
            head = seq[0]
            # A valid head must not appear in the *tail* of any sequence.
            if all(not any(x is head for x in s[1:]) for s in work):
                candidate = head
                break
        if candidate is None:
            raise TypeError(f"Inconsistent MRO for {cls['name']}")
        result.append(candidate)
        for seq in work:
            if seq and seq[0] is candidate:
                seq.pop(0)

    # De-duplicate by identity (preserves order).
    seen, unique = set(), []
    for c in result:
        if id(c) in seen:
            continue
        seen.add(id(c))
        unique.append(c)
    return unique


# ----------------------------------------------------------- class creation --
def new_class(name: str, bases=(), attrs=None) -> Dict:
    cls = {"name": name, "bases": list(bases), "attrs": dict(attrs or {})}
    cls["mro"] = _c3_linearize(cls)
    return cls


# --------------------------------------------------------------- binding -----
def bind(function: Callable, instance: Dict, owner: Dict) -> Callable:
    """Bind a plain function to an instance (simplified descriptor protocol)."""
    def method(*args, **kwargs):
        return function(instance, *args, **kwargs)
    method.__name__ = getattr(function, "__name__", "<method>")
    method.__self__ = instance
    method.__objclass__ = owner
    return method


def _find_in_mro(cls: Dict, name: str):
    for c in cls["mro"]:
        if name in c["attrs"]:
            return c, c["attrs"][name]
    return None, None


# --------------------------------------------------------- attribute access --
def get_attr(obj: Any, name: str):
    # Instance branch: instance dict wins, then class chain.
    if _is_instance(obj):
        instance = obj
        cls = instance["__class__"]
        if name in instance.get("__dict__", {}):
            return instance["__dict__"][name]
    else:
        instance = None
        cls = obj

    defining, value = _find_in_mro(cls, name)
    if defining is None:
        raise AttributeError(f"{cls['name']!r} has no attribute {name!r}")

    # Bind methods to instances, unless accessed on the class itself.
    if instance is not None and callable(value):
        return bind(value, instance, defining)
    return value


def set_attr(obj: Any, name: str, value: Any) -> None:
    if _is_instance(obj):
        obj.setdefault("__dict__", {})[name] = value
    else:
        obj["attrs"][name] = value


# ---------------------------------------------------------------- super -----
class SuperProxy:
    """Minimal super(): continue MRO search *after* the given class."""

    def __init__(self, cls: Dict, instance: Dict):
        self.cls = cls
        self.instance = instance

    def __getattr__(self, name: str):
        cls = self.instance["__class__"]
        mro = cls["mro"]
        try:
            start = next(i for i, c in enumerate(mro) if c is self.cls)
        except StopIteration:
            raise TypeError("super(): class not in instance MRO")
        for c in mro[start + 1:]:
            if name in c["attrs"]:
                value = c["attrs"][name]
                if callable(value):
                    return bind(value, self.instance, c)
                return value
        raise AttributeError(f"super has no attribute {name!r}")


def super_(cls, instance):
    return SuperProxy(cls, instance)


# ----------------------------------------------------------- instantiation --
def instantiate(cls: Dict, *args, **kwargs):
    obj = {"__class__": cls, "__dict__": {}}
    defining, init = _find_in_mro(cls, "__init__")
    if init is not None:
        bind(init, obj, defining)(*args, **kwargs)
    return obj


# ----------------------------------------------------------- predicates -----
def is_instance(obj, cls) -> bool:
    if not _is_instance(obj):
        return False
    return any(c is cls for c in obj["__class__"]["mro"])


def is_subclass(a, b) -> bool:
    return any(c is b for c in a["mro"])


# ----------------------------------------------------------------- demo ----
if __name__ == "__main__":
    # Base class
    Animal = new_class("Animal", (), {"species": "unknown"})

    def animal_init(self, name):
        set_instance_attr(self, "name", name)
    Animal["attrs"]["__init__"] = animal_init

    def animal_speak(self):
        return f"{get_attr(self, 'name')} makes a sound"
    Animal["attrs"]["speak"] = animal_speak

    # Mixin
    Flyer = new_class("Flyer", (), {})

    def flyer_fly(self):
        return f"{get_attr(self, 'name')} flies"
    Flyer["attrs"]["fly"] = flyer_fly

    # Subclass overriding __init__ and speak
    Dog = new_class("Dog", (Animal,), {})

    def dog_init(self, name, breed):
        super_(Dog, self).__init__(name)   # calls Animal.__init__
        set_instance_attr(self, "breed", breed)
    Dog["attrs"]["__init__"] = dog_init

    def dog_speak(self):
        return f"{get_attr(self, 'name')} barks"
    Dog["attrs"]["speak"] = dog_speak

    # Multiple inheritance
    Bat = new_class("Bat", (Animal, Flyer), {})

    # --- usage ---
    rex = instantiate(Dog, "Rex", "Labrador")
    print(get_attr(rex, "speak")())          # Rex barks
    print(get_attr(rex, "breed"))            # Labrador
    print("is Dog?", is_instance(rex, Dog))  # True
    print("is Animal?", is_instance(rex, Animal))  # True

    bruce = instantiate(Bat, "Bruce")
    print(get_attr(bruce, "speak")())        # Bruce makes a sound
    print(get_attr(bruce, "fly")())          # Bruce flies
    print("Bat MRO:", [c["name"] for c in Bat["mro"]])

    # class-level access (unbound)
    print("species:", get_attr(Animal, "species"))  # unknown
```

### How this maps to real Python
- `new_class` ≈ `type(name, bases, attrs)`; `type` is the metaclass.
- `_c3_linearize` ≈ `type.__mro_entries__` / C3 algorithm used by CPython.
- `get_attr` ≈ `object.__getattribute__` + descriptor protocol (`__get__`).
- `bind` ≈ function descriptor (`function.__get__`).
- `super_` ≈ `super()`.
- `instantiate` ≈ `type.__call__` → `__new__` + `__init__`.

### Quick real-world examples

```python
# Abstract base class
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...

# Mixin
class JsonMixin:
    def to_json(self): import json; return json.dumps(self.__dict__)

class Circle(Shape, JsonMixin):
    def __init__(self, r): self.r = r
    def area(self): return 3.14 * self.r * self.r
```

### Interview talking points (short)
- Prefer **composition** when “has-a”; use inheritance for true “is-a” and polymorphism.
- Watch shared **mutable class attributes** (`cls.data = []`).
- `super()` cooperates across MRO; in multiple inheritance it’s not “call parent”, it’s “call next in MRO”.
- Slots (`__slots__`) reduce per-instance dict overhead.
- Tests: `isinstance`, `issubclass`, MRO inspection (`cls.__mro__`).

Below is a complete, self-contained Python program that demonstrates a comprehensive, idiomatic input-validation system. It uses only the standard library, aggregates all errors (instead of failing on the first), supports normalization, and includes runnable doctest-style assertions and a small CLI demo.

```python
"""
input_validation.py

A thorough, stdlib-only input-validation example.

Run:
    python input_validation.py            # runs built-in demos + assertions
    python input_validation.py --demo     # interactive-ish demo
"""

from __future__ import annotations

import argparse
import re
from dataclasses import dataclass, field
from datetime import date, datetime
from decimal import Decimal, InvalidOperation
from typing import Any, Callable, Dict, Iterable, List, Optional, Tuple, Type, Union


# ---------------------------------------------------------------------------
# 1. Error model
# ---------------------------------------------------------------------------

class ValidationError(Exception):
    """Raised (or collected) when one or more fields are invalid."""

    def __init__(self, errors: Dict[str, List[str]]):
        self.errors = errors
        super().__init__(self._format())

    def _format(self) -> str:
        lines = []
        for field, msgs in self.errors.items():
            for m in msgs:
                lines.append(f"  - {field}: {m}")
        return "Validation failed:\n" + "\n".join(lines)

    def __str__(self) -> str:
        return self._format()


@dataclass
class FieldResult:
    value: Any = None
    errors: List[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.errors


# ---------------------------------------------------------------------------
# 2. Small reusable validator primitives
# ---------------------------------------------------------------------------

def _is_none(v: Any) -> bool:
    return v is None


def require(value: Any, field: str, out: FieldResult) -> bool:
    """Return True if value is present (not None and not empty str)."""
    if value is None or (isinstance(value, str) and value.strip() == ""):
        out.errors.append("is required")
        return False
    return True


def coerce_type(value: Any, target: Type, field: str, out: FieldResult) -> Any:
    """Best-effort coercion; records error on failure."""
    if value is None:
        return None
    if isinstance(value, target):
        return value
    try:
        if target is int:
            # allow "42", 42.0-ish only if integral
            if isinstance(value, float) and not value.is_integer():
                raise ValueError
            return int(value)
        if target is float:
            return float(value)
        if target is bool:
            if isinstance(value, str):
                low = value.strip().lower()
                if low in {"true", "1", "yes", "y", "on"}:
                    return True
                if low in {"false", "0", "no", "n", "off"}:
                    return False
                raise ValueError
            return bool(value)
        if target is str:
            return str(value)
        if target is Decimal:
            return Decimal(str(value))
        if target is date:
            if isinstance(value, datetime):
                return value.date()
            return date.fromisoformat(str(value).strip())
        if target is datetime:
            return datetime.fromisoformat(str(value).strip().replace("Z", "+00:00"))
    except (ValueError, TypeError, InvalidOperation, OverflowError) as exc:
        out.errors.append(f"must be a valid {target.__name__} (got {value!r})")
    return None


def length(
    value: Any,
    field: str,
    out: FieldResult,
    *,
    min_len: Optional[int] = None,
    max_len: Optional[int] = None,
) -> None:
    if value is None:
        return
    n = len(value) if hasattr(value, "__len__") else None
    if n is None:
        return
    if min_len is not None and n < min_len:
        out.errors.append(f"must have length >= {min_len} (got {n})")
    if max_len is not None and n > max_len:
        out.errors.append(f"must have length <= {max_len} (got {n})")


def numeric_range(
    value: Any,
    field: str,
    out: FieldResult,
    *,
    min_val: Any = None,
    max_val: Any = None,
    inclusive_min: bool = True,
    inclusive_max: bool = True,
) -> None:
    if value is None or isinstance(value, str):
        return
    try:
        if min_val is not None:
            ok = value >= min_val if inclusive_min else value > min_val
            if not ok:
                op = ">=" if inclusive_min else ">"
                out.errors.append(f"must be {op} {min_val}")
        if max_val is not None:
            ok = value <= max_val if inclusive_max else value < max_val
            if not ok:
                op = "<=" if inclusive_max else "<"
                out.errors.append(f"must be {op} {max_val}")
    except TypeError:
        out.errors.append("not comparable for range check")


def regex_match(
    value: Any,
    field: str,
    out: FieldResult,
    pattern: str,
    message: Optional[str] = None,
) -> None:
    if value is None:
        return
    if not isinstance(value, str):
        return
    if not re.fullmatch(pattern, value):
        out.errors.append(message or f"must match pattern {pattern!r}")


def one_of(value: Any, field: str, out: FieldResult, choices: Iterable[Any]) -> None:
    if value is None:
        return
    choices = list(choices)
    if value not in choices:
        out.errors.append(f"must be one of {choices!r}")


def email_format(value: Any, field: str, out: FieldResult) -> None:
    if value is None or not isinstance(value, str):
        return
    # Reasonable (not RFC-perfect) email regex
    pat = r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"
    if not re.fullmatch(pat, value):
        out.errors.append("must be a valid email address")


# ---------------------------------------------------------------------------
# 3. A declarative schema-style validator
# ---------------------------------------------------------------------------

@dataclass
class FieldSpec:
    """
    Declarative field specification.

    normalizer: optional callable applied before type coercion (e.g. strip).
    validators:  extra callables (value, field, out) -> None
    """
    required: bool = True
    type: Optional[Type] = None
    min_len: Optional[int] = None
    max_len: Optional[int] = None
    min_val: Any = None
    max_val: Any = None
    pattern: Optional[str] = None
    choices: Optional[Iterable[Any]] = None
    email: bool = False
    normalizer: Optional[Callable[[Any], Any]] = None
    validators: List[Callable[[Any, str, FieldResult], None]] = field(default_factory=list)


class Schema:
    def __init__(self, specs: Dict[str, FieldSpec]):
        self.specs = specs

    def validate(self, data: Dict[str, Any]) -> Tuple[Dict[str, Any], Dict[str, List[str]]]:
        """
        Validate a dict. Returns (cleaned, errors).
        cleaned contains only fields that passed (with coerced/normalized values).
        """
        cleaned: Dict[str, Any] = {}
        errors: Dict[str, List[str]] = {}

        for name, spec in self.specs.items():
            raw = data.get(name, None)
            res = FieldResult()

            # 1. normalize
            val = raw
            if spec.normalizer is not None and val is not None:
                try:
                    val = spec.normalizer(val)
                except Exception as exc:
                    res.errors.append(f"normalization failed: {exc}")
                    val = None

            # 2. required
            if spec.required:
                if not require(val, name, res):
                    # still may be optional downstream, but record & skip coercion
                    pass

            # 3. type coercion (only if no fatal error yet or value present)
            if not res.errors or val is None:
                if spec.type is not None and val is not None:
                    coerced = coerce_type(val, spec.type, name, res)
                    if res.errors and coerced is None and val is not None:
                        # type failed; skip further checks
                        pass
                    else:
                        val = coerced if coerced is not None or val is None else val

            # only run further checks if no errors so far
            if not res.errors and val is not None:
                length(val, name, res, min_len=spec.min_len, max_len=spec.max_len)
                numeric_range(val, name, res, min_val=spec.min_val, max_val=spec.max_val)
                if spec.pattern:
                    regex_match(val, name, res, spec.pattern)
                if spec.choices is not None:
                    one_of(val, name, res, spec.choices)
                if spec.email:
                    email_format(val, name, res)
                for v in spec.validators:
                    v(val, name, res)

            if res.errors:
                errors[name] = res.errors
            else:
                # keep value (even None for optional absent fields? only if present in data)
                if name in data or val is not None:
                    cleaned[name] = val

        # Unknown fields? collect as warning-ish errors (optional policy)
        unknown = set(data) - set(self.specs)
        if unknown:
            errors["_unknown"] = [f"unexpected field: {u}" for u in sorted(unknown)]

        return cleaned, errors


# ---------------------------------------------------------------------------
# 4. Domain-specific example: User registration
# ---------------------------------------------------------------------------

USERNAME_RE = r"[A-Za-z][A-Za-z0-9_]{2,19}"

def password_strength(value, field, out):
    if not isinstance(value, str):
        return
    issues = []
    if len(value) < 8:
        issues.append("at least 8 chars")
    if not re.search(r"[A-Z]", value):
        issues.append("an uppercase letter")
    if not re.search(r"[a-z]", value):
        issues.append("a lowercase letter")
    if not re.search(r"\d", value):
        issues.append("a digit")
    if issues:
        out.errors.append("password must contain " + ", ".join(issues))


USER_SCHEMA = Schema(
    {
        "username": FieldSpec(
            required=True,
            type=str,
            min_len=3,
            max_len=20,
            pattern=USERNAME_RE,
            normalizer=lambda x: str(x).strip().lower(),
        ),
        "email": FieldSpec(
            required=True,
            type=str,
            email=True,
            normalizer=lambda x: str(x).strip().lower(),
        ),
        "age": FieldSpec(
            required=True,
            type=int,
            min_val=13,
            max_val=120,
        ),
        "password": FieldSpec(
            required=True,
            type=str,
            min_len=8,
            max_len=128,
            validators=[password_strength],
        ),
        "role": FieldSpec(
            required=False,
            type=str,
            choices=["user", "admin", "moderator"],
            normalizer=lambda x: str(x).strip().lower() if x is not None else None,
        ),
        "birth_date": FieldSpec(
            required=False,
            type=date,
        ),
        "newsletter": FieldSpec(
            required=False,
            type=bool,
        ),
        "score": FieldSpec(
            required=False,
            type=Decimal,
            min_val=Decimal("0"),
            max_val=Decimal("100"),
        ),
    }
)


# ---------------------------------------------------------------------------
# 5. Helper: validate and either return cleaned or raise
# ---------------------------------------------------------------------------

def validate_or_raise(schema: Schema, data: Dict[str, Any]) -> Dict[str, Any]:
    cleaned, errors = schema.validate(data)
    if errors:
        raise ValidationError(errors)
    return cleaned


# ---------------------------------------------------------------------------
# 6. Demo / tests
# ---------------------------------------------------------------------------

def _run_assertions() -> None:
    # --- happy path ---
    good = {
        "username": "  Alice_01 ",
        "email": "ALICE@Example.COM",
        "age": "25",
        "password": "Secret123",
        "role": " Admin ",
        "birth_date": "1999-05-10",
        "newsletter": "yes",
        "score": "98.5",
    }
    cleaned, errors = USER_SCHEMA.validate(good)
    assert not errors, errors
    assert cleaned["username"] == "alice_01"
    assert cleaned["email"] == "alice@example.com"
    assert cleaned["age"] == 25
    assert cleaned["role"] == "admin"
    assert cleaned["birth_date"] == date(1999, 5, 10)
    assert cleaned["newsletter"] is True
    assert cleaned["score"] == Decimal("98.5")

    # --- bad path: aggregate errors ---
    bad = {
        "username": "ab",          # too short + pattern
        "email": "not-an-email",
        "age": 10,                  # under min
        "password": "weak",
        "role": "superuser",        # not in choices
        "birth_date": "not-a-date",
        "newsletter": "maybe",
        "score": 150,
        "extra": "x",               # unknown field
    }
    cleaned, errors = USER_SCHEMA.validate(bad)
    assert errors, "expected errors"
    for f in ("username", "email", "age", "password", "role", "birth_date", "newsletter", "score", "_unknown"):
        assert f in errors, f"missing error for {f}"
    print("All built-in assertions passed.\n")

    # --- required missing ---
    cleaned, errors = USER_SCHEMA.validate({})
    assert "username" in errors and "email" in errors and "age" in errors and "password" in errors

    # --- validate_or_raise ---
    try:
        validate_or_raise(USER_SCHEMA, {"username": "x"})
    except ValidationError as e:
        assert "email" in e.errors
    else:
        raise AssertionError("expected ValidationError")

    # --- coerce_type direct ---
    r = FieldResult()
    assert coerce_type("42", int, "n", r) == 42 and r.ok
    r2 = FieldResult()
    assert coerce_type("3.14", int, "n", r2) is None and not r2.ok

    # --- bool coercion ---
    r3 = FieldResult()
    assert coerce_type("on", bool, "b", r3) is True

    print("Extended assertions passed.\n")


def _demo_cli() -> None:
    parser = argparse.ArgumentParser(description="Input validation demo")
    parser.add_argument("--demo", action="store_true", help="Run interactive-ish demo")
    args = parser.parse_args()

    if not args.demo:
        return

    samples = [
        {
            "username": "bob",
            "email": "bob@example.com",
            "age": 30,
            "password": "StrongPass1",
        },
        {
            "username": "x",
            "email": "bad",
            "age": 5,
            "password": "weak",
        },
    ]
    for i, s in enumerate(samples, 1):
        print(f"--- sample {i} ---")
        cleaned, errors = USER_SCHEMA.validate(s)
        if errors:
            print(ValidationError(errors))
        else:
            print("OK:", cleaned)
        print()


def main() -> None:
    _run_assertions()
    _demo_cli()
    print("Done.")


if __name__ == "__main__":
    main()
```

### What this demonstrates

| Concern | Where |
|---|---|
| **Aggregate errors** | `Schema.validate` collects per-field errors instead of stopping early. |
| **Type coercion** | `coerce_type` converts strings → `int`, `float`, `bool`, `date`, `Decimal`, etc. with clean errors. |
| **Normalization** | `normalizer=` (e.g. `.strip().lower()`) runs before validation. |
| **Constraints** | `min_len`, `max_len`, `min_val`, `max_val`, `pattern`, `choices`, `email`. |
| **Custom validators** | `password_strength` shows cross-rule logic; add more via `validators=[...]`. |
| **Optional fields** | `required=False` skips required check but still validates if present. |
| **Unknown fields** | Collected under `_unknown` (easy to drop or reject). |
| **Domain example** | `USER_SCHEMA` for a realistic registration payload. |
| **Stdlib only** | No third-party dependencies; easy to adapt or replace with `pydantic`/`marshmallow`. |

### Extending it

- **Nested objects**: make a `FieldSpec` whose `type` is another `Schema` and validate recursively.
- **Cross-field rules** (e.g. “password ≠ username”): add a post-validation step on `cleaned`.
- **Async validators** (DB uniqueness): make `validators` async and `await` them in an async variant of `Schema.validate`.
- **Localization**: replace hard-coded messages with a message catalog keyed by `(field, code)`.

If you want, I can also show a **Pydantic v2** version of the same domain model for comparison.

## Exercise

Write a Python function `validate_registration(data)` that validates a user-registration payload coming from untrusted input (e.g. a JSON body or CLI args).

Rules:

- `data` must be a `dict`.
- `name`: required, string, stripped, non-empty, ≤ 50 chars.
- `age`: required, integer (or a string that is a pure integer), between `0` and `120`. Booleans must **not** be accepted as integers.
- `email`: required, string, stripped + lowercased, matches a simple email regex, and its domain is not in a blocked list.
- Collect **all** field errors (do not stop at the first one), and raise a single `ValidationError` whose `.errors` is `{field: [messages]}`.
- On success return a cleaned dict with normalized values.

---

## Step-by-step solution

### 1. Define a custom exception

We want callers to be able to inspect every failure at once:

```python
class ValidationError(Exception):
    def __init__(self, errors):
        self.errors = errors
        super().__init__(str(errors))
```

### 2. Constants and regex

Keep validation rules in one obvious place so they are easy to tune:

```python
import re

EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")
BLOCKED_DOMAINS = {"tempmail.com", "mailinator.com"}
```

### 3. Per-field validators

Each returns `(cleaned_value, list_of_errors)`. Returning both lets us aggregate errors without losing partial normalization.

```python
def _validate_name(raw):
    errors = []
    if not isinstance(raw, str):
        return "", ["must be a string"]
    name = raw.strip()
    if not name:
        errors.append("must not be empty")
    elif len(name) > 50:
        errors.append("must be at most 50 characters")
    return name, errors
```

Age needs special care: `bool` is a subclass of `int` in Python, so `True` would otherwise pass as `1`. We also accept `" 25 "` style strings.

```python
def _validate_age(raw):
    errors = []
    if isinstance(raw, bool):
        return None, ["must be an integer, not a boolean"]
    if isinstance(raw, int):
        age = raw
    elif isinstance(raw, str):
        s = raw.strip()
        if not re.fullmatch(r"-?\d+", s):
            return None, ["must be an integer"]
        age = int(s)
    else:
        return None, ["must be an integer or numeric string"]
    if not (0 <= age <= 120):
        errors.append("must be between 0 and 120")
    return age, errors
```

Email: normalize case early so comparison against the blocked list is reliable.

```python
def _validate_email(raw):
    errors = []
    if not isinstance(raw, str):
        return "", ["must be a string"]
    email = raw.strip().lower()
    if not EMAIL_RE.fullmatch(email):
        errors.append("invalid email format")
        return email, errors
    domain = email.rsplit("@", 1)[-1]
    if domain in BLOCKED_DOMAINS:
        errors.append(f"domain '{domain}' is not allowed")
    return email, errors
```

### 4. Top-level aggregator

Check `dict` type first, then presence of each required key, then run the field validators. Only raise at the end, so every problem is reported together.

```python
def validate_registration(data):
    if not isinstance(data, dict):
        raise ValidationError({"_root": ["input must be a dict"]})

    cleaned = {}
    errors = {}

    required = ("name", "age", "email")

    for field in required:
        if field not in data:
            errors[field] = ["is required"]
            continue

        raw = data[field]
        if field == "name":
            value, field_errors = _validate_name(raw)
        elif field == "age":
            value, field_errors = _validate_age(raw)
        else:
            value, field_errors = _validate_email(raw)

        if field_errors:
            errors[field] = field_errors
        else:
            cleaned[field] = value

    # Also reject unexpected keys? Optional; here we ignore extras.

    if errors:
        raise ValidationError(errors)
    return cleaned
```

### 5. Try it

```python
if __name__ == "__main__":
    tests = [
        {"name": "  Alice  ", "age": "25", "email": "Alice@Example.com"},
        {"name": "", "age": True, "email": "bad@@example.com"},
        {"age": 30, "email": "x@tempmail.com"},  # missing name
    ]
    for t in tests:
        try:
            print("OK:", validate_registration(t))
        except ValidationError as e:
            print("FAIL:", e.errors)
```

