## Final solution

```python
"""Input validation example: user registration payload."""

import re
from typing import Any, Dict, List, Optional, Tuple


class ValidationError(Exception):
    """Raised when one or more fields fail validation."""

    def __init__(self, errors: Dict[str, List[str]]):
        self.errors = errors
        super().__init__(str(errors))


EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")
BLOCKED_DOMAINS = {"tempmail.com", "mailinator.com"}


def _validate_name(raw: Any) -> Tuple[str, List[str]]:
    errors: List[str] = []
    if not isinstance(raw, str):
        return "", ["must be a string"]
    name = raw.strip()
    if not name:
        errors.append("must not be empty")
    elif len(name) > 50:
        errors.append("must be at most 50 characters")
    return name, errors


def _validate_age(raw: Any) -> Tuple[Optional[int], List[str]]:
    errors: List[str] = []
    # bool is a subclass of int in Python; reject it explicitly.
    if isinstance(raw, bool):
        return None, ["must be an integer, not a boolean"]
    if isinstance(raw, int):
        age = raw
    elif isinstance(raw, str):
        s = raw.strip()
        if not re.fullmatch(r"-?\d+", s):
            return None, ["must be an integer"]
        age = int(s)
    else:
        return None, ["must be an integer or numeric string"]
    if not (0 <= age <= 120):
        errors.append("must be between 0 and 120")
    return age, errors


def _validate_email(raw: Any) -> Tuple[str, List[str]]:
    errors: List[str] = []
    if not isinstance(raw, str):
        return "", ["must be a string"]
    email = raw.strip().lower()
    if not EMAIL_RE.fullmatch(email):
        errors.append("invalid email format")
        return email, errors
    domain = email.rsplit("@", 1)[-1]
    if domain in BLOCKED_DOMAINS:
        errors.append(f"domain '{domain}' is not allowed")
    return email, errors


def validate_registration(data: Any) -> Dict[str, Any]:
    """Validate and normalize a registration payload.

    Returns a cleaned dict on success; raises ValidationError listing
    all field errors otherwise.
    """
    if not isinstance(data, dict):
        raise ValidationError({"_root": ["input must be a dict"]})

    cleaned: Dict[str, Any] = {}
    errors: Dict[str, List[str]] = {}
    required = ("name", "age", "email")

    for field in required:
        if field not in data:
            errors[field] = ["is required"]
            continue

        raw = data[field]
        if field == "name":
            value, field_errors = _validate_name(raw)
        elif field == "age":
            value, field_errors = _validate_age(raw)
        else:
            value, field_errors = _validate_email(raw)

        if field_errors:
            errors[field] = field_errors
        else:
            cleaned[field] = value

    if errors:
        raise ValidationError(errors)
    return cleaned


if __name__ == "__main__":
    samples = [
        {"name": "  Alice  ", "age": "25", "email": "Alice@Example.com"},
        {"name": "", "age": True, "email": "bad@@example.com"},
        {"age": 30, "email": "x@tempmail.com"},
    ]
    for s in samples:
        try:
            print("OK:", validate_registration(s))
        except ValidationError as exc:
            print("FAIL:", exc.errors)
```

### Key takeaways

- Validate at the boundary; return normalized data to the rest of the program.
- Collect all errors so users can fix everything in one round-trip.
- Watch Python’s `bool`-is-`int` quirk when validating integers.
- Keep regexes/limits in named constants for easy maintenance.

Here is a complete, runnable implementation of custom `Integer` and `Float` number classes in Python. They wrap Python’s built-in numeric values, but expose a clean object model with arithmetic, comparisons, conversions, bitwise operations (for integers), IEEE-754 bit access (for floats), and mixed-type behavior similar to Python’s own `int`/`float`.

```python
from __future__ import annotations

import math
import struct
from typing import Any, Union

NumberLike = Union[int, float, "Integer", "Float"]


class Integer:
    """An integer number type with value semantics similar to Python's int."""

    __slots__ = ("value",)

    def __init__(self, value: Any = 0) -> None:
        if isinstance(value, Integer):
            self.value = value.value
        elif isinstance(value, Float):
            self.value = int(value.value)  # truncation toward zero
        elif isinstance(value, str):
            self.value = int(value, 0)
        else:
            self.value = int(value)

    # ------------------------------------------------------------------ #
    # Internal helpers
    # ------------------------------------------------------------------ #
    def _coerce(self, other: Any) -> Union["Integer", "Float"]:
        if isinstance(other, (Integer, Float)):
            return other
        if isinstance(other, bool):
            return Integer(other)
        if isinstance(other, int):
            return Integer(other)
        if isinstance(other, float):
            return Float(other)
        if isinstance(other, str):
            try:
                return Integer(other)
            except ValueError:
                return Float(other)
        raise TypeError(
            f"unsupported operand type: 'Integer' and {type(other).__name__!r}"
        )

    # ------------------------------------------------------------------ #
    # Representation / conversion
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:
        return f"Integer({self.value!r})"

    def __str__(self) -> str:
        return str(self.value)

    def __hash__(self) -> int:
        return hash(self.value)

    def __bool__(self) -> bool:
        return bool(self.value)

    def __int__(self) -> int:
        return self.value

    def __float__(self) -> float:
        return float(self.value)

    def __complex__(self) -> complex:
        return complex(self.value)

    def __index__(self) -> int:
        return self.value

    # ------------------------------------------------------------------ #
    # Arithmetic
    # ------------------------------------------------------------------ #
    def __add__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(self.value + o.value)
        return Integer(self.value + o.value)

    __radd__ = __add__

    def __sub__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(self.value - o.value)
        return Integer(self.value - o.value)

    def __rsub__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(o.value - self.value)
        return Integer(o.value - self.value)

    def __mul__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(self.value * o.value)
        return Integer(self.value * o.value)

    __rmul__ = __mul__

    def __truediv__(self, other: Any) -> "Float":
        o = self._coerce(other)
        return Float(self.value / o.value)

    def __rtruediv__(self, other: Any) -> "Float":
        o = self._coerce(other)
        return Float(o.value / self.value)

    def __floordiv__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(self.value // o.value)
        return Integer(self.value // o.value)

    def __rfloordiv__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(o.value // self.value)
        return Integer(o.value // self.value)

    def __mod__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(self.value % o.value)
        return Integer(self.value % o.value)

    def __rmod__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(o.value % self.value)
        return Integer(o.value % self.value)

    def __pow__(self, other: Any, modulo: Any = None) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if modulo is not None:
            m = self._coerce(modulo)
            if isinstance(o, Float) or isinstance(m, Float):
                raise TypeError("pow() 3rd argument requires all integers")
            return Integer(pow(self.value, o.value, m.value))
        if isinstance(o, Float):
            return Float(self.value ** o.value)
        if o.value < 0:
            return Float(self.value ** o.value)
        return Integer(self.value ** o.value)

    def __rpow__(self, other: Any) -> Union["Integer", "Float"]:
        o = self._coerce(other)
        if isinstance(o, Float):
            return Float(o.value ** self.value)
        if self.value < 0:
            return Float(o.value ** self.value)
        return Integer(o.value ** self.value)

    def __divmod__(self, other: Any):
        return (self.__floordiv__(other), self.__mod__(other))

    def __neg__(self) -> "Integer":
        return Integer(-self.value)

    def __pos__(self) -> "Integer":
        return Integer(self.value)

    def __abs__(self) -> "Integer":
        return Integer(abs(self.value))

    # ------------------------------------------------------------------ #
    # Bitwise operations (integers only)
    # ------------------------------------------------------------------ #
    def _require_integer(self, other: Any) -> "Integer":
        o = self._coerce(other)
        if isinstance(o, Float):
            raise TypeError("bitwise operations require integer operands")
        return o

    def __invert__(self) -> "Integer":
        return Integer(~self.value)

    def __and__(self, other: Any) -> "Integer":
        o = self._require_integer(other)
        return Integer(self.value & o.value)

    __rand__ = __and__

    def __or__(self, other: Any) -> "Integer":
        o = self._require_integer(other)
        return Integer(self.value | o.value)

    __ror__ = __or__

    def __xor__(self, other: Any) -> "Integer":
        o = self._require_integer(other)
        return Integer(self.value ^ o.value)

    __rxor__ = __xor__

    def __lshift__(self, other: Any) -> "Integer":
        o = self._require_integer(other)
        return Integer(self.value << o.value)

    def __rlshift__(self, other: Any) -> "Integer":
        o = self._require_integer(other)
        return Integer(o.value << self.value)

    def __rshift__(self, other: Any) -> "Integer":
        o = self._require_integer(other)
        return Integer(self.value >> o.value)

    def __rrshift__(self, other: Any) -> "Integer":
        o = self._require_integer(other)
        return Integer(o.value >> self.value)

    # ------------------------------------------------------------------ #
    # Comparison
    # ------------------------------------------------------------------ #
    def __eq__(self, other: Any) -> Any:
        try:
            o = self._coerce(other)
        except TypeError:
            return NotImplemented
        return self.value == o.value

    def __ne__(self, other: Any) -> Any:
        eq = self.__eq__(other)
        if eq is NotImplemented:
            return eq
        return not eq

    def __lt__(self, other: Any) -> Any:
        try:
            o = self._coerce(other)
        except TypeError:
            return NotImplemented
        return self.value < o.value

    def __le__(self, other: Any) -> Any:
        try:
            o = self._coerce(other)
        except TypeError:
            return NotImplemented
        return self.value <= o.value

    def __gt__(self, other: Any) -> Any:
        try:
            o = self._coerce(other)
        except TypeError:
            return NotImplemented
        return self.value > o.value

    def __ge__(self, other: Any) -> Any:
        try:
            o = self._coerce(other)
        except TypeError:
            return NotImplemented
        return self.value >= o.value


class Float:
    """A floating-point number type with value semantics similar to Python's float."""

    __slots__ = ("value",)

    def __init__(self, value: Any = 0.0) -> None:
        if isinstance(value, Float):
            self.value = value.value
        elif isinstance(value, Integer):
            self.value = float(value.value)
        else:
            self.value = float(value)

    # ------------------------------------------------------------------ #
    # Internal helpers
    # ------------------------------------------------------------------ #
    def _to_float(self, other: Any) -> float:
        if isinstance(other, Float):
            return other.value
        if isinstance(other, Integer):
            return float(other.value)
        return float(other)

    # ------------------------------------------------------------------ #
    # Representation / conversion
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:
        return f"Float({self.value!r})"

    def __str__(self) -> str:
        return str(self.value)

    def __hash__(self) -> int:
        return hash(self.value)

    def __bool__(self) -> bool:
        return bool(self.value)

    def __int__(self) -> int:
        return int(self.value)

    def __float__(self) -> float:
        return self.value

    def __complex__(self) -> complex:
        return complex(self.value)

    def __index__(self) -> int:
        return int(self.value)

    # ------------------------------------------------------------------ #
    # IEEE-754 helpers
    # ------------------------------------------------------------------ #
    @property
    def bits(self) -> int:
        """Return the 64-bit IEEE-754 representation."""
        return struct.unpack("!Q", struct.pack("!d", self.value))[0]

    @classmethod
    def from_bits(cls, bits: int) -> "Float":
        bits &= 0xFFFFFFFFFFFFFFFF
        return cls(struct.unpack("!d", struct.pack("!Q", bits))[0])

    def is_nan(self) -> bool:
        return math.isnan(self.value)

    def is_inf(self) -> bool:
        return math.isinf(self.value)

    def is_finite(self) -> bool:
        return math.isfinite(self.value)

    def as_integer_ratio(self):
        return self.value.as_integer_ratio()

    # ------------------------------------------------------------------ #
    # Arithmetic
    # ------------------------------------------------------------------ #
    def __add__(self, other: Any) -> "Float":
        return Float(self.value + self._to_float(other))

    __radd__ = __add__

    def __sub__(self, other: Any) -> "Float":
        return Float(self.value - self._to_float(other))

    def __rsub__(self, other: Any) -> "Float":
        return Float(self._to_float(other) - self.value)

    def __mul__(self, other: Any) -> "Float":
        return Float(self.value * self._to_float(other))

    __rmul__ = __mul__

    def __truediv__(self, other: Any) -> "Float":
        return Float(self.value / self._to_float(other))

    def __rtruediv__(self, other: Any) -> "Float":
        return Float(self._to_float(other) / self.value)

    def __floordiv__(self, other: Any) -> "Float":
        return Float(self.value // self._to_float(other))

    def __rfloordiv__(self, other: Any) -> "Float":
        return Float(self._to_float(other) // self.value)

    def __mod__(self, other: Any) -> "Float":
        return Float(self.value % self._to_float(other))

    def __rmod__(self, other: Any) -> "Float":
        return Float(self._to_float(other) % self.value)

    def __pow__(self, other: Any, modulo: Any = None) -> "Float":
        if modulo is not None:
            raise TypeError("pow() with modulo is not supported for floats")
        return Float(self.value ** self._to_float(other))

    def __rpow__(self, other: Any) -> "Float":
        return Float(self._to_float(other) ** self.value)

    def __divmod__(self, other: Any):
        other_f = self._to_float(other)
        return (Float(self.value // other_f), Float(self.value % other_f))

    def __neg__(self) -> "Float":
        return Float(-self.value)

    def __pos__(self) -> "Float":
        return Float(self.value)

    def __abs__(self) -> "Float":
        return Float(abs(self.value))

    # ------------------------------------------------------------------ #
    # Comparison
    # ------------------------------------------------------------------ #
    def __eq__(self, other: Any) -> Any:
        try:
            return self.value == self._to_float(other)
        except (TypeError, ValueError):
            return NotImplemented

    def __ne__(self, other: Any) -> Any:
        eq = self.__eq__(other)
        if eq is NotImplemented:
            return eq
        return not eq

    def __lt__(self, other: Any) -> Any:
        try:
            return self.value < self._to_float(other)
        except (TypeError, ValueError):
            return NotImplemented

    def __le__(self, other: Any) -> Any:
        try:
            return self.value <= self._to_float(other)
        except (TypeError, ValueError):
            return NotImplemented

    def __gt__(self, other: Any) -> Any:
        try:
            return self.value > self._to_float(other)
        except (TypeError, ValueError):
            return NotImplemented

    def __ge__(self, other: Any) -> Any:
        try:
            return self.value >= self._to_float(other)
        except (TypeError, ValueError):
            return NotImplemented


