    inf = Float(float("inf"))
    print("nan eq nan:", nan == nan, "nan ne nan:", nan != nan)
    print("inf + 1:", inf + 1)

    # IEEE-754 bit round trip
    one = Float(1.0)
    bits = one.bits
    print("bits(1.0):", format(bits, "064b"))
    assert Float.from_bits(bits) == one

    # Cross-type equality and hashing
    assert Integer(5) == Float(5.0)
    assert hash(Integer(5)) == hash(Float(5.0))
    print("cross-type equality: OK")

    # Conversions
    assert int(Float(3.7)) == 3
    assert float(Integer(42)) == 42.0
    assert Integer("0b1010") == Integer(10)
    print("conversions: OK")

    # Bitwise integer operations
    print("bitwise:", Integer(0b1010) & Integer(0b1100), Integer(5) << 2)
    try:
        Float(1.0) & Integer(2)
    except TypeError as exc:
        print("bitwise type error:", exc)

    # Ordering
    assert Integer(3) < Float(3.5)
    assert Float(3.5) > Integer(3)
    print("ordering: OK")

