Below is a small, self-contained lazy-evaluation toolkit. It combines three common ideas:

1. **Memoized thunks** (`LazyValue`, `lazy`) — compute a value only when forced, then cache it.
2. **Lazy object attributes** (`lazy_property`) — compute an attribute only on first access.
3. **Lazy functional lists** (`LazyList`, `cons`, `from_iterable`, `lazy_map`, `lazy_filter`) — infinite/very large sequences whose elements are produced on demand.

All of it is runnable as-is.

```python
# lazy_eval.py
import functools
import itertools
import threading

_UNSET = object()


# --------------------------------------------------------------------------- #
# 1. Memoized thunks
# --------------------------------------------------------------------------- #
class LazyValue:
    """A value computed at most once (thread-safe)."""

    def __init__(self, factory):
        self._factory = factory
        self._lock = threading.Lock()
        self._value = _UNSET

    def force(self):
        if self._value is _UNSET:
            with self._lock:
                if self._value is _UNSET:
                    self._value = self._factory()
        return self._value

    def __call__(self):
        return self.force()

    def __repr__(self):
        state = "forced" if self._value is not _UNSET else "unforced"
        return f"<LazyValue {state}>"


def lazy(func):
    """Decorator: calling the function returns a LazyValue instead of a value."""

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return LazyValue(lambda: func(*args, **kwargs))

    return wrapper


# --------------------------------------------------------------------------- #
# 2. Lazy instance attributes
# --------------------------------------------------------------------------- #
def lazy_property(func):
    """Descriptor: attribute is computed on first access and then cached."""

    attr_name = "_lazy_" + func.__name__

    @property
    def wrapper(self):
        if not hasattr(self, attr_name):
            setattr(self, attr_name, func(self))
        return getattr(self, attr_name)

    return wrapper


# --------------------------------------------------------------------------- #
# 3. Lazy (possibly infinite) lists
# --------------------------------------------------------------------------- #
class _Empty:
    def __repr__(self):
        return "Empty"

    def __bool__(self):
        return False


EMPTY = _Empty()


class LazyList:
    """
    A cons cell whose tail is either:
      - another LazyList / EMPTY, or
      - a zero-argument callable that produces the tail (forced once).
    """

    def __init__(self, head, tail):
        self.head = head
        self._tail = tail
        self._forced = False
        self._tail_value = None

    @property
    def tail(self):
        if not self._forced:
            t = self._tail
            # Drop the thunk reference after forcing to help GC.
            self._tail = None
            self._tail_value = t() if callable(t) else t
            self._forced = True
        return self._tail_value

    def __iter__(self):
        node = self
        while node is not EMPTY:
            yield node.head
            node = node.tail

    def __repr__(self):
        return f"LazyList({self.head!r}, <lazy tail>)"


def cons(head, tail):
    return LazyList(head, tail)


def from_iterable(iterable):
    """Wrap any (possibly infinite) iterable into a LazyList."""
    it = iter(iterable)

    def make():
        try:
            head = next(it)
        except StopIteration:
            return EMPTY
        return LazyList(head, lambda: make())

    return make()


def lazy_map(func, lst):
    if lst is EMPTY:
        return EMPTY
    return LazyList(func(lst.head), lambda: lazy_map(func, lst.tail))


def lazy_filter(pred, lst):
    if lst is EMPTY:
        return EMPTY
    if pred(lst.head):
        return LazyList(lst.head, lambda: lazy_filter(pred, lst.tail))
    # Skip non-matching elements. (May recurse for long runs; fine for demos.)
    return lazy_filter(pred, lst.tail)


def take(n, lst):
    result = []
    node = lst
    while n > 0 and node is not EMPTY:
        result.append(node.head)
        node = node.tail
        n -= 1
    return result


# --------------------------------------------------------------------------- #
# Demo
# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    # --- Thunks ------------------------------------------------------------- #
    @lazy
    def expensive_sum():
        print("computing expensive sum...")
        return sum(range(1_000_000))

    v = expensive_sum()          # nothing computed yet
    print("created:", v)
    print("first force:", v.force())
    print("second force (cached):", v())   # no recomputation

    # --- Lazy property ------------------------------------------------------ #
    class Dataset:
        @lazy_property
        def normalized(self):
            print("normalizing dataset...")
            return [x / 10 for x in range(5)]

    ds = Dataset()
    print("access 1:", ds.normalized)
    print("access 2:", ds.normalized)      # cached

    # --- Infinite lazy list ------------------------------------------------- #
    naturals = from_iterable(itertools.count(1))

    squares = lazy_map(lambda x: x * x, naturals)
    print("first 5 squares:", take(5, squares))

    # Lazy Fibonacci
    def fibs():
        def loop(a, b):
            return LazyList(a, lambda: loop(b, a + b))

        return loop(0, 1)

    print("first 10 Fibonacci numbers:", take(10, fibs()))

    # Lazy filter: primes via trial division
    def is_prime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    primes = lazy_filter(is_prime, from_iterable(itertools.count(2)))
    print("first 10 primes:", take(10, primes))

    # --- Memoization across LazyValue instances ----------------------------- #
    counter = {"n": 0}

    def make_value():
        counter["n"] += 1
        return counter["n"]

    a = LazyValue(make_value)
    b = LazyValue(make_value)
    print("two independent thunks:", a.force(), b.force())  # distinct values

    # --- Iteration stops lazily ------------------------------------------- #
    print("sum of first 100 naturals:", sum(take(100, naturals)))
```

### Notes on the design

- **Thunks and caching:** `LazyValue.force()` uses double-checked locking so the factory runs exactly once even under concurrency. After forcing, the cached value is returned on every subsequent call.
- **Lazy attributes:** `lazy_property` stores the computed value in a private instance attribute, so each instance gets its own cache.
- **Lazy lists:** Elements are produced only when someone asks for `head` or `tail`. `take(n, ...)` is the key primitive that makes infinite sequences usable: it forces exactly `n` cells and stops.
- **Python already has some laziness built in:** boolean `and`/`or`, generator expressions, `itertools`, and short-circuiting are all lazy. This toolkit adds *memoized* laziness and *infinite functional sequences* on top.
- **Limitations to be aware of:**
  - `lazy_filter` may recurse deeply if there are long runs of non-matching elements.
  - Recursive lazy definitions (like Fibonacci) create one thunk per cell; for very large indices you may want an iterative/generator-based approach.
  - No automatic forcing in arithmetic: if you want `lazy_map(lambda x: x + 1, lst)`, the lambda runs only when that cell is forced, which is the desired behavior.

