```bash
python lazy_eval.py
```

Below is a complete, runnable implementation of a small `Matrix` class in pure Python. It supports creation, addition, subtraction, scalar multiplication, matrix multiplication (`@` / `*`), transpose, determinant, inverse, trace, and pretty printing. I also show a short usage example at the bottom and mention NumPy as the production alternative.

```python
#!/usr/bin/env python3
"""A small, self-contained Matrix implementation in pure Python."""

from __future__ import annotations

import math
from typing import Iterable, Sequence

EPS = 1e-9


class Matrix:
    """A rectangular matrix stored as a list of rows."""

    def __init__(self, data: Sequence[Sequence[float]]):
        if not data:
            raise ValueError("Matrix data must not be empty")
        rows = [list(row) for row in data]
        ncols = len(rows[0])
        if any(len(row) != ncols for row in rows):
            raise ValueError("All rows must have the same length")
        self.data = rows
        self.rows = len(rows)
        self.cols = ncols

    # ---------- factory helpers ----------
    @classmethod
    def zeros(cls, m: int, n: int) -> "Matrix":
        return cls([[0.0] * n for _ in range(m)])

    @classmethod
    def identity(cls, n: int) -> "Matrix":
        m = cls.zeros(n, n)
        for i in range(n):
            m.data[i][i] = 1.0
        return m

    @classmethod
    def from_list(cls, flat: Sequence[float], m: int, n: int) -> "Matrix":
        if len(flat) != m * n:
            raise ValueError("Flat list length does not match m*n")
        return cls([list(flat[i * n:(i + 1) * n]) for i in range(m)])

    # ---------- basic properties ----------
    def __getitem__(self, idx):
        # Supports m[i] -> row list and m[i, j] -> scalar
        if isinstance(idx, tuple):
            i, j = idx
            return self.data[i][j]
        return self.data[idx]

    def __setitem__(self, idx, value):
        if isinstance(idx, tuple):
            i, j = idx
            self.data[i][j] = value
        else:
            self.data[idx] = list(value)

    def shape(self) -> tuple[int, int]:
        return (self.rows, self.cols)

    def is_square(self) -> bool:
        return self.rows == self.cols

    def trace(self) -> float:
        if not self.is_square():
            raise ValueError("Trace is defined only for square matrices")
        return sum(self.data[i][i] for i in range(self.rows))

    # ---------- arithmetic ----------
    def __add__(self, other: "Matrix") -> "Matrix":
        if not isinstance(other, Matrix) or self.shape() != other.shape():
            raise ValueError("Matrices must have the same shape for addition")
        return Matrix(
            [[self.data[i][j] + other.data[i][j]
              for j in range(self.cols)]
             for i in range(self.rows)]
        )

    def __sub__(self, other: "Matrix") -> "Matrix":
        if not isinstance(other, Matrix) or self.shape() != other.shape():
            raise ValueError("Matrices must have the same shape for subtraction")
        return Matrix(
            [[self.data[i][j] - other.data[i][j]
              for j in range(self.cols)]
             for i in range(self.rows)]
        )

    def __mul__(self, other):
        # Matrix * Matrix  or  Matrix * scalar
        if isinstance(other, Matrix):
            if self.cols != other.rows:
                raise ValueError(
                    f"Incompatible shapes for multiplication: "
                    f"{self.shape()} and {other.shape()}"
                )
            result = [
                [sum(self.data[i][k] * other.data[k][j]
                     for k in range(self.cols))
                 for j in range(other.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)

        if isinstance(other, (int, float)):
            return Matrix(
                [[self.data[i][j] * other for j in range(self.cols)]
                 for i in range(self.rows)]
            )

        return NotImplemented

    __rmul__ = __mul__  # scalar * Matrix

    def __matmul__(self, other: "Matrix") -> "Matrix":
        return self * other

    def __neg__(self) -> "Matrix":
        return self * (-1)

    # ---------- linear-algebra helpers ----------
    def transpose(self) -> "Matrix":
        return Matrix(
            [[self.data[i][j] for i in range(self.rows)]
             for j in range(self.cols)]
        )

    def determinant(self) -> float:
        if not self.is_square():
            raise ValueError("Determinant is defined only for square matrices")
        n = self.rows
        # Work on a copy.
        m = [row[:] for row in self.data]
        det = 1.0

        for col in range(n):
            # Partial pivoting.
            pivot_row = max(range(col, n), key=lambda r: abs(m[r][col]))
            if abs(m[pivot_row][col]) < EPS:
                return 0.0  # Singular (or numerically singular)
            if pivot_row != col:
                m[col], m[pivot_row] = m[pivot_row], m[col]
                det = -det

            det *= m[col][col]

            # Eliminate rows below.
            for r in range(col + 1, n):
                factor = m[r][col] / m[col][col]
                for c in range(col, n):
                    m[r][c] -= factor * m[col][c]

        return det

    def inverse(self) -> "Matrix":
        if not self.is_square():
            raise ValueError("Inverse is defined only for square matrices")
        n = self.rows

        # Augmented matrix [A | I]
        aug = [self.data[i][:] + [1.0 if i == j else 0.0 for j in range(n)]
               for i in range(n)]

        for col in range(n):
            pivot_row = max(range(col, n), key=lambda r: abs(aug[r][col]))
            if abs(aug[pivot_row][col]) < EPS:
                raise ValueError("Matrix is singular and cannot be inverted")
            aug[col], aug[pivot_row] = aug[pivot_row], aug[col]

            # Normalize pivot row.
            pv = aug[col][col]
            aug[col] = [x / pv for x in aug[col]]

            # Eliminate this column from all other rows.
            for r in range(n):
                if r != col:
                    factor = aug[r][col]
                    aug[r] = [aug[r][k] - factor * aug[col][k]
                              for k in range(2 * n)]

        return Matrix([row[n:] for row in aug])

    # ---------- utilities ----------
    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Matrix) or self.shape() != other.shape():
            return False
        return all(
            math.isclose(self.data[i][j], other.data[i][j], rel_tol=1e-9, abs_tol=1e-9)
            for i in range(self.rows)
            for j in range(self.cols)
        )

    def __repr__(self) -> str:
        rows = ",\n  ".join(repr(row) for row in self.data)
        return f"Matrix([\n  {rows}\n])"

    def pretty(self, precision: int = 3) -> str:
        fmt = f"{{:.{precision}f}}"
        lines = []
        for row in self.data:
            lines.append("[" + ", ".join(fmt.format(x) for x in row) + "]")
        return "\n".join(lines)


# --------------------------------------------------------------------------- #
# Runnable demonstration
# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    A = Matrix([
        [1.0, 2.0, 3.0],
        [0.0, 1.0, 4.0],
        [5.0, 6.0, 0.0],
    ])
    B = Matrix([
        [7.0, 8.0],
        [9.0, 10.0],
        [11.0, 12.0],
    ])

    print("A =")
    print(A.pretty())
    print()

    print("B =")
    print(B.pretty())
    print()

    print("A + A =")
    print((A + A).pretty())
    print()

    print("A * 2.5 =")
    print((A * 2.5).pretty())
    print()

    print("A @ B =")
    print((A @ B).pretty())
    print()

    print("A^T =")
    print(A.transpose().pretty())
    print()

    print("det(A) =", A.determinant())
    print("trace(A) =", A.trace())
    print()

    A_inv = A.inverse()
    print("A^{-1} =")
    print(A_inv.pretty())
    print()

    # Verify: A * A^{-1} should be identity.
    identity_check = A @ A_inv
    print("A @ A^{-1} =")
    print(identity_check.pretty())
    print("Is it identity?", identity_check == Matrix.identity(3))

    # Solve A x = b using the inverse.
    b = Matrix([[1.0], [2.0], [3.0]])
    x = A_inv @ b
    print("\nSolution to A x = b:")
    print(x.pretty())
```

### Notes and practical advice

- **Numerical stability**: The implementation uses partial pivoting, which is better than naive elimination, but for large or ill-conditioned systems you would still prefer a dedicated library.
- **Performance**: Pure-Python triple loops are fine for small matrices (say, up to a few hundred elements) but become slow for large ones.
- **Production use**: In real code, prefer **NumPy** (or SciPy for advanced decompositions):

```python
import numpy as np

A = np.array([[1.0, 2.0, 3.0],
              [0.0, 1.0, 4.0],
              [5.0, 6.0, 0.0]])
b = np.array([1.0, 2.0, 3.0])

x = np.linalg.solve(A, b)   # stable, fast, well-tested
print(x)
```

- If you need exact arithmetic (e.g., for rational matrices), consider `fractions.Fraction` or `sympy.Matrix`.

# Memoization in Python — Complete Guide

Memoization caches the result of a function call keyed by its arguments, so repeated calls with the same inputs return instantly.

---

## 1. The standard way: `functools.lru_cache`

```python
import functools
import time

@functools.lru_cache(maxsize=128)   # None = unbounded
def fibonacci(n: int) -> int:
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

t0 = time.perf_counter()
print(fibonacci(40))          # 102334155
print(f"first call: {time.perf_counter() - t0:.4f}s")

t0 = time.perf_counter()
print(fibonacci(40))          # instant
print(f"cached call: {time.perf_counter() - t0:.6f}s")

print(fibonacci.cache_info()) # hits/misses/maxsize/currsize
fibonacci.cache_clear()        # invalidate
```

**Key options**

| Option | Meaning |
|---|---|
| `maxsize` | Max entries (LRU eviction); `None` = unbounded |
| `typed=True` | `f(1)` and `f(1.0)` cached separately |
| `functools.cache` (Py 3.9+) | Alias for `lru_cache(maxsize=None)` |

---

## 2. Manual decorator (to understand the mechanism)

```python
import functools
import time

def memoize(func):
    cache = {}
    lock = None  # add threading.Lock() for thread safety

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # Build a stable, hashable key. Values must be hashable.
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]

    wrapper.cache = cache
    wrapper.cache_clear = cache.clear
    return wrapper

@memoize
def expensive(x, y, *, factor=1):
    time.sleep(0.2)
    return (x + y) * factor

print(expensive(2, 3))          # computes
print(expensive(2, 3))          # cached
print(expensive(2, 3, factor=2)) # different key -> computes
expensive.cache_clear()
```

---

## 3. Handling unhashable arguments (lists, dicts)

`lru_cache` requires hashable args. Convert them inside the function, or use a custom key:

```python
import functools

def make_hashable(obj):
    if isinstance(obj, (list, tuple)):
        return tuple(make_hashable(x) for x in obj)
    if isinstance(obj, dict):
        return tuple(sorted((k, make_hashable(v)) for k, v in obj.items()))
    if isinstance(obj, set):
        return frozenset(make_hashable(x) for x in obj)
    return obj

def memoize_flexible(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (make_hashable(args), make_hashable(kwargs))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    wrapper.cache_clear = cache.clear
    return wrapper

@memoize_flexible
def process(data: list, config: dict):
    return sum(data) * config.get("factor", 1)

print(process([1, 2, 3], {"factor": 2}))  # 12
print(process([1, 2, 3], {"factor": 2}))  # cached
```

---

## 4. Memoizing instance methods (include `self` in the key)

`lru_cache` on methods works, but the cache lives on the *function*, shared across instances unless you use `typed`/per-instance caches. Common pattern: per-instance cache via a descriptor or store cache on `self`.

```python
import functools

class Greeter:
    def __init__(self, prefix):
        self.prefix = prefix
        self._cache = {}

    def greet(self, name):
        # manual instance-level cache
        if name not in self._cache:
            self._cache[name] = f"{self.prefix}, {name}!"
        return self._cache[name]

# Alternative: lru_cache on a "pure" helper that takes immutable state
class Greeter2:
    def __init__(self, prefix):
        self.prefix = prefix

    @functools.lru_cache(maxsize=None)  # careful: shared across instances
    def greet(self, name):
        return f"{self.prefix}, {name}!"

# Safer pattern: cache key includes the instance
def method_cache(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        key = (id(self), args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(self, *args, **kwargs)
        return cache[key]
    return wrapper

class Greeter3:
    def __init__(self, prefix):
        self.prefix = prefix

    @method_cache
    def greet(self, name):
        return f"{self.prefix}, {name}!"
```

---

## 5. LRU cache from scratch (capacity-based eviction)

```python
from collections import OrderedDict
import functools

class LRUCache:
    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key):
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)  # mark recently used
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)  # evict LRU

def lru_memoize(capacity=128):
    cache = LRUCache(capacity)
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            v = cache.get(key)
            if v is None and key not in cache.cache:
                v = func(*args, **kwargs)
                cache.put(key, v)
            return v
        wrapper.cache_clear = lambda: cache.cache.clear()
        return wrapper
    return decorator

@lru_memoize(capacity=2)
def square(n):
    print("computing", n)
    return n * n

for n in [1, 2, 3, 1]:   # 1 evicted after 3 new entries? capacity=2
    print(square(n))
```

