## 6. Time-to-Live (TTL) cache

```python
import functools
import time

def ttl_cache(ttl_seconds: float, maxsize: int = None):
    cache = {}  # key -> (value, expires_at)
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            now = time.monotonic()
            if key in cache:
                value, expires = cache[key]
                if now < expires:
                    return value
                del cache[key]
            value = func(*args, **kwargs)
            cache[key] = (value, now + ttl_seconds)
            if maxsize and len(cache) > maxsize:
                # evict oldest by insertion order (simple)
                oldest = next(iter(cache))
                del cache[oldest]
            return value
        wrapper.cache_clear = cache.clear
        return wrapper
    return decorator

@ttl_cache(ttl_seconds=1.0)
def fetch_price(symbol):
    print("network call", symbol)
    return 42.0

print(fetch_price("AAPL"))
print(fetch_price("AAPL"))   # cached
time.sleep(1.1)
print(fetch_price("AAPL"))   # recomputed
```

