```python
"""memo_demo.py — run with: python memo_demo.py"""
import functools, time, asyncio

# --- basic ---
@functools.lru_cache(maxsize=64, typed=True)
def fib(n):
    return n if n < 2 else fib(n-1) + fib(n-2)

assert fib(35) == 9227465
print("fib(35) cached OK; info:", fib.cache_info())

# --- manual with unhashable support ---
def _hashable(o):
    if isinstance(o, (list, tuple)):
        return tuple(_hashable(x) for x in o)
    if isinstance(o, dict):
        return tuple(sorted((_hashable(k), _hashable(v)) for k, v in o.items()))
    if isinstance(o, set):
        return frozenset(_hashable(x) for x in o)
    return o

def memoize(func):
    cache = {}
    @functools.wraps(func)
    def w(*a, **k):
        key = (_hashable(a), _hashable(k))
        if key not in cache:
            cache[key] = func(*a, **k)
        return cache[key]
    w.cache_clear = cache.clear
    return w

@memoize
def total(items, opts):
    time.sleep(0.1)
    return sum(items) * opts.get("mult", 1)

print(total([1,2,3], {"mult": 2}))  # 12
print(total([1,2,3], {"mult": 2}))  # cached
total.cache_clear()

# --- TTL ---
def ttl(seconds):
    store = {}
    def dec(f):
        @functools.wraps(f)
        def w(*a, **k):
            key = (a, tuple(sorted(k.items())))
            now = time.monotonic()
            if key in store and now < store[key][1]:
                return store[key][0]
            v = f(*a, **k)
            store[key] = (v, now + seconds)
            return v
        w.cache_clear = store.clear
        return w
    return dec

@ttl(0.5)
def now():
    return time.time()

print("ttl:", now())
time.sleep(0.6)
print("ttl after expiry:", now())

print("All demos passed.")
```

Run it and you'll see instant cached results, TTL expiry, and unhashable-arg support.

Below is a complete, runnable example that demonstrates the major kinds of test doubles (dummy, stub, fake, spy, mock) and common `unittest.mock` techniques in Python (patching, `side_effect`, `PropertyMock`, autospec, context managers, spies with `wraps`, etc.).

Save as `test_doubles_demo.py` and run with `python test_doubles_demo.py`.

```python
import os
import time
import unittest
from unittest.mock import (
    Mock, MagicMock, patch, PropertyMock,
    create_autospec, call
)

# ============================================================
# 1. Application code under test
# ============================================================

class UserRepository:
    def get(self, user_id): raise NotImplementedError
    def save(self, user): raise NotImplementedError

class EmailClient:
    def send(self, to, subject, body): raise NotImplementedError
    @property
    def is_configured(self): raise NotImplementedError

class Cache:
    def get(self, key): raise NotImplementedError
    def set(self, key, value, ttl=None): raise NotImplementedError

class InMemoryCache(Cache):
    def __init__(self):
        self._data = {}
    def get(self, key):
        return self._data.get(key, None)
    def set(self, key, value, ttl=None):
        self._data[key] = value

class UserService:
    def __init__(self, repo, email, cache):
        self.repo = repo
        self.email = email
        self.cache = cache

    def get_user(self, user_id):
        cached = self.cache.get(f"user:{user_id}")
        if cached is not None:
            return cached
        user = self.repo.get(user_id)
        self.cache.set(f"user:{user_id}", user, ttl=60)
        return user

    def register(self, name, email_addr):
        user = {"name": name, "email": email_addr}
        saved = self.repo.save(user)
        if self.email.is_configured:
            self.email.send(email_addr, "Welcome", f"Hi {name}")
        return saved

    def notify_all(self, user_ids, subject):
        for uid in user_ids:
            u = self.repo.get(uid)
            self.email.send(u["email"], subject, "hello")

def process_batch(items, worker):
    for item in items:
        worker(item)
        time.sleep(0.05)

class RegistrationService:
    def __init__(self):
        self.repo = UserRepository()
    def create(self, data):
        return self.repo.save(data)

def read_config():
    api_key = os.environ.get("API_KEY")
    if not api_key:
        raise RuntimeError("missing API_KEY")
    return api_key

def load_template(path):
    with open(path) as f:
        return f.read()

# ============================================================
# 2. Hand-written test doubles
# ============================================================

class StubUserRepo(UserRepository):
    """Stub: returns canned data, ignores input."""
    def __init__(self, user):
        self._user = user
    def get(self, user_id):
        return self._user
    def save(self, user):
        return user

class FakeUserRepo(UserRepository):
    """Fake: working in-memory implementation."""
    def __init__(self):
        self._store = {}
        self._next = 1
    def get(self, uid):
        if uid not in self._store:
            raise KeyError(uid)
        return self._store[uid]
    def save(self, user):
        user = dict(user)
        if "id" not in user:
            user["id"] = self._next
            self._next += 1
        self._store[user["id"]] = user
        return user

class SpyEmail(EmailClient):
    """Spy: delegates + records calls."""
    def __init__(self, configured=True):
        self.configured = configured
        self.calls = []
    @property
    def is_configured(self):
        return self.configured
    def send(self, to, subject, body):
        self.calls.append((to, subject, body))

# ============================================================
# 3. Tests
# ============================================================

class TestStub(unittest.TestCase):
    def test_get_user_returns_stubbed_user_and_caches(self):
        user = {"id": 7, "name": "Alice"}
        repo = StubUserRepo(user)          # stub
        cache = Mock()
        cache.get.return_value = None
        svc = UserService(repo, Mock(), cache)
        self.assertEqual(svc.get_user(7), user)
        cache.set.assert_called_once_with("user:7", user, ttl=60)


class TestFake(unittest.TestCase):
    def test_register_persists_and_emails(self):
        repo = FakeUserRepo()              # fake
        email = SpyEmail(configured=True)  # spy
        cache = Mock()
        svc = UserService(repo, email, cache)
        saved = svc.register("Bob", "bob@example.com")
        self.assertIn("id", saved)
        self.assertEqual(repo.get(saved["id"])["name"], "Bob")
        self.assertEqual(len(email.calls), 1)
        self.assertEqual(email.calls[0][0], "bob@example.com")


class TestMockExpectations(unittest.TestCase):
    def test_notify_all_calls_repo_and_email_in_order(self):
        repo = Mock()
        repo.get.side_effect = [
            {"id": 1, "email": "a@x.com"},
            {"id": 2, "email": "b@x.com"},
        ]
        email = Mock()
        svc = UserService(repo, email, Mock())
        svc.notify_all([1, 2], "Hi")
        self.assertEqual(repo.get.call_count, 2)
        email.send.assert_has_calls([
            call("a@x.com", "Hi", "hello"),
            call("b@x.com", "Hi", "hello"),
        ])


class TestSideEffectException(unittest.TestCase):
    def test_propagates_repo_error_and_skips_cache_write(self):
        repo = Mock()
        repo.get.side_effect = KeyError(42)
        cache = Mock()
        svc = UserService(repo, Mock(), cache)
        with self.assertRaises(KeyError):
            svc.get_user(42)
        cache.set.assert_not_called()


class TestPropertyMock(unittest.TestCase):
    def test_no_email_when_unconfigured(self):
        repo = Mock()
        repo.save.return_value = {"id": 1, "name": "X", "email": "x@x.com"}
        email = Mock()
        type(email).is_configured = PropertyMock(return_value=False)
        svc = UserService(repo, email, Mock())
        svc.register("X", "x@x.com")
        email.send.assert_not_called()


class TestAutospec(unittest.TestCase):
    def test_autospec_enforces_method_arity(self):
        repo = create_autospec(UserRepository, instance=True)
        repo.get.return_value = {"id": 1, "name": "Z"}
        svc = UserService(repo, Mock(), Mock())
        svc.get_user(1)
        repo.get.assert_called_once_with(1)
        with self.assertRaises(TypeError):
            repo.get(1, 2)  # wrong number of args


class TestPatchFunction(unittest.TestCase):
    def test_process_batch_calls_worker_and_sleeps(self):
        with patch("time.sleep") as mock_sleep:
            worker = Mock()
            process_batch([1, 2, 3], worker)
            self.assertEqual(worker.call_count, 3)
            self.assertEqual(mock_sleep.call_count, 3)
            mock_sleep.assert_called_with(0.05)


class TestPatchClass(unittest.TestCase):
    def test_registration_service_uses_patched_repo(self):
        with patch("__main__.UserRepository") as MockRepo:
            instance = MockRepo.return_value
            instance.save.return_value = {"id": 99}
            reg = RegistrationService()
            result = reg.create({"name": "Y"})
            MockRepo.assert_called_once_with()
            instance.save.assert_called_once_with({"name": "Y"})
            self.assertEqual(result["id"], 99)


class TestPatchDict(unittest.TestCase):
    def test_read_config_from_env(self):
        with patch.dict(os.environ, {"API_KEY": "abc123"}, clear=False):
            self.assertEqual(read_config(), "abc123")


class TestContextManagerMock(unittest.TestCase):
    def test_load_template(self):
        m = MagicMock()
        m.__enter__.return_value = m
        m.read.return_value = "hello template"
        with patch("builtins.open", return_value=m) as mock_open:
            data = load_template("foo.txt")
            self.assertEqual(data, "hello template")
            mock_open.assert_called_once_with("foo.txt")


class TestSpyWithWraps(unittest.TestCase):
    def test_cache_spy_records_and_delegates(self):
        real = InMemoryCache()
        original_set = real.set
        real.set = Mock(wraps=original_set)
        real.set("k", "v")
        self.assertEqual(real._data.get("k"), "v")   # real behavior preserved
        real.set.assert_called_once_with("k", "v")   # call recorded


class TestCallAssertions(unittest.TestCase):
    def test_call_introspection(self):
        m = Mock()
        m(1, key="v")
        m(2)
        self.assertTrue(m.called)
        self.assertEqual(m.call_count, 2)
        self.assertEqual(m.call_args_list, [call(1, key="v"), call(2)])
        m.assert_any_call(2)
        m.assert_called_with(2)  # last call


if __name__ == "__main__":
    unittest.main(verbosity=2)
```

### Key ideas covered

- **Dummy/Stub/Fake/Spy/Mock taxonomy**:
  - `StubUserRepo` always returns canned data.
  - `FakeUserRepo` is a working in-memory database.
  - `SpyEmail` records interactions while still being functional.
  - `Mock`/`MagicMock` are programmable fakes used to set expectations and verify calls.
- **Patching**: `patch`, `patch.object`, `patch.dict`, and `patch` as context managers.
- **Controlling behavior**: `return_value`, `side_effect` (sequences and exceptions), `PropertyMock`.
- **Safety**: `autospec`/`create_autospec` to prevent typos and enforce signatures.
- **Spies**: `Mock(wraps=...)` to observe real objects without losing their behavior.
- **Call verification**: `assert_called_once_with`, `assert_has_calls`, `call_args_list`, `ANY` (importable if needed), `assert_any_call`.
- **Context managers**: mocking `__enter__`/`__exit__` for file-like objects.

Run the file to see all tests pass.

## Explanation

**Test doubles** are substitutes for real dependencies so a test can focus on one unit:
- **Dummy**: passed around but never used.
- **Stub**: returns canned values.
- **Fake**: working but simplified implementation, e.g. in-memory DB.
- **Spy**: real object + records how it was used.
- **Mock**: pre-programmed with expectations; verifies behavior.

**Mocking** creates objects that:
1. return controlled values (`return_value`, `side_effect`)
2. record calls (`call_count`, `call_args`, `call_args_list`)
3. assert expected interactions (`assert_called_once_with`, etc.)

Python’s standard tool is `unittest.mock`, but the core idea is simple: an object that is callable, records invocations, delegates optionally, and exposes assertions.

## Core implementation

```python
from __future__ import annotations

import importlib
from collections import namedtuple
from functools import wraps

# Sentinels
DEFAULT = object()
UNSET = object()

# A recorded call: (positional_args, keyword_args)
Call = namedtuple("Call", ["args", "kwargs"])


class Mock:
    """
    A minimal but useful mock object.

    Supports:
    - callable behavior
    - return_value / side_effect
    - wrapping a real object/function
    - call recording and assertions
    - automatic child mocks for attribute access
    """

    def __init__(self, name: str | None = None,
                 return_value=UNSET,
                 side_effect=None,
                 wraps=None):
        # Initialize children storage first to avoid __getattr__ recursion.
        self._mock_children = {}
        self._mock_name = name or "mock"
        self._mock_return_value = return_value
        self._mock_side_effect = side_effect
        self._mock_side_effect_iter = None
        self._mock_wraps = wraps
        self._mock_calls: list[Call] = []

    # ------------------------------------------------------------------ #
    # Properties exposed like unittest.mock
    # ------------------------------------------------------------------ #
    @property
    def return_value(self):
        return self._mock_return_value

    @return_value.setter
    def return_value(self, value):
        self._mock_return_value = value

    @property
    def side_effect(self):
        return self._mock_side_effect

    @side_effect.setter
    def side_effect(self, value):
        self._mock_side_effect = value
        self._mock_side_effect_iter = None

    @property
    def wraps(self):
        return self._mock_wraps

    @wraps.setter
    def wraps(self, value):
        self._mock_wraps = value

    @property
    def called(self) -> bool:
        return bool(self._mock_calls)

    @property
    def call_count(self) -> int:
        return len(self._mock_calls)

    @property
    def call_args(self):
        return self._mock_calls[-1] if self._mock_calls else None

    @property
    def call_args_list(self):
        return list(self._mock_calls)

    # ------------------------------------------------------------------ #
    # Callable behavior
    # ------------------------------------------------------------------ #
    def __call__(self, *args, **kwargs):
        # Record first, even if side_effect raises.
        self._mock_calls.append(Call(args, kwargs))

        side_effect = self._mock_side_effect

        # Exception instance as side_effect
        if isinstance(side_effect, BaseException):
            raise side_effect

        if side_effect is not None:
            # Callable side_effect: invoke it
            if callable(side_effect):
                return side_effect(*args, **kwargs)

            # Iterable side_effect: yield next value
            if self._mock_side_effect_iter is None:
                self._mock_side_effect_iter = iter(side_effect)
            try:
                result = next(self._mock_side_effect_iter)
            except StopIteration:
                raise
            if isinstance(result, BaseException):
                raise result
            return result

        # Wrap a real object/function
        if self._mock_wraps is not None:
            wrapped = self._mock_wraps
            if callable(wrapped):
                return wrapped(*args, **kwargs)
            return wrapped

        # Normal return value
        rv = self._mock_return_value
        return None if rv is UNSET else rv

    # ------------------------------------------------------------------ #
    # Auto-child mocks for attribute access
    # ------------------------------------------------------------------ #
    def __getattr__(self, name: str):
        # Called only when normal attribute lookup fails.
        if name.startswith("_mock_"):
            raise AttributeError(name)

        children = self._mock_children
        if name not in children:
            children[name] = Mock(name=f"{self._mock_name}.{name}")
        return children[name]

    # ------------------------------------------------------------------ #
    # Reset / assertions
    # ------------------------------------------------------------------ #
    def reset_mock(self):
        self._mock_calls.clear()
        self._mock_side_effect_iter = None
        for child in self._mock_children.values():
            child.reset_mock()

    def assert_called(self):
        if not self._mock_calls:
            raise AssertionError(f"{self._mock_name} was not called")

    def assert_not_called(self):
        if self._mock_calls:
            raise AssertionError(
                f"{self._mock_name} was called unexpectedly: "
                f"{self._mock_calls[-1]!r}"
            )

    def assert_called_once(self):
        if len(self._mock_calls) != 1:
            raise AssertionError(
                f"Expected {self._mock_name} to be called once, "
                f"but it was called {len(self._mock_calls)} times"
            )

    def assert_called_with(self, *args, **kwargs):
        expected = Call(args, kwargs)
        if not self._mock_calls or self._mock_calls[-1] != expected:
            actual = self._mock_calls[-1] if self._mock_calls else None
            raise AssertionError(
                f"Expected call: {expected!r}\nActual call:   {actual!r}"
            )

    def assert_called_once_with(self, *args, **kwargs):
        self.assert_called_once()
        self.assert_called_with(*args, **kwargs)

    def assert_any_call(self, *args, **kwargs):
        expected = Call(args, kwargs)
        if expected not in self._mock_calls:
            raise AssertionError(f"{expected!r} was not found in calls")

    def __repr__(self):
        return f"<Mock name={self._mock_name!r} calls={len(self._mock_calls)}>"


class _patch:
    """
    Context manager and decorator for temporarily replacing an attribute.
    """

    def __init__(self, target, attribute, new=DEFAULT, **kwargs):
        # target + attribute can describe either:
        #   ("module.path.attr", None)  for string patching
        #   (obj, "attr")               for object patching
        if attribute is None:
            module_name, attr = str(target).rsplit(".", 1)
            self._obj = importlib.import_module(module_name)
            self._attr = attr
        else:
            self._obj = target
            self._attr = attribute

        self._new = new
        self._kwargs = kwargs

        self._mock = None
        self._original = None
        self._missing = False
        try:
            self._original = getattr(self._obj, self._attr)
        except AttributeError:
            self._missing = True

    def _make_value(self):
        if self._new is DEFAULT:
            return Mock(**self._kwargs)
        return self._new

    def __enter__(self):
        self._mock = self._make_value()
        setattr(self._obj, self._attr, self._mock)
        return self._mock

    def __exit__(self, exc_type, exc, traceback):
        if self._missing:
            try:
                delattr(self._obj, self._attr)
            except AttributeError:
                pass
        else:
            setattr(self._obj, self._attr, self._original)
        return False

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            with self:
                # Inject mock as the last positional argument.
                return func(*args, self._mock, **kwargs)
        return wrapper


def patch(target, attribute=None, new=DEFAULT, **kwargs):
    """patch('pkg.mod.attr') or patch(obj, 'attr', ...)."""
    return _patch(target, attribute, new=new, **kwargs)


def patch_object(obj, attribute, new=DEFAULT, **kwargs):
    """Explicit object/attribute patching."""
    return _patch(obj, attribute, new=new, **kwargs)


def install_spy(obj, attribute):
    """
    Replace obj.attribute with a Mock that wraps and records calls to
    the original callable.
    """
    original = getattr(obj, attribute)
    mock = Mock(name=f"spy[{attribute}]", wraps=original)
    setattr(obj, attribute, mock)
    return mock


# ---------------------------------------------------------------------- #
# Example usage and self-checks
# ---------------------------------------------------------------------- #
if __name__ == "__main__":
    # ---------- Service under test ----------
    class OrderService:
        def __init__(self, gateway, repository):
            self.gateway = gateway
            self.repository = repository

        def place_order(self, amount):
            transaction_id = self.gateway.charge(amount)
            self.repository.save(transaction_id)
            return transaction_id

    # ---------- Basic mock test ----------
    gateway = Mock()
    gateway.charge.return_value = "TX-123"

    repository = Mock()
    service = OrderService(gateway, repository)

    result = service.place_order(50)

    assert result == "TX-123"
    gateway.charge.assert_called_once_with(50)
    repository.save.assert_called_once_with("TX-123")
    print("basic mock test: OK")

    # ---------- side_effect as iterable ----------
    m = Mock()
    m.side_effect = [1, 2, ValueError("boom")]
    assert m() == 1
    assert m() == 2
    try:
        m()
        raise AssertionError("expected ValueError")
    except ValueError:
        pass
    print("side_effect iterable test: OK")

    # ---------- patch as context manager ----------
    class Settings:
        DEBUG = False

    with patch_object(Settings, "DEBUG", new=True):
        assert Settings.DEBUG is True
    assert Settings.DEBUG is False
    print("patch context manager test: OK")

    # ---------- spy ----------
    class Calculator:
        def add(self, a, b):
            return a + b

    calc = Calculator()
    spy = install_spy(calc, "add")
    assert calc.add(2, 3) == 5
    spy.assert_called_once_with(2, 3)
    print("spy test: OK")

    print("all self-checks passed")
```

## Key interview points to mention

- **Mock vs stub vs fake**: mocks verify interactions; stubs provide data; fakes implement real behavior simply.
- **Don’t over-mock**: if every dependency is mocked, you may test wiring rather than behavior.
- **Prefer behavior assertions** (`assert_called_once_with`) over deep implementation assertions when possible.
- **`side_effect`** is for dynamic behavior, exceptions, or sequences.
- **`wraps`** lets a spy keep real behavior while recording calls.
- **Patching** should be restored reliably, hence context managers/decorators.
- In production, prefer `unittest.mock` or `pytest-mock`; the above demonstrates the underlying mechanics.

## Exercise

Build a small terminal **Contact Book** using the MVC pattern.

- **Model**: stores contacts and supports `add`, `list_all`, and `search`.
- **View**: handles all terminal input/output.
- **Controller**: connects user actions to model operations and view updates.

Supported actions:

1. Add a contact
2. List all contacts
3. Search contacts by name
4. Quit

---

## Step-by-step solution

### 1. Define the Model

The model knows nothing about the terminal. It only stores and searches data.

```python
from dataclasses import dataclass

@dataclass
class Contact:
    name: str
    phone: str
    email: str

class ContactBook:
    def __init__(self):
        self._contacts: list[Contact] = []

    def add(self, contact: Contact) -> None:
        self._contacts.append(contact)

    def all(self) -> list[Contact]:
        return list(self._contacts)

    def search(self, query: str) -> list[Contact]:
        query = query.strip().lower()
        return [
            contact for contact in self._contacts
            if query in contact.name.lower()
        ]
```

### 2. Define the View

The view is responsible for printing and reading input. It does not decide what the data means.

```python
class ConsoleView:
    def show_menu(self) -> None:
        print("\nContact Book")
        print("1. Add contact")
        print("2. List contacts")
        print("3. Search contacts")
        print("4. Quit")

    def get_choice(self) -> str:
        return input("Choose an option: ").strip()

    def get_contact_fields(self) -> tuple[str, str, str]:
        name = input("Name: ").strip()
        phone = input("Phone: ").strip()
        email = input("Email: ").strip()
        return name, phone, email

    def show_contacts(self, contacts: list[Contact]) -> None:
        if not contacts:
            print("No contacts found.")
            return

        print("\nContacts:")
        for index, contact in enumerate(contacts, start=1):
            print(f"{index}. {contact.name} | {contact.phone} | {contact.email}")

    def show_message(self, message: str) -> None:
        print(message)

    def show_error(self, message: str) -> None:
        print(f"Error: {message}")
```

### 3. Define the Controller

The controller coordinates the model and view. Business rules such as “name cannot be empty” belong here or in the model, not in the view.

```python
class ContactController:
    def __init__(self, model: ContactBook, view: ConsoleView):
        self.model = model
        self.view = view

    def run(self) -> None:
        while True:
            self.view.show_menu()
            choice = self.view.get_choice()

            if choice == "1":
                self._add_contact()
            elif choice == "2":
                self._list_contacts()
            elif choice == "3":
                self._search_contacts()
            elif choice == "4":
                self.view.show_message("Goodbye.")
                break
            else:
                self.view.show_error("Invalid menu choice.")

    def _add_contact(self) -> None:
        name, phone, email = self.view.get_contact_fields()

        if not name:
            self.view.show_error("Name is required.")
            return

        contact = Contact(name=name, phone=phone, email=email)
        self.model.add(contact)
        self.view.show_message("Contact added.")

    def _list_contacts(self) -> None:
        contacts = self.model.all()
        self.view.show_contacts(contacts)

    def _search_contacts(self) -> None:
        query = input("Search name: ").strip()
        contacts = self.model.search(query)
        self.view.show_contacts(contacts)
```

### 4. Wire everything together

```python
def main() -> None:
    model = ContactBook()
    view = ConsoleView()
    controller = ContactController(model, view)
    controller.run()

if __name__ == "__main__":
    main()
```

