Below is a complete, runnable example that shows:

1. Python’s built‑in null (`None`) and optional type hints.
2. A small, reusable `Option`/`Maybe` monad (`Some` / `Nothing`) for explicit optional values.
3. Null‑safe helpers: coalescing, safe attribute access, safe dict access.
4. A realistic demo (user lookup with optional fields).

Save as `optional_demo.py` and run with `python optional_demo.py`.

```python
# optional_demo.py
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable, Generic, Iterable, TypeVar, Union

T = TypeVar("T")
U = TypeVar("U")

# --------------------------------------------------------------------------- #
# 1. Explicit optional values: Some / Nothing
# --------------------------------------------------------------------------- #

class Nothing:
    """Singleton representing the absence of a value."""
    _instance: "Nothing | None" = None

    def __new__(cls) -> "Nothing":
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:
        return "Nothing"

    def __bool__(self) -> bool:
        return False

    def map(self, f: Callable[[Any], U]) -> "Nothing":
        return self

    def flat_map(self, f: Callable[[Any], "Option[U]"]) -> "Nothing":
        return self

    def filter(self, pred: Callable[[Any], bool]) -> "Nothing":
        return self

    def or_else(self, default: Any) -> Any:
        return default() if callable(default) else default

    def get_or_none(self) -> None:
        return None

    def get_or_raise(self, exc: Exception | None = None) -> Any:
        raise exc if exc is not None else ValueError("Called get_or_raise on Nothing")

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Nothing)

    def __hash__(self) -> int:
        return hash("Nothing")


@dataclass(frozen=True)
class Some(Generic[T]):
    value: T

    def __repr__(self) -> str:
        return f"Some({self.value!r})"

    def __bool__(self) -> bool:
        return True

    def map(self, f: Callable[[T], U]) -> "Option[U]":
        return Some(f(self.value))

    def flat_map(self, f: Callable[[T], "Option[U]"]) -> "Option[U]":
        return f(self.value)

    def filter(self, pred: Callable[[T], bool]) -> "Option[T]":
        return self if pred(self.value) else NOTHING

    def or_else(self, default: Any) -> T:
        return self.value

    def get_or_none(self) -> T:
        return self.value

    def get_or_raise(self, exc: Exception | None = None) -> T:
        return self.value

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Some) and self.value == other.value

    def __hash__(self) -> int:
        return hash(("Some", self.value))


NOTHING: Nothing = Nothing()
Option = Union[Some[T], Nothing]


def some(value: T) -> Some[T]:
    return Some(value)


def nothing() -> Nothing:
    return NOTHING


def option(value: T | None) -> Option[T]:
    """Lift a possibly-None Python value into an Option."""
    return NOTHING if value is None else Some(value)


# --------------------------------------------------------------------------- #
# 2. Null-safe helpers
# --------------------------------------------------------------------------- #

def coalesce(*values: Any) -> Any:
    """Return the first value that is not None."""
    for v in values:
        if v is not None:
            return v
    return None


def safe_get(obj: Any, path: str, default: Any = None) -> Any:
    """Safely traverse attributes/dict keys using a dotted path.

    Example: safe_get(user, "profile.email", default="n/a")
    """
    cur = obj
    for part in path.split("."):
        if cur is None:
            return default
        if isinstance(cur, dict):
            cur = cur.get(part, default=None)
        else:
            cur = getattr(cur, part, None)
        if cur is None:
            # still continue? If an intermediate is None we already return default
            pass
    return cur if cur is not None else default


def null_object_proxy() -> Any:
    """A Null Object that swallows attribute access and calls, returning itself."""
    class _Null:
        def __getattr__(self, name: str) -> "_Null":
            return self

        def __call__(self, *args: Any, **kwargs: Any) -> "_Null":
            return self

        def __bool__(self) -> bool:
            return False

        def __repr__(self) -> str:
            return "Null"

    return _Null()


# --------------------------------------------------------------------------- #
# 3. Demo domain
# --------------------------------------------------------------------------- #

@dataclass
class Profile:
    bio: str | None = None
    email: str | None = None


@dataclass
class User:
    id: int
    name: str
    profile: Profile | None = None
    tags: list[str] = field(default_factory=list)


def find_user(users: list[User], uid: int) -> Option[User]:
    for u in users:
        if u.id == uid:
            return Some(u)
    return NOTHING


def user_email(users: list[User], uid: int) -> str:
    """Return an email or a fallback, never None."""
    return (
        find_user(users, uid)
        .flat_map(lambda u: option(u.profile))
        .flat_map(lambda p: option(p.email))
        .or_else("no-email@example.com")
    )


def upper_tags(users: list[User], uid: int) -> list[str]:
    return (
        find_user(users, uid)
        .map(lambda u: [t.upper() for t in u.tags])
        .or_else([])
    )


# --------------------------------------------------------------------------- #
# 4. Runnable demo + assertions
# --------------------------------------------------------------------------- #

def main() -> None:
    users = [
        User(1, "Alice", Profile(bio="hi", email="alice@example.com"), ["admin", "dev"]),
        User(2, "Bob", Profile(bio="hello")),          # email is None
        User(3, "Carol", None),                        # profile is None
    ]

    # --- basic Option usage ---
    assert find_user(users, 1) == Some(users[0])
    assert find_user(users, 999) == NOTHING
    assert bool(find_user(users, 1)) is True
    assert bool(find_user(users, 999)) is False

    # --- map / flat_map ---
    name = find_user(users, 1).map(lambda u: u.name).or_else("unknown")
    assert name == "Alice"

    bio = (
        find_user(users, 3)
        .flat_map(lambda u: option(u.profile))
        .flat_map(lambda p: option(p.bio))
        .or_else("(no bio)")
    )
    assert bio == "(no bio)"

    # --- filter ---
    admins = (
        find_user(users, 1)
        .filter(lambda u: "admin" in u.tags)
        .map(lambda u: u.name)
        .or_else("none")
    )
    assert admins == "Alice"

    non_admin = (
        find_user(users, 2)
        .filter(lambda u: "admin" in u.tags)
        .or_else("not-admin")
    )
    assert non_admin == "not-admin"

    # --- email coalescing / safe access ---
    assert user_email(users, 1) == "alice@example.com"
    assert user_email(users, 2) == "no-email@example.com"
    assert user_email(users, 3) == "no-email@example.com"
    assert user_email(users, 999) == "no-email@example.com"

    assert safe_get(users[0], "profile.email") == "alice@example.com"
    assert safe_get(users[1], "profile.email", default="MISSING") == "MISSING"
    assert safe_get(users[2], "profile.email", default="MISSING") == "MISSING"
    assert safe_get(users[2], "profile.email.bio", default="MISSING") == "MISSING"

    assert coalesce(None, None, "x", "y") == "x"
    assert coalesce(None, None) is None

    # --- upper tags ---
    assert upper_tags(users, 1) == ["ADMIN", "DEV"]
    assert upper_tags(users, 999) == []

    # --- Null Object pattern ---
    n = null_object_proxy()
    assert bool(n) is False
    assert repr(n.foo.bar.baz()) == "Null"

    print("All assertions passed.")
    print("user 1 email:", user_email(users, 1))
    print("user 3 bio:  ", bio)
    print("upper tags:  ", upper_tags(users, 1))


if __name__ == "__main__":
    main()
```

### What this demonstrates

- **Null (`None`)**: Python’s single null value. We never “invent” another null; we just handle `None` consistently.
- **Optional types**: `str | None`, `Profile | None`, and `Option[T]` for explicit presence/absence.
- **`Option` monad**: `Some`/`Nothing` make “missing” a first‑class value, avoiding `AttributeError` chains and accidental `None` propagation. `map`, `flat_map`, `filter`, and `or_else` compose safely.
- **`option(value)`**: lifts `None`‑able Python values into the monad at boundaries (e.g., parsed JSON, DB rows).
- **`safe_get` / `coalesce`**: pragmatic null‑safe traversal and default selection for real‑world data.
- **Null Object**: `null_object_proxy()` shows the pattern where a sentinel absorbs operations instead of raising.

You can scale this pattern up in real projects by replacing `Option` with a library such as `returns` or `pydantic`, but the above is fully self‑contained and runnable.

## Null and optional values in Python

### 1) `None` is Python’s null
- `None` is a singleton object of type `NoneType`.
- A function with no `return` (or bare `return`) returns `None`.
- Test with identity: `x is None` / `x is not None` (do **not** use `==`).

```python
def find_user(user_id):
    return None  # means "no result"

user = find_user(42)
if user is None:
    print("not found")
```

### 2) `Optional[T]` is a type hint, not runtime behavior
- `typing.Optional[T]` (or `T | None` in 3.10+) means “either `T` or `None`”.
- Python does not enforce it at runtime; static tools (mypy/pyright) do.

```python
from typing import Optional

def parse_int(s: str) -> Optional[int]:
    try:
        return int(s)
    except ValueError:
        return None
```

### 3) `None` vs “missing/unset”
- `None` can legitimately mean “no value”, but sometimes you need to distinguish **“not provided”** from **“explicitly None”**.
- Use a **sentinel** for “unset”:

```python
_MISSING = object()

def create(name, age=_MISSING):
    if age is _MISSING:
        age = 0
```

### 4) Null-safety patterns
- **EAFP** (try/except) is idiomatic:
```python
try:
    value = obj.nested.attr
except AttributeError:
    value = None
```
- Avoid truthiness for optionals (`if x:` fails for `0`, `""`, `[]`). Use `if x is not None:`.
- Avoid mutable default args: use `None` + sentinel/replace.

### 5) A “real” Optional container (Maybe)
Python has no built-in `Optional` monad like Java/Scala/Rust. We can implement a small, safe container that:
- wraps a value or absence,
- supports `map`, `flat_map`, `filter`,
- avoids `None` propagation bugs.

---

## Implementation: `Maybe` (core optional container)

```python
from __future__ import annotations

from typing import TypeVar, Generic, Callable, Optional as Opt

T = TypeVar("T")
U = TypeVar("U")


class Maybe(Generic[T]):
    """
    A minimal optional container.

    Invariants:
      - Either holds a concrete value (_has_value is True)
      - Or is empty (_has_value is False)

    This prevents accidental use of None as a real value and makes
    transformations explicit.
    """

    __slots__ = ("_value", "_has_value")

    def __init__(self, value: Opt[T], has_value: bool) -> None:
        # Private constructor. Prefer Maybe.some / Maybe.nothing / Maybe.of.
        self._value = value
        self._has_value = has_value

    # ---- Constructors ----

    @classmethod
    def some(cls, value: T) -> "Maybe[T]":
        """Wrap a non-None value."""
        if value is None:
            raise ValueError("Maybe.some() does not accept None; use Maybe.nothing()")
        return cls(value, True)

    @classmethod
    def nothing(cls) -> "Maybe[T]":
        """Create an empty optional."""
        return cls(None, False)

    @classmethod
    def of(cls, value: Opt[T]) -> "Maybe[T]":
        """Lift a possibly-None value into Maybe."""
        if value is None:
            return cls.nothing()
        return cls.some(value)

    # ---- State queries ----

    def is_present(self) -> bool:
        return self._has_value

    def is_empty(self) -> bool:
        return not self._has_value

    # ---- Value access ----

    def get(self) -> T:
        """Return value or raise if empty."""
        if not self._has_value:
            raise RuntimeError("Cannot get value from empty Maybe")
        return self._value  # type: ignore[return-value]

    def get_or_else(self, default: U) -> T | U:
        """Return value if present else default."""
        if self._has_value:
            return self._value  # type: ignore[return-value]
        return default

    def get_or_else_get(self, supplier: Callable[[], U]) -> T | U:
        """Lazy default: supplier called only when empty."""
        if self._has_value:
            return self._value  # type: ignore[return-value]
        return supplier()

    # ---- Transformations ----

    def map(self, fn: Callable[[T], U]) -> "Maybe[U]":
        """Apply fn if present; propagate emptiness otherwise."""
        if self._has_value:
            return Maybe.some(fn(self._value))  # type: ignore[arg-type]
        return Maybe.nothing()

    def flat_map(self, fn: Callable[[T], "Maybe[U]"]) -> "Maybe[U]":
        """Apply fn returning Maybe; avoid nested Maybe."""
        if self._has_value:
            result = fn(self._value)  # type: ignore[arg-type]
            if not isinstance(result, Maybe):
                raise TypeError("flat_map function must return Maybe")
            return result
        return Maybe.nothing()

    def filter(self, predicate: Callable[[T], bool]) -> "Maybe[T]":
        """Keep value only if predicate is True."""
        if self._has_value and predicate(self._value):  # type: ignore[arg-type]
            return self
        return Maybe.nothing()

    # ---- Interop ----

    def to_optional(self) -> Opt[T]:
        """Convert back to normal Python Optional."""
        return self._value if self._has_value else None

    def or_else(self, other: "Maybe[T]") -> "Maybe[T]":
        """Return self if present, else other."""
        return self if self._has_value else other

    # ---- Dunder methods ----

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Maybe):
            return NotImplemented
        if self._has_value != other._has_value:
            return False
        if not self._has_value:
            return True  # both empty
        return self._value == other._value

    def __repr__(self) -> str:
        if self._has_value:
            return f"Maybe.some({self._value!r})"
        return "Maybe.nothing()"

    def __bool__(self) -> bool:
        # Makes Maybe usable in conditionals, but explicit is clearer.
        return self._has_value
```

