## Usage examples

```python
# Lift None safely
m = Maybe.of(parse_int("abc"))   # Maybe.nothing()
print(m.get_or_else(0))          # 0

# Transform
name = Maybe.some("  alice  ") \
          .map(str.strip) \
          .map(str.title)
print(name)                      # Maybe.some('Alice')

# Flat map: chained lookup
def find_email(user_id: int) -> Maybe[str]:
    return Maybe.of(None) if user_id == 0 else Maybe.some("a@b.com")

email = Maybe.some(7).flat_map(find_email)
print(email.get_or_else("unknown"))  # a@b.com

# Filter
adult = Maybe.some(17).filter(lambda age: age >= 18)
print(adult)  # Maybe.nothing()

# Conditional use
if Maybe.some("x"):
    print("present")
```

