## Operator overloading in Python

Below is a complete, runnable example. It implements a mutable `Vector` class with:

- arithmetic: `+`, `-`, `*`, `/`, `//`, `%`, `**`
- reflected operands: `0 + v`, `0 - v`
- in-place variants: `+=`, `-=`, `*=`, `/=`
- unary operators: `-v`, `+v`, `abs(v)`
- rich comparisons with `functools.total_ordering`
- indexing and slicing: `v[i]`, `v[i] = x`, `v[a:b]`
- iteration, membership, length
- `@` as dot product
- readable `repr`, `str`, and formatting

```python
import math
from functools import total_ordering


@total_ordering
class Vector:
    """A simple mutable vector with overloaded operators."""

    __hash__ = None  # Mutable objects should generally not be hashable.
    __slots__ = ("_components",)

    def __init__(self, *components):
        # Convenient construction: Vector([1, 2, 3]) as well as Vector(1, 2, 3)
        if (
            len(components) == 1
            and not isinstance(components[0], (int, float, complex))
            and hasattr(components[0], "__iter__")
        ):
            components = tuple(components[0])

        values = []
        for value in components:
            if not isinstance(value, (int, float)):
                raise TypeError(
                    f"Vector components must be ints or floats, got {type(value).__name__}"
                )
            values.append(value)

        self._components = list(values)

    # ------------------------------------------------------------------
    # Basic container behavior
    # ------------------------------------------------------------------

    def __len__(self):
        return len(self._components)

    def __getitem__(self, index):
        if isinstance(index, slice):
            return Vector(self._components[index])
        return self._components[index]

    def __setitem__(self, index, value):
        if isinstance(index, slice):
            indices = range(*index.indices(len(self)))
            if isinstance(value, (int, float)):
                values = [value] * len(indices)
            else:
                values = list(value)

            if len(values) != len(indices):
                raise ValueError(
                    f"Expected {len(indices)} values for slice, got {len(values)}"
                )

            for i, item in zip(indices, values):
                if not isinstance(item, (int, float)):
                    raise TypeError("Vector components must be ints or floats")
                self._components[i] = item
        else:
            if not isinstance(value, (int, float)):
                raise TypeError("Vector components must be ints or floats")
            self._components[index] = value

    def __iter__(self):
        return iter(self._components)

    def __contains__(self, value):
        return value in self._components

    # ------------------------------------------------------------------
    # Representation
    # ------------------------------------------------------------------

    def __repr__(self):
        return f"Vector({', '.join(repr(x) for x in self._components)})"

    def __str__(self):
        return "(" + ", ".join(str(x) for x in self._components) + ")"

    def __format__(self, format_spec):
        return "(" + ", ".join(format(x, format_spec) for x in self._components) + ")"

    def __bool__(self):
        return any(self._components)

    # ------------------------------------------------------------------
    # Unary operators
    # ------------------------------------------------------------------

    def __neg__(self):
        return Vector(-x for x in self._components)

    def __pos__(self):
        return Vector(self._components)

    def __abs__(self):
        return math.sqrt(sum(x * x for x in self._components))

    def __round__(self, ndigits=None):
        return Vector(round(x, ndigits) for x in self._components)

    # ------------------------------------------------------------------
    # Binary arithmetic operators
    # ------------------------------------------------------------------

    def __add__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        if len(self) != len(other):
            raise ValueError("Vectors must have the same dimension")
        return Vector(a + b for a, b in zip(self._components, other._components))

    def __radd__(self, other):
        # Allows expressions such as sum([v1, v2, v3]).
        if isinstance(other, (int, float)) and other == 0:
            return Vector(self._components)
        return NotImplemented

    def __sub__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        if len(self) != len(other):
            raise ValueError("Vectors must have the same dimension")
        return Vector(a - b for a, b in zip(self._components, other._components))

    def __rsub__(self, other):
        if isinstance(other, (int, float)) and other == 0:
            return -self
        return NotImplemented

    def __mul__(self, other):
        # Here * means scalar multiplication.
        if not isinstance(other, (int, float)):
            return NotImplemented
        return Vector(x * other for x in self._components)

    __rmul__ = __mul__

    def __truediv__(self, other):
        if not isinstance(other, (int, float)):
            return NotImplemented
        if other == 0:
            raise ZeroDivisionError("division by zero")
        return Vector(x / other for x in self._components)

    def __floordiv__(self, other):
        if not isinstance(other, (int, float)):
            return NotImplemented
        if other == 0:
            raise ZeroDivisionError("division by zero")
        return Vector(x // other for x in self._components)

    def __mod__(self, other):
        if not isinstance(other, (int, float)):
            return NotImplemented
        if other == 0:
            raise ZeroDivisionError("division by zero")
        return Vector(x % other for x in self._components)

    def __pow__(self, other):
        if not isinstance(other, (int, float)):
            return NotImplemented
        return Vector(x ** other for x in self._components)

    def __matmul__(self, other):
        # @ is dot product for two vectors.
        if not isinstance(other, Vector):
            return NotImplemented
        if len(self) != len(other):
            raise ValueError("Vectors must have the same dimension")
        return sum(a * b for a, b in zip(self._components, other._components))

    __rmatmul__ = __matmul__

    # ------------------------------------------------------------------
    # In-place operators
    # ------------------------------------------------------------------

    def __iadd__(self, other):
        if not isinstance(other, Vector) or len(self) != len(other):
            return NotImplemented
        for i, value in enumerate(other._components):
            self._components[i] += value
        return self

    def __isub__(self, other):
        if not isinstance(other, Vector) or len(self) != len(other):
            return NotImplemented
        for i, value in enumerate(other._components):
            self._components[i] -= value
        return self

    def __imul__(self, other):
        if not isinstance(other, (int, float)):
            return NotImplemented
        for i in range(len(self)):
            self._components[i] *= other
        return self

    def __itruediv__(self, other):
        if not isinstance(other, (int, float)):
            return NotImplemented
        if other == 0:
            raise ZeroDivisionError("division by zero")
        for i in range(len(self)):
            self._components[i] /= other
        return self

    # ------------------------------------------------------------------
    # Rich comparisons
    # ------------------------------------------------------------------

    def __eq__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return self._components == other._components

    def __lt__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        if len(self) != len(other):
            raise ValueError("Vectors must have the same dimension")
        return self._components < other._components


if __name__ == "__main__":
    v = Vector(1, 2, 3)
    w = Vector(4, 5, 6)

    print("v =", v)
    print("w =", w)
    print("v + w =", v + w)
    print("v - w =", v - w)
    print("3 * v =", 3 * v)
    print("v / 2 =", v / 2)
    print("v @ w (dot product) =", v @ w)
    print("abs(v) =", abs(v))
    print("-v =", -v)
    print("v[1] =", v[1])
    print("v[:2] =", v[:2])

    # In-place mutation
    v += Vector(10, 20, 30)
    print("after v += ...:", v)

    # Comparisons
    print("v == w:", v == w)
    print("Vector(1, 2) < Vector(1, 3):", Vector(1, 2) < Vector(1, 3))

    # sum() works because of __radd__
    total = sum([Vector(1, 1), Vector(2, 2), Vector(3, 3)])
    print("sum of vectors:", total)

    # Slice assignment
    u = Vector(0, 0, 0, 0)
    u[1:3] = 7
    print("after slice assignment:", u)
```

## What each method does

| Python syntax | Special method |
|---|---|
| `a + b` | `__add__` |
| `b + a` when `a + b` fails | `__radd__` |
| `a += b` | `__iadd__` |
| `a - b` | `__sub__` |
| `a * b` | `__mul__` |
| `b * a` for scalar | `__rmul__` |
| `a / b` | `__truediv__` |
| `a // b` | `__floordiv__` |
| `a % b` | `__mod__` |
| `a ** b` | `__pow__` |
| `a @ b` | `__matmul__` |
| `-a` | `__neg__` |
| `+a` | `__pos__` |
| `abs(a)` | `__abs__` |
| `a == b` | `__eq__` |
| `a < b` | `__lt__` |
| `len(a)` | `__len__` |
| `a[i]` | `__getitem__` |
| `a[i] = x` | `__setitem__` |
| `x in a` | `__contains__` |
| `for x in a` | `__iter__` |
| `bool(a)` | `__bool__` |

## Important implementation notes

1. **Return `NotImplemented`, do not raise, for unsupported operands.**  
   This lets Python try the reflected operation or produce the standard `TypeError`.

2. **Use `functools.total_ordering`.**  
   Implement only `__eq__` and `__lt__`; Python generates the other comparisons.

3. **Mutable objects are usually unhashable.**  
   Setting `__hash__ = None` prevents `Vector` from being used as a dictionary key or set member, which is safer for mutable types.

4. **In-place operators should mutate and return `self`.**  
   For example, `v += w` updates `v` rather than creating a new vector.

5. **Validate dimensions explicitly.**  
   Addition, subtraction, dot product, and ordering require vectors of the same length.

6. **Be careful with ambiguity.**  
   In this example, `*` means scalar multiplication and `@` means dot product. This avoids the common ambiguity of defining `*` as either scalar multiplication or dot product.

Operator overloading in Python means defining special methods (often called “dunder” methods) on a class so that built-in operators and functions behave sensibly for your objects. Python itself translates expressions like `a + b` into method calls such as `a.__add__(b)`.

## Core idea

- You do not change the operator itself; you implement the protocol.
- Operators should usually return **new objects** and leave operands unchanged unless in-place semantics are appropriate.
- If an operation is unsupported, return `NotImplemented` so Python can try the reflected operation (`b.__radd__(a)`) or raise a clear `TypeError`.

## Basic syntax

```python
class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __add__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return Vector(self.x + other.x, self.y + other.y)

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

v1 = Vector(1, 2)
v2 = Vector(3, 4)
print(v1 + v2)  # Vector(4, 6)
```

## Common operator families

### Arithmetic

```python
class Money:
    def __init__(self, amount):
        self.amount = amount

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.amount + other.amount)

    def __mul__(self, factor):
        if not isinstance(factor, (int, float)):
            return NotImplemented
        return Money(self.amount * factor)

    def __rmul__(self, factor):   # supports 2 * money
        return self.__mul__(factor)

    def __repr__(self):
        return f"Money({self.amount})"
