## Final solution

```python
from abc import ABC, abstractmethod
from dataclasses import dataclass


class NotificationChannel(ABC):
    @abstractmethod
    def send(self, recipient: str, message: str) -> str:
        ...

    @property
    @abstractmethod
    def channel_name(self) -> str:
        ...

    def prepare_message(self, message: str) -> str:
        return message.strip()


@dataclass
class EmailChannel(NotificationChannel):
    smtp_server: str = "smtp.example.com"

    def send(self, recipient: str, message: str) -> str:
        return f"[EMAIL via {self.smtp_server}] To={recipient}: {self.prepare_message(message)}"

    @property
    def channel_name(self) -> str:
        return "email"

    def prepare_message(self, message: str) -> str:
        return f"<p>{message.strip()}</p>"


@dataclass
class SMSChannel(NotificationChannel):
    max_length: int = 160

    def send(self, recipient: str, message: str) -> str:
        return f"[SMS] To={recipient}: {self.prepare_message(message)}"

    @property
    def channel_name(self) -> str:
        return "sms"

    def prepare_message(self, message: str) -> str:
        cleaned = message.strip()
        if len(cleaned) <= self.max_length:
            return cleaned
        return cleaned[: self.max_length - 3] + "..."


@dataclass
class PushChannel(NotificationChannel):
    app_name: str = "MyApp"

    def send(self, recipient: str, message: str) -> str:
        return f"[PUSH via {self.app_name}] To={recipient}: {self.prepare_message(message)}"

    @property
    def channel_name(self) -> str:
        return "push"

    def prepare_message(self, message: str) -> str:
        return f"🔔 {message.strip()}"


class AlertService:
    def __init__(self, channels: list[NotificationChannel]) -> None:
        self.channels = list(channels)

    def broadcast(self, recipient: str, message: str) -> list[str]:
        return [channel.send(recipient, message) for channel in self.channels]


if __name__ == "__main__":
    channels = [
        EmailChannel(),
        SMSChannel(max_length=40),
        PushChannel(app_name="OpsAlert"),
    ]

    service = AlertService(channels)
    for result in service.broadcast("alice@example.com", "  Server CPU usage is above 90%  "):
        print(result)
```

## Why this is polymorphic

- `AlertService.broadcast` calls `channel.send(...)` on objects of different concrete types.
- Python chooses the correct `send` implementation at runtime.
- Each channel also overrides `prepare_message`, so message formatting is channel-specific.
- The service remains closed to modification: new channels can be added without changing `AlertService`.

## Polymorphism in Python (interview answer)

**Definition.** Polymorphism = “many forms”: the *same interface* (method name, operator, or function) dispatches to *different implementations* depending on the actual object/type at runtime.

In Python this shows up in several flavors:

| Flavor | Mechanism | Dispatch time |
|---|---|---|
| Duck typing | `obj.method()` resolved at runtime | runtime |
| Inheritance / overriding | subclass overrides base method, MRO | runtime |
| ABC / nominal subtyping | `isinstance` checks against abstract base | runtime |
| `Protocol` / structural subtyping | interface by shape, static + runtime | both |
| Operator overloading | `__add__`, `__len__`, … | runtime |
| Parametric (generics) | `TypeVar`, `Generic[T]` | static (typing) |
| Function overloading | `functools.singledispatch` | runtime by type |

Key runtime idea: Python is dynamically typed, so “polymorphic dispatch” is just *attribute lookup + call* (`type(obj).__mro__`). There’s no vtable in the C++ sense, but the effect is the same: the *actual* class of the object determines which method runs (Liskov substitution principle).

---

### Clean implementation of the core

```python
"""Polymorphism in Python: duck typing, ABCs, Protocols, generics, singledispatch."""
from __future__ import annotations

import math
from abc import ABC, abstractmethod
from dataclasses import dataclass
from functools import singledispatch
from typing import Generic, Iterable, Protocol, TypeVar, runtime_checkable


# ------------------------------------------------------------------ #
# 1. Duck typing: NO shared base class required.
#    Polymorphism comes from "having the right method", not from lineage.
# ------------------------------------------------------------------ #
class Circle:
    def __init__(self, radius: float):
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2

    def perimeter(self) -> float:
        return 2 * math.pi * self.radius


class Square:
    def __init__(self, side: float):
        self.side = side

    def area(self) -> float:
        return self.side ** 2

    def perimeter(self) -> float:
        return 4 * self.side


def total_area(shapes: Iterable) -> float:
    """Works for ANY object exposing .area() — pure duck typing."""
    return sum(s.area() for s in shapes)


# ------------------------------------------------------------------ #
# 2. Nominal polymorphism via Abstract Base Class (ABC).
#    Enforces a contract at instantiation time.
# ------------------------------------------------------------------ #
class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...

    @abstractmethod
    def perimeter(self) -> float: ...

    # Shared (non-polymorphic) behavior built on polymorphic primitives.
    def describe(self) -> str:
        return f"area={self.area():.2f}, perimeter={self.perimeter():.2f}"


@dataclass(frozen=True)
class Rectangle(Shape):
    width: float
    height: float

    def area(self) -> float:
        return self.width * self.height

    def perimeter(self) -> float:
        return 2 * (self.width + self.height)


# Liskov substitution: a Rectangle can stand in for any Shape.
def print_shape(s: Shape) -> None:
    print(s.describe())   # dispatches to Rectangle's area/perimeter


# ------------------------------------------------------------------ #
# 3. Structural subtyping via Protocol (PEP 544).
#    No inheritance needed; static checkers + runtime isinstance both work.
# ------------------------------------------------------------------ #
@runtime_checkable
class Measurable(Protocol):
    def area(self) -> float: ...
    def perimeter(self) -> float: ...


def report(x: Measurable) -> str:
    """Accepts Circle, Square, Rectangle, or any matching object."""
    assert isinstance(x, Measurable)   # runtime structural check
    return f"{type(x).__name__}: area={x.area():.2f}"


# ------------------------------------------------------------------ #
# 4. Operator overloading: polymorphism through special methods.
# ------------------------------------------------------------------ #
@dataclass
class Vector:
    x: float
    y: float

    def __add__(self, other: "Vector") -> "Vector":
        return Vector(self.x + other.x, self.y + other.y)

    def __len__(self) -> int:          # len(v) becomes polymorphic
        return 2

    def __repr__(self) -> str:
        return f"Vector({self.x}, {self.y})"


# ------------------------------------------------------------------ #
# 5. Parametric polymorphism (generics) + function overloading.
# ------------------------------------------------------------------ #
T = TypeVar("T")


class Box(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def get(self) -> T:
        return self.value


# singledispatch: one function name, multiple implementations by type.
@singledispatch
def render(obj) -> str:
    raise NotImplementedError(f"no renderer for {type(obj).__name__}")


@render.register(Circle)
def _(c: Circle) -> str:
    return f"● radius={c.radius}"

@render.register(Rectangle)
def _(r: Rectangle) -> str:
    return f"▬ {r.width}×{r.height}"

@render.register(Square)
def _(s: Square) -> str:
    return f"■ side={s.side}"


# ------------------------------------------------------------------ #
# Demo
# ------------------------------------------------------------------ #
if __name__ == "__main__":
    shapes = [Circle(2), Square(3), Rectangle(4, 5)]
    print("total_area (duck typing):", total_area(shapes))

    print_shape(Rectangle(3, 4))

    for s in shapes:
        print(report(s), "|", render(s))

    v = Vector(1, 2) + Vector(3, 4)
    print(v, "len=", len(v))

    boxed: Box[int] = Box(42)
    print("boxed:", boxed.get())
```

### Talking points you can add in the interview

1. **Resolution order.** Method lookup follows `type(obj).__mro__` (Method Resolution Order). `super()` walks that chain — this is how cooperative multiple inheritance stays polymorphic.
2. **No overloading by signature.** Python has *one* method per name; `@singledispatch` (or manual `isinstance` chains) is the idiomatic workaround.
3. **Static vs. runtime.** Type hints + `Protocol` let a type checker (mypy/pyright) verify polymorphism *statically*, while runtime still uses duck typing. `@runtime_checkable` bridges the two.
4. **Composition over inheritance.** Because duck typing needs no shared base, you often get polymorphism by *having the method* rather than *being a subclass* — prefer protocols/duck typing for flexibility, ABCs when you need enforced contracts.
5. **LSP in practice.** A subtype must honor the base contract (preconditions no stronger, postconditions no weaker). Python won’t enforce it; tests/mypy do.

Polymorphism in Python is dynamic: it depends on protocols, MRO, descriptors, and runtime checks more than inheritance alone. Below are important edge cases and how to handle them.

## 1. Missing methods in duck-typed APIs

Duck typing assumes a method exists, but the object may not implement it.

```python
_MISSING = object()

def area(shape):
    attr = getattr(shape, "area", _MISSING)
    if attr is _MISSING:
        raise TypeError(f"{type(shape).__name__} does not support area()")
    return attr() if callable(attr) else attr
```

Handle both “method” and “property named `area`.” Do not assume `shape.area()` will always exist.

## 2. Proxy objects and `__getattr__` recursion

A proxy that delegates attribute access can recurse infinitely if it touches its own state incorrectly.

```python
class Proxy:
    def __init__(self, target):
        self._target = target

    def __getattr__(self, name):
        # Avoid recursion by reading _target through object.__getattribute__
        target = object.__getattribute__(self, "_target")
        return getattr(target, name)
```

Always access proxy-internal attributes through `object.__getattribute__`.

## 3. Replacing descriptors/properties in subclasses

A base class may expose a property, while a subclass wants a plain attribute or method. Also, instance assignment may fail if there is no setter.

```python
class Base:
    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, v):
        self._value = v

class Sub(Base):
    value = 42  # replaces the property with a class attribute in Sub

def safe_set(obj, v):
    setter = getattr(type(obj), "value", None)
    if isinstance(setter, property) and setter.fset is None:
        raise AttributeError("value is read-only on this type")
    obj.value = v
```

Polymorphic setters should check whether the attribute is actually assignable.

## 4. Inconsistent multiple-inheritance MRO

Python uses C3 linearization. Some combinations are impossible.

```python
class A: pass
class B(A): pass
class C(A): pass
class D(B, C): pass

print(D.__mro__)  # D, B, C, A, object

class X(A, B): pass
class Y(B, A): pass

try:
    class Z(X, Y): pass
except TypeError as e:
    print(e)  # Cannot create a consistent method resolution order
```

Always inspect `__mro__` when debugging multiple inheritance.

## 5. Cooperative `super()` and broken diamonds

If one branch fails to call `super()`, another branch may be skipped.

```python
class Base:
    def ping(self):
        return ["Base"]

class Left(Base):
    def ping(self):
        return ["Left"] + super().ping()

class Right(Base):
    def ping(self):
        return ["Right"] + super().ping()

class Diamond(Left, Right):
    pass

print(Diamond().ping())  # ['Left', 'Right', 'Base']
```

For cooperative multiple inheritance, every override should call `super()` unless intentionally terminating the chain.

## 6. ABC virtual registration gives false safety

`ABC.register` makes an object a virtual subclass without checking methods.

```python
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self): ...

class Blob:
    pass

Shape.register(Blob)

print(isinstance(Blob(), Shape))  # True, but area() is missing

def area_of(x):
    if not isinstance(x, Shape) or not callable(getattr(x, "area", None)):
        raise TypeError(f"{type(x).__name__} is not a usable Shape")
    return x.area()
```

Virtual subclass checks are nominal, not structural.

## 7. `typing.Protocol` runtime checks are shallow

`runtime_checkable` protocols only check method existence, not signatures.

```python
from typing import Protocol, runtime_checkable
import inspect

@runtime_checkable
class Renderable(Protocol):
    def render(self, canvas) -> None: ...

class Bad:
    def render(self):  # wrong arity
        pass

assert isinstance(Bad(), Renderable)  # True incorrectly

def validate_renderable(obj):
    method = getattr(obj, "render", None)
    if not callable(method):
        raise TypeError("missing render")
    params = list(inspect.signature(method).parameters)
    if len(params) != 1:
        raise TypeError("render must accept canvas")
```

Use `inspect.signature` when protocol compliance matters.

## 8. `isinstance` with generics fails at runtime

Generics such as `list[int]` are not runtime types.

```python
from typing import List

try:
    isinstance([1, 2], List[int])
except TypeError as e:
    print(e)

def is_int_list(value):
    return isinstance(value, list) and all(type(x) is int for x in value)
```

Separate container checks from element checks.

## 9. Operator overloading and `NotImplemented`

Returning `NotImplemented` lets Python try the reflected operator. Raising breaks polymorphic fallback.

```python
class Money:
    def __init__(self, amount):
        self.amount = amount

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.amount + other.amount)

    __radd__ = __add__

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.amount == other.amount
```

If both sides return `NotImplemented`, Python raises `TypeError`.

## 10. Truthiness and `__bool__` vs `__len__`

An object with `__len__` returning zero is false unless `__bool__` says otherwise.

```python
class Packet:
    def __init__(self, payload=()):
        self.payload = payload

    def __len__(self):
        return len(self.payload)

    def __bool__(self):
        # Explicit truthiness; __bool__ wins if both are defined.
        return bool(self.payload)

print(bool(Packet([])))      # False
print(bool(Packet([1])))     # True
```

Implement `__bool__` when zero length does not imply falsiness.

## 11. Equality and hashing contract

Defining `__eq__` without `__hash__` makes instances unhashable in Python 3.

```python
class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return (self.x, self.y) == (other.x, other.y)

    # Identity-based hashing keeps Point hashable.
    __hash__ = object.__hash__

# Value-based alternative:
    # def __hash__(self):
    #     return hash((self.x, self.y))
```

Choose identity hashing or value hashing consistently with equality.

## 12. Ordering and `total_ordering`

Use `@total_ordering` to reduce ordering methods, but validate types.

```python
from functools import total_ordering

@total_ordering
class Version:
    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.value == other.value

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.value < other.value
```

If `__lt__` returns `NotImplemented` for unrelated types, Python can still attempt reflected comparison.

## 13. `__slots__` conflicts in multiple inheritance

Two bases cannot define the same slot.

```python
class A:
    __slots__ = ("x",)

class B:
    __slots__ = ("y",)

class C(A, B):
    __slots__ = ()  # works

class D:
    __slots__ = ("x",)

try:
    class E(A, D):
        __slots__ = ()
except TypeError as e:
    print(e)  # multiple bases have instance lay-out conflict
```

Use unique slot names or an empty `__slots__` in the subclass.

## 14. Pickling and copying custom objects

Polymorphic frameworks often clone or serialize objects. Make this explicit.

```python
import copy

class Cloneable:
    def __init__(self, value):
        self.value = value

    def __copy__(self):
        return Cloneable(self.value)

    def __deepcopy__(self, memo):
        return Cloneable(copy.deepcopy(self.value, memo))

    def __reduce__(self):
        return (Cloneable, (self.value,))
```

For slotted classes, ensure the class is importable and state is reconstructible.

## 15. Name mangling breaks cross-class polymorphism

`__name` becomes `_ClassName__name`, so base and subclass do not share it.

```python
class Base:
    def __init__(self):
        self.__token = "base"

    def token(self):
        return self.__token

class Sub(Base):
    def token(self):
        # self.__token here means _Sub__token, which does not exist
        return getattr(self, "_Base__token")

print(Sub().token())  # base
```

Use one leading underscore for attributes that must cooperate across classes.

## 16. Metaclass conflicts

Incompatible metaclasses prevent subclassing even when the APIs match.

```python
class Meta1(type): pass
class Meta2(type): pass

class A(metaclass=Meta1): pass
class B(metaclass=Meta2): pass

try:
    class C(A, B): pass
except TypeError as e:
    print(e)

# Fix: common metaclass
class CommonMeta(Meta1, Meta2): pass
class A2(metaclass=CommonMeta): pass
class B2(metaclass=CommonMeta): pass
class C2(A2, B2): pass
```

## 17. Dataclass inheritance and `__post_init__`

Dataclass-generated methods can override or omit base behavior.

```python
from dataclasses import dataclass

@dataclass
class Base:
    x: int

    def total(self):
        return self.x

@dataclass
class Sub(Base):
    y: int = 0

    def __post_init__(self):
        if hasattr(super(), "__post_init__"):
            super().__post_init__()
        if self.y < 0:
            raise ValueError("y must be non-negative")

print(Sub(3, 4).total())  # 3
```

Call `super().__post_init__()` explicitly when both base and subclass use post-initialization.

## 18. Monkeypatching and `super()` closures

`super()` with no arguments depends on the `__class__` cell. A moved or patched function may not have it.

```python
class A:
    def m(self):
        return "A"

class B(A):
    def m(self):
        return "B-" + super().m()

def patched(self):
    return "P-" + super(B, self).m()

B.m = patched
print(B().m())  # P-B-A? Actually B.m patched replaces; base B.m no longer called.
```

When patching methods, use explicit `super(CurrentClass, self)`.

## 19. `bool` is a subclass of `int`

Strict numeric polymorphism must reject booleans if ints are required.

```python
def accept_count(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("expected int, not bool or other type")
    return n + 1

# True passes isinstance(True, int), so reject it explicitly.
```

## 20. `None` and sentinel defaults

Using `None` as a default can conflict with valid `None` input. Use a sentinel.

```python
_UNSET = object()

def find(items, default=_UNSET):
    if not items:
        if default is _UNSET:
            raise ValueError("items is empty")
        return default
    return items[0]
```

This avoids ambiguity between “not provided” and “explicitly None.”

## 21. Generators are single-pass iterables

Polymorphic code that iterates twice may silently get empty results.

```python
def pairs(items):
    data = list(items)  # materialize once
    return list(zip(data, data[1:]))

g = (x for x in range(4))
print(pairs(g))  # [(0, 1), (1, 2), (2, 3)]
```

Materialize unknown iterables if they must be reused, but beware memory use for large streams.

## 22. Async vs sync polymorphism

A caller cannot blindly `await` a polymorphic method.

```python
import inspect

async def call_fetch(obj):
    method = obj.fetch
    if inspect.iscoroutinefunction(method):
        return await method()
    result = method()
    if inspect.isawaitable(result):
        return await result
    return result
```

Check both coroutine functions and awaitable return values.

## 23. Pattern matching and `__match_args__`

Structural pattern matching needs positional match metadata.

```python
class Circle:
    __match_args__ = ("radius",)

    def __init__(self, radius):
        self.radius = radius

def describe(shape):
    match shape:
        case Circle(r) if r > 0:
            return f"circle radius {r}"
        case Circle(0):
            return "point"
        case _:
            raise TypeError(f"unsupported shape: {type(shape).__name__}")

print(describe(Circle(3)))  # circle radius 3
```

Without `__match_args__`, positional class patterns fail.

## 24. `Enum` equality surprises

Enums compare by identity, not by underlying value, unless you use `IntEnum` etc.

```python
from enum import Enum, IntEnum

class Color(Enum):
    RED = 1

class Status(IntEnum):
    OK = 200

print(Color.RED == 1)     # False
print(Status.OK == 200)   # True
print(Status.OK + 1)      # 201
```

Polymorphic numeric code should use `IntEnum`/`IntFlag` or access `.value`.

## 25. Single dispatch is first-argument and MRO-based

`functools.singledispatch` manages its global registry; subclasses use the nearest registered base unless explicitly registered.

```python
from functools import singledispatch

@singledispatch
def render(obj):
    return f"default: {obj!r}"

@render.register(list)
def _(obj):
    return f"list with {len(obj)} items"

class MyList(list):
    pass

print(render(MyList([1, 2])))  # uses list implementation
```

Register exact types when subclass behavior must differ.

---

### Practical checklist

- Validate protocol compliance beyond `isinstance`, especially for protocols.
- Handle missing attributes with `getattr(..., sentinel)`.
- Use `NotImplemented` in operator/equality methods.
- Keep `__eq__` and `__hash__` consistent.
- Call `super()` consistently in multiple inheritance.
- Test cloning, pickling, slots, and subclassing.
- Avoid name mangling for cooperative attributes.
- Distinguish sync from async polymorphic methods.
- Materialize iterators before reuse.
- Treat `bool` specially when an `int` is required.

Here is a complete, runnable example that demonstrates refactoring in Python. It includes:

1. A **legacy, smelly implementation**
2. A **refactored, testable, object-oriented implementation**
3. A **differential test suite** that checks that refactoring preserved behavior
4. A small **automated AST-based refactoring helper** (`rename_identifier`)
5. Runnable `unittest` tests and a demo

Save this as `refactoring_example.py` and run:

```bash
python refactoring_example.py
```

```python
"""Complete runnable example: manual refactoring + automated rename refactoring."""

from __future__ import annotations

import ast
import random
import unittest
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP
from typing import Protocol


# =============================================================================
# 1. LEGACY IMPLEMENTATION (intentionally messy)
# =============================================================================

def calculate_invoice_legacy(order: dict) -> float:
    """One long function with magic numbers, mixed responsibilities, and poor names."""
    total = 0.0

    for item in order["items"]:
        price = item["price"]
        quantity = item["quantity"]
        line_total = price * quantity
        category = item.get("category", "other")

        if category == "food":
            line_total *= 0.90
        elif category == "electronics" and line_total > 100:
            line_total *= 0.85

        total += line_total

    if total > 200:
        total *= 0.95

    tax = total * 0.08
    shipping = 5.99 if total < 50 else 0.0

    if order.get("premium_member"):
        shipping = 0.0

    return round(total + tax + shipping, 2)


# =============================================================================
# 2. REFACTORED IMPLEMENTATION
# =============================================================================

@dataclass(frozen=True)
class OrderItem:
    name: str
    unit_price: Decimal
    quantity: int
    category: str = "other"

    def line_total(self) -> Decimal:
        return self.unit_price * self.quantity


@dataclass(frozen=True)
class Order:
    items: tuple[OrderItem, ...]
    premium_member: bool = False


class CategoryDiscountPolicy:
    """Knows category-specific discounts."""

    def rate_for(self, item: OrderItem) -> Decimal:
        if item.category == "food":
            return Decimal("0.10")
        if item.category == "electronics" and item.line_total() > Decimal("100"):
            return Decimal("0.15")
        return Decimal("0")

    def apply(self, item: OrderItem) -> Decimal:
        rate = self.rate_for(item)
        return item.line_total() * (Decimal("1") - rate)


class BulkDiscountPolicy:
    """Applies a bulk discount to the whole subtotal."""

    threshold = Decimal("200")
    rate = Decimal("0.05")

    def apply(self, amount: Decimal) -> Decimal:
        if amount > self.threshold:
            return amount * (Decimal("1") - self.rate)
        return amount


class TaxCalculator:
    rate = Decimal("0.08")

    def calculate(self, amount: Decimal) -> Decimal:
        return amount * self.rate


class ShippingCalculator:
    free_shipping_threshold = Decimal("50")
    standard_cost = Decimal("5.99")

    def calculate(self, subtotal: Decimal, premium_member: bool) -> Decimal:
        if premium_member or subtotal >= self.free_shipping_threshold:
            return Decimal("0")
        return self.standard_cost


def money(value: Decimal) -> Decimal:
    """Normalize money to 2 decimal places."""
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceCalculator:
    """Coordinates the invoice calculation without owning every rule."""

    def __init__(
        self,
        category_discount: CategoryDiscountPolicy | None = None,
        bulk_discount: BulkDiscountPolicy | None = None,
        tax: TaxCalculator | None = None,
        shipping: ShippingCalculator | None = None,
    ):
        self.category_discount = category_discount or CategoryDiscountPolicy()
        self.bulk_discount = bulk_discount or BulkDiscountPolicy()
        self.tax = tax or TaxCalculator()
        self.shipping = shipping or ShippingCalculator()

    def calculate(self, order: Order) -> Decimal:
        subtotal = sum(
            (self.category_discount.apply(item) for item in order.items),
            Decimal("0"),
        )
        subtotal = self.bulk_discount.apply(subtotal)
        tax = self.tax.calculate(subtotal)
        shipping = self.shipping.calculate(subtotal, order.premium_member)
        return money(subtotal + tax + shipping)


def order_from_legacy_dict(legacy_order: dict) -> Order:
    """Adapter: convert old dictionary shape to the new domain model."""
    items = tuple(
        OrderItem(
            name=item.get("name", f"item-{index}"),
            unit_price=Decimal(str(item["price"])),
            quantity=item["quantity"],
            category=item.get("category", "other"),
        )
        for index, item in enumerate(legacy_order["items"])
    )
    return Order(
        items=items,
        premium_member=legacy_order.get("premium_member", False),
    )


# =============================================================================
# 3. AUTOMATED REFACTORING HELPER (AST-based rename)
# =============================================================================

class RenameIdentifier(ast.NodeTransformer):
    """Rename a simple identifier across defs, args, and references."""

    def __init__(self, old_name: str, new_name: str):
        self.old_name = old_name
        self.new_name = new_name

    def visit_Name(self, node: ast.Name) -> ast.Name:
        if node.id == self.old_name:
            node.id = self.new_name
        return node

    def visit_FunctionDef(self, node: ast.FunctionDef):
        if node.name == self.old_name:
            node.name = self.new_name
        self.generic_visit(node)
        return node

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef):
        if node.name == self.old_name:
            node.name = self.new_name
        self.generic_visit(node)
        return node

    def visit_arg(self, node: ast.arg):
        if node.arg == self.old_name:
            node.arg = self.new_name
        self.generic_visit(node)
        return node


def rename_identifier(source: str, old_name: str, new_name: str) -> str:
    """Parse Python source, rename an identifier, and return new source."""
    tree = ast.parse(source)
    tree = RenameIdentifier(old_name, new_name).visit(tree)
    ast.fix_missing_locations(tree)
    return ast.unparse(tree)


# =============================================================================
# 4. TESTS
# =============================================================================

class TestInvoiceRefactoring(unittest.TestCase):
    def make_legacy_order(self) -> dict:
        return {
            "items": [
                {"name": "apple", "price": 2.50, "quantity": 4, "category": "food"},
                {"name": "tv", "price": 120.00, "quantity": 1, "category": "electronics"},
            ],
            "premium_member": False,
        }

    def test_sample_order_matches_legacy(self):
        legacy_order = self.make_legacy_order()
        new_order = order_from_legacy_dict(legacy_order)

        expected = calculate_invoice_legacy(legacy_order)
        actual = float(InvoiceCalculator().calculate(new_order))

        self.assertAlmostEqual(actual, expected, places=2)

    def test_differential_random_orders(self):
        """Characterization-style test: compare old and new over many inputs."""
        rng = random.Random(20240517)
        categories = ["food", "electronics", "other"]

        for _ in range(300):
            item_count = rng.randint(0, 7)
            items = []

            for _ in range(item_count):
                items.append({
                    "price": round(rng.uniform(0.50, 150.00), 2),
                    "quantity": rng.randint(1, 5),
                    "category": rng.choice(categories),
                })

            legacy_order = {
                "items": items,
                "premium_member": rng.choice([False, False, True]),
            }
            new_order = order_from_legacy_dict(legacy_order)

            expected = calculate_invoice_legacy(legacy_order)
            actual = float(InvoiceCalculator().calculate(new_order))

            # Allow for tiny rounding differences between float and Decimal.
            self.assertTrue(
                abs(actual - expected) <= 0.015,
                msg=(actual, expected, legacy_order),
            )

    def test_rename_helper(self):
        source = (
            "def countdown(n):\n"
            "    return countdown(n - 1) if n > 0 else 0\n"
        )
        renamed = rename_identifier(source, "countdown", "recurse")

        self.assertIn("def recurse", renamed)
        self.assertIn("recurse(n - 1)", renamed)

        namespace = {}
        exec(renamed, namespace)
        self.assertEqual(namespace["recurse"](10), 0)


# =============================================================================
# 5. DEMO
# =============================================================================

def demo() -> None:
    order = {
        "items": [
            {"name": "book", "price": 12.00, "quantity": 2, "category": "other"},
            {"name": "laptop", "price": 900.00, "quantity": 1, "category": "electronics"},
            {"name": "bread", "price": 3.00, "quantity": 3, "category": "food"},
        ],
        "premium_member": True,
    }

    print("Legacy result:   ", calculate_invoice_legacy(order))
    print("Refactored result:", InvoiceCalculator().calculate(order_from_legacy_dict(order)))

    source = "def total(values):\n    return sum(total(xs) for xs in values) if values else 0\n"
    # The above is deliberately odd; demonstrate renaming only.
    print("\nOriginal source:\n" + source)
    print("Renamed source:\n" + rename_identifier(source, "total", "nested_sum"))


if __name__ == "__main__":
    unittest.main(argv=["ignored"], exit=False, verbosity=2)
    print("\n--- Demo ---")
    demo()
```

### What this demonstrates

- **Characterization tests first**: `test_differential_random_orders` compares the old and new implementations over hundreds of random inputs.
- **Extract method / strategy pattern**: discount, tax, and shipping rules moved into small policy objects.
- **Value objects**: `OrderItem` and `Order` make the domain explicit and immutable.
- **Decimal for money**: avoids binary floating-point surprises.
- **Adapter**: `order_from_legacy_dict` lets old callers migrate gradually.
- **Automated refactoring**: `rename_identifier` parses source with `ast`, renames identifiers, and unparses it back. In production, prefer `libcst` or `rope` because they preserve comments and formatting better.
